window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[4]=[{"i":13942,"n":"*הלפרין-ליפשיץ, משה אשכנזי מבר","f":"זבולון אליעזר אשכנזי","k":"בעל זכרון משה","bp":"היילברון","dt":"שסה","dp":"ירושלים","b":"למד בקראקא אצל המהרש\"ל, ואולי גם אצל הרמ\"א. היה חותנו של המהרש\"א הקרוי על שם איידל אשתו של ר משה. מקור השם הלפרין הוא העיר היילברון בגרמניה משם מוצאו. בשנת ש' התיישב בבריסק, עלה לירושלים. חיבר \"זכרון משה\" חמד שעא. לפי וונדר היה כנראה גיסו או חותנו של המהרש\"א (נשואים לשתי אחיות). חתן ר משה ב\"ר יצחק ליפשיץ מבריסק. חיבר \"זכרון משה\" לובלין שעא, \"לחם השמים\" על המשניות. בניו - ר יונה מזולקוא, ר אברהם מלבוב. רב בבריסק-של. ישב בדין יחד עם המהרש\"ל באוסטרהא ועם ר שמשון מפינסק (על מקום הדיין השלישי ר מרדכי מטיקטין שנפטר באמצע הדיון). חתנו - ר משה אשכנזי-חותנו של המהרש\"א. (יש מחליפים בינו לבין בעל 'לחם משנה' ואולי היה חתנו?)."},{"i":13943,"n":"האברבאנד, יהושע מסלומניק","b":"פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":13944,"n":"האגיו, יצחק הספרדי מפיררה","dp":"ש - בערך","b":"סוחר מחכמי פיררה, עלה לירושלים-שנת ש' בערך ונפטר שם. נזכר ב\"מאור עינים\" לר עזריה מן האדומים. (אולי הוא שהיה רבו של ר חיים אחי המהר\"ל ונזכר בספרו \"אגרת הטיול\")."},{"i":13945,"n":"האדמו\"ר משטעפנעשט זצוקללה\"ה זיע\"א","dt":"כא תמוז"},{"i":13946,"n":"האוואשי שמעון, צדוק","f":"מרק הנדלר","k":"בעל בעית איוב","b":"רב ניאולוגי ראשי בבודפשט. חבר ומייסד ארגונים יהודיים תרבותיים. פרסם בכתב עת ובהם \"הצפה\" \"הסוקר\", ועוד. חיבר גם פירוש ל\"קהילת\" - בעברית, פירוש למורה נבוכים, ועוד."},{"i":13947,"n":"האוואשי, אפרים","f":"צדוק","k":"בעל תולדות הפילוסופי","dt":"1950","dp":"ארה\"ב","b":"רב ניאולוגי בבודפשט. ד\"ר בתחום הפילוסופיה של הדתות. חיבר \"תולדות הפילוסופיה הדתית\". ניצל מהשואה, ואחריה היגר לארה\"ב-1946."},{"i":13948,"n":"האוושא, יחיאל מיכל משקוד","f":"ראובן צבי בן אליעזר","k":"בעל מיכל מים","bt":"תרה","bp":"קלם-ליטא","dt":"תרעז - כה אלול","b":"נכד ר אליעזר גוטמן מקלם. חתן ר צבי הירש רלבה משאווילן. רב בפרנוב-אסטוניה, שקוד. חיבר גם \"וימת שמואל\" - הספד על ר שמואל מוהליבר."},{"i":13949,"n":"האופליג, יהודה","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":13950,"n":"האז, חיים מציפר","dt":"תקפד - כג תשרי","dp":"טירנא","b":"רב בציפר, טירנא-תקסד. תשובה אליו ב\"חתם סופר\"."},{"i":13951,"n":"האז, שלמה מפפד\"מ","b":"מראשי קהילת פפד\"מ-תקן, השתתף במשלחת אל הקיסר ליאופולד, עם חבריו ר יוסף גונדרשהיים, ור יצחק שפייר. השתתפו גם במשלחת אל הקיסר פרנץ השני-תקנב."},{"i":13952,"n":"האזובי, אברהם מאמריקה","dt":"תקסה","b":"רב בצ'רלסטון-דרום קרולינה - תקמה."},{"i":13953,"n":"האזובי, אלעזר מפרובנס","f":"חנן","b":"ממשפחת חכמים פייטנים ומשוררים. רב בקרפנטרץ-ן'. חיבר פיוטים ושירים ומהם במחזור הספרדי. אחיו: ר יוסף, ור משלם."},{"i":13954,"n":"האזובי, יוסף מצרפת","f":"חנן בן נתן","k":"בעל קערת כסף","b":"מחכמי פרובאנס, פייטן בפירפיניינו-ד'תתקנ. מתלמידיו - ר אברהם בדרשי. בנו - ר שמואל. אולי הוא שחיבר את ספר המלואים הנזכר ברשב\"א."},{"i":13955,"n":"האזובי, מרדכי מספרד","f":"יצחק","b":"רב בקרקשונא-ספרד-ס', בזמן הרשב\"א ונזכר בתשובות הרשבא."},{"i":13956,"n":"האזובי, שלמה מאיטליה וצרפת","f":"יהודה","k":"בעל אגודת אזוב","bt":"תקלה-תקם","bp":"סופה או קושטא","dt":"תרח","b":"עבר לצרפת וכיהן כרב בקרפנטרץ-תקף, טורינו-תקצו, קוניו, ליוורנו-תקצז, תרז-פירנצה. תרגם לוחות אסטרונומים של עמנואל בן יעקב לבקשתו של המלומד פיירז. לימד עברית למלומד ז'אן פלנטוויט דה לה פאוזה. חיבר גם דרשות, ושו\"ת. ?? לא באוצר ??"},{"i":13957,"n":"האזובי, שלמה משלוניקי","b":"מחכמי צפת?, שלוניקי, סייע לר יצחק ביגא בהוצאת ספרו \"בית נאמן\", ונזכר בספר."},{"i":13958,"n":"האיי גאון סורא","f":"נחשון","b":"ראש ישיבת סורא-ד'תרמ\"ח-תרנ\"ח"},{"i":13959,"n":"האיי גאון פומפדיתא","f":"דוד","b":"דיין בבגדד, ראש ישיבת פומבדיתא, ד'תר\"נ-תרנ\"ח, העביר את ישיבת פומבדיתא לבגדד"},{"i":13960,"n":"האייטין, משה מברזנא","k":"בעל אמרי נועם","b":"רב בבארזנא-פלך טשרניגוב. חיבר גם \"נועם מגדים\", ובסופו תשובה מבנו - ר מנחם מנדל."},{"i":13961,"n":"האיסטיילינו, משה מפאס","dt":"שפב","b":"מחכמי פאס. נספד מאת ר שאול סירירו."},{"i":13962,"n":"האיתמרי, אליהו הכהן","f":"אברהם שלמה הכהן","k":"בעל שבט מוסר","bt":"תכח","bp":"אזמיר","dt":"תפט - ח אד\"ב","b":"תלמיד ר בנימין מלמד. מגדולי חכמי איזמיר, דרשן, איש מופת. נספד מאת ר ברזילי יעבץ באזמיר, ר אברהם יצחק בירושלים. חיבר גם \"מדרש תלפיות\", ועוד. אחיו - ר יצחק, ר מיכאל.","bk":[["אגדת אליהו",""],["מדרש האתמרי",""],["מעיל צדקה",""],["שבט מוסר",""],["חוט של חסד","על התורה"]],"e":"תי\"ט~-תפ\"ט"},{"i":13963,"n":"האיתמרי, יצחק הכהן מירושלים","f":"אברהם שלמה האתמרי","bt":"תל","bp":"אזמיר","b":"מחכמי אזמיר, ירושלים בזמן ר משה בן חביב ור\"א יצחקי בשנים תכ-תס. אחיהם של ר אליהו בעל \"שבט מוסר\" הכותב עליו בספרו \"מדרש אליהו\" , ור מיכאל. הסכים על \"חמדת ימים\" עם ר חיים בנבנישתי."},{"i":13964,"n":"האיתמרי, מיכאל הכהן מאזמיר","f":"אברהם שלמה האתמרי","b":"מחכמי ירושלים-תפ. אחיהם של ר אליהו הכהן מאזמיר, שהביא מתורתו ב\"שבט מוסר\" ור אברהם שלמה הכהן."},{"i":13965,"n":"האכרמן, יעקב מצנסטחוב","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":13966,"n":"האכרמן, יצחק מאיר הלוי","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":13967,"n":"האלאש, שמחה מערטשי","f":"משה מפרשבורג","bt":"תרטז","bp":"פרשבורג","dt":"תרנז","dp":"ערטשי","b":"תלמיד השב\"ס. חתן ר יעקב קופל קרויס מאטש ועבר לשם. רב בערטשי."},{"i":13968,"n":"האלי, שמעון מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":13969,"n":"האלישוי, משה מפפד\"מ","b":"תלמיד ר נתן אדלר בפפד\"מ. כשיצא החרם נגד רבו-תקמט גורש מפפד\"מ."},{"i":13970,"n":"האללע, אהרן משטמפן","f":"פסח משטמפן","dt":"תרמב - יג סיון","dp":"שטמפן","b":"מראשי קהלת שטמפן."},{"i":13971,"n":"האללע, חנוך הניך משטמפן","f":"פסח משטמפן","dt":"תרלא - כג טבת","dp":"שטמפן","b":"מראשי קהלת שטמפן."},{"i":13972,"n":"האללע, פסח משטמפן","dt":"תקצח - כח אדר","dp":"שטמפן","b":"מחכמי שטמפן, חתם-תקנג על מינוי ר שלום אולמן לרבה של שטמפן. בניו - שמואל, חנוך הניך, ליב הרש מוערבוי, אהרן."},{"i":13973,"n":"האלעק, שמעון מדאלינה","dt":"תשג","b":"רב בדאלינה"},{"i":13974,"n":"האמיל, גדליה מפפד\"מ","b":"מראשי קהילת פפד\"מ-תקלח, ממנהלי קרן הצדקה של ליב רייס."},{"i":13975,"n":"האמיל, גליקל מהמבורג","b":"אשת ר חיים או משה האמיל. חיברה ספר זכרונות. מבניה - ר יוסף האמיל."},{"i":13976,"n":"האמיל, חיים מהמבורג","f":"יוסף","dt":"תמט - כד טבת","dp":"אלטונא","b":"בעלה של גליקל בעלת \"זכרונות גליקל\". נכד ר שמואל שטוטגרט. אחיו - ר שמואל מהילדסהיים."},{"i":13977,"n":"האמיל, יוסף מאה\"ו","f":"חיים מהמבורג וגליקל","b":"פרנס באה\"ו. חתנו - ר אליהו דב משוואבאך."},{"i":13978,"n":"האמיל, שמואל מהילדסהיים","f":"יוסף","b":"רב בהילדסהיים-תמ. אחיו של ר חיים-בעלה של גליקל."},{"i":13979,"n":"האן, אברהם יוסף מהמבורג","f":"משה","dt":"תקסג - כה אדר","dp":"המבורג","b":"דיין ודרשן באה\"ו. חתם בהמבורג-תקמט על החרם כנגד הספר \"מצפה יקותיאל\" - שפנה נגד ר רפאל הכהן מהמבורג. עמד לצדו של ר יונתן איבשיץ בזמן המחלוקת עם היעב\"ץ."},{"i":13980,"n":"האן, יצחק","b":"זקנו של ר יוסף בעל \"יוסף אומץ\". חזן, הדפיס תפילה מר מנחם לונזנו (ולפי בריל הדפיס את כל הספר)."},{"i":13981,"n":"האן, יצחק מפפד\"מ","b":"נכד ר יצחק החזן. אחיו של ר יוסף בעל \"יוסף אומץ\" והזכירו בספרו שסייע לו בחיבור ספרו."},{"i":13982,"n":"האן, מרדכי ממאהר","b":"ראש הקהל במאהר-תרא בזמן רבנות ר יצחק שטרנפלד."},{"i":13983,"n":"האן, משה שמואל זנויל","f":"יעקב","b":"מראשוני המשפחה - הגיע מפפד\"מ לאלטונא."},{"i":13984,"n":"האן, שמואל","b":"רב בדמבושיץ-ת\"ר"},{"i":13985,"n":"האנויער, יוסף מפפד\"מ","b":"מראשי קהילת פפד\"מ, ומבין 12 מחברי תקנות הקהילה-תקיג."},{"i":13986,"n":"האנזן, הירש מפפד\"מ","b":"דיין מחכמי פפד\"מ-תע."},{"i":13987,"n":"האניג אליהו","bt":"1860","dt":"ה'תרפד 1924","bk":[["בית מושב זקנים",""]]},{"i":13988,"n":"האנעלעש, אברהם ממינסק","b":"רב מטעם במינסק-תרן בערך."},{"i":13989,"n":"האנף, צבי זלמן מסלעפיאנקא","b":"חתן ר מנחם מנדל הוטנר ממינסק. מו\"צ בסלעפיאנקא."},{"i":13990,"n":"האס, אברהם","dt":"תש..","b":"ממקורבי ר משהניו פרידמן בקראקא. נספה בשואה."},{"i":13991,"n":"האס, הרץ מפפד\"מ","b":"דיין מחכמי פפד\"מ-תע."},{"i":13992,"n":"האס, טבלי ממנהיים","b":"רב במנהיים-תקכו. היה מהמערערים על הגט מקליווא. הסכים על \"עמודי בית יהודה\", נזכר אצל ה\"נודע ביהודה\"."},{"i":13993,"n":"האס, יוסף מפיורדא","k":"בעל בן פורת יוסף","dt":"תקנד - כז חשון","b":"דיין בפיורדא,רב בקאסל ומדינת הסן. חיבר \"בן פורת יוסף עם הגהות מבנו - ר יצחק."},{"i":13994,"n":"האס, יצחק מלנגספלד","f":"יוסף-בן פורת יוסף","k":"בעל שיח יצחק","bt":"תקכב-ה","bp":"פורטה-ליד נירנברג או פיור","dt":"תקפז - טז אב","b":"רב בלבנפעלד(=לנגספלד) ומדינת ויימאר-תקפד. עסק בפעילות צבור והקים חברות ותקן תקנות. הו\"ל ספר אביו \"בן פורת יוסף\", עם ביאורים ממנו בשם \"שיח יצחק\"."},{"i":13995,"n":"האס, מאיר מהמבורג","f":"פסח מהמבורג","k":"בעל נתיב הלשון","dt":"תרח -","dp":"המבורג","b":"ר\"מ בהמבורג, מחכמי הקלויז עם ר יוסף הנובר, ור זלמן וינהיים. דיין באלטונא. חיבר \"נתיב הלשון\" אלטונא תקפח, \"בקשת הלומדים\"."},{"i":13996,"n":"האס, משה"},{"i":13997,"n":"האס, משה מירוסלב","f":"שמעון","bt":"תרן","bp":"טיטשין","dt":"תשכד","b":"חתן רצ\"ה פרידברג מטרנופול. חסיד ר פנחס מאוסטילה. בעל תפלה בירוסלב. ברח לסיביר בזמן השואה, ועבר לפריז ולונדון."},{"i":13998,"n":"האס, שלמה מדרזניץ","k":"בעל כרם שלמה","b":"רב בדרזניץ-תק\"פ"},{"i":13999,"n":"האפט, אריה ליב מקאנטופ","f":"אליעזר יעקב","k":"בעל דברי טעם","bt":"תקצד","b":"רב בקאראפ, קאזאלץ, קאנטופ(=קאנאטאפ)-פלך צרניגוב-תרם. חיבר גם \"טוב טעם\" - בכת\"י. בנו - ר בן ציון מקלינציא, חתנו - ר שמעון הכהן מצוראוויץ."},{"i":14000,"n":"האפט, בן ציון מקליניצא","f":"אריה ליב מקאנטופ","b":"חתן ר חיים מצרניגוב. מו\"צ בקליניצא-תרע."},{"i":14001,"n":"האפרתי יוסף","bt":"1770","dt":"ה'תקסד 1804","bk":[["מלוכת שאול",""]]},{"i":14002,"n":"האק, ליב מהעכניגן","b":"אב\"ד העכינגן-תקעג. חיבר תפלות עבור בתו שהיתה בסכנת חיים."},{"i":14003,"n":"הארחוב, טבלי מליסא וברוד","b":"אב\"ד ליסא. החרים את \"דברי שלום ואמת\" לנפתלי הירץ ויזל-תקמב, וכתב עם רבנים מפולין מכתב לר צבי הירש מברלין שיאסור על ויזל להמשיך לכתוב בענין תיקונים בחינוך ילדי ישראל."},{"i":14004,"n":"הארט הצייר מאנגליה","dt":"תרמב - כסלו","dp":"אנגליה","b":"מצאצאי הגביר ר משה הארט. צייר את ר מנשה בן ישראל בפגישתו עם קרומוול לבקשת הגביר פרנס גולדשמיד."},{"i":14005,"n":"הארעליק, יוסף מחברון","b":"מראשי חסידות חב\"ד בחברון, מתלמידיו - ר חיים נאה."},{"i":14006,"n":"הארפנס, דוד מקלויזנבורג","f":"ראובן יואל","k":"הו\"ל עמודי גולה","bt":"תרמה","b":"תלמיד בעל \"קדושת יום טוב\". חסיד סיגט. רב ודיין בנאסוד, אחרי מלחמת העולם ה-I עבר לקלויזנבורג והקים שם ישיבה. נספה בשואה. עורך כתב העת \"שערי דעה\" - קלויזנבורג-דעווא תרפח, ו\"קול מחזיקי הדת\". עליו וקורותיו בספר אחיו ר יחזקאל \"בכף הקלע\". ?? לא באוצר ??"},{"i":14007,"n":"הארפנס, יחזקאל","k":"בעל כף הקלע-תשמא","b":"אחיו של ר דוד בקלויזנבורג."},{"i":14008,"n":"הארקר, צבי הירש הלוי","f":"אברהם","dt":"תקפה","dp":"טבריה","b":"מראשי עדת החסידים שעלו בשנת תקלז, חתם על אגרת החסידים בשנת תקמה. בשנת תקמז בשליחות ברוסיה, חזר לטבריה בשנת תקן, והיה בשליחות נוספת."},{"i":14009,"n":"הארשיץ, טוביה מבייאה","b":"רב בבאייה-תקן על מקום ר יצחק גרוסהאבר שעבר לפאקש ור ישעיהו בן ישראל הכהן על מקומו אחריו."},{"i":14010,"n":"האתמרי, אברהם שלמה","b":"רב באיזמיר-ת\"מ"},{"i":14011,"n":"הבבלי, צבי דן מוילנא","k":"בעל חליפות אגרות","b":"מחכמי וילנא. חיבר גם \"שרש דבר\", \"מפתח למגילת אסתר\"."},{"i":14012,"n":"הבדלה (עבדאללה), רפאל שלמה","k":"בעל מנחת זכרון","bp":"מוריאה-יון","dt":"תץ - ניסן","dp":"ירושלים","b":"חתם שמו \"הבדלה\" וכנראה במקורו היה \"עבדלה\". לאחר שנתייתם עבר לשלוניקי, תלמיד ר חיים יהודה משלוניקי, תלמיד וחתן ר שלמה אמריליו בעל \"כרם שלמה\" (לפי גאון - רבו של ר שלמה ולא תלמידו). מחכמי שלוניקי, גיסו של ר רפאל פנחס מזרחי בעל \"אדמת קדש\". עלה לירושלים-תע. דיין אצל ר אברהם יצחקי בעל \"זרע אברהם\". ראב\"ד בירושלים - ואצלו הדיינים ר ישעיה אזולאי, ור מתתיהו בן רפאל אישפריאל. כמה מפסקיו בספרי חכמי דורו, חיבר גם חיבור על השו\"ע, ושו\"ת. תקנה ממנו מביא החיד\"א - שלא ינשאו בנות פחות מגיל 12. ?? לא באוצר ??","bk":[["מנחת זכרון – שו\"ת וענינים (כת\"י)",""]]},{"i":14013,"n":"הבדלה, משה מירושלים","dt":"תריב - יז חשון","b":"מרבני ירושלים"},{"i":14014,"n":"הבלין, אליהו דוד","b":"תלמיד ישיבת חב\"ד. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":14015,"n":"הבנשטירט, יצחק מרישא","k":"בעל דורש חמורות","bt":"תרס","dt":"תש","b":"מחכמי רישא, נכד ר ישראל הבנשטריט אב\"ד סאנוק. חיבר \"דורש חמורות\" פשמישל תרפא, \"קברות התאוה\" רישא תרפט."},{"i":14016,"n":"הבנשטריט, יהושע מסוקולוב","b":"אב\"ד סוקולוב על מקום אביו."},{"i":14017,"n":"הבנשטריט, יוסף שאול מרוה-רוסקא","f":"שמחה","bt":"תרי","dt":"תרף","b":"נכד ר נתן באבד מיאברוב. חתן ר משולם זושא מלבוב. רב ברוה-רוסקה-תרע על מקום אחיו ר נתן שעבר לטומשוב."},{"i":14018,"n":"הבנשטריט, יעקב בריש מראווה","b":"נכד ה\"ברוך טעם\". חסיד בלז בראווה."},{"i":14019,"n":"הבנשטריט, יצחק מסוקולוב","b":"אב\"ד סוקולוב-תרך, בנו ר יהושע ישב על כסאו אחריו."},{"i":14020,"n":"הבנשטריט, נתן מראווא","f":"שמחה","bt":"תר","dt":"תרעה","b":"דיין ברוהרוסקה, ראב\"ד טומשוב-תרכד, רב בזמושץ, ראב\"ד בפשמישל. ר אברהם באבד שהיה נכדו או חתנו מילא את מקומו אחריו. הו\"ל זוהר מוגה מכתבי יד - פשמישל תרסה."},{"i":14021,"n":"הבנשטריט, שמחה מקרשצינקה","b":"אב\"ד קרשצינה. תשובה אליו \"אמרי רגש\"."},{"i":14022,"n":"הבקינד, אליעזר מאיר","b":"גביר תלמיד חכם בליטא. גיסו של ר חיים עוזר גרודזנסקי."},{"i":14023,"n":"הבר, זאב וולף מפודהייץ","b":"חתן רנ\"נ לייטר בעל \"מאורות נתן\" ובספר הערות ממנו."},{"i":14024,"n":"הבר, זאב וולף מפודהיץ","dt":"תש..","b":"רב בפודהיץ, חתן ר נתן נטע לייטר מלבוב. נספה בשואה."},{"i":14025,"n":"הבר, זאב יהודה","b":"חתן ר יוסף תאומים אב\"ד בורשטין, קלוש."},{"i":14026,"n":"הבר, יחיאל מיכל מסטרליסק","b":"רב בסטרליסק-תרל."},{"i":14027,"n":"הבר, ישראל מטלומטש","b":"אב\"ד טלומטש-תרי"},{"i":14028,"n":"הבר, ישראל צבי מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":14029,"n":"הבר, מרדכי אריה מגוליגור","b":"רב בגאליגור-תר\"ע"},{"i":14030,"n":"הבר, שמאי מקראקא","f":"שמואל","bp":"פודגורוזע","b":"מחכמי קראקא, תשובה אליו \"אמרי דוד\"."},{"i":14031,"n":"הברבנד, אליהו יהושע","b":"פרסם מאמרים ב\"אחיאסף\" - סטריזוב תרפט."},{"i":14032,"n":"הברבנד, קלונימוס קלמיש","b":"עורך \"הכרם\" - וארשא תרפז."},{"i":14033,"n":"הברבנד, שמעון מוארשא ופיעטרקוב","dt":"תשב","b":"חתן ר יעקב זילברשטין (הראב\"ד מפיעטרקוב?). מחכמי פיעטרקוב. תלמיד ישיבת \"דעת משה\" בוארשא. רב בועד הרבנים בוארשא. פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר, פרסם מאמרים ב\"הכרם\" - וארשא תרצא, \"כרמנו\" - אלכסנדר-לודז תרצג. נספה בשואה."},{"i":14034,"n":"הברכה, משה משלוניקי","b":"רב בשלוניקי. נספד ב\"רני ושמחי\" וב\"כסא שלמה\"."},{"i":14035,"n":"הברלנד, אליהו מארה\"ב","f":"ישראל","bt":"תרמב","bp":"וארשא","b":"מצאצאי אדמורי שידלובצה. תלמיד דודו רבה של לימנוב וסלאמניק, ר אברהם בורנשטין בעל \"אבני נזר\", ר מאיר יחיאל הולצשטוק האמדור מאוסטרווצא. נסמך מאת ר יוסף אנגל מקראקא, ומאת דודו. חתן ר יהושע השל בן פנחס פרנקל-תאומים. רב בגרודזיסק, קהלת \"לינת הצדק\" בברלין-תרעה, , היגר לארה\"ב-תרפה וכיהן כרב קהלת זאווידוואסט בניו-יורק-תרץ. חבר אגודת הרבנים באמריקה."},{"i":14036,"n":"הברמן אברהם מאיר","bt":"1901","dt":"ה'תשמא 1981","bk":[["גזירות אשכנז וצרפת",""],["המדפיסים בני שונצינו",""],["נשים עבריות בתור מדפיסות",""],["סתומים וחתומים",""],["שערי חב\"ד",""],["תולדות הספר העברי",""]]},{"i":14037,"n":"הברמן, אורי פיבל מזורובנא","b":"מחכמי זורובנא-תרסא. בנו אברהם מאיר הברמן מגדולי הביבליוגרפים והחוקרים. לזכרו \"יד להימן\" לוד תשמד."},{"i":14038,"n":"הברמן, יצחק מבילגוריי","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":14039,"n":"הברמן, מרדכי אריה מגוליגור","f":"שמחה","k":"בעל מראה החודש","bt":"תרמב","bp":"רווה-רוסקא","dt":"תשה","b":"חתן ר יצחק צבי גסנבויאר מווהנילוב. רב בגוליגור-תרסט, רב בוינה. ברח מהנאצים לארה\"ב וכיהן כרב בברונזוויל. חיבר \"מראה החודש\" ניוארק תשז. ?? לא באוצר ??"},{"i":14040,"n":"הברמן, שמחה מרווה-רוסקה","f":"ישכר","bt":"תרכב","bp":"רווה-רוסקה","dt":"תשג","b":"מחכמי רווה-רוסקה. נספה בשואה. פרסם מאמרים ב\"ועד חכמים\" - יזלוביץ (ועוד) תרנח."},{"i":14041,"n":"הברפלד, אביעזר מאלשא","f":"מרדכי הלוי","bt":"תרמג","dt":"תרצו - כט כסלו","dp":"פרשבורג","b":"תלמיד השב\"ס. חתן ר יונה שיפר מפארינצה. מחכמי אלשא-קובין וסירב לרבנות."},{"i":14042,"n":"הברפלד, אריה מטשארנא","f":"יצחק איזיק מסבאטישט","dt":"תשג","b":"תלמיד הדעת סופר. חתן ר זאב וולף כהנא מטשארנא. רב בטשארנא לצד חותנו ועל מקומו אחריו-תש. נספה בשואה."},{"i":14043,"n":"הברפלד, יעקב הלוי מטשארנא","dt":"תש..","b":"רבה האחרון של טשארנא(=צ'ורנא) וראש ישיבה שם. נספה בשואה."},{"i":14044,"n":"הברפלד, יעקב הלוי מפאפא","f":"משה שמעון צבי מטאפלט","dt":"תשד - יז תמוז","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור יוסף צבי דושינסקי. חתן ר שמואל גוטליב מפאפא. רב קהילה בוינה-תרפו, פאפא-תרצב על מקום חותנו. נספה בשואה."},{"i":14045,"n":"הברפלד, יעקב מטוראלוקא","b":"דומ\"צ בטוראלעקע-תר\"ע, חתן ר דוד שיק מטאקייא."},{"i":14046,"n":"הברפלד, יצחק איזיק מסאבטישט","f":"יעקב מטוראלוקא","bt":"תרכח","dt":"תרפד - כו טבת","dp":"בודפשט - בני ברק","b":"תלמיד השב\"ס, ור משה צבי פוקס מגרוסורדין. חתן ר אליהו קליין מהאלמין ועבר לשם-תרנד. רב בטור-טרבעטש-תרנה, סאבאטישט-תרנז, רב ביהמ\"ד אהל אסתר בבודפשט וחתנו ר משה שיק על מקומו אחריו. חתנו - ר יעקב יוסף שיק רב בבודפשט וסידני (אוסטרליה)."},{"i":14047,"n":"הברפלד, מרדכי אריה מארניאש","f":"משה שמעון צבי הלוי","bt":"תרעג","dt":"תשד","dp":"זאקזנהוזן","b":"תלמיד הדעת סופר. חתן ר שמואל יפה-שלזינגר מארניאש-מארוטה. רב במארניאש-מארוטה על מקום חותנו. נספה בשואה."},{"i":14048,"n":"הברפלד, מרדכי הלוי מברעזאווא","f":"יעקב מטוראלקע","bt":"תרל","bp":"טוראלקע","dt":"תשב-ג","dp":"אושוויץ","b":"תלמיד השב\"ס. דיין בברעזאווא-תרעג. נספה בשואה."},{"i":14049,"n":"הברפלד, משה שמעון צבי מטאפלטשן","f":"יעקב הלוי מטוראלאקע","bt":"תרלז-ם","bp":"טוראלאקע","dt":"תשה - תשרי","b":"תלמיד השב\"ס, ור מרדכי יהודה ליב וינקלר מהעדילא-מאדע ועוד. נסמך מאת השב\"ס. חתן ר יוסף ואלד מקיראל-העלמעץ. רב בלעלעס-תרסד, נאדי-קאוועשעד-תרעג, טאפלטשאן. נספה בשואה. בעל \"ישב מצרף\"."},{"i":14050,"n":"הברקשטן, קלונימוס קלמן מאוסטרה","f":"פנחס מקוריץ","k":"אדמור מאוסטרהא","dt":"יוה\"כ","b":"חתן ר יוסף מאוסטרהא."},{"i":14051,"n":"הברקשטן, קלמן קלונימוס","f":"יעקב","k":"חותן המהרש\"ל","dt":"שח - אחרי","dp":"ירושלים","b":"תלמיד ר דניאל שהיה תלמיד ר איסרל בעל \"תרומת הדשן\". אחד משלושת ראשי הישיבות שהביא בעל צמח דוד (יחד עם ר שכנא ור קלמן ורמייזא. רבו וחותנו של המהרש\"ל. רב בלבוב, אוסטרהא-לפני רעח וחתנו המהרש\"ל על מקומו אחריו, בריסק, עלה לירושלים-שנת ש בערך וכיהן כאב\"ד עדת האשכנזים-שח. פגש את האר\"י - שהיה גם קרובו של חתנו המהרש\"ל. ור חיים ויטל הביא ממנו בספרו \"לקוטי תורה\". בספרו של ר ישראל אלגזי \"שלמי חגיגה\" מסופר על נס שעשה להציל הקהל מעלילת דם. לדעת מרגלית \"סיני\" קנג - אין זהות בין ר קלונימוס חותן המהרשל לבין ר קולנימוס הברקשטן. ראה גם: ר קלונימוס מירושלים (רבה של הקהלה האשכנזית-שח)."},{"i":14052,"n":"הגיסים ר' מרדכי זאב איטינגא ור' יוסף שאול נטנזון","bt":"ר' יוסף שאול תקסח \\ תקע ר' מרדכי זאב בערך תקסה","dt":"ר' יוסף שאול נפטר כז אדר א' תרלה ר' מרדכי זאב נפטר ב' תמוז \\ סיון תרכג","bk":[["מפרשי הים, מאירת עינים - בדיקת הריאה, מגן גבורים - שו\"ע או\"ח, מעשה אלפס - רי\"ף",""],["מאירת עינים - בדיקת הריאה",""],["מגן גבורים - שו\"ע או\"ח",""],["מעשה אלפס - רי\"ף",""],["מפרשי הים",""]]},{"i":14053,"n":"הגנויאר, ברוך מצרפת ואלגיר","f":"בנימין","dt":"תשד","b":"רב בקצמטינא מטעם הקונסיסטואר-תרסא-תרסו. הסכים על \"גן הירק\". בזמן כהונתו נסגרו בעיר \"מדרשים\" (כתות למוד מסורתיות) רבים. נספה בשואה."},{"i":14054,"n":"הגנויאר, פסח מצרפת","b":"רב בבסנסון-צרפת-תרע."},{"i":14055,"n":"הג'ר ן, דוד מגרנדה","k":"בעל דיני הגט","b":"מחכמי ספרד הקדמונים בגרנדה-ד'תתפ, מדקדק, תלמיד הרי\"ף, חיבר \"דיני הגט\", \"ספר המלכים - מאזנים\". נזכר אצל ר אברהם ן עזרא."},{"i":14056,"n":"הגר, אברהם יהושע השל","f":"שרגא פיבוש מזלישטשיק","k":"אדמור מקוסוב","bt":"1755","b":"שרד את השואה. חתן ר יחזקאל שרגא סנדר מדעש. כיהן כאדמור מקוסוב בברוקלין. הו\"ל ספר זקנו \"לקט עני\".","bk":[["אוהב ישראל [תורה]","חסידות"],["אוהב ישראל [ליקוטים]","חסידות"],["אוהב ישראל [ליקוטים חדשים]","חסידות"],["תורת אמת","חסידות"]]},{"i":14057,"n":"הגר, אברהם יהושע השל מדמיטש","f":"יוסף דוד","k":"אדמור מדאמיטש","bt":"תרל","dt":"תשב - ח חנוכה","b":"שמו \"הגר\" כשם משפחת אמו. רב ואדמור בדמיטש על מקום זקנו-ר מנחם מנדל מדאמיטש, רב בזבלטוב. נספה בשואה. הו\"ל ספר זקנו \"צמח דוד\"."},{"i":14058,"n":"הגר, אליעזר מסערט וחיפה","f":"ברוך מסערט","k":"אדמור מסרט-ויזניץ","bt":"תרפה","bp":"גרוסוורדין","b":"חתן ר עוזר ברוין. ניצל מהשואה. עלה לארץ-תשו, אדמור בחיפה על מקום אביו. חיבר \"אגרא דבי הילולא\" חיפה תשלג. מתורתו ב\"אגרא דבי הלולא\"."},{"i":14059,"n":"הגר, אלתר מנחם מנדל מבורשא","f":"פנחס מבורשה","k":"אדמור מבורשה","bt":"תרנז","bp":"ויזניץ","dt":"תשד - כט אייר","dp":"אושוויץ","b":"חתן דודו ר ישראל מויזניץ, ובזיוו\"ש חתן ר אהרן מנחם מנדל מאלסק. רב בבורשה-תרפא בחיי אביו, ואדמור-תשא על מקומו אחריו. ביקר בארץ-תרצה. נספה בשואה. חתנו האדמור מספינקא ר יעקב יוסף וייס. יש דעה שנרצח ב-א כסלו תשג בגיטו סעליש."},{"i":14060,"n":"הגר, ברוך מויזניץ","f":"מנחם מנדל","k":"אדמור מויזניץ","r":"יצא עליו הספר קדוש וברוך","bt":"תרה","dt":"תרנג - כ כסלו","b":"נכד ר ישראל מרוזין. חתן ר אריה ליב שפירא בעל דפוס זיטומיר. אדמור בויזניץ-תרמה. חיבר \"אמרי ברוך\" קולומיה תרעב. בנו ר שלום-חתן ר מנחם מנדל מדאמיטש - נפטר בחיי אביו.","bk":[["אמרי ברוך – עה\"ת",""],["אמרי ברוך (ויז'ניץ)",""]]},{"i":14061,"n":"הגר, ברוך מוישובה","f":"מנחם מנדל","k":"אדמור מוישיוה ויזניץ","bt":"תרסח","bp":"ויזניץ","dt":"תשה - כט כסלו","b":"חתן ר צבי הירש אריה רובין ממישלניץ (רופשיץ) - נכד ה\"דברי חיים\". רב ואדמור בווישיווה(=אויבר ווישווא) על מקום אביו-תשא. עסק בהצלה בתקופת השואה ונתפס ונכלא על זיוף תעודות לפליטים. נספה בשואה. בנו ר נפתלי צבי בארה\"ב."},{"i":14062,"n":"הגר, ברוך מסערט","f":"ישראל","k":"אדמור מסערט-ויזניץ","r":"רב בשימאני - הונגריה","bt":"תרנה","bp":"ויזניץ","dt":"תשכד - ב חשון","b":"רבה של פוליען--ריסקובה-מרמורש-תרפג ופעל לשלום במחלקות חסידי קוסוב וויזניץ, קוצמן-תרפח, סערעט-תרצו ושימש שם רב ואדמור. ניצל מהשואה בעזרת אחיו ר אליעזר האדמור מויזניץ. עלה לארץ-תשז, והקים קריה חסידית בחיפה. חתן ר ישכר דב רוקח אדמור מבלז ואף אחר גירושיו נשארו בקשרים טובים, ובזיווג שני חתן ר אליעזר ניסן הורביץ מדזיקוב (רופשיץ) וצפת. חיבר \"מקור ברוך\" חיפה תשלו. קורותיו בשואה בספר \"חי וברוך\" - \"בעמק הבכא\" מאת ר מנשה מילר - חיפה תשנד.","bk":[["מקור ברוך – עה\"ת ומועדים",""],["מקור ברוך (סערט ויז'ניץ)",""]]},{"i":14063,"n":"הגר, ברוך מקוצמן","f":"יחיאל מיכל מהורדנקא","k":"אדמור מאטיניא","bt":"תרנט","dt":"תשב - יג כסלו","b":"חתן דודו ר שרגא פיבוש מזלישטשיק. אב\"ד קוצמן-בוקובינה - תרצו, רב בטשרנוביץ. ממנהיגי ה\"מזרחי\". ה\"אמרי חיים\" השיאו והכתירו כאדמור מאטיניא."},{"i":14064,"n":"הגר, גרשון מטויסט וארה\"ב","f":"מנחם מנדל מזבלטוב","k":"בעל מנחת הגרשוני","bt":"תרמד או תרמא","bp":"זבלאטוב","dt":"תשיד","b":"נסמך מאת ר שלום מרדכי שבדרון, בעל \"אבן יקרה\" מטשרנוביץ, בעל \"פרי עץ חיים\" מקיטוב. חתן ר זאב הורן. רבה של טויסט(=טאוסט)-תרעב, רב ודיין בוינה וראש ישיבת \"תומכי תורה\", ומראשי תנועת \"אגודת ישראל\", היגר לארה\"ב לפני השואה והתישב בניו יורק. חיבר \"מנחת הגרשוני\" ניו יורק תשט. פרסם מאמרים ב\"רבותינו שבגולה\" - פרשבורג תרעה."},{"i":14065,"n":"הגר, גרשון מפטשניזין","f":"צבי הירש","bt":"תרטו","dt":"תש","b":"רב בפטשניזין-תרנט."},{"i":14066,"n":"הגר, דוד אליעזר מקוסטניץ","f":"משה צבי","b":"רבה של קוסטניץ-בוקובינה - תרן. חתן ר יחיאל מיכל מסטרוזיניץ."},{"i":14067,"n":"הגר, חיים","f":"אלתר מנחם מנדל הגר","dt":"תשג"},{"i":14068,"n":"הגר, חיים בן ציון מסיגט","f":"פנחס מבוארשא","dt":"תשג - כה אייר","b":"אדמור בסיגט על מקום אביו, עם אחיו ר יצחק מאיר. נספה בשואה."},{"i":14069,"n":"הגר, חיים יהודה מאיר מוישובה","f":"מנחם מנדל מוישובה","k":"אדמור מווישעווע","bt":"תרעב","bp":"ויזניץ","dt":"תשכט - יא אייר","dp":"תל אביב","b":"תלמיד בישיבת אביו באויבר-ווישיווה. חתן ר אלעזר ריינמן מביטשקוב. רב בביטשקוב והתגורר ליד אביו בווישווה וסייע לצד אחיו בניהול הישיבה. רב בווישווה על מקום אחיו ר ברוך שהוגלה בידי השלטונות-תשב. ניצל מהשואה ואחריה עבר לשבדיה ולארה\"ב-תשו וכיהן כרב ואדמור מוישיבא בניו יורק, עלה לארץ-תשך והתישב בתל אביב. חיבר \"זכר חיים\" תל אביב תשמא. נפטר ללא ילדים.","bk":[["זכר חיי\"ם",""]]},{"i":14070,"n":"הגר, חיים מאיר מויזניץ","f":"ישראל","k":"אדמור מויזניץ-אמרי ח","r":"האדמו\"ר מויז'ניץ","bt":"תרמח","bp":"ויזניץ","dt":"תשלב - ט ניסן","dp":"בני ברק","b":"חתן ר זאב וולף מרחמיסטריבקא (טשרנוביל). תלמיד דודו האדמור יהושע הורביץ מדזיקוב. אב\"ד וילחוביץ-מארמרוש-תרע ויחד עם זאת ישב רוב הזמן אצל אביו. רב ואדמור בגרוסורדין-תרצו על מקום אביו פתח ישיבה-תשא ובראשה בנו ר משה יהושע - לימים האדמור מויזניץ. ביקר בארץ-תרצה. ניצל בשואה ועבר לאנטורפן-תשז, עלה לארץ וכיהן כאדמור על מקום אחיו ר ישראל. חיבר \"דרשה\" בודפסט תשג, ועוד. בשליחות כמה פעמים באמריקה, והקים שם בתי כנסת ומוסדות תורה וחסידות. חיבר \"אמרי חיים\". בנו ר משה יהושע על מקומו בבני ברק, ובנו ר מרדכי על מקומו במונסי.","bk":[["אמרי חיים – עה\"ת",""],["מכתבי קודש",""],["מכתבי קודש , אמרי חיים – עה\"ת",""],["אמרי חיים (ויז'ניץ)",""],["מכתבי קודש - אמרי חיים","מכתבי תורה חיזוק והנהגות"]]},{"i":14071,"n":"הגר, חיים מזבלטוב","f":"משה מזבלטוב","k":"אדמור מזבלטוב","bt":"תרנג-ט","dt":"תשג - חשון","b":"רב ואדמור בזבלטוב-תרעו. חתן ר צבי הירש אשכנזי מסטניסלב (אלעסק). ביקר בארץ-תרצח. נספה בשואה, והיה האדמור האחרון לבית זבלטוב."},{"i":14072,"n":"הגר, חיים מקוסוב","f":"מנחם מנדל מקוסוב","k":"אדמור מקוסוב","r":"רב דק\"ק ליסא","bt":"תקנה","dt":"תריד - כה אייר","b":"חתן ר יהודה שפירא אב\"ד שפיטיבקה. רב ואדמור בקוסוב על מקום אביו. תכנן לעלות לארץ ואף רכש בית בצפת - אך לא עלה בידו. חיבר \"תורת חיים\" למברג תרטז. חתנו ר ישראל בן מיכל מוישנויבץ. לתולדותיו \"נזר החיים\" לרנ\"א רוט.","bk":[["תורת חיים - עה\"ת",""],["תורת חיים (קוסוב)",""]]},{"i":14073,"n":"הגר, חיים משאץ","f":"משה משאץ","k":"אדמור משאץ","bt":"תרע","dt":"תשלז - כד טבת","b":"חתן ר שלמה זלמינא מראשקוב, ובזיוו\"ש חתן ר שלמה פרוכטר משיעף. רב ואדמור בשאץ. עלה לארץ-תשי והקים בימ\"ד בחיפה, עבר לבני ברק-תשכט."},{"i":14074,"n":"הגר, יהודה זונדל מסטנוביץ וי-ם","f":"יצחק מאיר מסאווראן","k":"בעל רמזי דברים","bt":"תרסו","bp":"סטנוביץ","dt":"תשנג - טז סיון","dp":"ירושלים","b":"תלמיד ר אליעזר גרינוואלד מסטמר בעל \"קרן לדוד\". חתן ר שמואל אהרן שזורי-ובר - מחסיד ללוב, גבאי כולל קוסוב. עלה לארץ-תרפא והיה מראשוני תלמידי ישיבת \"שפת אמת\" והיה מקורב לר יהודה ליב אשלג בעל ה\"סולם\". סירב לאדמורות בסאווראן על מקום אביו. אדמור בבית כנסת שער השמים בקטמון. מבניו ר ישכר דב מירושלים, ר בן ציון, ר יחיאל מיכל, ר אברהם יהושע השיל, ר יצחק מאיר רב בפורזדור ירושלים."},{"i":14075,"n":"הגר, יוסף אלתר מרדוביץ","f":"חיים מקוסוב","k":"אדמור מרדוביץ","bt":"תקף","dt":"תרלט - ח תמוז","dp":"חיפה","b":"חתן ר ישראל-חתנו של ר משה צבי מסאוראן. בשנת תריד אדמור ברדוביץ על מקום אביו, בשנת תרלג עלה לצפת ואחר כך בחיפה, והקים בית מדרש לחסידיו. טבע בים בחיפה ונטמן ליד האמורא רב אבדימי דמן חיפה. מתורתו בספר בנו \"ויקח משה\". אלמנתו הרבנית לאה נפטרה בצפת-י כסלו תרלט , ונקברה בסמוך לקבר האר\"י."},{"i":14076,"n":"הגר, יוסף מטיסמניץ","f":"מנחם מנדל מזבלטוב","bt":"תרלח","bp":"זבלטוב","dt":"תשב","dp":"סטניסלב","b":"חתן ר יצחק קוטן אדמור מטיסמניץ (ברדיטשוב). רב ואדמור בטיסמניץ על מקום חותנו-תרסד. נספה בשואה."},{"i":14077,"n":"הגר, יוסף מרדוביץ","f":"ישראל","bt":"תרסא","dt":"תשמא","dp":"ניו יורק","b":"היגר לארה\"ב-תרעג, וכיהן כרב בניו יורק ומיסד בתי ספר דתיים."},{"i":14078,"n":"הגר, יחיאל מיכל מהורודנקא","f":"ברוך מאטיניא","k":"אדמור מהורודנקא","bt":"תרלב","dt":"תשב - יג כסלו","dp":"טרנסדניסטריה","b":"חתן אחיו ר חיים מאטיניא. אדמור בהורודנקה על מקום אחיו ר שמואל אברהם. עבר לוינה, טשרנוביץ. נספה בשואה. בנו ר ברוך-נספה באותו היום."},{"i":14079,"n":"הגר, יחיאל מיכל מסטרוזיניץ","f":"דוד מזבלטוב","k":"אדמור מסטרוזניץ","bt":"תקפד","dt":"תרסה - יד ניסן","b":"רב ואדמור בסטרוזיניץ. חתן ר אלעזר רוקח מבלז. חיבוריו בכתב יד."},{"i":14080,"n":"הגר, יעקב דוד","f":"מנחם מנדל הגר","b":"רב-שנת תר\"מ"},{"i":14081,"n":"הגר, יעקב יצחק דוד מסטרוזיניץ","f":"ברוך מויזניץ","k":"אדמור מסטרוזיניץ","bt":"תרכו","dt":"תרצב - יג אד\"ב","dp":"וינה","b":"נכד ר מנחם מנדל בעל \"צמח צדיק\", ר חיים מקוסוב בעל \"תורת חיים\". חתן ר יששכר דב איכנשטין מדולינא (זידיטשוב). רב ואדמור בסטרוזיניץ-תרנג, טשודין-בוקובינה, וינה."},{"i":14082,"n":"הגר, יעקב מזבלטוב","f":"דוד מזבלטוב","k":"אדמור מזבלטוב","bt":"תקעג","dt":"תרמא - טו-ז שבט","b":"רב ואדמור בזבלטוב על מקום אביו. חתן ר יהודה צבי איכנשטין מראזלא ובזיוו\"ש חתן ר ישעיה שור מיאסי בעל \"כליל תפארת\". בנו ר מנחם מנדל מילא את מקומו אחריו. מתורתו בספר חתנו \"עטרת יעקב וישראל\"."},{"i":14083,"n":"הגר, יעקב מפשקן יאס","f":"משה צבי מסטנוביץ","k":"אדמור מפשקן ביאס","b":"חתן ר יצחק איזיק טויביש מפשקן. רב בפשקן-תרעא על מקומו אחריו. עבר ליאס-[תש..] וכיהן כאדמור מפשקן ביאס. תשובה אליו - רב\"ז."},{"i":14084,"n":"הגר, יעקב קופל מקולומיאה","f":"נחמיה פיבל","bt":"תץ","dt":"תקמז","b":"חתן דודו ר זלמן אחי אביו. מחסידיו הקרובים של הבעשט שהפקיד בידיו כאזור השפעה את מרמורוש. חי כצדיק נסתר. גיסו הגביר ר שאלתיאל איזיק שטרנהל."},{"i":14085,"n":"הגר, יעקב שמשון מקוסוב","f":"חיים מקוסוב","k":"אדמור מקוסוב","bt":"תקעד","dt":"תרם - יט אדר","b":"חתן הגביר ר דוד שטרנהל מקולומיא, ובזיוו\"ש חתן ר יעקב יוסף מאוסטרהא, ובזיוו\"ש חתן אלמנת ר נחום טברסקי. רב ואדמור בקוסוב-תריד על מקום אביו, ובנו ר משה על מקומו אחריו."},{"i":14086,"n":"הגר, יצחק איזיק מאיר מרנזוב","f":"יוסף דוד","bt":"תרלה","dt":"תשי","b":"חתן ר מנחם מנדל מדמיטש. רב ברוזנוב (ליד זבלטוב). עלה לירושלים אחר השואה-תשט. בנו ר צבי."},{"i":14087,"n":"הגר, יצחק איזיק מברדיטשוב","f":"מנחם מנדל מזבלטוב","bt":"תרל","dt":"תשא - ג אייר","dp":"פיט-הולנד - אנטורפן","b":"רב בברדיטשוב, טלומץ, וינה, בלגיה-ולפי אלפסי נפטר בכפר זאנהאפען-בלגיה, בנו ר ישראל אליהו על מקומו-נספה בשואה."},{"i":14088,"n":"הגר, יצחק מאיר מסאווראן","f":"יהודה זינדל מסאווראן","bt":"תרצא","b":"רב בפרוזדור ירושלים וחבר מערכת אוצר הפוסקים. חתן ר משה אדלר מירושלים (שושלת ללוב). מבניו - ר בן ציון האדמור מזבלטוב, ר ישכר דב אב\"ד בירושלים. חתנו - ר אברהם בידרמן האדמור מללוב."},{"i":14089,"n":"הגר, יצחק מאיר מסאוראן סטנוביץ","f":"משה צבי מסאוראן סטנו","k":"אדמור מסוורן סטנוביץ","bt":"תרכב-ו","dt":"תרפו - כז ניסן","b":"חתן ר ישכר דב באב\"ד אב\"ד בוסק. רב ואדמור מסאווראן סטנוביץ על מקום אביו. מבניו ר יחיאל מיכל בארה\"ב."},{"i":14090,"n":"הגר, יצחק מאיר מסיגט","f":"פנחס מבוארשא","dt":"תשג - כה אייר","b":"אדמור בסיגט על מקום אביו, עם אחיו ר חיים בן ציון. נספה בשואה."},{"i":14091,"n":"הגר, יצחק מטלומטש","f":"מנחם מנדל","bt":"תרסה","dt":"תשד","b":"רבה של טלומטש(=טלומץ)-תרצב. חתן ר יצחק קוטן מטיסמניץ. נספה בשואה."},{"i":14092,"n":"הגר, ישראל מויזניץ -אוהב ישראל","f":"ברוך מויזניץ","k":"אדמור מויזניץ","r":"אדמו\"ר מויז'ניץ","bt":"תרך","bp":"ויזניץ","dt":"תרצו - ב סיון","dp":"גרוסורדין - בני ברק","b":"נכדו של ר ישראל מרוזין. חתן ר מאיר מדזיקוב (רופשיץ) ובזיוו\"ש חתן ר יעקב כהנא אב\"ד חצי-עמר, ובזיוו\"ש חתן ר יעקב אריה ליב מטריסק (טשרנוביל). רב בבידבליא(=בידעוולע)-מרמורוש-תרמה. רב ואדמור בויזניץ-תרנג על מקום אביו ובנו ר חיים מאיר על מקומו אחריו. עבר לגרוסוורדין. מראשי אגודת ישראל. חיבר \"אהבת ישראל\" גרוסוורדין תשג. מתולדותיו ב\"קדוש ישראל\". (ברח מהשלטון ההונגרי שרצה לאוסרו - בגלל התנגדותו להשכלה ועבר לביטשקוב. עוד מבניו: ר מנחם מדוישוי, ר ברוך מסערעט וחיפה, ר שמואל אבא מגרוסורדין.","bk":[["אהבת ישראל",""],["אהבת ישראל - על התורה",""],["אור ישראל (ויז'ניץ)",""]]},{"i":14093,"n":"הגר, ישראל מרדוביץ","f":"משה מרדוביץ","k":"אדמור מרדוביץ","bt":"תרלו","dt":"תש","b":"אדמור ברדוביץ על מקום אביו שעלה לארץ. היגר לניו יורק-תרעג, והקים שם ישיבת \"תורת חיים\", ויסד חברת \"בני ישראל\". בנו ר יוסף שמואל על מקומו אחריו. תרם לבית היתומים בצפת. הו\"ל ספר אביו \"ויקח משה\"."},{"i":14094,"n":"הגר, ישראל שלום יוסף מאטיניא","f":"חיים מאטיניא","k":"אדמור מאטיניא בסטני'","bt":"תרמד","dt":"תשד - יט אייר","b":"רב ואדמור אטיניא בסטניסלב על מקום אביו. חתן דודו ר שמואל אברהם אבא מהורוקודנקא ובזיוו\"ש חתן ר מאיר מדזיקוב. נספה בשואה. כתביו אבדו בשואה נדפס ממנו קונטרס \"נפש ישי\" בתוך ספר אביו \"נמוקי חיים\". בנו ר ברוך שהיה מאורס לבת ר חיים מקוסוב - נספה עם אביו."},{"i":14095,"n":"הגר, מנחם מנדל מאטיניא","f":"חיים מאטיניא","dt":"תש..","b":"חתן ר יצחק מטיסמניץ-נכד \"הדגל מחנה אפרים\" והבעש\"ט. רב באנטניע(=אטיניא)-תרפ. נספה בשואה."},{"i":14096,"n":"הגר, מנחם מנדל מדמיטש","f":"דוד מזבלטוב","k":"אדמור מדמיטש","bt":"תקפז","dt":"תרנד","b":"רב ואדמור בדמיטש (ליד זבלטוב). חתן ר ישראל מליטשניץ (ברדיטשוב) ובזיוו\"ש חתן ר יוסף מדרוהוביטש-נכד ר ברוך ממזבוז."},{"i":14097,"n":"הגר, מנחם מנדל מוישובה","f":"ישראל-אהבת ישראל","k":"אדמור מויזניץ","r":"האדמו\"ר מווישווא","bt":"תרמ-ו","bp":"בדווליא או ויזניץ","dt":"תשא - יג טבת","dp":"קלויזנבורג - בני ברק","b":"חתן דודו ר מרדכי חודורוב מקולומיאה. אב\"ד ויזניץ-תרסח וראש ישיבת \"בית ישראל\" (שהיתה הישיבה היחידה בבוקובינה) בחיי אביו האדמור. גלה עם אביו לגרוסורדין, רבה של אויבר-וישובה-מרמורוש-תרפא על מקום בעל \"קרן לדוד\" שעבר לסטמר והקים ישיבה \"בית ישראל\" ועמד בראשה. אדמור במארמרוש-תרצו אחר פטירת אביו. בשליחות בארה\"ב-תרצו וביקר אצל חותנו שם. בנו ר ברוך הי\"ד על מקומו אחריו, בנו ר חיים יהודה מאיר ניצל מהשואה והגיע לארה\"ב, ועלה לארץ. הו\"ל עם תלמידיו ירחון תורני \"דגל התורה\". חיבר \"שארית מנחם\" בני ברק תשלד, ועוד.","bk":[["שארית מנחם – עה\"ת ותהילים",""]]},{"i":14098,"n":"הגר, מנחם מנדל מוישובה","f":"נפתלי","k":"הו\"ל אבן שתיה","bt":"תרנה","bp":"וישובה","dt":"תשח","dp":"ירושלים","b":"נכד רא\"ק פרלשטיין. עלה לארץ-תרצו עם אביו. נהרג במלחמת השחרור מפגז. הוציא לאור את ספר קרובו ר חיים כהנא \"אבן שתיה\" לתולדות צדיקי השושלת."},{"i":14099,"n":"הגר, מנחם מנדל מוישובה","f":"אברהם חיים","dt":"תרעה","dp":"אובר-ווישא","b":"חתן ר יהודה אריה פרוכטר מאובר-ווישא."},{"i":14100,"n":"הגר, מנחם מנדל מזבלטוב","f":"יעקב מזבלטוב","k":"אדמור מזבלטוב","bt":"תר","dt":"תרע","b":"רב ואדמור בזבלטוב על מקום אביו (היה בנו יחידו). חתן ר יצחק ליבוש טויב אב\"ד חאטין ויאסי. חתניו ר ישראל ברגר, ר יואל בלומנפלד, ר מאיר מנאויסליץ בן שמשון מלשקוביץ (זבאריז)."},{"i":14101,"n":"הגר, מנחם מנדל מלינסק","b":"רב בלינסק"},{"i":14102,"n":"הגר, מנחם מנדל מניישטט","f":"דוד אליעזר מקוסטניץ","k":"בעל מנחם אבלים","bt":"תרמט","bp":"קוסטשטיה","dt":"תשטו","b":"חתן ר אלעזר רוקח מלוביטש, ראב\"ד בהליטש, שירת כרב צבאי במורביה. רב בניישטט-תרפג וסוסנוביץ. מראשי המזרחי. עלה לארץ-תשג, רב בתל אביב. חיבר \"מנחם אבלים\" תל אביב תשי, ועוד. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו, \"ירושלים\" - וארשא תרצו."},{"i":14103,"n":"הגר, מרדכי ממונסי","f":"חיים מאיר","bt":"תרפב","bp":"ויזניץ","b":"תלמיד ר יואל טיטלבוים בסאמר, ור יוסף גרינוולד בפאפא. חתן ר יעקב יוסף טברסקי מסקווירא (טשרנוביל). הגיע לארה\"ב אחרי השואה. רב ואדמור מויזניץ בניו יורק, הקים קהלה במונסי."},{"i":14104,"n":"הגר, משה יהושע מוילחוביץ","f":"חיים מאיר מויזניץ","k":"אדמור מויזניץ","bt":"תרעו","bp":"גרוסורדין","b":"תלמיד דודו ר אליעזר הגר בויזניץ. רבה האחרון של וילחוביץ-תרצו על מקום אביו שנתמנה לאדמור מויזניץ. רב וראש הישיבה בגרוסורדין-תשא. חתן ר מנחם מנדל פאנט מדעש. עלה לארץ-תשד וכיהן כראש ישיבת ויזניץ בתל אביב ובני ברק אצל דודו האדמור בעל \"דמשק אליעזר\". אדמור מויזניץ-תשלב על מקום אביו. בניו ר ישראל, ר מנחם מנדל, חתנו ר מנחם ארנסטר-ראש ישיבת בית ישראל."},{"i":14105,"n":"הגר, משה מאטיניא","f":"ברוך בן יחיאל מיכל","k":"אדמור מאטיניא בב\"ב","bt":"תרפט","b":"נכד ר יחיאל מיכל מהורודנקא. חתן ר אריה ליב הלוי. אדמור מאטיניא בבני ברק וראש ישיבת \"טל חיים ונפש ישי\"."},{"i":14106,"n":"הגר, משה מויזניץ","f":"ישראל בן ברוך מויזני","bt":"תרם","b":"ר\"מ בישיבת ויזניץ-תרסח אצל אביו. נסמך מאת: ר מהרש\"ם מברעזן, ר בנימין אריה וייס מטשרנוביץ."},{"i":14107,"n":"הגר, משה מזבלטוב","f":"מנחם מנדל מזבלטוב","bt":"תרך","dt":"תרעו","dp":"וינה","b":"רב בזבלטוב-תרסו על מקום אביו עוד בחיי אביו. בנו ר חיים על כסאו אחריו והיה הרב האחרון של זבלטוב. עבר לוינה-במלחה\"ע ה-I."},{"i":14108,"n":"הגר, משה מסרעט","f":"ברוך מסערט","r":"ראש ישיבת סערט ויז'ניץ","bt":"תרפו","bp":"גרוסורדין","dt":"תשנט","dp":"ניו יורק","b":"חתן ר חיים מנחם דוד מדזיקוב (רופשיץ). ניצל מהשואה, עלה לארץ-תשו עם אביו אחר השואה. ראש ישיבת ויזניץ בחיפה. לזכרו \"זכרון משה\" - מאמרים ממנו ועליו - חיפה תשס.","bk":[["ברכת משה - על התורה",""]]},{"i":14109,"n":"הגר, משה מצונטג","dt":"תרצו - טו אייר","b":"רב הכולל בצונטג-בוקובינה"},{"i":14110,"n":"הגר, משה מראדוביץ","f":"יוסף אלתר מראדוביץ","k":"בעל ויקח משה","bt":"תר","dt":"תרסב - א כסלו","dp":"צפת","b":"רב ואדמור בראדוביץ-תרלג על מקום אביו שעלה לצפת, ביקר אצל אביו ולבסוף עלה לארץ התישב בחיפה והיה מחיה הישוב האשכנזי בה, ואחר כך עבר לצפת. חיבר \"ויקח משה\" מונקטש תרסז. ?? לא באוצר ??","bk":[["ויקח משה",""]]},{"i":14111,"n":"הגר, משה משאץ","f":"ברוך מויזניץ","k":"אדמור מויזניץ בשאץ","bt":"תרכג","bp":"ויזניץ","dt":"תרפו - טו אייר","b":"נכד בעל \"אמרי צדיק\" וגדל אצלו. חתן ר אברהם יהושע השל ממזיבוז (אפטא). אדמור בגורא-הומורא, עבר לשאץ. נודע כבעל תפלה ומנגן."},{"i":14112,"n":"הגר, משה צבי מסטנוביץ","f":"ברוך","k":"אדמור מסטנוביץ","bt":"תרב","dt":"תרנו - כט טבת","b":"חתן ר יוסף מטיבריב(=טבריוב) (ברדיטשוב), ובזיוו\"ש חתן הגביר ר שמעון רפפורט. גדל אצל זקנו ר דוד מזבלטוב, ואצל אביו חורגו ר יוסף באב\"ד בעל מנחת חינוך\". קרובו האדמור ר מנחם מנדל מויזניץ הכתירו לאדמור בסטנוביץ."},{"i":14113,"n":"הגר, נפתלי צבי מוישובה","f":"ברוך","bt":"תרצא","bp":"וישובה","dt":"תשס","dp":"מונסי","b":"תלמיד פאפא. ניצל מהשואה - שריד יחיד למשפחת רבני אויבר ווישווא, היגר לניו יורק-תשו. הקים בתי מדרש \"ווישווא\" בבני ברק ובירושלים. בניו - ר ברוך רב וראש כולל וישובה בירושלים, ר יצחק רב \"וישובה\" בארה\"ב."},{"i":14114,"n":"הגר, פיבוש מזלישטשיק","dt":"תשג","b":"רב בזאלושטשיק"},{"i":14115,"n":"הגר, פנחס מבורשה","f":"ברוך מויזניץ","k":"אדמור מבורשה","bt":"תרכז","dt":"תשא - יג אדר","dp":"סיגט - בני ברק","b":"חתן דודו ר שמואל רוקח מסקול - בן האדמור מבלז. אדמור בבורשה-תרנג, אויבר וישובה, סיגט-תרפז, ובנו ר אלתר מנחם על מקומו אחריו. כתביו אבדו בשואה. בנו ר חיים בן ציון. מתורתו ב\"מאור החיים\"."},{"i":14116,"n":"הגר, צבי הירש מפיטשניזין","f":"דוד מזבלטוב","bt":"תקפה","dt":"תרנז - יג חשון","b":"רב ואדמור בפיטשניזין-תרך ובנו ר גרשון על מקומו אחריו, חתן ר אברהם חיים הורביץ מלינסק ובזיוו\"ש חתן הגביר ר דוד שטרנהל מקולומיאה (גרושתו של ר יעקב שמשון מקוסוב)."},{"i":14117,"n":"הגר, צבי מירושלים","f":"יצחק איזיק מאיר","bt":"תרסז","dt":"תשסג","dp":"ירושלים","b":"נכד אדמורי אפטא. עלה לירושלים-תרצה והתגורר בשערי חסד. חתן ר חיים בן ציון קליבנסקי."},{"i":14118,"n":"הגר, שלום מבנילוב","f":"יחיאל מיכל מסטרוזניץ","bt":"תרל","dt":"תשי - יד סיון","dp":"לונדון - תל אביב","b":"רבה של מאלד-באנילה (בנילוב-בוקובינה). עבר מבנילוב לסטרוזיניץ-תרסה. ניצל מהשואה - ברח ללונדון. בניו ר אלעזר מלונדון, ר יחיאל מיכל."},{"i":14119,"n":"הגר, שמואל אבא מויזניץ","f":"ישראל-אהבת ישראל","bt":"תרנח","dt":"תש","dp":"גרוסורדין","b":"בנו הצעיר של האדמור מויזניץ. חתן דודו ר משה משאץ."},{"i":14120,"n":"הגר, שמואל אברהם אבא מהורודנקה","f":"ברוך מויזניץ","k":"בעל שפתי צדיק","bt":"תרכה","bp":"ויזניץ","dt":"תרנה - כט ניסן","dp":"הורודנקא","b":"חתן ר משה מרדכי טברסקי ממקרוב (טשרנוביל). חיבר שירים. אדמור בהורודנקא-תרנג. חיבר \"שפתי צדיק\" קאלאמעא תרנו."},{"i":14121,"n":"הגר, שמואל מוינה","f":"גרשון","bt":"תרסג","dt":"תשג","b":"חתן האדמור מסמבור. רב בוינה. נספה בשואה. פרסם מאמרים ב\"קבוצי אפרים\" - יאסי-בוקרשט תרעד, \"המגיד\" - סטמר תרפח-תרצט, \"תלפיות\" - טרנוב תרצח."},{"i":14122,"n":"הגר, שרגא פיבוש","f":"ברוך","dt":"תשג","b":"נכד ר מנחם מנדל בעל \"צמח צדיק\", ונכד ר חיים מקוסוב בעל \"תורת חיים\". מצאצאי ר ישראל מרוזין. רב בזאלישטיק(=זלישטשיק)."},{"i":14123,"n":"הגר, שרגא פיבוש מזלישטשיק","f":"ברוך מויזניץ","bt":"תרל","dt":"תרצז - יג טבת","dp":"ויזניץ","b":"חתן ר חיים מנחם מזינקוב (אפטא), ובבזיוו\"ש חתן ר משה הגר מקוסוב. רב בזלישטשיק-תרנז, טשרנוביץ."},{"i":14124,"n":"הגר-אדלר-הורביץ, צירל","f":"אליעזר ניסן מצפת","b":"בזיוו\"ר אשת ר מרדכי אדלר, ובזיוו\"ש אשת האדמור ר ברוך מסערט ויזניץ. בנה מזיוו\"ר - ר נפתלי חיים אדלר, ומיזו\"ש - האדמור מסערט ויזניץ חיפה."},{"i":14125,"n":"הגר-הורביץ, יהודה מדזיקוב י-ם","f":"אלטר יחזקאל אליהו","k":"אדמור מדזיקוב בי-ם","r":"רב בגרוסוורדין, ואח\"כ במנתשסטר ובסוף ימיו גאב\"ד העדה החרדית בירושלים","bt":"תרס או תרסה","bp":"דזיקוב","dt":"תשמט - יא סיון","dp":"לונדון","b":"אביו היה האדמור מדזיקוב. תלמיד ר מאיר אריק מטורנא. התחנך אצל סבו האדמור- אוהב ישראל מויזניץ. חתן דודו ר חיים מאיר הגר מגרוסורדין-ויזניץ. רב בקלויזנבורג. עלה לארץ והתישב בתל אביב ועבר לירושלים-תשה ושימש ר\"מ בישיבת \"תרביצא\" וסירב לשמש כאדמור מדזיקוב אך בסוף ימיו קיבל פיתקאות. הכין לדפוס \"יהודה מחקקי\" - גליונות מהר\"י ו\"אמרי יושר\" - הגהות ר\"מ ארק על המשנה - ניו יורק תשן. ספרים שחוברו עליו - \"בית יהודה\" ממרדכי גנוט, \"וזאת ליהודה\" - ירושלים תשמט, \"כבתה השלהבת\" - ירושלים תשן.","bk":[["גליוני מהר\"י - גליונות הספרים",""],["זכרון יהודה",""],["יהודה מחוקקי",""],["משנת יהודה - אבות",""],["משנת יהודה - אבות , גליוני מהר\"י - גליונות הספרים , זכרון יהודה , יהודה מחוקקי",""]]},{"i":14126,"n":"הגרמן, יצחק יהודה מזארנווצה","f":"משה יואל מטשיזאווע","bt":"תרכה","b":"חתן ר אלכסנדר זיסקינד ליפשיץ מאוזרקוב. רב בזרנובצה(=זארנאווצע)-פלך קיעלץ-תרנד."},{"i":14127,"n":"הגרמן, משה יואל מיוזפוף","k":"בעל שי למורא","dt":"תרנד","b":"נכד הרב מסלאויטיש-גיסו של ר ליב מקאוולי בן מהר\"ם מנעזשכיז. תלמיד האדמור בעל חדושי הרי\"ם. רב בציזיבה(=טשיזאווע)-תרלח, זרנובצא-תרמו, יוזפוף. חיבר גם \"ראשית דעת\". חתנו - ר אהרן אלתר סטשבסקי מסקאלמירז."},{"i":14128,"n":"הגרשוני, בנימין הכהן ממרוקו","b":"מחכמי מרוקו-שנות ה-ת'."},{"i":14129,"n":"הגרשוני, חיים הכהן ממרוקו","f":"בנימין","b":"מחכמי מרוקו-שנות ה-ת'."},{"i":14130,"n":"הדאיה, חיים רחמים","b":"מחכמי חברון, בשנת תקצט חתם על אגרת שליחות ר מנחם בורלה ור יוסף אליקים"},{"i":14131,"n":"הדאיה, יצחק מאר\"ץ","f":"שלום","bt":"תרמח","bp":"אר\"ץ","dt":"תשכב - ו אלול","dp":"ירושלים","b":"רב באר\"ץ, עלה לירושלים-תרצה ועסק בקבלה. חיבר דרושים על התורה בכת\"י."},{"i":14132,"n":"הדאיה, עובדיה מירושלים","f":"שלום","k":"בעל ישכיל עבדי","r":"חבר מועצת הרבנות הראשית ובית הדין הגדול","bt":"תרן","bp":"חלב","dt":"תשכט - כ שבט","b":"נכד ר מרדכי חיים לבטון בעל \"נכח השלחן\". עלה לארץ בילדותו עם אביו. תלמיד ת\"ת \"דורש ציון\", תלמיד המקובל ר שלום בוחבוט. מחברי \"בית אל\" ומגדולי המקובלים בירושלים, ר\"מ בישיבת \"פורת יוסף\". רב בפתח תקוה-תרצט. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ, \"כרם ציון\" - ירושלים תשכג - קובץ \"מדרש בני ציון\", \"הפוסק\" - תל אביב תש-תשיד.","bk":[["ישכיל עבדי","שו\"ת - אחרונים"],["דע\"ה והשכל – שו\"ת בקבלה",""],["ויקח עבדיהו – דרשות",""],["ישכיל עבדי – שו\"ת",""],["עבד המלך – רמב\"ם",""],["עבדא דרבנן - ש\"ס",""],["שלום וצדק – עץ חיים",""],["שלום עבדו – עה\"ת",""],["דע\"ה השכל",""],["ודובר שלום (שו\"ת)",""],["ישכיל עבדי (א",""]],"e":"תר\"נ-תשכ\"ט"},{"i":14133,"n":"הדאיה, שלום מחלב וירושלים","f":"משה חיים","k":"בעל שלום לעם","bt":"ה'תרכד-ז","dt":"ה'תשה","b":"מקובל מחכמי חלב, וחתם לפעמים \"עבד אל ואחד\". תלמיד ר משה סואיט, בכור מזרחי, ר יעקב אלפייה. חתן ר יצחק בן כלפון לבטון. ביקר בירושלים-תרן, ועלה לירושלים-תרנט, וכיהן כדיין, ראב\"ד, וזקן המקובלים ב\"בית אל\". התכתב-תרצו עם ר אלחנן וסרמן בתורת הסוד. חיבר גם \"ודובר שלום\" ועוד. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ, \"תורה מציון\" - ירושלים תרנה-תרסה.","bk":[["שלום לעם",""],["ודובר שלום [שו\"ת]",""],["ודובר שלום",""]]},{"i":14134,"n":"הדה, עוזר","b":"חכם השלם בנגלה ונסתר,מגדולי חכמי קושטא-תק\"י"},{"i":14135,"n":"הדמרי, חואתי מגרבה","b":"פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו."},{"i":14136,"n":"הדמרי, פרג'י מתונס","k":"בעל ראש פנה","dt":"תרסג - יג ניסן","dp":"אלחאמה-תונס","b":"רב באלחאמה שליד גאבס-תונס. תלמיד ר אברהם עלוש. חיבר גם \"פדה בשלום\"."},{"i":14137,"n":"הדס, אהרן מפיקלן","b":"גביר חובב תורה מפיקלן(=פיקלין)-פלך קובנא, חתניו היו גדולי תורה ובהם ר אריה ליב פרומקין"},{"i":14138,"n":"הדס, יקותיאל איסר מליטא וירושל","bt":"תרט","dt":"תרפה - ג כסלו","dp":"ירושלים","b":"מחכמי פיקלין-פלך קובנא, רב במיישד(=מיסיאד), עלה לירושלים. חברו של ר אריה ליב פרומקין."},{"i":14139,"n":"הדס, שלמה מירושלים","b":"מחכמי ירושלים, בשנת תצז חתם על תקנה של ר אליעזר נחום בעל \"חזון נחום\"."},{"i":14140,"n":"הדפני, אברהם השומרוני משכם","f":"יעקב","b":"מחכמי השומרונים בשכם-תק. חיבר ספר על קורות המאורעות בשכם בזמן דהר בן עומר."},{"i":14141,"n":"הוברמן, יצחק מרעננה","k":"אדמור מרעננה","bt":"תרנג-ו","bp":"פולין","dt":"תשלז - יב טבת","b":"תלמיד ר יעקב מרדכי מבילגורי, ר אברהם מסוכטשוב, ורצ\"ה גליקזון-חתן ר חיים מבריסק. בזמן השואה היה בסיביר, ואחריה רב בוצלר-גרמניה כ-6 שנים, עלה לארץ-תשי והתישב ברעננה, ונתפרסם כאיש מופת. חיבר \"בן לאשרי - ברכה המשולשת\".","bk":[["ברכה משולשת",""]]},{"i":14142,"n":"הובשה, חיים אהרן","bp":"שקוד"},{"i":14143,"n":"הובשה, יחיאל מיכל","k":"בעל וימת שמואל","bt":"תרה","bp":"קלם","dt":"תרעז","b":"תלמיד ישיבות ליטא. רב בפארנו-אסטוניה-תרלב, שקוד-תרם או תרע, סירב להצעה לכהן כרב בלונדון. פרסם מאמרים בעתוני הזמן ובהם \"הצפירה\", \"העברי\", ועוד. חיבר גם \"מיכל המים\", בבל\" - הפירוש הנכון לספר הספרים כנגד ספרו של דליטש \"ביבל אונד בבל\". בניו ר אהרן משקוד, ראובן צבי מלטביה -נפטר בגלות סיביר."},{"i":14144,"n":"הודיה הנשיא ממצרים","f":"ישי","b":"מחכמי מצרים, מזרע הנשיאים, בדורו של ר' אברהם הנגיד בן הרמב\"ם, עמד במחלוקת עם ר' יוסף בן גרשון"},{"i":14145,"n":"הודס, יואל זוסמן מבלפסט","f":"שלמה זלמן","bt":"תרל","b":"תלמיד ר מאיר מעראליא. נסמך מאת: ר מרדכי ליכטנשטין מטסלן-קורלנד, ר יצחק יעקב ריינס. רב בבלפסט-תרסו. חיבר ספר על התפילות - באנגלית."},{"i":14146,"n":"הודס, יעקב","f":"אליעזר ישראל","bt":"1886","bp":"ואינוטה-ליטא","dt":"1961","dp":"ירושלים","b":"היגר בילדותו עם משפחתו לאנגליה. תלמיד ד\"ר דרטנהיים-יהודי בן תורה מגרמניה. פרסם בעתוני אנגליה יהודים וכלליים. עורך המוסף האידי של \"ג'ואיש וורלד\" - בו השתתפתו גם \"שלום עליכם\" ושלום אש. עלה לארץ-1945, עורך \"ציון\"."},{"i":14147,"n":"הוזיגר, שמעון מרופשיץ","dp":"ניו יורק","b":"רב ברופשיץ, עבר לארה\"ב לפני מלחמת העולם הראשונה. פרסם מאמרים ב\"פרח הלבנון\" - וארשא תרעח."},{"i":14148,"n":"הוטנר, בנימין","b":"רב בהורודק"},{"i":14149,"n":"הוטנר, יהודה ליב (הרץ מנדל)","f":"יוסף זונדל הוטנר","bt":"תרל (תרלז)","dt":"תרפז (תרצה)","b":"רב בטלוטש, רב באיישישוק, מו\"צ בוארשא. פרסם מאמרים ב\"פרח הלבנון\" - וארשא תרעח."},{"i":14150,"n":"הוטנר, יוסף זונדל","f":"חיים","k":"בעל חבל יוסף","r":"רב בדרעטשין ואיישישוק","bt":"תרו","bp":"דוינסק","dt":"תרעט","b":"למד בביאליסטוק יחד עם ר מאיר שמחה בעל \"אור שמח\". סירב לרבנות דוינסק והעבירה לבעל \"אור שמח\". רב בדראצין(=דראטשין)-תרמא, איישישוק-תרנז ור שמעון רוזובסקי על מקומו אחריו. חיבר גם \"בכורי יוסף\", \"אולם המשפט\", \"חדרי דעה\", ועוד. החפץ חיים כבדו מאוד וביקש ממנו ברכה באמצעות שליח והוא בירך את החפץ חיים שיזכה \"ללכת יחף ולסחוב אבנים\" (שיהיה כהן גדול וישא את אבני החשן) ועל זה אמר החפץ חיים שמספיקה לו הברכה הראשונה (שיהיה כהן הדיוט). הסכים על \"לקוטי הלכות\" לבעל \"חפץ חיים\". חיבר גם \"ביכורי יוסף\", ועוד.","bk":[["בכורי יוסף","מערכות"],["בכורי יוסף – ענינים",""],["חבל יוסף אולם המשפט – חו\"מ",""],["חבל יוסף גנזי חיים – או\"ח",""],["חבל יוסף חדרי דעה – יו\"ד",""],["חבל יוסף חוקי העזרה – אה\"ע",""],["אולם המשפט",""],["חבל יוסף וגנזי חיים",""],["גנזי חיים - חבל יוסף","שו\"ע אורח חיים"],["אולם המשפט","מפרשי שו\"ע"]],"e":"תר\"ו-תרע\"ט"},{"i":14151,"n":"הוטנר, יצחק מניו יורק","k":"בעל פחד יצחק","b":"ראש ישיבת רבי חיים ברלין בניו יורק. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":14152,"n":"הוטנר, מנחם מנדל ממינסק","f":"בנימין","bp":"אוזדא","dt":"תרנח - יז טבת","b":"רב ברובינישוק, פרעספא, הקאסארין, מחכמי מינסק, חובב ציון ויסד אגודת האלף במינסק, עלה לארץ-תרן. חתנו - ר צבי זלמן האנף מסלעפיאנקא."},{"i":14153,"n":"הוטנר, נפתלי מנחם מאיישישוק","b":"מחכמי איישישוק. חתנו - ר מאיר חדש - ר\"מ בישיבת חברון."},{"i":14154,"n":"הוטרר, שאול מאושפיצין","f":"אברהם מקטוביץ","k":"בעל ימי שאול בכתובים","bt":"תרף","b":"מחסידי בובוב. ניצל מהשואה ועבר לאנטורפן. מוציא לאור של כתבי יד. חיבר \"ימי שאול בכתובים\" - זכרונותיו באידיש - ניו יורק תשס."},{"i":14155,"n":"הויברגר, אברהם יוסף מקשאנוב","f":"אהרן","bt":"תרף","bp":"קשנוב","dt":"תש..","b":"תלמיד ישיבת בובוב, נספה בשואה. תשובה אליו \"מנחת יחיאל\"."},{"i":14156,"n":"הויזדורף חיים אליעזר בן עזריאל זליג","bt":"1864","dt":"ה'תש 1940","bk":[["הלכות ומנהגי ערב פסח שחל להיות בשבת",""],["יקרא דחיים",""]]},{"i":14157,"n":"הויזדורף, אלעזר","f":"מרדכי","b":"חיבר תשובה בענין קבורת אינו ישראל בקבר ישראל - ליפציג תרמד."},{"i":14158,"n":"הויזדורף, חיים אליעזר מירושלים","f":"עזריאל זליג","k":"בעל מנהגי ערב פסח","b":"חתן ר יושע בצלאל קנטרוביץ בעל \"חינוך בצלאל\" וחיבר הקדמה לספר חותנו בשם \"חנוכת הבית\". עסקן מחכמי ירושלים, בשליחות הקהלה."},{"i":14159,"n":"הויזדורף, חנוך מניו יורק","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":14160,"n":"הויזדורף, מיכאל שאול מרוטרדם","bt":"תריד","dt":"תש","b":"רב ברוטרדם. חיבר פירוש בסדר א-ב על פי פירושי הרב הירש לנביאים."},{"i":14161,"n":"הויזדורף, עזריאל זליג מירושלים","b":"פרסם מאמר ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז - על בית המדרש \"בית אל\" בירושלים. חתם-תרכב עם ראשי הכוללות בירושלים על כתב שליחות ר נתן נטע נאטקין."},{"i":14162,"n":"הויזמן, אשר מטיסמניץ","b":"רב בטיסמניץ, תשובות אליו \"בר ליואי\"."},{"i":14163,"n":"הויזמן, גרשון מסטרי","b":"מחכמי סטרי, תשובה אליו ב\"כוכב מיעקב\" לפני תרנד."},{"i":14164,"n":"הויזמן, יצחק מרישא","b":"מחכמי רישא, ממשתתפי \"אהל מועד\"-תרנט. היה בירוסלב ומשם הפיץ את הספר \"אות זכרון\" לרא\"ב קלוגר."},{"i":14165,"n":"הויזמן, שמעון מחברון","b":"מראשי חסידי חב\"ד בחברון-תרן."},{"i":14166,"n":"הויזן, ישראל מאלטונא","f":"יוקל","bt":"תפח","bp":"אלטונא","dt":"תקסד - כ תמוז","dp":"אלטונא","b":"תלמיד ר אפרים הקשר. גביר מחכמי אה\"ו. מתומכי היעב\"ץ בזמן המחלוקת עם ר יונתן איבשיץ. חיבר חדושים על הש\"ס. משפחתו עברה לקופנהגן. בנו - ר מאיר."},{"i":14167,"n":"הויזן, מאיר מאה\"ו","f":"ישראל מאלטונא","dt":"תקסח - כב אב","dp":"אלטונא","b":"חתן ר צבי הירש-אב\"ד ברלין. פרנס מחכמי אה\"ו."},{"i":14168,"n":"הויזר, אברהם מפשמישל","f":"משה","b":"מוהל מפשמישל-תרע. נכד ר מנחם מנדל הויזר מרוזלא."},{"i":14169,"n":"הויזר, מנחם מנדל מבוריסלב","b":"גביר בבוריסלוב - התעשר בברכת אורחו המהרי\"א מזידיטשוב. מימן הדפסת מדרש רבה עם פירוש מהרי\"א."},{"i":14170,"n":"הויזר, משה מגלינא","k":"בעל עת ספוד","b":"חסיד ר ישראל לנגנר האדמור מרוהטין בברודי. דרשן נודד מגלינא שעבר לברודי-תרנט. חיבר \"עת ספוד\" דרוהוביטש תרנט. (דב סדן מספר עליו בספרו \"ממחוז הילדות\"."},{"i":14171,"n":"הויזר, שמואל מפרשבורג","b":"ממיסדי ביה\"ס בפרשבורג-תקף כנגד דעת החרדים."},{"i":14172,"n":"הויסינסקי, יצחק אברהם מסטאויטש","f":"ישראל מסטאויטש","bt":"תריז","b":"תלמיד דודו ר רפאל הויסינסקי. רב בסטאוויטש-תרמג על מקום אביו וזקנו. בנו - ר ניסן מטולנא, חתניו: ר זליג טוניצקי, ר דב בר טשרני, ר אריה יהודה ספקטור מזשייאטהעוו."},{"i":14173,"n":"הויסינסקי, ניסן","b":"רב בסטאוויטש"},{"i":14174,"n":"הויסנסקי, יצחק","f":"ניסן היסנסקי","b":"רב בסטאוויטש-תק\"פ"},{"i":14175,"n":"הויער, בנימין מגרוסורדין","k":"בעל עת לדבר","dt":"תרפו - ו סיון","dp":"גרוסורדין","b":"מחכמי גרוסורדין, עסק בגמ\"ח ובצרכי ציבור. חיבר קונטרס \"עת לדבר\" קלויזנבורג תרע - בדבר המחלוקת בענין משקה הסליבוביץ (נזכר אצל אבראהאם). ר משה הויער נזכר ב\"קול יעקב\" ואולי היה בנו של ר בנימין. ?? לא באוצר ??"},{"i":14176,"n":"הויפט, יעקב ממונקטש","dt":"תרם.","b":"תלמיד הכת\"ס, ור שמואל שמלקא קליין מסעליש, ור מאיר פרלס מקראלי. מחכמי מונקטש-תרכו. נפטר צעיר. רשם תורת רבו בכת\"י."},{"i":14177,"n":"הוך, יהודה ליב מהכינגן","k":"בעל מנחת יהודה","bt":"תקי","dt":"תקף","b":"תלמיד הנודע ביהודה, וחברו של בנו ר שמואל סגל לנדא. רב בהכינגן, ראש בית המדרש קול יעקב. בספרו הביא תשובות שהשיב לנפוליאון כחבר בסנהדרין."},{"i":14178,"n":"הוכבוים, משה מקשאנוב","b":"מחכמי קשאנוב ומגיד שיעור. נספה בשואה."},{"i":14179,"n":"הוכברג, אריה יהודה ליב מטופרוב","f":"אברהם","k":"בעל פני אריה","bt":"תרם","dt":"תרץ","b":"חתן ר לוי מונטנר מבלז בעל \"בית לוי. מו\"צ בטופרוב-תרסט, ואחר כך בסקול. נסמך מאת: ר אריה ליב מסטניסלב, בעל \"דרך המלך\", מהרש\"ם מברזען, הרי\"ש מלבוב. פרסם מאמרים ב\"שערי חכמה\" - אוזרוב תרפד."},{"i":14180,"n":"הוכברג, בנימין","dt":"תשג","b":"רב בקלצק"},{"i":14181,"n":"הוכברג, דוד משה"},{"i":14182,"n":"הוכברג, חיים ברוך מקרופיטש","f":"דוד משה","bt":"תרכה","bp":"גלינא","dt":"תרפט","b":"חתן ר יחיאל מיכל היבנר מניזנוב בעל \"משכנות הרועים\". רב בקרופיטש-תרמו, ניזנוב-תרסז על מקום חותנו."},{"i":14183,"n":"הוכברג, יוסף מחודרוב","dt":"תש..","b":"משגיח בישיבת חכמי לובלין. חתן הרב מזוולין. נספה בשואה."},{"i":14184,"n":"הוכברג, יעקב מקרעניץ","b":"רב בקרעניץ. תשובה אליו \"מנחת יחיאל\"."},{"i":14185,"n":"הוכברג, יקותיאל זושא מגלינא","f":"אברהם","bt":"תרן","dt":"תרצז","dp":"למברג","b":"רב בגלינא, תלמיד חבר למהר\"ם שפירא."},{"i":14186,"n":"הוכברג, רפאל יחזקאל מגלינא","f":"דוד משה","k":"בעל מראה יחזקאל","bt":"תרלא-ג","bp":"גלינא","dt":"תשב","b":"רב בזידיטשוב-תרנז, גלינא-תרעא. נפטר ללא בנים. חיבר \"מראה יחזקאל\" בילגוריא תרצז. ?? לא באוצר ??"},{"i":14187,"n":"הוכברג, שמואל מרדכי מניזנוב","f":"חיים ברוך","bt":"תרן","dt":"תשב","b":"רבה האחרון של ניזנוב על מקום אביו."},{"i":14188,"n":"הוכגלובר, מרדכי מוארשא","b":"רב בציפילוב,דיין בוורשה-תר\"ע"},{"i":14189,"n":"הוכגלנרטר, חיים מאוסטרובצא","f":"יוסף הוכגלרנטר","bt":"תקל","dt":"תקסט - כה אדר","b":"רב באסטרווצע-תקמ\"ט,הרובישוב,גרבוביץ"},{"i":14190,"n":"הוכגלרנטר, דוד מסטולין","f":"יעקב יצחק הוכגלרנטר","b":"רב בסטאלין. בנו - ר שלמה מקרלין."},{"i":14191,"n":"הוכגלרנטר, זאב וולף מטיקטין","f":"אליעזר","k":"בעל זבחי תודה","bp":"וילנא","b":"בנו של בעל \"דמשק אליעזר\", חתן ר משה קרמר, רב בקוסובה-ליטא, סעלץ וטיקטין. חיבר \"זבחי תודה\" למברג תרט."},{"i":14192,"n":"הוכגלרנטר, יעקב יצחק מזאמושט","f":"משה חיים","bt":"תס","dt":"תקלא","b":"נכד ר משה חריף מלמברג - ומכאן מקור השם (הוכגלרנטר=חריף). חתן ר אברהם ר חיימש הלפרין מלובלין. אב\"ד זאמושט-תק."},{"i":14193,"n":"הוכגלרנטר, יצחק מזאמושט","f":"יוסף","k":"בעל זכרון יצחק","bt":"תקלא","dt":"תקפה-ז - כ כסלו","b":"אב\"ד טרניגרד, חעלמא,זאמטשט-תקסז על מקום אביו.","bk":[["זכרון יצחק",""]]},{"i":14194,"n":"הוכגלרנטר, ישראל יוסף מדויד-הו","f":"דוד הוכגלרנטר","b":"תלמיד ר שלמה מקרלין. רב בדויד-הורודוק-תר."},{"i":14195,"n":"הוכגלרנטר, משה חיים מלבוב","f":"אלעזר","dt":"תקכ","b":"נכד ר זכריה מנדל בעל באר היטב, ונכד(-אבי אמו) ר משה חריף מקרמניץ. רב בקומארנא(=קומורנה), זלוטשוב-תעט, לבוב-תפד, ברח לבסרביה-תפח. הסכים על \"מאמר מרדכי\" - תעט, חתם-תפז בפנקס קהלת לבוב. בנו - ר יעקב יצחק מזאמושט."},{"i":14196,"n":"הוכגלרנטר, משה יעקב מקראקא","f":"חיים","b":"מגדולי חכמי קרקא-תק\"צ"},{"i":14197,"n":"הוכגלרנטר, משה שלמה מירושלים","f":"ישראל יוסף מדוידהורד","dt":"תרכו - ח שבט","dp":"ירושלים","b":"רב בפיעטרקוב-תרכ, עלה לירושלים וכיהן כדיין, ומראשי כולל ווהלין. חתנו - ר חיים דב אדלמן מפטריקוב."},{"i":14198,"n":"הוכולד, זכריה מנדל מקראקא","b":"מחכמי קראקא לפני השואה, תשובה אליו ב\"תפארת יוסף\"."},{"i":14199,"n":"הוכמות, אברהם מואספרום","b":"רב הקהלה הניאולוגית בואספרום-1859, היה גם מנהל בי\"ס, ופרסם מאמרים."},{"i":14200,"n":"הוכמן, אברהם שלום מקראקא","f":"משה יצחק","k":"אדמור ממוגיל-קראקא","dt":"תרצו - בערך","b":"האדמור ממוגיל בקראקא. חיבר \"גילת שלום\" פיעטרקוב תרצז. פרסם מאמרים ב\"המפלפל\" - קראקא תרעג."},{"i":14201,"n":"הוכמן, גמליאל מחעלמא","dt":"תשג","b":"רב בחעלמא"},{"i":14202,"n":"הוכמן, חיים","f":"יהודה","bt":"1851","bp":"דרוהיצין-פלך גרודנא","dt":"1916","b":"פרופ' למתמטיקה באודסה, מפקח בביהמ\"ד למורים בזיטומיר. חיבר עבודות חשובות בפיסיקה. עסק בחקר המושגים המדעיים של היהודים בימי קדם והיכח שלחכמי התלמוד כבר היו ידועים חוק שמירת החומר, צורתו הכדורית של כדור הארץ, ודן בשיטות ההוכחה המתמטית בתלמוד."},{"i":14203,"n":"הוכמן, חיים יחזקאל מיאבורזנא","dt":"תש","b":"רב ביאבורזנא"},{"i":14204,"n":"הוכמן, יהודה","f":"אברהם שלום ממויגל","dt":"תרפא","b":"בן האדמור ממויגל-קראקא. עורך \"המפלפל\" - קראקא תרעג - יחד עם ר מאיר רוך בעל \"דבר מאיר\"."},{"i":14205,"n":"הוכמן, יונה ממאלין","f":"נחום יודל","bt":"תרמג-ד","dt":"תשיז","b":"נכד ר משה ממאלין. חתן ר מרדכי ישראל ברגובסקי מרדומישל. רב במאלין-פלך קיוב-תרסה, עלה לארץ, ראב\"ד בתל אביב."},{"i":14206,"n":"הוכמן, יוסף מלונדון","bt":"תרמג","b":"תלמיד ביהמ\"ד לרבנים בלונדון, ד\"ר מאוני' היידלברג. רב בהכנ\"ס בלונדון-תרסח. חיבר באנגלית \"הכתב הישן בעברית..\", \"החגים בבית המקדש\". פרסם מאמרים בכתב עת, ועסק בעניני צבור."},{"i":14207,"n":"הוכמן, יחזקאל מבילגוריי","dt":"תשג","b":"דומ\"צ בבילגורייא"},{"i":14208,"n":"הוכמן, יצחק יחזקאל מקשאנוב","k":"אדמור מקשנוב","dt":"תש..","b":"ממשפחת אדמורי נדבורנא - קרטשניף. חתן ר ישכר דב בערטשע מסטמר. אדמור בקשנוב, וביבוזנה."},{"i":14209,"n":"הוכמן, מרדכי הלוי מקאלווריה","bt":"תקפא","dt":"תרלג - יג טבת","b":"רב בפאריטש, קאלוואריע(=קאלווריה)-תרכה."},{"i":14210,"n":"הוכמן, שלום שכנא ממאלין","f":"נחום יודל","bt":"תרמ","b":"רב במאלין-פלך קיוב-תרסג."},{"i":14211,"n":"הוכנר, יצחק מביליץ","f":"מנחם מנדל","k":"בעל מנחת יצחק","bt":"תרן","dt":"תשב","b":"חתן ר יוסף טהלער. רב בביליץ. חיבר \"מנחת יצחק\" לובלין תרצח."},{"i":14212,"n":"הוכפלד, אברהם הכהן מאוסטרהא","f":"נפתלי הירץ מגלוגא וא","b":"פרנס באוסטרהא-תקלב."},{"i":14213,"n":"הוכפלד, אהרן שמואל מסטפין","f":"נפתלי הרץ מגלוגא ואו","k":"בעל וצוה הכהן","r":"תלמיד המגיד ממזריטש","bt":"תק","dt":"תקעד- ד ניסן","b":"חתן ר יוסף יואל הלפרין מסטעפין-תלמיד הבעשט. תלמיד המגיד ממזריטש ור פנחס מקוריץ והביא מתורתם בספריו. רב בסטעפין על מקום חותנו, רב באוסטרהא, יאמפולי, שדה לבן על מקום אביו. בקי בחכמות ובלשונות (ואף מומחה במשחק השח). הרבה מחבוריו נשרפו בשריפה הגדולה בסטעפאן. חיבר גם \"אבן הראשה\" (אב\"ן=אהרן בן נ פתלי, הראש\"ה=ר אהרן שמואל הכהן) עם הסכמת ר לוי יצחק מברדיטשוב, \"קורא מראש\"-רובו נשרף באוסטרהא, ועוד. (סיפר בשם חותנו שפעם היה הבעשט אצלו בסטעפאן ואח\"כ חזר חותנו עם הבעשט בעגלה וביער שמעו צפצוף צפורים - הבעשט אמר שאומרים לו ששכחו דבר נחוץ בעיר וחותנו הקפיד שהדבר היה רחוק בעיניו שיודע שפת העופות - אך כשחזרו התברר שאכן כך היה הדבר). בנו ר חיים משה נפטר צעיר והניח בן ר נפתלי הרץ שהו\"ל ספר זקנו.","bk":[["וצוה הכהן",""]]},{"i":14214,"n":"הוכפלד, אשר ענזיל הכהן מאוסטרה","f":"נפתלי הירץ מגלוגא וא","b":"פרנס באוסטרהא-תקיא, וחתם פעמים רבות בפנקס הח\"ק."},{"i":14215,"n":"הוכפלד, יוסף יוזפא נחמן מאוסטר","f":"נפתלי הירץ מגלוגא וא","b":"מחכמי אוסטרהא-תקכח."},{"i":14216,"n":"הוכפלד, יצחק הכהן מימפולא","f":"נפתלי הירץ מגלוגא וא","dt":"תקפ - כח חשון","dp":"שדה לבן","b":"רב ביאמפולא-תקנא, באר."},{"i":14217,"n":"הוכפלד, משה הכהן מאוסטרהא","f":"נפתלי הירץ מגלוגא וא","b":"פרנס באוסטרהא-תקלג."},{"i":14218,"n":"הוכשטין, א' מפינסק","b":"תלמיד ר משה ליב לחוביצקי, וחיבר שיר לכבודו ונדפס בספרו \"מפתח התורה\"."},{"i":14219,"n":"הוכשטין, אפרים בנימין מקמינקא","f":"אברהם","dt":"תרעז","dp":"ירושלים","b":"רב בקמינקא, עלה לירושלים ושימש דיין - תרס. בנו - ר מנחם מנדל מסינסינטי-ארה\"ב. מחותן עם ר פנחס המבורגר מירושלים."},{"i":14220,"n":"הוכשטין, מנחם מנדל מארה\"ב","f":"אפרים בנימין מקמינקא","k":"בעל מאור עינים","bp":"ירושלים","b":"רב בסינסינטי-ארה\"ב-תרצח."},{"i":14221,"n":"הוכשטין, משה הירש מארה\"ב","b":"רב קהלת \"זכרון תורת משה\" בניו יורק, פעל להקמת כולל אמריקה בירושלים (יחד עם ישראל דב איזנשטין), והיה מחלוקת כנגדו מצד רבני אמריקה."},{"i":14222,"n":"הוכשטין, שאול מבוכניה","b":"ראה הקהל בבוכניה."},{"i":14223,"n":"הולדר, יוסף מאסלאני","b":"רב באסלאני. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":14224,"n":"הוליץ' (שנפלד), אהרן מרכניץ","b":"רב ברכניץ-תקמב כ-20 שנה, עלה לארץ לבד (אשתו סירבה לעלות עמו)."},{"i":14225,"n":"הוליש, מרדכי מרכניץ","b":"רב בדאברי-ת\"נ"},{"i":14226,"n":"הוליש, צבי הירש מלבוב","b":"מראשי קהלת לבוב, חתם-תקלב עם ר יחיאל מיכל בריסקר, ר מנחם מנדל רפפורט, ועוד."},{"i":14227,"n":"הולך, מנחם זלקא מדולינא","f":"משה דוב","bt":"תרכח","dt":"תרץ","b":"חתן ר יצחק קרויטהמר מניזנוב. ראב\"ד דולינא-תרסא. מכתב שלו פורסם בספר זכרון לרי\"ל גרויברט - לודז תרפו."},{"i":14228,"n":"הולך, שמעון מדולינא","f":"מנחם זלקא","bt":"תרם","dt":"תשב","b":"רב בדולינא על מקום אביו. חתן ר יקותיאל יוזפסברג מראווה. נספה בשואה."},{"i":14229,"n":"הולנד, חיים דוב משימאנצי","f":"יהודה צבי","bt":"תרמו","b":"נכד ר גרשון משקלוב. תלמיד ישיבת \"תורת חסד\" בבריסק אצל ר יעקב זלמן ליפשיץ, תלמיד ר ברוך דב מהלוסק וסלובודקא, ר איסר זלמן מלצר. ר\"מ בקוברין, רב בשימנצי-פלך קובנא-תרע. נסמך מאת: ר חיים סולוביציק, ר יצחק יעקב רבינוביץ מפוניבז, ר איסר זלמן מלצר, ר ברוך דב מסלובודקא. פרסם מאמרים ב\"יגדיל תורה\"."},{"i":14230,"n":"הולנדר, אברהם מארה\"ב","f":"מנחם מנדל","b":"גביר בנוארק-ניו ג'רסי, סייע בהדפסת הש\"ס-תרע.. ונזכר בשער מסכת פסחים - תרעט."},{"i":14231,"n":"הולנדר, אברהם מברנוב","f":"שמחה","k":"בעל תפארת אברהם","bt":"תרכה","bp":"ברנוב","dt":"תרעה","b":"חתן ר שמואל יצחק צוקר ממאדין. ראב\"ד ברודניק-תרסב, ראש ישיבה בויזניץ ובטרנוב. חיבר \"תפארת אברהם\" מונקטש תרסג. ?? לא באוצר ??"},{"i":14232,"n":"הולנדר, אברהם מליזנסק","b":"היגר מליזנסק לניו יורק וכיהן שם כרב בתקופת מלחמת העולם הראשונה."},{"i":14233,"n":"הולנדר, אהרן אריה הכהן","f":"נתן דוד הולנדר","b":"רב באמסענע"},{"i":14234,"n":"הולנדר, אהרן אריה ליב מאמסנא","f":"נתן דוד","dt":"תשב","b":"רבה של אמסנא על מקום אביו. נספה בשואה."},{"i":14235,"n":"הולנדר, אליעזר מצאנז","bt":"תקל","b":"אבי משפחת הולנדר חתן הגביר ר יודלי פרנס מוישניצא וגיסו של ה\"ברוך טעם\". בניו - ר יהודה יודלי - הדב\"ח כתב לו בתקפח אודות רבנות צאנז, ר מנדל - חתן ר חיים שנקר (צאצאיו בספר שנקר), ר מרדכי דוד מסוכא, ר אשר ישעיה."},{"i":14236,"n":"הולנדר, בנימין אליהו מפרשבורג","f":"ישעיה מפרשבורג","k":"בעל שלחן הטהור","bp":"פרשבורג","dt":"תרפו - יד חשון","dp":"פרשבורג","b":"תלמיד השב\"ס. חתן ר אלעזר הכהן עהרנטריא מפרשבורג וירושלים. משגיח ומנקר בפרשבורג."},{"i":14237,"n":"הולנדר, זאב וולף מאלטונא","b":"חתן היעב\"ץ. פרנס באלטונא."},{"i":14238,"n":"הולנדר, חיים דב מפעלדהאזא","bt":"תרכד","dt":"תרצו - ד-ה חשון","b":"תלמיד השב\"ס. דיין בפעלעדהאזא(=פלדיהאז). נזכר בשו\"ת \"נהרי אפרסמון\"."},{"i":14239,"n":"הולנדר, יהודה יודלי מצאנז","f":"אליעזר","b":"ראש הקהל בצאנז, הביא לרבנות צאנז את קרובו ה\"דברי חיים\". חתן ר מתתיהו צדיק נסתר מדרוהוביטש."},{"i":14240,"n":"הולנדר, יהודה מבובוב","f":"משה דוד","bt":"תרמה","bp":"בובוב","dt":"תשב","b":"חסיד בובוב. רב במישלניץ. נספה בשואה. (תולדותיו בספר תלמידו ר מנחם ברכפלד \"כרם שלמה\" תשלט)"},{"i":14241,"n":"הולנדר, יוזפא מברלין","b":"מראשי הקהילה בברלין. חתם על הסכם ויתור מס הקהילה ממשה מנדלסון-תקכג."},{"i":14242,"n":"הולנדר, יוסף הכהן מאמסנא","f":"שמואל","k":"אדמור מאמסנא","bt":"תרט","dt":"תרמב-נא-יז תמוז","dp":"קראקא","b":"תלמיד מובהק ל\"דברי חיים\" שאמר עליו שמחשיבו כאחד מבניו והכתירו כאדמור. רב ואדמור באמסנא-תרן. חתן ר אריה ליבוש קנר מרימנוב. בנו ר דוד מילא את מקומו אחריו."},{"i":14243,"n":"הולנדר, יוסף מברדיוב","dt":"תשד","b":"רב בברדיוב"},{"i":14244,"n":"הולנדר, יוסף מנחם ממונקטש","f":"יעקב מפמורן","bt":"תרלב","dt":"תשד","b":"חסיד בלז, רב במונקטש וסמבטהעלי. חתן ר שמואל בן יעקב יהודה הכהן ברנשטין. נספה בשואה וכתביו אבדו."},{"i":14245,"n":"הולנדר, יחזקאל","f":"יוסף מאמסנא","dt":"תש..","b":"מחכמי קראקא. נספה בשואה."},{"i":14246,"n":"הולנדר, יחיאל מיכל מטרנוב","f":"שלמה","k":"בעל אמרי ברוך","bt":"תרסח","bp":"טרנוב","dt":"תשב","b":"מגדולי רבני גליציה בדורו. חתן ר בנימין זאב וקסלר. רב בטרנוב-תרצג. חיבר \"אמרי כהן\" פיעטרקוב תרצז. מתלמידיו ר\"נ וויטשנר מברוקלין. פרסם מאמרים ב\"הירדן\" - רישא תרץ, \"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, \"הלבנון\" - גורליץ תרפח. סקירה על ספרו ב\"תלפיות\" - טרנוב תרצח.","bk":[["אמרי כהן",""]]},{"i":14247,"n":"הולנדר, יעקב אריה מטרנוב","f":"שלמה","bt":"תרף","bp":"טרנוב","dt":"תשב","b":"מחכמי טרנוב, תשובות אליו בספרי חכמי דורו. נספה בשואה. מתורתו - \"דגל הצעירים\"-תרפה."},{"i":14248,"n":"הולנדר, יעקב מטריער","f":"ישעיה מאלטונא","b":"אב\"ד טריער. פרסם בכתב העת \"העברי\" את תולדות אביו וחדושי תורה ממנו."},{"i":14249,"n":"הולנדר, יעקב מפמורן","f":"מאניש","bt":"תר","dt":"תרע","b":"חתן ר שמואל הכהן זינגר מטומשוב. רב בפומורן."},{"i":14250,"n":"הולנדר, יצחק","f":"אליעזר","b":"אחיו של ר יהודה ראש הקהל בצאנז. מחכמי צירץ למד ונתגדל אצל ה\"דברי חיים\" לאחר פטירת אביו."},{"i":14251,"n":"הולנדר, ישעיה הכהן מאלטונא","f":"אהרן","bt":"תקסו","bp":"אלטונא","dt":"תרלג - כה תשרי","dp":"אטענזען (ליד אלטונא)","b":"תלמיד החת\"ס (עם חברו וגיסו ר יעקב כץ), ור גמליאל ור עקיבא ורטהימר מאלטונא. דיין באלטונא-תקצג עם ר יעקב עטלינגר. חתן ר משה כץ מאלטונא. (שאל עצה מהחת\"ס עם לשוב לאשכנז או להישאר בהונגריה - ואמר לו ולחבריו מאשכנז - כי ארץ אשכנז זקוקה לכם כעת ושלחם לשם). בין כתביו נמצא חדושים מהחת\"ס על נדה - שלא נדפסו. נסמך מאת: ר שמואל פריינד מפראג, ר זנוויל איגר מברוינשוייג. מתורתו ב\"שומר ציון הנאמן\". בנו - ר יעקב מטריער פרסם מתורת אביו ואת תולדות אביו בכתב העת \"העברי\"."},{"i":14252,"n":"הולנדר, ישעיה מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":14253,"n":"הולנדר, ליב מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":14254,"n":"הולנדר, מאיר מדעש","dt":"תרצח - יט ניסן","b":"תלמיד ר משה פאנט האדמור מדעש. שו\"ב ורב באורישור-ליד דעש. חתנו היה ר חנניה יו\"ט ליפא ברוין מגרוסורדין שהזכירו בספרו \"דרכי משה החדש\"."},{"i":14255,"n":"הולנדר, מנחם מנדל הכהן מבובוב","b":"רב בבובוב. תלמיד רנ\"צ מרופשיץ."},{"i":14256,"n":"הולנדר, מרדכי ממישקולץ","b":"חתניו - ר עזריאל אקשטין מאנטורפן, ר משה שמואל שטרן מסערענטש, ור יוסף פרידמן מאנטורפן."},{"i":14257,"n":"הולנדר, מרדכי מפרשוב","bt":"תקכ","bp":"טרנופול","b":"גביר שהתישב בפרשוב-תקם כיהודי הראשון, ופיתח חיי יהדות גם בעיירות הסמוכות. ראש מחוז שאראש-תקסו. שתדלן בפרלמנט בפרשבורג ובחצר המלכות בוינה. בנה-תריב את ביה\"כ הגדול בפרשוב."},{"i":14258,"n":"הולנדר, משה","dt":"תשד","b":"רב ברעטא"},{"i":14259,"n":"הולנדר, משה מסמניץ","b":"חתן ר שמואל בנימין יונגרייז מפילעק. רב בסעמניץ."},{"i":14260,"n":"הולנדר, נפתלי חיים מליזנסק","f":"שרגא פייביש","b":"חתן ר יחזקאל פיבל שטולבך מליזנסק, רב בליזנסק, תשובה אליו ב\"שות מהרש\"-תרנא."},{"i":14261,"n":"הולנדר, נתן דוד מאמסנא","f":"יוסף הכהן","bt":"תרל","dt":"תרצח - כ סיון","b":"רב באמסנא(=אמסאנע)-תרנא על מקום אביו. חתן ר זאב יהודה שפרינגר וביזוו\"ש חתן ר משולם גוטסמן האדמור מלשקוביץ. (אצל וונדר תאריך פטירתו - תשא)."},{"i":14262,"n":"הולנדר, שמאי מזלוטשוב","b":"רב בזלוטשוב-תר\"י. תשובות אליו ב\"טוט\"ד\"."},{"i":14263,"n":"הולנדר, שמואל מאיר מאמסנא","f":"נתן דוד","k":"מהרש\"ם הכהן","bt":"תרמט","bp":"קראקא","dt":"תשכה - טז טבת","b":"רב באמסנא לצד אביו. חתן ר שלום הגר מסטרוזיניץ ובזיוו\"ש ר ישכר דב כהנא מפעסט. רב בטשרנוביץ-תרעג, ולאחר השואה רב בדרבני (ליד דורוהוי). רב בבוקרשט-תשז, עלה לארץ-תשח והיה רב בתל אביב. חיבר \"ש\"מ הכהן\" בוקרשט תשז, ועוד. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד.?? לא באוצר ??"},{"i":14264,"n":"הולנדר, שמואל מצאנז","f":"יהודה יודלי","b":"מחסידיו הקרובים של האדמור מצאנז. חתן ר בנימין זאב בלומנפלד ראב\"ד למברג."},{"i":14265,"n":"הולנדרסקי, ליאון","k":"בעל היהודים בפולין","bt":"1808","bp":"וישטיניץ","dt":"1878","dp":"פאריס","b":"סופר. מיסד הדפוס הראשון בסובאלק. ברח מרוסיה-1848 בגלל שנאשם בתמיכה במורדים הפולנים. חיבר בצרפתית \"היהודים בפולין\" - ובו תמך ברעיון שהיהודים בפולין צריכים להתבולל ועל כך הותקף בידי ההיסטוריון הרוסי ס' ברשדסקי. חיבר מילון צרפתי עברי, ועוד."},{"i":14266,"n":"הולס, אריה ליב מסמבור","dt":"תרלו - אחרי","b":"אב\"ד סמבור-תר."},{"i":14267,"n":"הולס, גרשון מבוכניה","f":"בריש מסטריזוב","b":"נזכר בלקוטי הרמ\"ל שפירא."},{"i":14268,"n":"הולס, זליג מלבוב","b":"חתן ר נפתלי הרץ אשכנזי מראווי וזולקוא. דיין בלבוב-תפ."},{"i":14269,"n":"הולס, יוסף מלבוב","b":"אב\"ד למברג, טיסמניץ (בזמן ביקור ה\"פני יהושע\") וסקאלי-תעח. חתן ר יצחק אחיו של הט\"ז. סבו של ר שלמה בובר. בנו ר זאב וולף מבוליחוב."},{"i":14270,"n":"הולס, יצחק איזיק מסטריזוב","dt":"תרע","b":"רב בסטריזוב."},{"i":14271,"n":"הולס, מנחם מנדל מסמבור","dt":"תרפה - לפני","b":"רב במושציסק."},{"i":14272,"n":"הולס, שלמה מלמברג","f":"צבי הירש","k":"בעל בנין אפריון","bt":"תקיג","b":"מו\"ץ ומגיד בלמברג בזמן הישועות יעקב. בנו ר יהושע השל זקנו של ר שלמה שפירא ממונקטש. חיבר \"בנין אפריון\" וממנו נדפס בשם \"כבוד חכמים עטרת פז\" על הרמב\"ם - ירושלים תשמט."},{"i":14273,"n":"הולצברג (עציון), יצחק רפאל","f":"שרגא פיבוש","k":"בעל ילקוט פירושים לת","bt":"תרמה","bp":"קובנא","dt":"תשמב","b":"נכד ר חיים שמחה סולוביציק-אחיו הצעיר של ר יוסף דב מבריסק, נתייתם בגיל צעיר וגדל אצל זקנו. למד מתמטיקה באוניברסיטת חרקוב. מנהל הגימנסיה העברית לבנות \"יבנה\" והסמינר למורים בטלז. ציר בסיים הליטאי מטעם מפלגת הדתיים. עלה לארץ-תרצג והיה מפקח בתי ספר \"המזרחי\" בארץ. חיבר ספרים בנושאי חינוך ויהדות. ממיסדי ישיבת הישוב החדש בתל אביב ומדרשית נועם בפרדס חנה. בנו - ר יוסף דב."},{"i":14274,"n":"הולצברג, חיים שמחה מברזאן","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":14275,"n":"הולצברג, יוסף דב מירושלים","bt":"תרע","dt":"תשס","b":"מצאצאי ר חיים שמחה סולוביצ'יק. תלמיד ישיבת טלז, עלה לירושלים ולימד בסמינר בית יעקב. התכתב עם גדולי דורו. העתיק במחברת את חדושי זקנו ר שמחה סולוביצ'יק ושיעורים מישיבת טלז-תרף - תרץ. אשתו - לאה שוחט."},{"i":14276,"n":"הולצברג, יעקב שלמה ממוהילוב","f":"אברהם","k":"בעל עטרת שלמה","b":"רב במוהילוב. הסכים על \"אהל יצחק\" - סטמר תרסג."},{"i":14277,"n":"הולצברג, משה","b":"פרסם מאמרים ב\"אהל תורה\" - ירושלים תרצט."},{"i":14278,"n":"הולצברג, שרגא פיבל הלוי מפריס","f":"שלמה זלמן מקולנא","k":"פיבל פאריזער","bt":"תרא","dt":"תרעז","b":"חתן ר חיים שמחה סולוביצ'יק-אחיו של בעל בית הלוי. ממקורבי ר ישראל סלנטר בהיותו בפריס. עבר למנצ'סטר-אנגליה-תרל, פריס-תרלח בעקבות רבו המהרי\"ל דיסקין שגלה מלומז'ה לפריס, עלה לארץ-תרנז והתישב ביפו וסייע למנות את ר נפתלי הרץ הלוי לרב, ולאחר פטירתו סייע במינוי הרב קוק לרבנות יפו. בנו - ד\"ר יצחק רפאל עציון-הולצברג."},{"i":14279,"n":"הולצמן, אליהו מניו יורק","k":"בעל עמק רפאים","b":"רב בניו יורק. חיבר \"עמק רפאים\" נ\"י תשכה - כנגד הריפורמים ובראשם יצחק מאיר ווייז ומקס לילנטל."},{"i":14280,"n":"הולצמן, משה מבילילובקה","f":"יוסף","bt":"תרכו","b":"נסמך מאת: ר יוסף יוזפא מברדיטשוב, ר נפתלי מסקווירא. רב בבילילובקה-פלך קיוב-תרמה. חיבר חדושי דינים בהלכות גטין - בכת\"י."},{"i":14281,"n":"הולצר, דב בר מסילאדי-פרטשען","f":"ליב","dt":"תרנז - ו תמוז","dp":"שימלויא","b":"חתן ר בנימין הכהן הרטמן משימלויא. תלמיד החת\"ס. רב בשמילויא והתגורר בסילאדי-פרטשען."},{"i":14282,"n":"הולצר, זאב מלבוב","k":"בעל עמוד המשא אשר","b":"מחכמי למברג, חיבר \"עמוד המשא אשר נשאתי..\" קראקא תרמט."},{"i":14283,"n":"הולצר, יעקב מדעש","dt":"תרנ.. - בערך","dp":"[דעש]","b":"דרשן מגיד ומלמד בדעש - אמצע המאה ה-19. במקורו מגליצה. מחדושיו בפנקס חדו\"ת של תלמידו ר אלכסנדר וירצברגר."},{"i":14284,"n":"הולצר, יצחק מקראקא","bt":"תרלג","bp":"קראקא","dt":"תשיא","b":"תלמיד בהימד\"ר בברלין. רב קהילת הנאורים בשדט (ליד נהר האודר), וורמייזא-תרע. חיבר ספר על יהודי וורמייזא בגרמנית. היגר לניו יורק-תש."},{"i":14285,"n":"הולצר, נח","bt":"תרי","bp":"צאנז","dt":"תרפג","b":"חסיד צאנז. חתן ר אליעזר גלזר מקשאנוב. רב בקשאנוב."},{"i":14286,"n":"הולר, ישראל אהרן מבקשביץ","f":"מתתיהו","k":"בעל בני אהרן","bt":"תרלה","bp":"בקשביץ","dt":"תש","b":"חתן ר משה צבי בליץ. תלמיד חכם שנאלץ לנדוד בין העיירות. חיבר \"בני אהרן\" למברג תרפו, ועוד. הדפיס תהלים עם פירוש ארץ החיים לר אברהם חיים מניקלשבורג - והוסיף פירוש \"לו יא\"ה\" (ר\"ת שמו) - למברג תרסד."},{"i":14287,"n":"הולשיצר, זאב וולף מהולשיץ","b":"רב בליזנסק, וכנראה גם בטרנוב."},{"i":14288,"n":"הומברג, נפתלי הרץ","k":"בעל אמרי שפר","bt":"תקט","bp":"כפר ליעבען","b":"למד בפרג, פרשבורג, וגלוגא, ברסלוי, ברלין והמבורג. התקרב למנדלסון, חיבר את הפירוש לתרגום האשכנזי לתנ\"ך של מנדלסון."},{"i":14289,"n":"הומינר, יעקב","b":"רב-שנת ת\"פ. אביו של ר אהרן זליג מאשווא. גיסו(-בעל אחותו) של ר יקותיאל זיסקינד-אביו של ר רפאל הכהן מהמבורג."},{"i":14290,"n":"הומינר, שלמה מירושלים","f":"שמואל","bt":"תרלח","bp":"מינסק","b":"עלה לירושלים-תרם עם משפחתו. תלמיד ישיבת \"עץ חיים\". שו\"ב בירושלים, עסקן ציבור."},{"i":14291,"n":"הוניגוקס, מרדכי","b":"תשובה אליו - מהר\"י הכהן."},{"i":14292,"n":"הונקיר, הירש"},{"i":14293,"n":"הוסטר, שלמה מפשמישל","dt":"תשג","b":"רב בפשמישל-תרצד."},{"i":14294,"n":"הוסקינד, שלום מנ\"י","b":"תלמיד בישיבת \"תומכי תמימים\" בנ\"י. פרסם מאמרים ב\"קובץ חדושי תורה\" - נ\"י תשד - קובץ תלמידי ישיבות \"תומכי תמימים ליובאויטש\"."},{"i":14295,"n":"הופבויער, ישכר דב מוינה","f":"אליקים גץ מפרשבורג","bt":"תרז","bp":"פרשבורג","dt":"תרץ 0- יח תשרי","dp":"וינה - פרשבורג","b":"תלמיד הכת\"ס. מראשי קהילת עדת ישראל בוינה-תרכז, ומהלוחמים ברפורמים. חתנו ר אברהם שמואל בנימין סופר בעל \"כתב זאת זכרון\" - לתולדות משפחת רעק\"א והחת\"ס."},{"i":14296,"n":"הופבויער, שלום מוינה","b":"חתנו - ר משה דוד פלש מוינה."},{"i":14297,"n":"הופמן, אברהם דוד ממישקולץ","f":"חנוך מנעמעש-סאלאק","bt":"תרמד","bp":"נעמעש-סאלאק","dt":"תשד","dp":"אושוויץ","b":"תלמיד השב\"ס, והדעת סופר, ור משה גרינולד מחוסט. חתן ר אברהם יעקב ספיר מסערענטש ועבר לשם. רב בסעטשין-תרעא, מישקולץ-תרעא. אדא-יוגוסלביה-תרפב. נספה בשואה. בנו - ר משה שמעון מבודפשט."},{"i":14298,"n":"הופמן, אברהם מינושהאזא","f":"שמואל זנויל מסערדאוה","dt":"תרפט - כד אייר","b":"תלמיד הכת\"ס, ור יהודה אסאד, ודודו ר מיכאל הופמן מסערדאוהל. מחכמי יאנושהאזא."},{"i":14299,"n":"הופמן, אליהו מנחם","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":14300,"n":"הופמן, ברוך","dt":"תשד","b":"רב בנ'קעוועשד"},{"i":14301,"n":"הופמן, דוד צבי מברלין","f":"משה יהודה ליב מוערבא","k":"בעל מלמד להועיל","bt":"תרד","bp":"וערבא","dt":"תרפב - יט חשון","dp":"ברלין","b":"תלמיד הכת\"ס, ור שמואל זומר מפאפא ומהרם שיק, בעל תואר ד\"ר. חתן ר יונה רוזנבוים מצעל-תרלב. מורה בהוכברג, בבית ספרו של הרש\"ר הירש בפפדמ-תרלא, ר\"מ בביהמ\"ד לרבנים בברלין ובהמשך עמד בראשו. חיבר \"סנהדרין בירושלים\", \"מדרש תנאים\", ועוד. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב, \"יגדיל תורה\" - ברלין תרנא, \"המסדרונה\" - פפד\"מ-ירושלים תרמה, \"הפלס\" - ברלין תרסא-תרסה - הגהות על המכילתא - כת\"י ברלין.","bk":[["רד\"צ הופמן","מפרשי תורה"],["פי' הרד\"צ הופמן",""],["מלמד להועיל (שו\"ת)",""],["מלמד להועיל","שו\"ת - אחרונים"]]},{"i":14302,"n":"הופמן, חיים אשר אנשיל מארגנטינ","b":"רב בבואנוס-אירס-ארגנטינה. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":14303,"n":"הופמן, יונה מנישטעטין","f":"משה יהודה ליב מוערבא","b":"רב בניישטעטין."},{"i":14304,"n":"הופמן, יעקב יהודה הלוי מפפדמ","f":"ישראל מנייפעסט","bt":"תרמא","bp":"פאפא","dt":"תשטז - יג תמוז","dp":"תל אביב","b":"תלמיד השב\"ס, ור משה אריה רוט מפאפא. חתן ר עקיבא גינז-שלזינגר מוינה. פעיל באגודת \"אהבת ציון\" בפרשבורג. רב בוינה-תרסז, קאסטל-תרסח, ראדיביץ-תרעג, פפד\"מ-תרפג, גורש ע\"י הנאצים-תרצז ועבר לוינה, הגיע לניו יורק-תרצח וכיהן שם כרב. עלה לארץ-תשיד והתישב בתל אביב.מהדיר פירוש הרמבן עמ\"ס ביצה ותענית עם הערותיו."},{"i":14305,"n":"הופמן, יצחק מארה\"ב","f":"פנחס","bt":"תרעד","bp":"ניו יורק","b":"תלמיד ישיבת \"תורה ודעת\" בניו יורק, תלמידר דוד ליבוביץ, כולל קובנא בסלובודקה עד המלחמה. רב בניו יורק, תלמיד ר אהרן קוטלר בלייקווד. ר\"מ בישיבת \"נר תמיד\" בניו יורק. חיבר ספר בהלכה. נסמך מאת ר דוד ליבוביץ, ר יהודה ליב פורר, ר יוסף רוזין מפאסאיק-ניו ג'רסי, ר משה בנימין טומשוב. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":14306,"n":"הופמן, ישראל הלוי מנייפעסט","b":"רב בפאפא, נייפעסט. בנו - ר יעקב יהודה מפפדמ."},{"i":14307,"n":"הופמן, ישראל מנחם אלתר","dt":"תשד","b":"רב בבנדעקעביץ"},{"i":14308,"n":"הופמן, מיכאל מסעראוהל","f":"יוסף מסערדאוהל","k":"שו\"ת מהרם מינץ","bt":"תקסח","bp":"[סערדאוהל]","dt":"תרלו - כב חשון","dp":"סערדאוהל","b":"גדל אצל דודו ר מאיר פולק מפאפא. תלמיד החת\"ס. רב בסערדאוהל וראש ישיבה שם. בנו - ר יוסף משה מפאפא. תלמידו - מאיר ברוין מפאפא - רשם ממנו חדושי תורה - שלא נדפסו (ורושם בפנקס תאריך פטירתו - תרנו)."},{"i":14309,"n":"הופמן, מרדכי","bt":"תרמב","dt":"תשלד - יב טבת","b":"דומ\"צ באויפאלו,עלה לבני ברק-תש\"ג"},{"i":14310,"n":"הופמן, משה יהודה","b":"רב בברסלוי,עלה לא\"י-תרצ\"ט"},{"i":14311,"n":"הופמן, משה יהודה ליב מוערבא","b":"רב בוערבא, פאפא. בניו ר דוד צבי מברלין, ור יונה אב\"ד נישטעטין."},{"i":14312,"n":"הופמן, משה יוסף מפאפא","f":"מיכאל מפאפא","k":"בעל מי באר מים-תרסו","r":"הדיין מפאפא","bt":"תרג","bp":"סערדאוהל","dt":"תרפח - א ניסן","dp":"ירושלים","b":"תלמיד הכת\"ס, ור נתן בנימין ליבר מפרשבורג. הוסמך על ידי ר יהודה אסאד. חתן ר משה וייס מסערדאוהל ועבר לשם. רב בסערדאוהל, פאפא-תרמב, עלה לירושלים-תרסו. נפטר ללא בנים. הו\"ל ספר אביו - שו\"ת מהר\"ם מינץ - פרג תקפז. נזכר בחת\"ס.","bk":[["מי באר מים חיים - ברכות",""]]},{"i":14313,"n":"הופמן, משה שמעון הלוי מטורנא","dt":"תשד","b":"חתן ר ישראל וועלץ, דומ\"צ בטארנא-אליא, בודפשט. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":14314,"n":"הופמן, נחמיה דב מקייפטאון","k":"בעל אוצר נחמד","bt":"1860","bp":"קובנא","dt":"1929","dp":"קייפטאון","b":"מחכמי בירז. חיבר ספרים בנושאי מדע. פרסם מאמרים בעתוני הזמן. הגיר לדרום אפריקה-1889 והו\"ל את העתון האידי הראשון \"דער אפריקאנער איזראעליט\", ועוד."},{"i":14315,"n":"הופמן, נתן הלוי מגרוסורדין","b":"דיין בגרוסורדין-[תרמ..]. נזכר ב\"בית שערים\"."},{"i":14316,"n":"הופמן, רפאל מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":14317,"n":"הופמן, שמואל יוסף מטעטש","b":"תלמיד ר שמואל דוד אונגר בישיבת טירנוי. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא."},{"i":14318,"n":"הופמנסטל, יצחק אריה","k":"איזאק לעוו עדלער","dt":"תרי","b":"גביר ופרנס בוינה, חוכר תעשיית המשי בהונגריה, מקורב למלכות ובעל תואר אצולה. פעל להקמת בית הכנסת הגדול בוינה עם חברו הגביר מיכאל בידרמן, ומינו את יצחק נח מנהיימר למטיף שם, ואת שלמה זולצר לחזן."},{"i":14319,"n":"הופן, אהרן מאזיפולי","f":"משה","bt":"תרסג","dt":"תש..","b":"חתן ר יוסף חיים קירשנבוים מטרנוב. רבה של אזיפולי-אחרי מלחמת העולם הראשונה, סניאטין-תרפט. נספה בשואה. אחיו - ר שמואל שלמה-תרס מקטוביץ - נספה בשואה."},{"i":14320,"n":"הופנברג, צמח מארה\"ב","dt":"תרצט - ה כסלו","b":"רב בהרטפורד. פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג, \"הפלס\" - ברלין תרסא-תרסה."},{"i":14321,"n":"הופנר, א\"ה מניו יורק","k":"בעל זבח פסח","b":"רב בארה\"ב. חיבר \"זבח פסח\" על הפרעות בגליציה - ניו יורק תרסה."},{"i":14322,"n":"הופנר, חיים אהרן מסקאהל","f":"אשר זליג","k":"בעל עבריה","bt":"תרכד","bp":"סקול","dt":"תרפד","b":"נכד-אבי אמו ר חיים אהרן לוין מואריז. בדחן בבוברקא, מורה במונקטש. היגר מברודי לניו יורק ועסק בבדחנות ועתונות. חיבר \"עבריה\" ברודי תרמח, \"מנגינות\" ברודי תרס. ?? לא באוצר ??"},{"i":14323,"n":"הופר, אברהם מבודפשט","bt":"1870","dt":"1942","b":"מורה בביהמ\"ד לרבנים בבודפשט."},{"i":14324,"n":"הופר, הרמן מואספרום","b":"רב בקהלה הניאולוגית בואספרום-1902, וד\"ר ל. קון על מקומו אחריו. פרופ' בביהמ\"ד לרבנים בבודפשט."},{"i":14325,"n":"הופשטין, אהרן יחיאל","f":"ירחמיאל משה הופשטיין","k":"אדמור מקוזניץ","bt":"תרמט","bp":"קוזיניץ(=קוזניץ)","dt":"תשג - ג-ט תשרי","dp":"זעליחוב","b":"מצאצאי המגיד מקוזניץ. אדמור בקוזניץ על מקום אביו. הרבה בנדודים ועבר ללודז, וארשא, לובלין, אוטואצק. ביקר בלונדון וברומא. נפטר ללא ילדים. תולדותיו ב\"המופלא בדורו\"."},{"i":14326,"n":"הופשטין, אשר אלימלך","f":"ירחמיאל משה מקוזניץ","dt":"תרצה - א אלול","b":"עבד ה' מתוך יסורים"},{"i":14327,"n":"הופשטין, יחיאל יעקב מקוזניץ","f":"אלעזר בריעה מקוזניץ","k":"אדמור מקוזניץ","bt":"תרו","dt":"תרכו - ל סיון","b":"מצאצאי המגיד מקוזניץ. חתן ר אלימלך מגרודזיסק. תלמיד הדברי חיים מצאנז. אדמור בקוזניץ מגיל 16 כ-4 שנים-נפטר צעיר."},{"i":14328,"n":"הופשטין, ירחמיאל משה מקוזניץ","f":"יחיאל יעקב מקוזניץ","k":"אדמור מקוזניץ","bt":"תרך","dt":"תרסח-ט -יג אלול","dp":"קשאנוב - קוזניץ","b":"מצאצאי המגיד מקוזניץ. לאחר שנתייתם גדל אצל אביו חורגו ר אשר מקרלין, וזקנו ר אהרן בעל \"בית אהרן\". חתן ר מרדכי מלויעב (טשרנוביל). שילב בין מנהגי קרלין לקוזניץ, והיה בידידות עם אחיו ר ישראל ה\"ינוקא\" מסטולין. מתורתו ב\"ספרן של צדיקים\"."},{"i":14329,"n":"הופשטין, ישראל אלעזר מארה\"ב","f":"ירחמיאל משה מקוזניץ","bt":"תרנט","bp":"קוזניץ-פלך קיעלץ","dt":"תשכו","b":"חתן האדמור ר מרדכי יוסף טברסקי מזלוטשוב ורחמיסטריבקא. ממלא מקום אביו בקוזניץ, יסד חברה \"עבודת ישראל\" להתישבות חסידים בארץ, עלה לארץ-תרפז ויסד את כפר חסידים, רב בפאריס-תרצה על מקום ר יואל הרצוג, בזמן השואה ברח לבורדו, נלקח למחנה גירס, ניס ויסד שם בי\"ד, היגר לארה\"ב-תשא ועמד בראש קהלת \"עבודת ישראל\"."},{"i":14330,"n":"הופשטין, ישראל המגיד מקוזניץ","f":"שבתי כורך ספרים","k":"המגיד מקוזניץ","r":"המגיד מקוז'ניץ","bt":"תצג או תק","dt":"תקעה - יד תשרי","b":"תלמיד ר דב בעריש כץ מאפטא, ור יחזקאל מאוסטרובצא, והנודע ביהודה. תלמיד בחסידות של המגיד ממזריטש, ר שמואל שמלקא מניקלשבורג, ור אלימלך מליזנסק. ישב בפשיסחא אצל חותנו ולמד אצל ר אברהם המגיד שם. כונה \"בעש\"ט השני\". מגיד בקוזניץ, מגנישוב, וריקא. חיבר \"בית ישראל\", \"עגונת ישראל\", ועוד.","bk":[["עבודת ישראל","חסידות"],["עבודת ישראל (המגיד מקוז'ניץ)",""],["אור ישראל - תיקוני זוהר",""],["בית ישראל - כתובות, קדושין, נדרים, נדה, יבמות",""],["גבורות ישראל - הגדש\"פ",""],["חידושי היהודי - חילוקא דרבנן על סוגיות",""],["יקר מפז - עה\"ת",""],["מגיד מישרים - שבת",""],["נזר ישראל - זוהר",""],["נר ישראל (פתילת הנר) - פירוש ספרי קבלה",""],["עבודת ישראל - עה\"ת",""],["עגונת ישראל (בית ישראל) - העגונה מסטאשוב",""],["קדושת ישראל - עה\"ת",""],["רמזי ישראל - פירוש על ספרי קבלה",""],["שארית ישראל - עה\"ת",""],["תהלות ישראל - תהלים",""]]},{"i":14331,"n":"הופשטין-בריעה, אלעזר מקוזניץ","f":"משה אליקים מקוזניץ","k":"אדמור מקוזניץ","dt":"תרכב - כו כסלו","b":"תלמיד ר ישכר בער מרדושיץ, ודוד השרף ממוגלניצא. חתן ר יעקב ממעליץ (רופשיץ), וישב אצל חותנו זקנו ר נפתלי צבי מרופשיץ, עבר לר ישעיה מפשעדבורז עד תקצב, אדמור בקוזניץ-תרט לאחר פטירת רבו ה\"שרף\". מחסידיו ה\"יהודי הטוב\" מניישטאט, ר יעקב צבי מפוריסוב (פשיסחא). מתורתו ב\"לקוטי מהר\"א\"."},{"i":14332,"n":"הורביץ - משפחה","b":"משפחה המיוחסת לר זרחיה הלוי בעל המאור. נחשבת לאחת משלוש המשפחות המיוחסות שעליהם אמר הבעשט - שאם אחד מהם מוריד דמעה לפני הקבה מיד נענה וכו'. תולדות המשפחה - \"בית הורביץ\" תל אביב תשנג. מקור השם - ר אשר זלמן שהיגר מברצלונה לעיר הורוזוביץ-בוהמיה - בשנת רי."},{"i":14333,"n":"הורביץ אברהם בן שבתי","bt":"1550","dt":"ה'שעה 1615","bk":[["ברית אברהם",""],["יש נוחלין",""],["עמק ברכה",""]]},{"i":14334,"n":"הורביץ דוד בן אלעזר","f":"אלעזר","k":"בעל אמרי דוד","bt":"תרכא","bp":"רוהטין","dt":"תרצד","b":"אב\"ד קוזלוב-תרמח, רב בסטניסלב-תרעא. חיבר \"אמרי דוד\" בילגוריא תרצד. חתן הרב באב\"ד ממיקוליניץ. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"אהל תורה\" - קראקא תרפח. בניו: ר משה ממריאמפול, ר נחמן.","bk":[["אמרי דוד",""]]},{"i":14335,"n":"הורביץ יונתן בנימין בן משה יהודה","f":"משה יהודה ממיהאלביץ","k":"בעל ונתתי שלום","bt":"תרכו","bp":"מיהאלביץ(=מיכאלוביץ)","dt":"תש - יט תמוז","dp":"ירושלים","b":"תלמיד השב\"ס, ור שלום קוטנא מאיזנשטט. חתן ר אברהם גרינבורג מקעזמארק ועבר לשם, ובזיוו\"ש חתן ר משה נתן נטע יונגרייז מטיסא-פירעד (לאחר פטירת בעלה ר זאב בלאס מדברצין). רבה הראשון של ביסטריץ-תרמו - והיה מחלוקת בענין מבנה ביה\"כ כאשר ר משה שמואל גלזנר מקלויזנבורג טען כי הוא דומה לכנסיה, רב באלשא-קובין-תרנה, עלה לירושלים-תרסט וכיהן כראש כולל הו\"ד, היה מראשי אגו\"י והשתתף במסע הרבנים עם הרב קוק. מזכיר אסיפת הרבנים העולמית בקראקא ועורך הפרוטוקול.","bk":[["מספד בירושלים",""],["ציון לנפש חיה (שרה הורוויץ)",""]]},{"i":14336,"n":"הורביץ ישעיה בן אברהם","dt":"ה'שצ 1630","bk":[["בגדי ישע",""],["ברית אברהם",""],["דרך חיים",""],["העתק וקיצר ומראה מקום מספר",""],["סדר הגדה של פסח עם פירוש השל\"ה",""],["סדר הגדה של פסח שער השמים עם דרך חיים",""],["סדר מעמדות",""],["סידור שער השמים",""],["קיצור שני לוחות הברית",""],["קצור שני לוחות הברית",""],["שני לוחות הברית",""],["שער השמים",""]]},{"i":14337,"n":"הורביץ ישראל זאב בן פינחס","f":"פנחס","k":"בעל ארץ ישראל ושכנות","bt":"תרם","bp":"טבריה","dt":"תרעח","dp":"טבריה?","b":"מחכמי טבריה, חיבר \"ארץ ישראל ושכנותיה\" וינה תרפב. פרסם מאמרים ב\"ירושלים\" - ירושלים תרמב-תרעט.","bk":[["ארץ ישראל ושכנותיה",""],["מחקרי ארץ אבותינו",""],["שני מאמרים",""]]},{"i":14338,"n":"הורביץ מנחם מנדל בן ישראל יעקב יוקל","f":"יעקב יוקל","k":"בעל שושנת יעקב","bt":"תקסד","bp":"סטרי","dt":"תרכד","b":"חתן ר יעקב צבי קנר ממהלוב (או: ר יחיאל מיכל מטיסמניץ). רב בבוליחוב-תקצה על מקום אביו. עבר לסטרי-תר וחזר לבוליחוב. חיבר \"שושנת יעקב\" למברג תקצט.","bk":[["שושנת יעקב",""],["שושנת יעקב","מפרשי שו\"ע"],["שושנת יעקב – חו\"מ",""]],"e":"תקס\"ד-תרכ\"ד"},{"i":14339,"n":"הורביץ פינחס בן צבי הירש","bt":"1730","dt":"ה'תקסה 1805","bk":[["גבעת פנחס",""],["הפלאה (כתובה)",""],["חידושי הפלא\"ה",""],["נתיבות לשבת",""],["סדר הגדה של פסח עם פירוש הבעל הפלאה",""],["ספר המקנה",""],["ספר הפלא\"ה",""],["פנים יפות",""]]},{"i":14340,"n":"הורביץ צבי הירש מאברמוביץ","b":"מוהל באברמוביץ-סלובקיה והסביבה בשנים תרב-תרכה."},{"i":14341,"n":"הורביץ, אבא מסמבור","f":"צבי יהושע מטרנוב","b":"חתן ר יצחק חריף מסמבור. רב בסמבור. נינו ר יעקב נפתלי מסנוק - כתב את מגלת היוחסין שלו."},{"i":14342,"n":"הורביץ, אביגדור הלוי מקמינקא","f":"אברהם מליצקא","dt":"תקצא","b":"חתן ר משה צבי הירש מייזלש מזולקווא. רב בקמינקא-תקי. בניו: ר יצחק שמשון מייזלש-הורביץ מטשרנוביץ, ר משה צבי."},{"i":14343,"n":"הורביץ, אביגדור מברנוב","f":"יצחק מברנוב","bt":"תרן","dt":"תשב","b":"חתן ר מאיר הורביץ מלינסק. רב בברנוב על מקום אביו. נספה בשואה."},{"i":14344,"n":"הורביץ, אברהם","f":"החוזה מלובלין","bt":"תקמח","dt":"תקע - ט תשרי","dp":"לובלין","b":"חתן ר יעקב משה מלובלין. נפטר צעיר. בנו ר יעקב יצחק קאפיל הו\"ל ספר זקנו \"דברי אמת\"."},{"i":14345,"n":"הורביץ, אברהם","f":"טוביה משנדישוב","dt":"תש..","b":"חתן ר אלימלך פרנקל תאומים מיברוב. נספה בשואה."},{"i":14346,"n":"הורביץ, אברהם (אבא) משנדישוב","f":"יעקב ממעליץ","bt":"תקפג","dt":"תרסה - ל שבט","b":"רבה של שנדישוב-תרנג. חתן ר שמואל הכהן מפשוורסק ובזיוו\"ש חתן רמ\"מ ויינברגר מדוקלא (אצל אלפסי קודם זיוו\"ש לראשון). בנו ר טוביה היה רב על מקומו אחריו. חסיד רצ\"ה מרימנוב (שרצה לקחתו כחתן אך דודו ר אליעזר מדזיקוב לא הסכים). בנו ר אשר ירוחם מפיאנטיקוב ניצל מהשואה, היגר לארה\"ב, נפטר בפורים תשטו."},{"i":14347,"n":"הורביץ, אברהם אבא אביש מידלובה","f":"אלעזר מבארוב","dt":"תש..","b":"רבה של ידלובה-תרצו. נספה בשואה."},{"i":14348,"n":"הורביץ, אברהם אביש מקרולי","f":"נפתלי","k":"בעל ברוך מתיר אסורים","bt":"תרנה-ז","bp":"מעליץ","dt":"תשד - ב סיון","dp":"אושוויץ","b":"חתן ר יצחק איזיק וייס האדמור מספינקא. רבה היחיד של רמיט-ליד ספינקא, רבה של ספינקא על מקום חותנו בזמן מלחה\"ע ה-I כשחותנו ברח למונקטש. רב בקארלי(=קרולה)-תרצד על מקום ר יואל טיטלבוים (שעבר לסטמר) והקים ישיבה בשם \"בית אברהם\" - היה מחלוקת עם חסידי סטמר בקהילה על הרבנות וחלק בחרו בר שמואל גרוס - והקהלה התפלגה, והמחלוקת הגיעה לקיצה בהתערבות הלשכה האורטודוכסית המרכזית בטרנסילבניה. חיבר \"ברוך מתיר אסורים\" סעאיני תרצה. נספה בשואה. בנו ר שמואל צבי אדמור מקראלע ספינקא בניו יורק."},{"i":14349,"n":"הורביץ, אברהם אליעזר","f":"יעקב קופל מלוקבה","k":"אבי החוזה מלובלין","b":"רב בשברשין,יוזפוף"},{"i":14350,"n":"הורביץ, אברהם אריה ליב מברוד","f":"יצחק","bt":"תקכא","bp":"ברודי","dt":"תקסג - ד ניסן","b":"מחכמי ברודי. חתן ר אברהם יקותיאל זלמן הכהן רפפורט."},{"i":14351,"n":"הורביץ, אברהם אריה מלויצק","f":"מנחם מאניש מדובנא","b":"חתן ר אשר-רבה של אליק ונארול. רב בלויצק(=ליצקא)-תקנ. הסכים על \"מרגליות התורה\" פאריצק תקמח, ביאור מהר\"ם שי\"ף פאריצק תקע, ועוד. אחיו - ר משה פרץ מדובנא. בנו - ר אביגדור מקמינקא."},{"i":14352,"n":"הורביץ, אברהם הלוי מוילנא","f":"אשר מקאסאווי","k":"אברמיל ישראל פרצ'ס","bt":"תקסב","dt":"תריז - ב-כ אדר","b":"חתן הגביר ר ישראל בן ר יעקב פרץ קלאצקי. דרשן, ר\"מ בקלויז ר דוד שטרשון, מו\"צ בוילנא-תקצב על מקום ר שלום. בניו: ר יעקב מוילנא בעל \"נחלת יעקב\", ר שאול חיים מדובראוונא בעל \"כלילת שאול\"."},{"i":14353,"n":"הורביץ, אברהם הלוי מירושלים","f":"פנחס","k":"בעל גלות וגאולה","b":"מחכמי ירושלים."},{"i":14354,"n":"הורביץ, אברהם זאב וולף מפשוורס","f":"משה יצחק","bt":"תקץ","dt":"תרנט","b":"רב בשפוורסק."},{"i":14355,"n":"הורביץ, אברהם חיים מלינסק - א","f":"נפתלי צבי מרופשיץ","k":"אדמור מרופשיץ בלינסק","bt":"תקמט-נב","dt":"תקצא - כה אב","b":"רב ואדמור בלינסק, חתן דודו ר שמואל שמלקא מרומאן. בנו ר מנחם מנדל רב בלינסק על מקומו."},{"i":14356,"n":"הורביץ, אברהם חיים מלינסק - ב","f":"מנחם מנדל מלינסק","bt":"תקצב","dt":"תרסה - כג חשון","b":"חסיד בלז. רבה של לינסק-תרכה על מקום אביו. חתן ר דובריש מאיסטריק-ליטוביסק וחתן ר ישכר דובריש בר.. מבניו, ר שמעון, ר יעקב דיין בלינסק, ר אליעזר."},{"i":14357,"n":"הורביץ, אברהם חיים מפלנטש","f":"משה מרוזבדוב","k":"אדמור מפלנטש","bt":"תרי","dt":"תרעט - כט תשרי","b":"חתן הגביר ר בצלאל ויברגר מדוקלא. רבה של פלנטש ואדמור שם. גורש ע\"י השלטונות ועבר לרדומישל ושימש כאדמור. ברח לוינה בזמן מלחה\"ע ה-I, ומשם עבר לרישא-תרעא. כתביו אבדו בשואה. בניו: ר דוד מפשצלוב, ר אליעזר מפלנטש. חתניו: אחיינו-ר אפרים הורביץ מרוזוודוב, ר אלימלך בן אב\"ד יאסלו, ר יואל טיטלבוים בעל \"ויואל משה\"-האדמור מסטמר."},{"i":14358,"n":"הורביץ, אברהם יואל","f":"צבי יהושע הורביץ"},{"i":14359,"n":"הורביץ, אברהם יעקב יוקל מלבוב","f":"אלעזר","b":"ראבד בלמברג-תקנט. רב בזלוזיץ-תקסה, על מקום אביו."},{"i":14360,"n":"הורביץ, אברהם יעקב מארה\"ב","b":"רב קהלת \"בית אל\" באולבני-ניו יורק."},{"i":14361,"n":"הורביץ, אברהם יצחק מארה\"ב","dt":"תרפג - ה אדר","dp":"ניו יורק","b":"מחכמי לעפלא-פלך ויטבסק, היגר לארה\"ב."},{"i":14362,"n":"הורביץ, אברהם יצחק מסינסינטי","k":"בעל עמק יהושפט","bp":"שצוצין","b":"רב בסינסינטי. פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג."},{"i":14363,"n":"הורביץ, אברהם יצחק מצעשינוב","f":"יעקב יוקל עזריאל","dt":"תרכט - לפני","b":"רב בצעשינוב, אב\"ד הולשיץ. (נקרא בטעות ר אברהם ישכר). נפטר ללא ילדים. בן אחיו הדפיס ממנו דרוש בספרו \"עת ספוד\"."},{"i":14364,"n":"הורביץ, אברהם מזלישטשיק","f":"אלעזר","bt":"תקץ","dt":"תרלא","b":"היה מועמד לרבנות על מקום אביו אך טבע עם משפחתו. 2 הספדים ממנו בספר \"עת ספוד\"."},{"i":14365,"n":"הורביץ, אברהם מזעלין ודמביץ","f":"אליהו מזעלין","bt":"תרמה","dt":"תשב","b":"נכד הצדיק מדזיקוב. חתן ר שמואל הורביץ אב\"ד דמביץ. הרבה להתבודד. נספה בשואה."},{"i":14366,"n":"הורביץ, אברהם מלצקובה","b":"רב בלצקובה-תרכד עד תרנח, ור שלמה יעקב שיין על מקומו אחריו."},{"i":14367,"n":"הורביץ, אברהם מפוזנא","f":"ישעיה מפפד\"מ","bt":"תכט","bp":"לייפניק","dt":"תקד - יט אלול","dp":"פפד\"א","b":"מצאצאי השל\"ה. רב בפוזנא-תעד. חתן ר אברהם הלוי ברסלא - רב בפוזנא. עבר לאמשטרדם והדפיס בה ספרי זקנו. נדד כדי למכור את הספרים. בניו: ר צבי מדרוגטשין, ר ישעיה מלמברג - ממנו משפחת הורביץ בסטניסלב, ר זאב וולף מאלטונא, ר יהודה בליטא."},{"i":14368,"n":"הורביץ, אברהם מפקשיבניצה","f":"יחיאל מפוקשבניצא","k":"אדמור מפקשיבניצה","bt":"תרן","dt":"תשג","dp":"בוכניה","b":"חתנו של ר משה אליקים בריעה אונגר מדומברובא. אב\"ד ואדמור בפקשיבניצה וראש ישיבה שם. נספה בשואה."},{"i":14369,"n":"הורביץ, אברהם מפרג","f":"שבתי שפטל","k":"בעל חסד לאברהם","bt":"שט","bp":"פרג","dt":"שסה","b":"אבי השל\"ה. תלמיד הרמ\"א והמהרש\"ל, רב בכמה עיירות בפולין, עבר ללבוב(=למברג). בנו ר יעקב משברשין הו\"ל את ספר אביו \"חסד לאברהם\" עם \"ברית אברהם\" לובלין שלז עם הסכמת המהרש\"א."},{"i":14370,"n":"הורביץ, אברהם מקראקא","f":"משה יהושע","bt":"תע","dt":"תקלב - כו סיון","b":"חתנו של ר שמעון דנציג הסופר מקראקא. ראב\"ד בקראקא על מקום חמיו."},{"i":14371,"n":"הורביץ, אברהם מקראקא","f":"יהושע","dt":"תקלב - כו ניסן","dp":"קראקא","b":"מלמד תורה בקראקא. בנו - ר שרגא פיבש מקראקא."},{"i":14372,"n":"הורביץ, אברהם מרדכי מירושלים","f":"יהודה נחום","k":"בעל כבוד ירושלים"},{"i":14373,"n":"הורביץ, אברהם מרדכי מפינטשוב","f":"בנימין זאב יעקב מזרנ","bt":"תקלו","dt":"תקפד - יז אב","b":"רב בפינטשוב. בן הרב מזרנובצא וואלברום. נכד ר משה המבורגר מבנדין-גיסו של ר אלימלך מליזנסק. תלמיד החוזה מלובלין. תולדותיו ב\"יד המאיר\". בנו ר יוסף דוד."},{"i":14374,"n":"הורביץ, אברהם משצבניץ","b":"אב\"ד שצבניץ-תרסג."},{"i":14375,"n":"הורביץ, אברהם צבי הירש מבייטש","f":"אהרן מבייטש","k":"אדמור מבייטש בנ\"י","bt":"תרמז","bp":"דזיקוב","dt":"תשכא - יז אדר","b":"חתן ר אריה ליבלי רוקח מבוקובסק. רב בטורנא, עבר לניו יורק-תרעג וכיהן כאדמור מבייטש בניו יורק, ובנו ר שלום היה אדמור מבייטש על מקומו אחריו. בנו - ר משה מבייטש - ר\"מ בישיבת בובוב בטורנא. נספה בשואה."},{"i":14376,"n":"הורביץ, אברהם שמחה ממעליץ","f":"ישראל ממעליץ","k":"אדמור ממעליץ","bt":"תרן","bp":"מעליץ","dt":"תשלג - ד ניסן","b":"בזיוו\"ש חתן ר ישראל וועג מגרוסורדין-ירושלים. ניצל מהשואה-יחד ממשפחתו, ואחריה עלה לארץ וכיהן כאדמור ממעליץ בירושלים. נפטר ללא ילדים."},{"i":14377,"n":"הורביץ, אהרן הלוי","dt":"כב תשרי","b":"רב בשנות ה-ש'. בנו ר שמואל הורביץ.","bk":[["עבודת הלוי",""]]},{"i":14378,"n":"הורביץ, אהרן הלוי מויטבסק וילנ","f":"מיכאל דוד מויטבסק","dt":"תרנט - כד אדר","dp":"וילנא","b":"נכד ר אהרן הורביץ מסטרשעלע בעל \"עבודת הלוי\". חתן ר יהושע השל עפרון מוילנא ועבר לשם מויטבסק. גביר מחכמי וילנא. אחיו של ר חיים רפאל."},{"i":14379,"n":"הורביץ, אהרן הלוי מסטרשעלע","f":"משה","k":"אדמור מסטראשלא-עבודת","bt":"תקכו","dt":"תקפט - כב תשרי","b":"אביו ר משה היה מתלמידי בעל התניא. גדול תלמידיו של בעל התניא-תקמג. אדמור בסטראשלא-תקעג לחלק מחסידי רבו. חיבר \"שער היחוד והאמונה\", \"שערי עבודה\", \"עבודת הלוי\", ועוד. כמה מניגוני חב\"ד מיוחסים אליו. בנו ר מיכאל דוד ונכדו ר חיים רפאל הו\"ל את ספרו. נכדו גם ר ישראל דב פרומקין בעל \"החבצלת\"."},{"i":14380,"n":"הורביץ, אהרן הלוי מעלקוש","dt":"תסג","b":"דומ\"צ בעלקוש"},{"i":14381,"n":"הורביץ, אהרן הלוי משקוד","f":"יוסף","k":"בעל מעלה בית חורין","bp":"ליטא","dt":"תקלט","dp":"ברלין","b":"שהה בקניגסברג, פרג, רב בשקוד-ליטא-תקך ור צבי הירש זק מפוסוואל על מקומו אחריו, האזינפוט(=האזנפוט)-קורלנד, דיין בברלין-תקלח אצל ר צבי הירש מלונדון וברלין. מתומכי מנדלסון והסכים על ביאורו לקהלת, הסכים גם על \"עמודי בית יהודה\" לר יהודה אסיא מוילנא, \"חקי חיים\" תקלז, ועוד. חיבר חדושים על הש\"ס, פירוש להגדה של פסח בשם \"מטה אהרן\" - בהגדה \"מעלה בית חורין\" ביאליסטוק תקסו. תשובות אליו ב\"נודע ביהודה\"."},{"i":14382,"n":"הורביץ, אהרן יהודה ליב מרומניה","k":"בעל רומניה ואמריקה","b":"היגר לארה\"ב, התישב בברלין. חיבר ספר במטרה לשכנע את יהודי רומניה להגר לארה\"ב."},{"i":14383,"n":"הורביץ, אהרן מבוסטון","f":"משה שלמה","bt":"תרכט","bp":"סיוויר-פלך וילנא","b":"ממשפחת הגר\"א, ור ישראל סלנטר. תלמיד ר אליהו יצחק מוילנא, ר יהושע קאלאב, ר יעקב יוסף מניו יורק. נסמך מאת: ר יצחק יעקב ריינס. חתן ר אברהם הרמן. היגר לארה\"ב-תרנא, וכיהן כרב בפאוטאקעט-רוד איילנד, בוסטון-תרנט בקהלת \"בני אברהם\", ממיסדי ישיבת \"עץ חיים\" - ישיבת רבי יצחק אלחנן. סגן נשיא כנסת הרבנים בארה\"ב, ממיסדי המזרחי בארה\"ב."},{"i":14384,"n":"הורביץ, אהרן מבייטש","f":"מאיר מדזיקוב","k":"אדמור מבייטש","bt":"תרי","dt":"תרפז - יב אד\"א","b":"אחיו של ר יהושע האדמור מדזיקוב, חתן ה\"דברי חיים\", וביזוו\"ש חתן אחיו ר נפתלי חיים. רב ואדמור בבייטש-תרמו, ובזמן מלחה\"ע ה-I עבר לקאשוי. חתנו - האדמור מפשמישל. (י\"א תאריך פטירתו - תרעז)"},{"i":14385,"n":"הורביץ, אהרן מוילנא","b":"דיין בוילנא. חתם שני אחרי ר אהרן טייבילס ברוידא-תרג."},{"i":14386,"n":"הורביץ, אהרן מזמיגרוד","f":"סיני","b":"רב בזמיגרוד-תרצח."},{"i":14387,"n":"הורביץ, אהרן מלוזוב","b":"אב\"ד לוזוב, תשובה אליו ב\"שו\"מ\". (יש אומרים שהיה בנו של ר נפתלי מרופשיץ ולא כך הוא)."},{"i":14388,"n":"הורביץ, אהרן מסימהלי","f":"יושיע","dt":"תש","b":"חסיד צאנז. שו\"ב בסמיהלי-הונגריה."},{"i":14389,"n":"הורביץ, אהרן משלם זלמן מפרג","f":"ישעיה מפרג","k":"זלמן ישעיה'ס - מונק","bt":"רל","dt":"שה - ה אלול","b":"גביר עשיר - אבי המשפחה אחר פטירת אביו. קיבל כתב מהמלך לודביג - שבכל עת יהיו בפרג שני מנהיגים ורב ממשפחת הורביץ - הדבר עורר כנגדו מחלוקת בראשות האב\"ד ר אברהם ב\"ר אביגדור - ולתווך הגיע השתדלן ר יוסף איש רוסהיים. בנה ביכ\"נ מפואר לזכר אשתו נחמה בת ר מנחם ונקרא \"פנחס שול\". בניו: ר ישראל, ר משה, ר שמואל אב\"ד דובנא ולובמלא - זקנו של החכם צבי. אחיו - ר פנחס מפרג וקראקא."},{"i":14390,"n":"הורביץ, אהרן סגל מזולקווא","f":"יהודה ליב","b":"מחכמי זולקווא, חתם-תנו בפנקס הקהלה."},{"i":14391,"n":"הורביץ, אורי מוילנא","f":"יעקב","b":"רב בוילנא בזמן רבנות ר משה קרמר, חתם-תסח על פסק דין עם ר יצחק בן אריה ליב ריאען."},{"i":14392,"n":"הורביץ, אליהו הלוי מלאבאווא","b":"חתנו של ר יעקב פרייא. רב בלאבאווא-תרנט."},{"i":14393,"n":"הורביץ, אליהו חיים יוסף מקליעא","f":"שבתי שפטל מקליעא","bt":"תרטז","b":"מו\"צ בקליעא-בסרביה-תרנה על מקום אביו שעלה לארץ."},{"i":14394,"n":"הורביץ, אליהו מזלין","f":"נפתלי חיים מדזיקוב","bt":"תרך","dt":"תרף","b":"גדל והתחנך אצל קרובו ר יהודה ליבר בבלוזוב (ולפי אלפסי היה גם חתנו), ואצל ר יואליש בנו. חתן רחמ\"י מברנוב ומקורב לרצ\"א מבלוזוב. רב בגאראיעץ, אב\"ד זלין-תרמו ובנו ר מנשה על מקומו אחריו, בסוף ימיו ברישא. בנו ר חיים צבי"},{"i":14395,"n":"הורביץ, אליהו מחודרוב","f":"דוד אב\"ד סטניסלב","dt":"תשג","b":"רבה של חודרוב-תרצד. נספה בשואה."},{"i":14396,"n":"הורביץ, אלימלך","dt":"תשג","b":"רב בקרקא"},{"i":14397,"n":"הורביץ, אלימלך מיברוב","f":"יעקב מלינסק","bt":"תרעא","dt":"תשנה","b":"חסיד בלז. תלמיד דודו ר פיביש מיברוב ור מיכל זולקוור - שניהם בבלז. ותלמיד ר יעקב בוימל בלינסק. חתן ר אהרן דוד רוזנפלד ב\"ר שלום מקמינקא. רב ביריטשוב. ניצל מהשואה והיה בטשקנט. עבר לפרג, פריז ולונזון. בעזרת דודו ר יצחק מיברוב הגיע לארה\"ב-תשז, וכיהן כרב ואדמור בניו יורק."},{"i":14398,"n":"הורביץ, אלימלך ממעליץ","f":"נפתלי","k":"אדמור ממעליץ","bt":"תרמא","dt":"תשב","dp":"רדומישל","b":"חתן רצ\"ה הורביץ מרוזוודוב. רב במלעיץ-תרע בחיי אביו ובהמשך אדמור. עזב בגלל המחלוקת, ועבר לניו יורק והיה מחכמיה, היה ידוע בניגוניו ואף הוציא תקליט של ניגוניו. חזר לפולין וויתר על כס הרבנות לטובת אחיו ר מנחם מנדל, ועבר לקראקא, בתרצא חזר לשמש כאדמור בקראקא. נספה בשואה (כשצלילי ניגון חדש על \"נשמת\" נשמעים מפיו). בניו ר נפתלי ור אברהם אביש-נספו בשואה."},{"i":14399,"n":"הורביץ, אליעזר אלימלך מדולינא","f":"משה מנחם","k":"בעל כנפי יונה","bt":"תרי","bp":"מיידן-מרמורוש","dt":"תרעה","b":"חתן ר יהושע הורביץ מפודקמין. רב בדולינא. חיבר \"כנפי יונה\" למברג תרמד, ועוד. ?? לא באוצר - שם מופיע תחת מנחם עזריה מפאנו ??"},{"i":14400,"n":"הורביץ, אליעזר הלוי","f":"צבי הורביץ","bt":"תקסז","dt":"תרג - י תמוז","dp":"לובלין"},{"i":14401,"n":"הורביץ, אליעזר הלוי מחנצ'ין","f":"חיים שמואל מחנטשין","k":"אדמור מקילץ חנטשין","bt":"תרכו","dt":"תרעט - ה סיון","b":"מצאצאי החוזה מלובלין. חתן ר משה יוסף באויהל. אדמור בקילץ - בזמן מלחה\"ע ה-I, ואחיו ר שלום על מקומו אחריו."},{"i":14402,"n":"הורביץ, אליעזר הלוי מטרניגרד","f":"יעקב משינאווא","k":"בעל נועם מגדים","bt":"תק","dt":"תקסו","b":"תלמיד המגיד מזלוטשוב, ור אלימלך מליזנסק, ור משולם פיבש מזבארז, ותלמיד חבר לחוזה מלובלין ולמגיד מקוזניץ. רבה של טרניגרד. בזיוו\"ש חתן ר ישראל משולם זלמן אשכנזי נכד החכם צבי. חיבר \"נועם מגדים וכבוד התורה\" למברגד תקסז, ועוד. חיבר גם \"אמרות טהורות\" על תהלים."},{"i":14403,"n":"הורביץ, אליעזר הלוי ממיר","f":"משה יהושע הורביץ","b":"רב במיר,הורדנא(=הורודנא)-תקמ."},{"i":14404,"n":"הורביץ, אליעזר ליפא מסטניסלב","f":"ישראל אברהם","bt":"תקפה","dt":"תרסה","b":"רב בסטניסלב, חתן ר מנחם מנדל ויינברגר מדוקלא."},{"i":14405,"n":"הורביץ, אליעזר ליפמן","bt":"1815","bp":"וילנא","dt":"1852","b":"הו\"ל \"פרחי צפון\" ושם גם מחקרו על \"תולדות מלאכת השיר\". חיבר ב\"ציון\" \"חקירות של ספר איוב\"."},{"i":14406,"n":"הורביץ, אליעזר ליפמן מוילנא","f":"חיים בן משה הלוי","bt":"תקע","bp":"וילנא","dt":"תריא - יד חשון","dp":"וילנא","b":"מחכמי ריגא, מנהל ביהמ\"ד למורים בוילנא. השתתף בכתיבת \"פרחי צפון\" יחד עם חברו רש\"י פין, ושם גם מחקרו על \"תולדות מלאכת השיר\". חיבר ב\"ציון\" \"חקירות של ספר איוב\". נפטר בחיי אביו."},{"i":14407,"n":"הורביץ, אליעזר מבוזנוב","f":"יהושע השל","b":"רב בצורטקוב, בוזנוב, יתכן שאביו היה רבה של יאנוב או רוהטין."},{"i":14408,"n":"הורביץ, אליעזר מדזיקוב","f":"נפתלי צבי מרופשיץ","k":"אדמור מדזיקוב","bt":"תקן","bp":"דוקלא","dt":"תרכא - ג חשון","b":"חתן הגביר ר יחיאל איכל רוזנפלד מרווה-רוסקה. רבה של דזיקוב ואדמור. חיבר \"דמשק אליעזר\" בכתב יד וציוה שלא להדפיסו - אבד בשואה. ספר \"קדושת אליעזר\" לר אברהם כהנא אודות תורותיו ומעשיות ממנו - וארשא תרץ."},{"i":14409,"n":"הורביץ, אליעזר מטרנוב","f":"יצחק","bt":"תק","dt":"תקע","b":"רבה של טרנוב-תקן."},{"i":14410,"n":"הורביץ, אליעזר מטשאבא","f":"משה אפרים","bt":"תקסח","bp":"תרכב - טז טבת","b":"תלמיד החת\"ס. רב בטשאבא-תקצט. תשובה אליו ב\"חתם סופר\"."},{"i":14411,"n":"הורביץ, אליעזר מלומזה","b":"פרסם מאמרים ב\"דבר בעתו\" - וארשא תרצט."},{"i":14412,"n":"הורביץ, אליעזר ממליץ","f":"יהודה","k":"אדמור ממעליץ","bt":"תרצג","dt":"תשנז","b":"ניצל מהשואה ועלה לארץ עם עלית הנוער. למד בפוניבז. חתן ר ירוחם ברנשטין - ר\"מ בחיי עולם. עבר לארה\"ב וכיהן כאדמור ממליץ. מחותן עם האדמורים משאץ, שינאווא, רצפרט."},{"i":14413,"n":"הורביץ, אליעזר מניישטאט","f":"צבי-בן החוזה מלובלין","dt":"תרג - י תמוז","b":"נכד החוזה מלובלין. חתן ר יוסף ברוך \"היהודי הטוב\" מנישטאט. תלמיד ר ישכר בער מרדושיץ. נפטר צעיר אחר פטירת רבו."},{"i":14414,"n":"הורביץ, אליעזר ניסן מצפת","f":"נפתלי חיים מדזיקוב","bt":"תרל","dt":"תרעו - ב תמוז","dp":"ירושלים","b":"בנו של הצדיק הפלאי. עלה לארץ והיה מחכמי צפת וירושלים. חתן ר יעקב כהנא אב\"ד חצי-עמר. בתו - צירל, וחתנו מזיוו\"ר - ר מרדכי אדלר, ובזיוו\"ש האדמור ר ברוך מסערעט ויזניץ. נכדו - האדמור מסערט ויזניץ חיפה."},{"i":14415,"n":"הורביץ, אליקום גציל מקלם -הזקן","f":"יצחק","bp":"קלם","dt":"תרלג","b":"חתן ר מרדכי בן דוד מוילקי וסרניק. רב באסטרין, קלם על מקום ר יחזקאל. כונה \"השלחן ערוך\" כי ידע בע\"פ כל חלקי השו\"ע. היה בעל כשרון ציור. חתנו ר יצחק הורביץ על מקומו אחריו, והיה מחלוקת על כך עד שהתערב ר ישראל סלנטר וסוכם שר יצחק יהיה מורה הוראה ולרב נבחר ר אליעזר גורדון. חיבר גם \"תורת המצוה\" עם הערות מאת האדר\"ת, \"זכרון ירושלים\". עמד בקשרי שו\"ת עם המהרש\"ם, האדר\"ת - שהביא ממנו בספרו \"עובר אורח\". דור 7 להשל\"ה. נכדו - ר אליקום בעל \"כבוד חכמים\". גיסו של ר יואל יצחק קצנלנבוגן בעל \"זרע יצחק\"."},{"i":14416,"n":"הורביץ, אליקום גציל מקלם -הנכד","f":"יצחק משאוולי ורדזיוי","b":"הו\"ל ספר אביו - \"כבוד חכמים\". דור 9 לשל\"ה."},{"i":14417,"n":"הורביץ, אלישע מדעש","f":"נפתלי צבי מדעש","k":"בעל זכרון אלישע-תשיג","bt":"תרס","bp":"דעש","dt":"תשה - כז תשרי","dp":"מחנה גוזן-אוסטריה","b":"נכד ר משה פאנט מדעש. תלמיד קרובו ר יעקב אלימלך פאנט בדעש, ר יוסף משה מייזלש, ור מרדכי בריסק בטשאנד. חתן ר אברהם צבי גינצלר מהומנא. מחכמי ביסטריץ, מגיד בדעש-תרצה על מקום אביו ומחזיק בישיבה. נספה בשואה, וכתביו אבדו. חיבר \"זכרון אלישע\" ונדפס בתוך \"זכרון יעקב\" לר יעקב פאנט - נ\"י תשיג."},{"i":14418,"n":"הורביץ, אלישע מקרוטשין","b":"מחכמי קרוטשין-תרנט."},{"i":14419,"n":"הורביץ, אלכסנדר סנדר מסטניסלב","b":"מחכמי סטניסלב. גיסו של ר\"א הלפרין."},{"i":14420,"n":"הורביץ, אלעזר מבוזנוב","b":"רב בבוזנוב-תרכג."},{"i":14421,"n":"הורביץ, אלעזר מבראווע (=בארוב)","f":"נפתלי","bt":"תרמב","dt":"תשב","b":"חתן דודו הגביר ר משה קנר מסאנוק ועבר לשם, ובזיוו\"ש חתן ר גרשון וינשטוק וגיסו של בעל \"קול דודי\". רבה של בארווע(=בארוב), רב ואדמור במעליץ. נספה בשואה. בניו ר אברהם אביש מידלובא, ור יעקב - נספו בשואה."},{"i":14422,"n":"הורביץ, אלעזר מגרודזיסק","f":"אברהם חיים מפלאנטש","k":"אדמור מטרנוב","bt":"תרמא","bp":"רוזבדוב","dt":"תשג - י כסלו","b":"חתן ר מאיר יהודה שפירא מבוקובסק (משושלת דינוב). רבה של גרודזיסק-תרסט, טרנוב אחרי מלחמת העולם הראשונה. אדמור בטרנוב אחר פטירת אביו והקים שם ישיבה. נספה בשואה. בניו ר משה מפלאנטש, ר דוד מגרודזיסק."},{"i":14423,"n":"הורביץ, אלעזר מוינה","f":"דוד יהושע השל מפלוס","k":"בעל יד אלעזר","r":"רב בוינה מ' שנה נפטר בן סד","bt":"תקסד","bp":"פלוס (בייערן)","dt":"תרכח - כא סיון","dp":"וינה","b":"תלמיד החת\"ס שהזכירו בספרו. מצאצאי בעל ההפלאה (כשהגיע לישיבת החת\"ס - ציוה למצוא לו מקום דירה ראוי לנכדו של בעל ההפלאה). חתן ר שלמה שפיגל מצעלים ועבר לשם. רבה של פרוינקירכן על מקום אביו. רב בוינה-תקפט. מחותן עם ר שלמה שפיגל מצעהלים. חיבר \"עלה נידף\" כנגד הספר \"נשק בר\", \"יד אליעזר\" וינה תרל. אביו חיבר \"בגדי קודש\". הו\"ל ספר זקנו (בעל אור חדש) - \"חקר הלכה\". פרסם מאמרים ב\"אוצר חכמה\" - לבוב תרך, \"כבוד הלבנון\" - ירושלים תרכג, \"פליטת סופרים\" - וילנא תרכג.","bk":[["יד אלעזר – שו\"ת",""],["יד אלעזר",""]]},{"i":14424,"n":"הורביץ, אלעזר מזלוזיץ","f":"יעקב עזריאל מברדיטשב","bt":"תקע","dt":"תרם","b":"רב בזלוזיץ. בנו ר זאב על כסאו אחריו אחר פטירת בנו הגדול ר אברהם."},{"i":14425,"n":"הורביץ, אלעזר מזלוזיץ","f":"יצחק מאה\"ו","bt":"תק","dt":"תקעג - ט אדר","b":"חתן ר שאול מאמשטרדם. רבה של שטרזיץ, אב\"ד-זלוזיץ-תקלז, בנו ר אברהם יעקב רב על מקומו אחריו."},{"i":14426,"n":"הורביץ, אלעזר מטורנא","dt":"תשג","b":"אדמו\"ר מגרדזינסק-טארנא"},{"i":14427,"n":"הורביץ, אלעזר ממליץ","dt":"תש","b":"רב במיעליץ"},{"i":14428,"n":"הורביץ, אלעזר מפרשבורג","b":"תלמיד החת\"ס. הקים בי\"ס לבנות. חיבר ספר לימוד דת לבנות בגרמנית עם הסמכה מהחת\"ס. לימד עברית את הנסיכה האוסטרית דורותיה - שכונתה \"הנסיכה היהודית\" - בגלל התענינותה ביהדות ובעברית."},{"i":14429,"n":"הורביץ, אלעזר מרוהטין","f":"משלם ישכר","k":"בעל דבר הלכה","bt":"תקפד","bp":"זלוזיץ","dt":"תרכו או תרכט","b":"חתן ר אפרים פישל הורביץ אב\"ד מונקטש. רב מריאמפול-תריא, רוהטין-תריב. חיבר \"דבר הלכה\" למברג תרכג."},{"i":14430,"n":"הורביץ, אלעזר משה הלוי מפינסק","f":"צבי הירש הורביץ","k":"בעל אהל משה","bt":"תקעח","dt":"תרנ - ו אב","b":"תלמיד ר ליבלה מקובנא. רב בפינסק-תר או תריט עד תרן. פרסם מאמרים ב\"תבונה\" - ממל-קניגסברג תרכא, \"מכילתא דרבנן\" - אודסה תרמו. חתניו - ר ברוך אפשטין בעל \"תורה תמימה\", בעל \"שערי דעה\". היה נערץ ע\"י גדולי דורו והחזון איש אמר עליו כי היה הגדול שבדורו (סיפר עליו שהגויים בקשו ממנו לדרוך על שדותיהם כדי שיתברכו).","bk":[["אהל משה",""],["הגהות ראמ\"ה – ש\"ס",""]]},{"i":14431,"n":"הורביץ, אלעזר משה מקראקא","f":"חיים אריה ליב מקראקא","k":"בעל טוב עין","bt":"תרכח","dt":"תשג","b":"רב בקראקא. חיבר \"טוב עין\" קראקא תרצה. נספה בשואה. פרסם מאמרים ב\"הכוכב\" - מונקטש-נ\"י תרצה, \"רבותינו שבגולה\" - פרשבורג תרעה."},{"i":14432,"n":"הורביץ, אלתר אליעזר מבייטש","f":"אהרן מבייטש","bt":"תרן","dt":"תרצז - יב אדר","dp":"קאשוי","b":"רב בקאשוי על מקום אביו, ובייטש על מקום אביו. חתן ר יוסף ריינמן מאיסטריק, ובזיוו\"ש חתן ר משה יהודה ליב מטסריזוב (משושלת דינוב)."},{"i":14433,"n":"הורביץ, אלתר אליעזר מריגליץ סט","f":"אברהם שמחה מבארנוב","bt":"תרל","dt":"תשג - כט חשון","b":"ממשפחת אדמורי רופשיץ-דזיקוב. חתן ר משה אפשטין בן ר קלונימוס קלמן מניישטאט. רב בריגליץ, סטאשוב. נספה בשואה."},{"i":14434,"n":"הורביץ, אלתר זאב (דב) מסטריזוב","f":"אברהם אבא משנדישוב","bt":"תריד","dt":"תרץ - יד ניסן","b":"חתן ר סנדר רדימישלר ממעליץ. רב בסטריזוב-תרמב כיובל שנים. מקורב לאדמורי בלז. היה בעל תפילה ומלחין ובצעירותו חיבר כל שבוע ניגון חדש ל\"ברוך אל עליון\". (באלפסי-נפטר תרף). חתנו - ר יהושע השל איכנשטין."},{"i":14435,"n":"הורביץ, אלתר יחזקאל מברוקלין","dt":"תשנד","dp":"ניו יורק","b":"חתן האדמור מקשנוב. תלמיד ר ראובן גרוזובסקי ור אהרן קוטלר."},{"i":14436,"n":"הורביץ, אלתר יחזקאל מדזיקוב","f":"יהושע הורביץ","k":"אדמור מדזיקוב","bt":"תרמה-לט","bp":"דזיקוב","dt":"תשג - ז אד\"ב","dp":"פלאשוב","b":"חתן דודו ר ישראל מויזניץ. רב בדזיקוב-תרסט,טרנוב-אחרי מלחה\"ע ה-I, הקים ישיבת \"בית דזיקוב\". ביקר את חסידיו באנגליה ובאנטורפן-תרצז. נספה בשואה. מתורתו ב\"זכרון יחזקאל\" בסוף \"עטרת ישועה\". מבניו: ר מאיר מרישא, ר יעקב מטורנא."},{"i":14437,"n":"הורביץ, אלתר ישעיה מדמביץ","f":"ראובן מדמביץ","bt":"תרז","dt":"תרנה - כז טבת","b":"רבה של דמביץ על מקום אביו. נפטר ללא ילדים ואחיו ר שמואל מילא את מקומו אחריו."},{"i":14438,"n":"הורביץ, אלתר מאיר מסטוטשין","f":"יצחק מסטוטשין","b":"אב\"ד סטוטשין-תרסד."},{"i":14439,"n":"הורביץ, אלתר מפקשובניצא","f":"יחיאל מפוקשבניצא","dt":"תש..","b":"חתן ר אברהם משה מרוספשא (משושלת פשעדבורז). רבה האחרון של פוקשבניצא, טרנוב. נספה בשואה."},{"i":14440,"n":"הורביץ, אלתר מריגליץ","f":"אברהם חיים הורביץ","b":"רב בריגליץ-תר\"פ"},{"i":14441,"n":"הורביץ, אפרים מאוסציא","b":"אב\"ד אוסציא-תרנט."},{"i":14442,"n":"הורביץ, אפרים מצורטקוב","f":"משה","k":"בעל יבקש רצון","b":"רב בצורטקוב-תקצד, וולוטשיסק-תקצד, פולטושאן-תרו. חיבר פירוש על מדרש שוחר טוב בשם \"יבקש רצון\" למברג תריא. גיסו - ר נחמן אליעזר רוזנצויג מצורטקוב. בנו ר יהודה ליב מפולטושאן - אליו בטוט\"ד."},{"i":14443,"n":"הורביץ, אפרים מרוזוודוב","f":"צבי הירש מרוזוודוב","dt":"תרצב או תשג","b":"חתן דודו ר אברהם חיים הורביץ מפלנטש. רב ברוזוודוב-תרעט על מקום אביו, נדד באירופה וחזר לרוזוודוב-תרץ. נספה בשואה (ולפי אלפסי נפטר תרצב). חתנו ר אליעזר שפירא."},{"i":14444,"n":"הורביץ, אפרים פישל","f":"עזריאל","b":"חתן ר מאיר ר זלמנס."},{"i":14445,"n":"הורביץ, אפרים פישל מליסיעץ","f":"דוד","bt":"תרן","dt":"תשג","b":"רב בליסיץ-תרף. חתן ראי\"ה השל משופישטיניץ. נספה בשואה."},{"i":14446,"n":"הורביץ, אפרים פישל ממונקטש","f":"יעקב יוקל","bt":"תקן","dt":"תרכא - יח כסלו","b":"חתן ר דוד הורביץ מלעשנוב. רב בבוליחוב לצד אביו, רבה של מריאמפול, אב\"ד לינסק, ראב\"ד מונקטש-תרג."},{"i":14447,"n":"הורביץ, אפרים פישל ממריאמפול","f":"אלעזר","bt":"תרכג","bp":"רוהטין","dt":"תרסג","dp":"וינה","b":"רבה של מריאמפול-תרנא."},{"i":14448,"n":"הורביץ, אריה יהודה ליבוש מצפת","f":"שלום מאליק","bt":"תק","bp":"זברז'","dt":"תקעג - כג תמוז","dp":"צפת","b":"מתלמידי המגיד ממזריטש. חתן ר יוסף יוסקא מאליק (ובזיוו\"ש נשא את אמו של המלבי\"ם - וכנראה לא נכון). רב בזבארז, ולוטשיסק, רב ביאס-תקנב על מקום ר מרדכי ב\"ר משה חיים אך מינה את בנו ר יוסף יוסקא תחתיו, עלה לצפת-תקסו או תקלז. (תמך בר נחמן מברסלב במחלוקת עם הסבא משפולה). בניו ר חיים אורי פייבש חתן ר משה אפרים (בן אחיו של הבת עין) או חתן ר נחמן מברסלב, ר פנחס זאב. תשובה ממנו ב\"עגונת ישראל\" למגיד מקוזניץ. ר פנחס זאב חתן ר נחמן מברסלב, ר שלום יקותיאל יחיאל. חתניו: ר צבי בן החוזה מלובלין, ר דוד קופיל בן ר ישראל בן החוזה, ר ישעיה יהודה ליב מקרוסנא. בהיותו בשנת תקנב בקהילת דרהיי הסכים על הספר \"אהבת דודים\" לר בנימין מזלוזיץ, הסכים על \"טהרת הקדש\" לגר\"א-תקסד."},{"i":14449,"n":"הורביץ, אריה ליב הלוי מזרנווצי","f":"ראובן הורביץ","b":"רב בזרנווצי"},{"i":14450,"n":"הורביץ, אריה ליב מזולקוא","f":"יהושע הארוך מפרמישלא","b":"מראשי קהלת זולקוא, חתם-תם על תקנה שלא להניח את ר מאיר כץ מקאליש לשבת בעיר זולקוא, חתם גם-תמט עם ר הלל בעל \"בית הלל\"."},{"i":14451,"n":"הורביץ, אריה ליב מזטל והנובר","k":"בעל מרגניתא טבא","bp":"ליטא","dt":"תעז - ד תשרי","dp":"זאטל-פולין","b":"מכונה בשם 'ר ליבל זעטלער'. יליד ליטא ורב בכמה קהלות בגרמניה ובהם הנובר, זעטיל-פלך סלונים, ראש ישיבה במינסק, זאטל-פולין. לפי \"יהדות ליטא\" תאריך פטירתו - תקי."},{"i":14452,"n":"הורביץ, אריה ליב מזלוזיץ","b":"רבה של זלוזיץ-תרלד."},{"i":14453,"n":"הורביץ, אריה ליב מירושלים","k":"ליב לומז'ר","b":"דיין בירושלים. עורך \"תורת ציון\" - ירושלים תרכב - המאסף התורני הראשון בירושלים."},{"i":14454,"n":"הורביץ, אריה ליב מירושלים","f":"משה","bp":"ירושלים","dt":"תרסט - כז אדר","dp":"ירושלים","b":"אחד משבעת המיסדים של שכונת \"נחלת שבעה\" בירושלים."},{"i":14455,"n":"הורביץ, אריה ליב מסטניסלב","f":"אלעזר מזלוזיץ","k":"בעל פני אריה","bt":"תקכ","dt":"תרד - כט כסלו","dp":"טיסמניץ","b":"חתן דודו ר ישכר שטרן ובזיוו\"ש חתן רצ\"ה מאה\"ו בעל תפארת צבי. נסמך מר משולם איגרא (אחד מהשלושה שסמך בכל ימיו). רבה של סטניסלב-תקעד במשך כששים שנה. בצוואתו ציוה שעל כסאו ישבו רק צאצאיו וכך היה במשך מאה וחמשים שנה. היה מתנגד לחסידות ולמרות זאת היה נכבד אצל גדולי החסידות וגם אצל הגר\"א. חיבר \"פני אריה\" פשמישל תרלז. מתורתו ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":14456,"n":"הורביץ, אריה ליב מסטרי","f":"יצחק","k":"בעל הרי בשמים","bt":"תרז","bp":"קריסנפולי","dt":"תרסט - כא סיון","b":"חתן הגביר ר משה וקס מסרעט ובזיוו\"ש חתן ר שאלתיאל איזיק שטרנהל מקולומיאה. רב בזלוזיץ-תרלא, סטרי-תרלח, ובסטניסלב-תרסד על מקום אביו. חיבר \"הרי בשמים\" למברג תרמג.","bk":[["הרי בשמים – שו\"ת",""]]},{"i":14457,"n":"הורביץ, אריה ליב מקראקא","b":"רב בקראקא. תשובה אליו ב\"ובחרת בחיים\". פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":14458,"n":"הורביץ, אריה ליב מרדושקביץ","b":"מו\"צ ברדושקביץ"},{"i":14459,"n":"הורביץ, אריה ליבש הלוי מירוסלב","f":"יעקב הורביץ","b":"דיין הגדול ביערוסלב-תק\"ס"},{"i":14460,"n":"הורביץ, אריה ליבש הלוי מירוסלב","f":"שמואל שמלקא הורביץ","b":"רב ביערוסלב"},{"i":14461,"n":"הורביץ, אריה ליבש מלנצהוט","f":"(חיים דב מרודניק)","bt":"תקפח","dt":"תרסג","b":"רב ברודניק ואחר כך ראב\"ד לנצהוט ובנו ר יעקב ישב על כסאו אחריו."},{"i":14462,"n":"הורביץ, אריה מאיר מבלוזוב","f":"אליהו מזלין","dt":"תשג","dp":"בלוזוב","b":"אב\"ד בלוזוב. נספה בשואה. תלמידו - ר אליקים גצל שיף ונסמך ממנו (הסמיכה גרמה להצלת משפחה מסיביר - ה שערים)."},{"i":14463,"n":"הורביץ, אשר ישעיה מרימנוב","f":"מאיר מדזיקוב-אמרי נע","k":"אדמור מרימנוב","bt":"תרך","dt":"תרצה - כד חשון","dp":"וינה","b":"חתן האדמור ר יוסף פרידמן מרימנוב. רב ואדמור ברימנוב על מקום חותנו. ובזיוו\"ש חתן ר גרשון וינשטוק מקיטוב. עבר לקראקא ולוינה. עבר לניו יורק-תרעט וחזר לקראקא. היה מחבר ניגונים ויחד עם האדמור מבובוב נחשב לעמוד התווך של הנגינה החסידית בגליציה. בנו ר צבי חיים מילא את מקומו אחריו. חיבר \"מעדני מלך\" ברטפלד תרעג. חתנו האדמור יצחק פרידמן מסדיגורא-רימנוב. (ברבני אמריקה מופיע שנפטר - יג חשון)."},{"i":14464,"n":"הורביץ, אשר לעמיל משנדישוב","f":"טוביה","k":"בעל שערי חיים","bt":"תרמו","dt":"תרצג - י סיון","b":"רב בשנדישוב על מקום אביו. חתן ר נפתלי ממעליץ. בנו ר מנחם מנדל על כסאו אחריו. חיבר גם \"שו\"ת מהרא\"ל\". ?? לא באוצר ??"},{"i":14465,"n":"הורביץ, אשר מקוסוב","f":"יעקב מהורדנא","b":"חתן ר זונדל טרוויש מוילנא. רב בקוסוב. בנו - ר אברהם מוילנא-חתנו ר ישראל קלצקי מוילנא."},{"i":14466,"n":"הורביץ, אשר מרוזוודוב","b":"רב ברוזוואדוב-תר\"ל"},{"i":14467,"n":"הורביץ, בוך מזגורז'","b":"אב\"ד זגורז' (ליד סנוק), גבאי ארץ ישראל."},{"i":14468,"n":"הורביץ, בילה אשת ר יוסף מוינה","f":"בער בן חזקיה הלוי","k":"בעל געיכטע דעמ הויזע","b":"מגולי וינה. חיברה-תסה \"געישכטע דעם הויזעס דוד\", וביחד עם רחל את ר ליב פארגעס ספר על קורות היהודים בפרג בשם \"איינע שאנע געשיכטע..\", חיברה גם תחינה בלשון אשכנז לעשרת ימי תשובה."},{"i":14469,"n":"הורביץ, בן ציון ממאדין","f":"טוביה ממאדין","bt":"תרכה","dt":"תש","dp":"רישא","b":"לאחר שנתייתם גדל אצל דודו ר יוהשע מדזיקוב. חתן ר פנחס רבינוביץ מקינצק (משושלת פשיחסא). רב במיידן(=מאדין) על מקום אביו. נספה בשואה."},{"i":14470,"n":"הורביץ, בן ציון מפרשוביץ","dt":"תשג","b":"רב בפרשוביץ"},{"i":14471,"n":"הורביץ, בנימין זאב סגל סירקש","k":"בעל פנים חדשות","dt":"תפז","b":"דומ\"צ בקראקא-תנה, רב בוואדיסלב-תסא. הסכים על 'תולדות יעקב' לר ייעקב אילנבורג. לדעת וייס היה גם בפרשבורג."},{"i":14472,"n":"הורביץ, בנימין מדריסוויאט","f":"יהודה","bt":"תרלא","b":"תלמיד ישיבת וולוזין, וילנא. רב בדריסוויאט-פלך קובנא-תרנז."},{"i":14473,"n":"הורביץ, בנימין מטולצ'ין","b":"חתן ר עקיבא שלום חיות מדובובא, והו\"ל כמה מכתביו."},{"i":14474,"n":"הורביץ, בצלאל מפילזנא","f":"נפתלי חיים מדזיקוב","k":"אדמור מדזיקוב פילנזא","bt":"תרכה","dt":"תרס","b":"בנו השני של ה\"צדיק הפלאי\". חתן ר ראובן מדמביץ. רב ואדמור מדזיקוב בפילזנא, ובנו ר מנשה על מקומו אחריו."},{"i":14475,"n":"הורביץ, ברוך הלוי משברשין","f":"יעקב יואל יוקל","dt":"תרמד - ח אייר","b":"רב בשעברעשין"},{"i":14476,"n":"הורביץ, ברוך יהושע הלוי מאלקס","bt":"תרל","bp":"פונידאל-מחוז ראקישוק","dt":"תרצו - א תשרי","b":"תלמיד ישיבות פוניבז, סלובודקה וראדין. תלמיד ר איצה'לה מפוניבז, והחפץ חיים. חתן ר שרגא פיבל פרנק מאלקסוט, וגיסם של ר משה מרדכי אפשטין, ור איסר זלמן מלצר. רב באלקסוט-תרס על מקום ר נפתלי אמשטרדם, ר\"מ בסלובודקה. מגדולי דורו. בזמן הכיבוש הגרמני במלחה\"ע ה-I נשאר בליטא ודאג לפתיחתה של ישיבת סלובודקה בעזרת חוגי חרדים בגרמניה. ממייסדי אגודת הרבנים בליטא, בשליחות בארה\"ב-תרפט. פרסם מאמרים רבים במאספים שונים. רוב חיבוריו אבדו בגיטו קובנא בזמן השואה. בנו ר שרגא ר\"מ בסלובודקה. מאמר לתולדותיו ב\"היהודי\" - נ\"י תרצו מאת ר אפרים ברמן מנ\"י. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"תבונה\" - קובנא תרפא. מתורתו בספר הזכרון \"אש תמיד\"."},{"i":14477,"n":"הורביץ, ברוך מזגורז","b":"חתן ר פנחס יוסף קנר מזגורז. רב בזגורז על מקום חותנו."},{"i":14478,"n":"הורביץ, ברוך מליזנסק","f":"נפתלי","bt":"תרסא","dt":"תשטו - כד כסלו","b":"חתן ר יצחק איזיק איכנשטין מפודהייץ, ובזיוו\"ש חתן ר חנה (אלחנן) ר מלכ'ס וייסבלום מליזנסק. רב בליזנסק-תרפג על מקום חותנו. הוגלה לסיביר והצליח להגיע לארה\"ב אחרי השואה."},{"i":14479,"n":"הורביץ, ברנדרד","bt":"1861","bp":"קובנא-פאנימון","dt":"1949","dp":"שיקגו","b":"עסקן ציוני. היגר לארה\"ב-1880. מייסד האגודות הציוניות בשיקגו. חבר הקונגרס היהודי באמריקה. נשיא הפדרציה של מוסדות הצדקה בשיקגו."},{"i":14480,"n":"הורביץ, גבריאל המלאך ממוגלניצא","f":"דוד","k":"אדמור מוארשא","dt":"תריח - ט אב","b":"תלמיד המגיד מקוזניץ, ור אברהם יהושע השל מאפטא. העתיק וסידר את כתבי רבו המגיד מקוזניץ. נסע גם אל ר משה אליקים בריעה מקוזניץ, ואל ר חיים מאיר יחיאל ממוגלניצא. דיין במוגלניצא. אדמור בוארשא."},{"i":14481,"n":"הורביץ, דב בער מנובואלכסנדרובס","f":"צבי","k":"בעל מפיק מרגליות","b":"רב בנובו-אלכסנדרובסקי. בניו - ר יצחק וב בנימין הו\"ל את ספרו - וילנא תרן."},{"i":14482,"n":"הורביץ, דב בער מנעשויז וביאליס","k":"בעל נחלת הלוים","b":"רב בנעשויז, ביאליסטוק. בנו - ר ברוך מרדכי - הו\"ל את ספרו בירושלים תשח."},{"i":14483,"n":"הורביץ, דב בער סגל מקמניץ","f":"צבי הירש הורביץ","b":"רב בקמניץ-ת\"צ"},{"i":14484,"n":"הורביץ, דב בריש","f":"מאיר הורביץ","b":"רב-שנת-תק\"ע"},{"i":14485,"n":"הורביץ, דב בריש מקרמניץ","f":"מאיר מטיקטין","b":"רב בקרמניץ, בנו ר משולם פיבוש על מקומו אחריו."},{"i":14486,"n":"הורביץ, דב נחמן","k":"בעל חדושי בר נחמני","b":"רב בויטבסק-תר\"ע"},{"i":14487,"n":"הורביץ, דוד הלוי איש","f":"יהושע העשל הורביץ","b":"רב-שנת תק\"צ"},{"i":14488,"n":"הורביץ, דוד הלוי מוינה","f":"פנחס מפולדא","dt":"תכא - יג שבט","b":"דיין בוינה, רב בקהילות מהרין."},{"i":14489,"n":"הורביץ, דוד יהושע השל מפרונקיר","f":"צבי הירש-מחנה לוי","dt":"תקפו - ב כסלו","b":"נכד ר פנחס בעל ההפלאה. חתן ר אליעזר קאלין בעל \"אור חדש\". רב בפרונקירכן. חתנו - חיים וולף בן ר יונתן מטאפאלשוין (שעיגן את אשתו ואף השתמד)."},{"i":14490,"n":"הורביץ, דוד מגרודזיסק","f":"אלעזר מגרודזיסק","dt":"תשג - יז אייר","b":"רב בגריבוב, גרודזיסק על מקום אביו שעבר לטרנוב. חתנו של ר מרדכי זאב הלברשטם מגריבוב-צאנז. נספה בשואה."},{"i":14491,"n":"הורביץ, דוד מדוקלא","b":"רב בדולקא וקריסנפולי. נסמך להוראה - תרצב. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":14492,"n":"הורביץ, דוד ממעליץ","f":"נפתלי"},{"i":14493,"n":"הורביץ, דוד מסטניסלב","b":"פרסם מאמרים ב\"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב, \"קהלת אשר\" - אושפיצין תרפג."},{"i":14494,"n":"הורביץ, דוד מפשצלוב","f":"אברהם חיים מפלאנטש","k":"אדמור מרישא","bt":"תרמב","dt":"תשב","dp":"סוקולוב","b":"חתן ר שמעון אלטר פרנקל-תאומים מפודגורזע. רבה של פשצלוב=פרזיצלב ובנו ר משה על מקומו אחריו, ואחר פטירת אביו אדמור ברישא. נספה בשואה."},{"i":14495,"n":"הורביץ, הנרי","f":"ברוך מסאווראן","bt":"1886","bp":"בוטרימנץ-ליטא","dt":"1961","b":"היגר לארה\"ב עם הוריו-1892, למד משפטים בהרווארד ויסד שם את \"אגודת מנורה\". עורך כתב העת \"מנורה\". נשיא הפדרציה של יהודי אמריקה. חיבר ספרים באנגלית בנושאים יהודיים."},{"i":14496,"n":"הורביץ, זאב וולף הלוי מאלטונא","f":"אברהם מפוזנא","bt":"תנג","dt":"תקלג-ז -יח אייר","dp":"אלטונא","b":"מחכמי אלטונא."},{"i":14497,"n":"הורביץ, זאב וולף מטרמבובלה","b":"רב בטרמבובלה, (אולי בנו של האב\"ד ר חיים אריה)."},{"i":14498,"n":"הורביץ, זאב וולף מטשיטש","b":"רב בטשיטש (ליד רישא)-תקנג."},{"i":14499,"n":"הורביץ, זאב מזלוזיץ","f":"אלעזר","b":"רב בזלזזיץ-תרם על מקום אביו."},{"i":14500,"n":"הורביץ, זלמן ישעיה","b":"בנו - ר ישראל ונכדו ר פנחס-גיסו של הרמ\"א."},{"i":14501,"n":"הורביץ, זלקינד מליטא ופריס","f":"יהודה זינדל מסאווראן","bt":"1740","bp":"זמלין-פלך קובנא","dt":"1812","dp":"פאריס","b":"גדל בקובנא, נדד מליטא והגיע לברלין, ננסי, ומיץ שם למד אצל בעל \"שאגת אריה\", עבר לפאריס וזכה שם בפרס בתחרות ספרותית - חיבורו \"היש אמצעי לעשות את יהודי צרפת מועילים ומאושרים יותר\" ונדפס אח\"כ בצרפתית. מזכיר ומתרגם בספריה המלכותית. פרסם בעתוני צרפת בענין זכויות ליהודים. השתתף במהפכה הצרפתית, במשלחת היהודית לקומונה הפאריסאית. חבר ב\"סנהדרין של נפוליאון\"."},{"i":14502,"n":"הורביץ, חזקיה הלוי מפרג","dt":"תטו - ו חשון","b":"מגדולי חכמי פרג"},{"i":14503,"n":"הורביץ, חיים","f":"יוסף אשר","b":"תלמיד רד\"צ זהמן מדוקלא. הביא לדפוס את תשובת ר יוסף אשר ארנברג - עם הערותיו והערות אחיו ר בצלאל - בסוף שו\"ת \"קב זהב\" של רבו."},{"i":14504,"n":"הורביץ, חיים אברהם","f":"משה מבוסטון","bt":"תרצג","b":"חתן ר אלעזר מזוויהל (זלוטשוב), ובזיוו\"ש חתן ר יונה האס. ראש ישיבת \"היכל הפלאה\" בניו יורק. מלחין."},{"i":14505,"n":"הורביץ, חיים אברהם הלוי מלמברג","f":"יצחק","dt":"תקל - יז תמוז","dp":"זולקוא","b":"מגיד מישרים בלבוב, נזכר בפרי מגדים."},{"i":14506,"n":"הורביץ, חיים אורי פיבוש הלוי","f":"אריה יהודה מואלטשיסק","b":"נכד ר שלום מזברז. עלה עם אביו לצפת-תקסה, וניצל מהרעש והאסונות שהיו בה. חתן ר משה אפרים בן אחיו של ר אברהם דב מאברוטש, ובזיוו\"ש חתן ר יעקב שמשון משפיטובקא. בנו ר אברהם יוסף סגל חתן ר נפתלי צבי מטבריה-נכד הבעשט. לפי מסורת חסידי ברסלב ייבם את אשת אחיו ר פנחס זאב - חתן ר נחמן מברסלב."},{"i":14507,"n":"הורביץ, חיים איסר מויטקוב","b":"רבה של ויטקוב-תרנה.."},{"i":14508,"n":"הורביץ, חיים אליעזר מקראקא","f":"מרדכי צבי הירש","k":"בעל נפש לחיים","bt":"תרסח","bp":"קראקא","dt":"תשב","b":"חתן ר מנדלי אלטר מפביאניץ. בגיל 18 החליף שו\"ת עם הרוגצ'ובר. רבה של בליכיטוב-תרצח. נספה בשואה. חיבר \"נפש לחיים\" (כולל מכתביו לרוגצ'ובר) בסוף ספר \"מנחת פרי\" של חתן אחיו. ?? לא באוצר ??"},{"i":14509,"n":"הורביץ, חיים אריה ליב מקראקא","f":"שאול-בשמים ראש החדשו","k":"בעל זכרון משה","bt":"תרי-יא","bp":"ברודי","dt":"תרסה או תרמה","b":"חתן הגיבר ר מיכאל ציפרס. יסד ת\"ת המשלב לימודי חול (הראשון במינו בגליציה), אב\"ד זולקווא-תרלט, קראקא-תרן. הוזמן לפגישות אצל הקיסר לטובת היהודים. חיבר גם \"חיי אריה\", ועוד. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"ועד חכמים\", \"יגדיל תורה\" - ברלין-קראקא תרנא.. בניו: ר מיכאל בעל \"עבודת הלויים\", ר אלעזר משה הי\"ד בעל \"טוב עין\", ר צבי בעל \"כתבי הגאונים\". חתנו - ר קלמן ברגלס."},{"i":14510,"n":"הורביץ, חיים אריה מטרמבובלה","f":"שאול","bt":"תק","dt":"תקנח - יב אייר","dp":"ברודי","b":"אימץ את שם משפחתו של סבו מצד אמו - ר איצק'ל מאה\"ו. רבה של טרמבובלה."},{"i":14511,"n":"הורביץ, חיים הלוי","f":"יהושע משה","k":"בעל נחלת חיים","b":"רב בפירינץ-מהרן. חיבר \"נחלת חיים\" פיורדא תעג."},{"i":14512,"n":"הורביץ, חיים הלוי","dt":"תרצה - יג חשון","b":"רב בגדרביץ-תר\"מ"},{"i":14513,"n":"הורביץ, חיים חייקא","f":"אהרן","b":"חיבר פירוש לחובות הלבבות, ונדפס יחד עם פירוש אחיו ר יצחק - פפד\"א תקלד."},{"i":14514,"n":"הורביץ, חיים חייקא מהורדנא","f":"שמואל שוורצר הורביץ","dt":"תלה","b":"תלמיד ר יעקב בן אפרים נפתלי אב\"ד בריסק. מגדולי חכמי דורו, רב בהרובשוב, רב בהורדנא-תטו או תכז על מקום ר יונה בעל קיקיון דיונה. ובעל \"תפארת למשה\" על מקומו אחריו. בנו - ר שמואל. אחיו של הקדוש ר צבי הירש. (ב\"יהדות ליטא\" יש טעות בתאריכים). שאלה ממנו ותשובה מרבו בענין ספק גרושה לכהן ב\"גאון צבי\" לאחיינו ר צבי הירש הורביץ."},{"i":14515,"n":"הורביץ, חיים חייקא מהורדנא","b":"רב בהורדנא. בנו ר שמחה."},{"i":14516,"n":"הורביץ, חיים יהודה מפמורן","b":"מחכמי פמורן-תרפב."},{"i":14517,"n":"הורביץ, חיים יהודה מרישא","f":"אלטר זאב","bt":"תרם","dt":"תשג","b":"רב ברישא, נקרא \"שר החוץ\" של בלז. נשא את נכדת \"המאור ושמש\"."},{"i":14518,"n":"הורביץ, חיים יעקב","f":"טוביה משנדישוב","b":"חתן ר חיים פינטר מבוקובסק. נספה בשואה."},{"i":14519,"n":"הורביץ, חיים יעקב מאולינוב","f":"חנינא מאולינוב","bt":"תריא","dt":"תרעה","b":"חתן ר משה אונגר. רבה של אולינוב-תרע אחר פטירת אביו."},{"i":14520,"n":"הורביץ, חיים יעקב מאלטשש","dt":"תשג","b":"אב\"ד אלטשטט-תרפא, אולי אחר כך אב\"ד טרווא-תרצא."},{"i":14521,"n":"הורביץ, חיים יעקב מדמביץ","f":"שמואל מדמביץ","dt":"תש..","b":"חתן הרב מפריסטיק. נספה בשואה."},{"i":14522,"n":"הורביץ, חיים יצחק מזלין","b":"מחכמי זלין-תרצה. מתורתו - \"תלפיות\"."},{"i":14523,"n":"הורביץ, חיים יצחק מרדומישל","b":"אב\"ד רדומישל קטן-תרמב."},{"i":14524,"n":"הורביץ, חיים מאיר יחיאל","f":"ישראל ממעליץ","k":"אדמור מרינזוב-סעליש.","bt":"תרלט","dt":"תשב - ד אלול","dp":"קמניץ-פודולסק","b":"רב במעליץ, אב\"ד איינזוב (ריינזוב או ראזינוב)-תרסה, אדמור בסעליש. חתן ר חנניה יו\"ט בעל \"קדושת יו\"ט\" מסיגט. אדמור בסעליש. נספה בשואה."},{"i":14525,"n":"הורביץ, חיים מאיר מפינסק וברלי","k":"בעל בית עקד האגדות","bt":"תרטו","bp":"פינסק","dt":"תרסה","b":"תלמיד ביהמ\"ד לרבנים בברלין. התישב בפפד\"מ. חיבר \"בית עקד האגדות\". הו\"ל \"קובץ מדרשים קטנים\", פירוש הראב\"ע על משלי מכת\"י עם מבוא והערות ממנו.","bk":[["אגדת אגדות",""],["בית נכות ההלכות חלק א",""],["תוספתא עתיקתא",""],["תורתן של ראשונים א",""],["תורתן של ראשונים ב",""]]},{"i":14526,"n":"הורביץ, חיים מבראנטיש","f":"יהושע סגל","k":"בעל באר מים חיים","b":"רב בברנטיש בזמן בעל \"דמשק אליעזר\". חיבר \"באר מים חיים\"."},{"i":14527,"n":"הורביץ, חיים מגדרוויץ","f":"אהרן מנחם הלוי","bt":"תרטו","b":"רב בגעדרעוויץ-תרם."},{"i":14528,"n":"הורביץ, חיים מזשילין","b":"פרסם מאמרים ב\"תלפיות\" - טרנוב תרצח."},{"i":14529,"n":"הורביץ, חיים מלונדון","k":"בעל דקדוק לשון הקדש","bp":"פולין","b":"התישב בלונדון, מדקדק. חיבר ספרים באנגלית בדקדוק לשון הקדש, ובהם - \"ראשון למקראי קדש\" לונדון 1807."},{"i":14530,"n":"הורביץ, חיים מנדל דוד מדזיקוב","f":"אלטר יחזקאל אליהו","k":"אדמור מדזיקוב","bt":"תרסד","bp":"דזיקוב","dt":"תשה - כג תשרי","b":"חתן דודו ר עמנואל מפאבניץ-לודז (משושלת פשעדבורז). רבה האחרון של דזיקוב-תרפד. הו\"ל \"עטרת ישועה\" לזקנו האדמור ר יהושע מדזיקוב. קובץ \"חמדה גנוזה\" לזכרו - ירושלים תשלה. נספה בשואה. בנו ר יהושע מבני ברק."},{"i":14531,"n":"הורביץ, חיים מקרמניץ וירושלים","f":"דב בער גינצבורג","k":"בעל חיבת ירושלים","dt":"תרד - לפני","dp":"ירושלים?","b":"תלמיד וסופר ר מרדכי מקרמניץ. עלה מעיר קרמניץ-תקעז-ט והתישב בצפת, ואחד החסידים הראשונים שהתישב בירושלים-תקפו, חיבר ספר \"חיבת ירושלים\" ירושלים תרד, בעריכת קרובו ר מרדכי הלוי הורביץ."},{"i":14532,"n":"הורביץ, חיים צבי","f":"אליהו הורביץ","b":"רב ברישא"},{"i":14533,"n":"הורביץ, חיים רפאל הלוי מסטרשלא","f":"אהרן מסטראשלא","k":"אדמור מסטראשלא","dp":"טולטשין","b":"אדמור בסטראשלא-תקף על מקום אביו. נפטר צעיר ואחריו פסקה השלשלת וחסידיו נתפזרו בין חסידי חב\"ד, לכוביץ, וילדניק, וקוידנוב."},{"i":14534,"n":"הורביץ, חיים שלמה מסטריזוב","f":"אלטר אליעזר מבייטש","k":"אדמור מסטריזוב","bt":"תרסה","bp":"סטריזוב","dt":"תשכט - כז כסלו","dp":"ירושלים","b":"נכד ר אהרן מבייטש, ור משה יהודה שפירא מסטריזוב. חתן ר רפאל גרוס מברבשט (שושלת אויהל). רב בשאמלוי-תרפט, אב\"ד זלישא-ליד מונקטש-תרצג, טימישואר-תרצו. ניצל מהשואה ואחריה הגיע לניו יורק והיה שם אדמור מסטריזוב. חיבר \"דרכי נועם\" ניו יורק תשטו."},{"i":14535,"n":"הורביץ, חיים שמואל מחנטשין","f":"אליעזר מניישטאט","k":"אדמור מחנטשין","bt":"תרג","dt":"תרעו - יח טבת","b":"מצאצאי החוזה מלובלין. חתן ר יהושע השל פרנקל תואמים בן ה\"ברוך טעם\". עבר לקילץ - בזמן מלחה\"ע ה-I. דיבר רק בלשון הקודש. בנו ר יעקב יצחק נפטר על פניו-א אייר תרסג. מתולדותיו ב\"בלבת אש\"."},{"i":14536,"n":"הורביץ, חנינא מאולינוב","f":"יעקב ממעליץ","bt":"תקפב","dt":"תרמב - ב חשון","b":"חתנ דודו ר אליעזר מדזיקוב. אב\"ד אולינוב-תרלב."},{"i":14537,"n":"הורביץ, טוביה ממאדין","f":"מאיר מדזיקוב","bt":"תרה","dt":"תרעח (ולא תרמז)","b":"רבה של מאדין-תרס, בנו ר בן ציון ישב על מקומו אחריו. בזמן מלחה\"ע ה-I ברח לוינה."},{"i":14538,"n":"הורביץ, טוביה מסאנוק","f":"בן ציון ממאדין","k":"בעל וואס פארט זיין","bt":"תרנג","bp":"מיידן","dt":"תשג - י שבט","dp":"בלזיץ","b":"גדל בויזניץ אצל דודו האדמור ר ישראל. חתן ר יהושע שפירא אב\"ד ריבטיטש. (משושלת דינוב). פעיל ב\"אגודת ישראל\" והיה מזכירו האישי של ר חיים עוזר גרודזנסקי ששימש כנשיא מועצת גדולי התורה. ממייסדי \"בית יעקב\" ובתרפד בשליחות במערב אירופה ובאמריקה למען \"בית יעקב\". רב בזלוצוב, וסאנוק-תרצג. נספה בשואה. השתתף בקבצים רבים גם כעורך. חיבר \"וואס פארט זיין מיט די כנסת ישראל\" ורשא תרפו. פרסם מאמרים ב\"יבנה\" - לבוב תרפט. ?? לא באוצר ??"},{"i":14539,"n":"הורביץ, טוביה משנדישוב","f":"אברהם אבא משנדישוב","bt":"תרכה","dt":"תשא - יב ניסן","dp":"ליד לובלין","b":"חתן ר אשר משה למל דים-חסיד רוזין. רב בשנדישוב בחיי אביו ועל מקומו אחריו ובנו ר אשר למל על מקומו אחריו. עבר לקראקא ונחשב לאחד מל\"ו צדיקים. מכתב ממנו-תרעב ב\"תשובה כהלכה\" נגד הכוללות קאסוב וויזניץ. הגיע לניו יורק-[תרע..] חתם-תרפג על אספה לחיזוק הדת, והקים שם ארגון עזרה לאלמנות ויתומים בפולין. חתם עם האדמורים בניו יורק ר מרדכי חודרוב, ר יהושע רבינוביץ ממנוסטרישץ ואחרים בענין כשרות. חזר לפולין והתישב בקראקא. (בוונדר נרשם פטירתו - תרפג, ובאוצה\"ר - תשג, וברבני אמריקה - תרצה). עוד מבניו ר מנחם דב בן ציון מפרשעוויץ, ר נפתלי צבי, ר אברהם, ר חיים יעקב מבוקובסק, ובנו או נכדו ר ישראל דוד משאץ - רב באמריקה."},{"i":14540,"n":"הורביץ, יהודה אהרן מסלאטווינא","f":"יעקב יוקל מבוליחוב","b":"חתן הגביר ר זלמן בריש רוטנברג מברודשין. רבה של סלאטווינה ושל בוליחוב על מקום אביו, רב בסאניוואץ (מיהאלען)-תריט, בנו ר נפתלי מילא מקומו בסלאטוינה אחרי שעזב."},{"i":14541,"n":"הורביץ, יהודה אסיא הלוי הרופא","f":"מרדכי","k":"בעל עמודי בית יהודה","bp":"פדובה","dt":"תקנח","dp":"הורדנא","b":"רב ורופא בוילנא וגרודנא בזמן בעל \"קרבן נתנאל\". למד רפואה בפדובה. בקי בשפות. ב\"אור החיים\" לר חיים מיכל כותב כי ר יהודה היה דיין בבית דינו של ר השל בוילנא, וחתם עם פס\"ד-תץ יחד עם ר יהודה ליב מטיקטין. ב\"פרידריכשטט קורלנד לר צבי הירש רוזנטל מופיע כי כיהן כרופא בוילנא, פאנדעל, זאגר, התישב במיטאווא(=מיטאוי)-קורלנד-תקל. חיבר שירים בעברית - בכת\"י, חיבר \"עמודי בית יהודה\" - אמשטרדם תקכה. בין המסכימים לספריו: משה מנדלסון ונפתלי הרץ ויזל."},{"i":14542,"n":"הורביץ, יהודה הלוי מלידא","f":"צבי הירש הורביץ","bt":"תד","dt":"תצא","b":"רב בלידא,וואסילישק,גליל הורדנא,ווילקומיר"},{"i":14543,"n":"הורביץ, יהודה ליב מוולאדאוי","f":"יעקב יצחק הלוי","b":"רב בוולאדאווי(=ולאדובא)-תר\"ל"},{"i":14544,"n":"הורביץ, יהודה ממעליץ","f":"יעקב ממעליץ","k":"אדמור ממעליץ","bt":"תקף","dt":"תרלט - ט טבת","b":"רב ואדמור במעליץ-תקצט על מקום אביו. תלמיד ר חיים מצאנז ודודו ר אליעזר מדזיקוב. חתן ר חיים מאיר יחיאל השרף ממוגילניצה (קוזניץ). בנו ר נפתלי רב ואדמור אחריו במעליץ. (אביו למדו לשון סתרים למכתביהם - נשמרה בידי צאצאיו). אשתו הרבנית רייזיל שרה עלתה לארץ ונפטרה בצפת כז סיון תרמג."},{"i":14545,"n":"הורביץ, יהודה מסטוטשין","f":"יצחק מסטוצין","k":"אדמור מסטוטשין","bt":"תרנב","bp":"רוזוודוב","dt":"תשמב - ט חשון","b":"חתן ר יהושע שפירא מריבטיטש ונסמך להנהגה מחו\"ז רצ\"א מבלוזוב. רב ואדמור בסטוטשין על מקום אביו שעבר לטרנוב. ניצל מהשואה ועבר לניו יורק וכיהן כאדמור מסטוטשין - הממשיך היחיד לבית רופשיץ-דזיקוב. חיבר \"מנחת יהודה\" ניו יורק תשמג."},{"i":14546,"n":"הורביץ, יהודה סגל מאונסדורף","b":"רב באונסדורף-תר\"ע"},{"i":14547,"n":"הורביץ, יהודה צבי","f":"יוסף מלינסק","bt":"תרעג","bp":"ליזנסק","b":"תלמיד ישיבת בובוב. חתן ר יעקב פסטר איזנבך. עלה לירושלים אחר השואה וכיהן כרב של גבעת שאול בירושלים. סירב לאדמורות. הדפיס את ספר \"זרע קודש\" תשיד - לזקנו ר נפתלי מרופשיץ."},{"i":14548,"n":"הורביץ, יהושע ארוך מפרמישלא","f":"פנחס או יעקב","dt":"תכא","b":"זקנם של אדמורי רופשיץ. בנו של ר פנחס גיס הרמ\"א או של ר יעקב (אחיו או בנו של השל\"ה). חיבר ניגון לשבת ששרו בחסידות רופשיץ. בניו: ר שמואל שמלקא מטרנוב, ר חיים אב\"ד ברטניץ בעל \"מים חיים\" ו\"נחלת חיים\", ר פנחס מקראקא-תל, ר יהודה אריה מזולקוא."},{"i":14549,"n":"הורביץ, יהושע הלוי מזולקוא","f":"מאיר מטיקטין","dt":"תקכז - ה טבת","dp":"זולקוא","b":"נכד ר שמואל שמלקא בן יהושע הארוך. מחכמי זולקוא. (רב בבוסק?)."},{"i":14550,"n":"הורביץ, יהושע השל","b":"רב-שנת תק\"מ"},{"i":14551,"n":"הורביץ, יהושע השל מדומברובה","f":"מנחם מניס מלבוב","b":"רב בדאמבראווי(=דומברובה)-תקכג, יוזעפוף גדול. גרש את אשתו בעל כרחה ע\"י שליח והדבר עורר מחלוקת בין כל גדולי הדור ובהם הנודע ביהודה."},{"i":14552,"n":"הורביץ, יהושע השל מחנטשין ואלק","f":"חיים שמואל מחנטשין","k":"אדמור מעלקוש","bt":"תרטז-ך","bp":"ניישטאט","dt":"תשג - ג אב","dp":"סוסנוביץ","b":"מצאצאי החוזה מלובלין. חתן ר פנחס מקינצק (פשיסחא). רב בחנטשין-תרע, אדמור בעלקוש על מקום אביו. בניו ר יוסף ברוך מחנטשין, ר נתן דוד מעלקוש."},{"i":14553,"n":"הורביץ, יהושע השל מיאנוב","f":"מנחם מנדל רובין מלינ","bt":"תקכה","dt":"תקפח - א חשון","b":"שינה שם משפחתו מרובין - ע\"ש זקנו - ר יצחק הלוי הורביץ מהמבורג. מתנגד לחסידות, חתן ר אברהם דוד מסטנוב. רב ביאנוב, עבר לברודי. (אצל וונדר תאריך הפטירה תקפה)."},{"i":14554,"n":"הורביץ, יהושע השל ממריאמפול","f":"אפרים פישל","b":"רבה של מריאפול על מקום אביו, רב ברוהטין."},{"i":14555,"n":"הורביץ, יהושע השל מרישוואל","f":"צבי הירש מצורטקוב","b":"אחיו של בעל ההפלאה. רב ברישוואל(=ריצוויל), לובלין-תקלב. הסכים על \"תפארת ישראל\" לר ישראל משקלוב."},{"i":14556,"n":"הורביץ, יהושע יצחק יאיר מדוקלא","f":"יעקב","k":"בעל אמונות ודעות","bt":"תקם","dt":"תריא- טז כסלו","b":"אב\"ד דוקלא-תקסה, רב בלמברג, ובזורובנה. חיבר \"אמונות ודעות\" למברג תריח."},{"i":14557,"n":"הורביץ, יהושע מבני ברק","f":"חיים מנחם דוד מדזיקו","b":"נכד ר עמנואל מפאביניץ-לודז (שושלת פשעדבורז). חתן ר יואל משה לנדא מליזנסק."},{"i":14558,"n":"הורביץ, יהושע מדזיקוב נ\"י","f":"מאיר מרישא","k":"אדמור מדזיקוב בנ\"י","b":"נכד ר אלתר יחזקאל אליהו האדמור מדזיקוב. חתן ר יצחק פיליפ מירושלים. אדמור מדזיקוב בניו יורק."},{"i":14559,"n":"הורביץ, יהושע מזורבנא","f":"[פנחס] מזורבנא","b":"אביו היה אב\"ד זורבנא. השתתף בועד חכמים (ציטרון)."},{"i":14560,"n":"הורביץ, יהושע מיסלו","f":"שמואל או נפת' מדמביץ","b":"חתן ר שמואל רוס מיאסלו. והיה מחכמי יאסלו. עבר לניו יורק ושימש כרב-תשי."},{"i":14561,"n":"הורביץ, יהושע מירוסלב","f":"מאיר הלוי","dt":"תקטז - ה טבת","b":"גדול בנגלה ונסתר,רב ביערוסלאב"},{"i":14562,"n":"הורביץ, יהושע מירושלים","b":"מחבורת המקובלים בירושלים-תשיב, מתלמידי ר יהודה אשלג בעל הסולם."},{"i":14563,"n":"הורביץ, יהושע ממעליץ","f":"יהודה","k":"אדמור ממעליץ-דזיקוב","b":"אדמור מעליץ-דזיקוב בטורנא על מקום אביו. חתן ר יעקב ארנברג. נספה בשואה."},{"i":14564,"n":"הורביץ, יהושע מניו יורק","f":"שמואל מדמביץ","b":"נכד ר יחיאל וגשל מפריסטיק-מצאצאי ר אלימלך מליזנסק, ור ראובן הורביץ מדמביץ-דזיקוב."},{"i":14565,"n":"הורביץ, יהושע מסוקולוב","b":"חתן ר אברהם אב\"ד קורטשין. אב\"ד סוקולוב."},{"i":14566,"n":"הורביץ, יהושע מפרמישלא","f":"פנחס הלוי","k":"ר' יהושע הארוך","dt":"ת'","b":"רב בפרעמיסלא. בנו - ר אריה יהודה מזולקוא."},{"i":14567,"n":"הורביץ, יהושע משה אהרן מקוזניץ","f":"שמואל שוורצר הורביץ","dt":"ג טבת","b":"רב בקוזניץ"},{"i":14568,"n":"הורביץ, יהושע משקלוב","f":"צבי הירש הלוי","k":"ר יהושע הורביץ חריף","bt":"תקפג","dt":"תרנ - ה אדר","b":"רב בשקלוב, על מקום ר הלל מיליקובסקי שויתר לו על הרבנות - לאחר שירד מנכסיו ונזקק לכך."},{"i":14569,"n":"הורביץ, יהושע פאלק","f":"שמעון","bt":"תקצו","dt":"תרנז - סיון","b":"ראש ישיבה באשמינא-פלך וילנא. מו\"צ בואנטאקליא-פרבר וילנא, טרוקי-תרל, וינדאווי-תרלו. הניח חדושים בכת\"י."},{"i":14570,"n":"הורביץ, יואל מזולקוא","f":"יעקב - אחי השל\"ה","b":"מחכמי זולקוא, חתם-תעד עם ראשי קהלת זולקוא."},{"i":14571,"n":"הורביץ, יואל מיסלו","b":"מחכמי יסלו. חתן ר משה ציטרוננבוים מזמיגרוד. מתורתו \"הכוכב\"-תשיב."},{"i":14572,"n":"הורביץ, יואל מירושלים","f":"שאול הלוי","k":"בעל כרם חמד","dt":"תרעא","dp":"ירושלים","b":"מחכמי ירושלים, חיבר \"כרם חמד\" ירושלים תרסג."},{"i":14573,"n":"הורביץ, יואל מסטניסלב","f":"אלכסנדר","k":"בעל ובא הלוי","bt":"תקצט","bp":"סטניסלב","dt":"תרעב - בערך","b":"חתן רש\"ז מרגולין מפאריטש. עבר לאנטורפן. חיבר \"ובא הלוי\" לונדון תרע."},{"i":14574,"n":"הורביץ, יואל מרישא","b":"רב ברישא. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":14575,"n":"הורביץ, יוסף","f":"משה סגל(14590)","b":"חתן ר מנחם מאניש מוילנא(13344). רב-שנת תל. בנו - ר ברוך חריף(4089), חתנו או בנו - ר וולף ר יוזפיש-חותנו של ר דוד לידא."},{"i":14576,"n":"הורביץ, יוסף ברוך מחנטשין","b":"פרסם מאמרים ב\"הכרם\" - וארשא תרפז."},{"i":14577,"n":"הורביץ, יוסף גרשון מירושלים","bt":"תרכה","dt":"תשיא - יג ניסן","b":"רב במאה שערים בירושלים על מקום דודו - הרב מדוברובנה, דיין אצל ר צבי פסח פרנק."},{"i":14578,"n":"הורביץ, יוסף דב מליסקוב וארה\"ב","f":"צבי גדליהו","k":"בעל דברי יוסף","bt":"תרלח","bp":"קלעצקאווא","dt":"תשיג - יד אלול","b":"תלמיד ישיבות לומזה, בריסק, איישישוק, וילנא. נסמך מאת: ר צבי הירש מה יפית, ר יצחק יעקב ריינס, ר חיים סולוביציק. רב בליסקובה-תרסג, היגר לארה\"ב-תרסו וכיהן כרב בסנט פאול-מינסוטה-ארה\"ב. חיבר גם \"קדושת יוסף\". חבר אגודת הרבנים באמריקה, תנועת המזרחי, עסקן צבור."},{"i":14579,"n":"הורביץ, יוסף זרח ממונקטש","b":"גביר במונקטש. הקדיש סכום גדול ובית מדרש לקהלה. גיסו - ר יוסף זלמן אסטרייכר ממונקטש."},{"i":14580,"n":"הורביץ, יוסף יוזל מנווהרדוק","f":"שלמה זלמן מפלונגיאן","k":"הסבא מנווהרדוק","r":"הסבא מנוברהדוק","bt":"תרח","bp":"פלונגיאן","dt":"תרפ - יז כסלו","dp":"קיוב - ירושלים","b":"תלמיד ר ישראל סלנטר בממל. הסתגר בבית נידח ועסק בלימוד תורה ומוסר, והמשכילים כינוהו \"בעל החוריים\" - בגלל החורים שדרכם הכניסו לו אוכל. מגדולי המוסר ומרביצי התורה. הקים ישיבה בנוברדוק, ויסד רשת ישיבות ברחבי רוסיה ואוקראינה. חיבר \"מדרגת האדם\".","bk":[["מדרגת האדם","מחשבה ומוסר - אחרונים"],["מדרגת האדם בדרכי החיים",""],["מדרגת האדם בחשבון הצדק",""],["מדרגת האדם ביראה ואהבה",""],["מדרגת האדם בתיקון המדות",""],["מדרגת האדם בתקופות העולם",""],["מדרגת האדם א. בבקשת השלמות. ב. בדרכי החיים. ג. ביראה ואהבה. ד. בנקודת האמת. ה. בתקופת העולם",""],["מדריגת האדם",""],["מדרגת האדם (הסבא מנובהרדוק)",""]],"e":"תר\"י-תר\"פ"},{"i":14581,"n":"הורביץ, יוסף יוזפא מהרובישוב","f":"ברוך חריף","b":"רב בהרובישוב"},{"i":14582,"n":"הורביץ, יוסף יונה צבי מאונסדור","f":"יהודה","k":"בעל חגוי הסלע","dt":"תשכה-ל","dp":"בני ברק","b":"נכד(-אבי אמו) ר שמואל רוזנברג מאונסדורף בעל \"באר שמואל\", ולמד אצלו. חתן ר ישעיה זילברשטין מוויצען. רב באונסדורף-תרעט על מקום זקנו וראש הישיבה שם, רב קהל \"עדת ישורון\" בפפד\"מ-תרפט, עבר ללונדון-תרצט, ארה\"ב ויסד בבורו פארק את ישיבת \"באר שמואל\", עלה לבני ברק-תשכ. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב."},{"i":14583,"n":"הורביץ, יוסף יוסקא מיאס","f":"אריה יהודה מואלטשיסק","bt":"תקכ","dt":"תקסז - ט שבט","dp":"יאס","b":"ביקר בילדותו אצל המגיד ממזריטש. תלמיד ר פנחס מקוריץ. חתן ר יוסף משה ב\"ר אליעזר ממזריטש. רב ביאס - ובהכתרתו השתתף ר לוי יצחק מברדיטשוב, ועל מקומו אחריו ה\"אוהב ישראל\". נפטר בחיי אביו. חתנו ר שמשון מאוזיראן (זבאריז)."},{"i":14584,"n":"הורביץ, יוסף ישעיה מפרג","f":"יצחק אייזיק הורביץ","dt":"שפו","b":"דיין הגדול בפרג"},{"i":14585,"n":"הורביץ, יוסף מאוסציא","f":"משלם ישכר","k":"בעל אלון בכות","bt":"תר","bp":"סטניסלב","dt":"תרנח","b":"אב\"ד אוסציא-תרמד, זיילונא, ראב\"ד סטניסלב. חיבר \"אלון בכות\" דרהביטש תרמח. חתן ר דוד ויטלש אב\"ד בוברקא."},{"i":14586,"n":"הורביץ, יוסף מאיר מסעלש","dt":"תשד","b":"רב בסעליש"},{"i":14587,"n":"הורביץ, יוסף מבוליחוב","f":"[מנחם מנדל]","dt":"תשב","b":"רב בבוליחוב. נספה בשואה."},{"i":14588,"n":"הורביץ, יוסף מביאלא","b":"רב בביאלא-תקפ\"ט"},{"i":14589,"n":"הורביץ, יוסף מגלינא ונ\"י","bt":"תרי","dt":"תרעה","b":"נגד הרב מזלוזיץ. חתן ר אפרים מגלינא. פרסם בקובצים שונים. עבר לארה\"ב ושימש כרב ברונזוויל ובניו יורק-תרסא. פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":14590,"n":"הורביץ, יוסף מזרשין וסנוק","f":"יחיאל","bt":"תרכז","bp":"זרשין","dt":"תשב","b":"חסיד רוזין ובויאן. רב בסאנוק. נספה בשואה."},{"i":14591,"n":"הורביץ, יוסף מחירוב","b":"רב בחירוב-תרכב. תשובה אליו ב\"שו\"מ\"."},{"i":14592,"n":"הורביץ, יוסף מטורטשין","f":"החוזה מלובלין","k":"אדמור מלובלין","bt":"תקמב","dt":"תקעח","b":"חתן ר מרדכי מקוריץ. רב בטורטשין-תר. לפי מסורת אחת ראהו אביו כיורשו באדמורות. חתנו - ר נחום ממאקרוב."},{"i":14593,"n":"הורביץ, יוסף מטרניגרד","f":"אברהם אליעזר הורביץ","dt":"תקפט","b":"רב בטארניגרד"},{"i":14594,"n":"הורביץ, יוסף מיאסי","f":"אריה יהודה ליבוש","b":"רבה של יאסי. ר לוי יצחק מברדיטשוב מחותנו של אביו בא להכתרתו."},{"i":14595,"n":"הורביץ, יוסף מפלנטש","b":"רב בפלנטש-תרצג. תשובה אליו ב\"דובב מישרים\"."},{"i":14596,"n":"הורביץ, יוסף מפרמישלא","dt":"תנ","b":"גדול בדורו,מראשי דד\"א בפולין,ראב\"ד בפרמיסלא"},{"i":14597,"n":"הורביץ, יוסף מקראס","f":"נפתלי צבי","bt":"תרך","dt":"תש","dp":"לינסק","b":"חסיד שינאווה. רב בקראס. חתן ר אלישע לנדא מקראס ועבר לשם. ממשתתפי \"אהל מועד\"."},{"i":14598,"n":"הורביץ, יוסף שלמה שבתי","f":"יהודה ליב מולאדאוי","bt":"תרכא","b":"מצאצאי החוזה מלובלין. רב בזאמוטשט-פלך לובלין-תרמט. נסמך מאת: ר חיים אלעזר וקס בעל \"נפש חיה\", ור צבי הירש תאומים מוולאדווי."},{"i":14599,"n":"הורביץ, יחזקאל אליהו מדזיקוב","f":"יהושע","k":"אדמור מדזיקוב","bt":"תרמה","dt":"תשג","b":"חתן דודו ר ישראל הגר מויזניץ. רבה של דזיקוב בחיי אביו ואף החל לנהוג אדמורות. עבר לטרנוב והיה שם אדמור מדזיקוב. הזהיר את חסידיו עוד לפני השואה לברוח מפולין. נספה בשואה. חיבר \"זכרון יחזקאל\" ירושלים תשלו (בתוך הספר \"עטרת ישועה\")."},{"i":14600,"n":"הורביץ, יחזקאל מארה\"ב","f":"אלישע","b":"ניצל מהשואה ועבר לארה\"ב. אב\"ד קהילת צאנז במונסי. מחותן עם האדמור מבובוב."},{"i":14601,"n":"הורביץ, יחזקאל מקראס","f":"אלישע","b":"נכד ר נפתלי צבי הורביץ מקראס - מכתב ממנו-תרנו - לרגל נישואיו, ב\"דברי יחזקאל\"."},{"i":14602,"n":"הורביץ, יחיאל אהרן מחנטשין","f":"יעקב יצחק בן חיים","b":"מצאצאי החוזה מלובלין. נכד ר חיים שמואל מחנטשין. חתן דודו ר אליעזר מחנטשין."},{"i":14603,"n":"הורביץ, יחיאל מאיר מרינזוב","f":"ישראל","dt":"תשד","b":"רב בריינוב(=ריינזוב)-סעליש-תרסד."},{"i":14604,"n":"הורביץ, יחיאל מיכל","f":"נפתלי הירץ מברזאן","b":"חתן ר צבי ר ישעיה מהליטש."},{"i":14605,"n":"הורביץ, יחיאל מיכל דוד מקראקא","b":"רב בקראקא. חתן ר יוקל הורביץ. בנו ר פנחס זלמן בעל \"אהבת תורה\"."},{"i":14606,"n":"הורביץ, יחיאל מיכל זאב","f":"אורי","k":"בעל גידולי ציון","b":"רב שכונת כנסת ישראל בירושלים."},{"i":14607,"n":"הורביץ, יחיאל מיכל מברניזוב","f":"ישראל הורביץ","bt":"תרלט","b":"רב בראניזוב-תרס\"ד"},{"i":14608,"n":"הורביץ, יחיאל מיכל מיפו","b":"רב ביפו. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"הדביר\" - ירושלים תרעט, \"ועד חכמים\" - ירושלים תרפג, \"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\", \"קול תורה\" - ירושלים תרץ, \"תורת ארץ ישראל\" - ירושלים תרץ, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":14609,"n":"הורביץ, יחיאל מיכל ממעליץ","b":"רב במעליץ ועבר להיות רב בפולין-תרלט. תשובה אליו ב\"הרי בשמים\"."},{"i":14610,"n":"הורביץ, יחיאל מיכל מפרוכניק","f":"יעקב הורביץ","b":"רב בפראחניק-תק\"פ"},{"i":14611,"n":"הורביץ, יחיאל מפקשיבניצה","f":"מאיר מדזיקוב","k":"אדמור מדזיקוב בטורנא","bt":"תרי","dt":"תרפח - י שבט","dp":"דזיקוב","b":"חתן ר דוד הלברשטם מקשנוב. אביו האדמור מינהו לרב בפקשיבניצה (מול דזיקוב)-תרם, גורש ע\"י השלטונות ועבר לטורנא."},{"i":14612,"n":"הורביץ, יחיאל מרישא","f":"אברהם זאב וולף","k":"בעל ועבד הלוי","bt":"תר","dt":"תרפה","b":"מו\"ל מחכמי רישא. חיבר \"ועבד הלוי\" מונקטש תרע. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":14613,"n":"הורביץ, יעקב","f":"אלעזר מבארוב","b":"אחיו של ר אברהם אביש מידלובא. חתן ר אריה ליביש מרדכי משינאווא (צאנז). נספה בשואה."},{"i":14614,"n":"הורביץ, יעקב אליהו מקראקא","f":"אברהם אריה הלוי","b":"מכתב ממנו-תרלד, לר\"א גוטמכר."},{"i":14615,"n":"הורביץ, יעקב חיים מנאויפולי","f":"יהושע הורביץ","b":"רב בנאוויפאלי-תק\"מ"},{"i":14616,"n":"הורביץ, יעקב יהושע מזלוזיץ","f":"צבי הירש","bt":"תקל","dt":"תרב - כז טבת","b":"גדל אצל זקנו בעל ההפלאה. חתן רא\"ז מרגליות מברודי. רבה של זלוזיץ ושב לברודי. מתורתו בספר חותנו \"בית אפרים\". השאיר חבור על התורה - נמצא אצל האדמור מקרלין. מתורתו בכר\"ש - תשמא, ועוד. חתנו - ר שלמה זלמן זוסמן מאוסטרהא."},{"i":14617,"n":"הורביץ, יעקב יוסף הכהן מולאדוב","f":"שמואל אליהו","bt":"תרכג","b":"תלמיד ר זלמן סנדר מקריניק. רב מגרש זאמד בלובלין-תרנב-תרסו, סירב לרבנות בעלשזיץ וסלאואטישץ, רב בוולאדובקה(=ולאדווקי)-פלך גרודנא-תרסו. נסמך מאת: ר שניאור זלמן מלובלין בעל \"תורת חסד\", ר אליהו קלצקי ממאריאמפול בעל \"אבן הראשה\". חתנו - ר מאיר אשר גרינברג מקוזמיר."},{"i":14618,"n":"הורביץ, יעקב יוסף מאלקסניץ","f":"יצחק מברודי","bt":"תקא","dt":"תרא - טז טבת","dp":"ברודי","b":"רב באלקסניץ. נפטר בגיל מאה.חתן דודו ר שמואל ב\"ר יעקב באב\"ד מברודי. בנו ר צבי הירש מברודי - חתנו של ר שלמה נפתלי צוזמיר מצורטקוב."},{"i":14619,"n":"הורביץ, יעקב יוקל הלוי מברודי","f":"אריה ליבש הורביץ","b":"רב בברודי-ת\"ר"},{"i":14620,"n":"הורביץ, יעקב יוקל מבוליחוב","f":"מנחם מנדל רובין מלינ","bt":"תקלג","dt":"תקצב - כה אייר","b":"אחיו של ר נפתלי מרופשיץ. התחבר למשכילים וחזר בתשובה. בזיוו\"ש חתן ר נחום צויזמיר מסטרי, ואחר כך חתן ר אברהם הלוי מבראד. אב\"ד בוליחוב-תקפד."},{"i":14621,"n":"הורביץ, יעקב יוקל מבוליחוב","f":"מאיר מטיקטין","k":"יוקל בעל שם","bt":"תלט","bp":"בוליחוב","dt":"תקטו - יג אלול","b":"רב בבוליחוב-תעא על מקום אביו. רב בגלוגא חתן ר השל מטרלא נכד הרבי ר השל. רב בברודי-תצה על מקום ר אלעזר רוקח שעבר לאמשטרדם (ונאלץ לשלם מס לשר העיר בסך 8000 זהובים). לחם בשבתאות ונאלץ להשתתף בויכוחים עם הנוצרים. היה מהגדולים שבפניהם נאלץ ר יונתן איבשיץ להצדיק עצמו (במחלוקת עמדין). (קיבל עדות שאשת רא\"ל ברנשטין - רב המדינה - אישה נואפת ואסורה לבעלה - ועקב כך נדרש מהשלטונות לעזוב את הרבנות - לדעת ראובן מרגליות הסיפור אינו נכון והמדובר באישה אחרת), עבר לכהן כרב בגלוגא-תקו. נספד בספר \"דברי רב משלם\". היה בין שלשת הדיינים שמונו לפסוק במחלקות היעב\"ץ ור יונתן איבשיץ. בתו - אשת ר שבתי הכהן רפפורט מקרסני - חיברה ספר \"תחינת אמהות\". בניו: ר יצחק מאה\"ו, ר מנחם מניש מלמברג-גיסו של הנודע ביהודה."},{"i":14622,"n":"הורביץ, יעקב יוקל מדלטין","f":"משלם ישכר","k":"בעל אבני השהם","bt":"תקצד","dt":"תרעה","dp":"סטרי","b":"רבה של דלטין-תרכא, סטניסלב. חיבר \"אבני השהם\" למברג תרם, ועוד."},{"i":14623,"n":"הורביץ, יעקב יוקל מוילקוביסק","b":"רב בוילקוביסק-תקן בערך על מקום ר ישראל קצנלנבוגן."},{"i":14624,"n":"הורביץ, יעקב יוקל מזלוזיץ","f":"אליעזר הורביץ","b":"רב בזלזיץ-תק\"פ"},{"i":14625,"n":"הורביץ, יעקב יצחק","f":"חיים שמואל מחנטשין","dt":"תרסג - א אייר","b":"מצאצאי החוזה מלובלין. נפטר צעיר בחיי אביו."},{"i":14626,"n":"הורביץ, יעקב יצחק הלוי","f":"משלם זושא הורביץ","b":"רב-שנת ת\"ר. בנו - ר יהודה ליב מולאדואי"},{"i":14627,"n":"הורביץ, יעקב יצחק מוולדובה","b":"נכד החוזה מלובלין. רב בוולדובה. מגדולי חסידי קוצק - בזמן מחלת רבו עזב את קהילתו ושהה במחיצת האדמור כמה חדשים."},{"i":14628,"n":"הורביץ, יעקב יצחק מרדומישלא","f":"חיים דוב מרודניק","bt":"תר","dt":"תרס","b":"חתן ר יוסף יוסקי בן בן ציון וסטרייך מקנטשוגה. רב ברודניק, רדומישלא-תרכד, רב בקנטשוגה על מקום חותנו. בנו היה ר משה אהרן אב\"ד ריינזוב."},{"i":14629,"n":"הורביץ, יעקב יצחק מריגליץ","f":"אברהם אבא","bt":"תרמז","bp":"ריגליץ","dt":"תש","dp":"צרפת","b":"חתן ר חיים יצחק ירוחם. רב בלימנוב. ריגליץ על מקום אביו. ברח מהנאצים ונפטר בצרפת."},{"i":14630,"n":"הורביץ, יעקב מאיר","f":"פנחס בעל ההפלאה","bt":"תקטז","dt":"תקמב","b":"חתן ר שאול אב\"ד אמשטרדם. מחדושיו בסוף \"ההפלאה\"."},{"i":14631,"n":"הורביץ, יעקב מאיר מפינסק","f":"משה ברוך","bt":"תרטו","bp":"שאד","b":"נכד-אבי אמו ר גרשון בעל \"עבודת הגרשוני\". דומ\"צ בפינסק-תרמה אצל ר אליעזר משה. נסמך מאת: המלבי\"ם, ר יצחק אלחנן מקובנא, ר ליפמן מביאליסטוק בעל \"עונג יו\"ט\"."},{"i":14632,"n":"הורביץ, יעקב מברוד","b":"מגדולי ברודי-תק\"פ"},{"i":14633,"n":"הורביץ, יעקב מדוקשיץ ומינסק","b":"גביר מראשי הקהלה במינסק-תר בערך. חתנו - ר ישעיהו זכריה יולס בעל \"דובר מישרים\"."},{"i":14634,"n":"הורביץ, יעקב מדלטין","b":"רב בדלטין-תרם, טרנוב-תרסד."},{"i":14635,"n":"הורביץ, יעקב מויזניץ","dt":"תקעח","dp":"ראווה","b":"חתן ר\"ש מנ\"ש. רב בויזניץ, קטלבורג (ליד פרשבורג)."},{"i":14636,"n":"הורביץ, יעקב מוילנא","f":"אברהם מוילנא","b":"דרשן, מג\"מ בוילנא-תרל. אחיו של ר שאול חיים בעל \"כלילת שאול\"."},{"i":14637,"n":"הורביץ, יעקב מזולקוא","b":"נאמן קהלת זולקוא, חתם בפנקס הקהלה."},{"i":14638,"n":"הורביץ, יעקב מטורנא","f":"אלתר יחזקאל מדזיקוב","b":"אחיו של ר מאיר מרישא-שנספה בשואה."},{"i":14639,"n":"הורביץ, יעקב מלינסק","f":"אברהם חיים מלינסק -ב","k":"אדמור מליסקא","bt":"תרל","dt":"תשג - יא תשרי","b":"ראב\"ד ואדמור בליסקא (=לינסק). חתן ר אלימלך רובין מיברוב (רופשיץ). נספה בשואה."},{"i":14640,"n":"הורביץ, יעקב מלנצהוט","f":"אריה ליב","bt":"תרלה","bp":"לנצהוט","dt":"תשה","b":"רב בלנצהוט על מקום אביו. אב\"ד דיסלדורף, עלה לארץ לפני השואה וכיהן כרב בתל אביב."},{"i":14641,"n":"הורביץ, יעקב ממעליץ","f":"נפתלי צבי מרופשיץ","k":"אדמור ממעליץ רופשיץ","r":"אב\"ד קלבסוב ומעליץ","bt":"תקמד","dt":"תקצז - יט טבת","b":"חתן ר פישל מפינטשוב (שעלה לארץ). רב בקולבסוב, רב ואדמור במעליץ-תקצד. נקרא על ידי חסידיו בשם \"בעל שם טוב קטן\" - בגלל מופתיו. חתן ר אברהם מרדכי מפינטשוב. חיבר \"זרע יעקב\" ניו יורק תשנד. תולדות אדמורי מעליץ בספר \"בית היי\"ן\" מהנכד ר אהרן הלברשטם - ניו יורק תשמט.","bk":[["זרע יעקב",""]]},{"i":14642,"n":"הורביץ, יעקב מניו יורק","k":"בעל רוח יעקב","bt":"תריט","bp":"נוברדוק","dt":"תרצו","dp":"ניו יורק","b":"תלמיד ר יצחק אלחנן בקובנא. היגר לארה\"ב וכיהן כרב בניו יורק-תרנח. תומך בציונות, פרסם מאמרים ודרשות גם בענין הציונות."},{"i":14643,"n":"הורביץ, יעקב מפיעטריקוב","f":"ישראל מוויסליץ","dt":"תשב","dp":"טרבלינקה","b":"נכד ר מנחם מנדל מלינסק. חתן ר מאיר מנחם מרדושיץ. נספה בשואה."},{"i":14644,"n":"הורביץ, יעקב מפפד\"מ","f":"מרדכי הורביץ","b":"רב בפפד\"מ-תרע\"א"},{"i":14645,"n":"הורביץ, יעקב מקולבסוב","f":"נפתלי מראפשיץ","b":"רב בקלבסוב,מליץ-תר\"כ"},{"i":14646,"n":"הורביץ, יעקב מקטלבורג","bt":"תקח","dt":"תקעו - יט אייר","b":"חתן ר שמואל שמלקא מניקלשבורג. רב בקרמינוב-מורביה, קטלבורג-ליד פרשבורג-תקמט. בנו ר צבי הירש מוישניצא-חתן בעל \"בית שמואל אחרון\"."},{"i":14647,"n":"הורביץ, יעקב מקראקא","f":"השל\"ה","bt":"שסד","bp":"פולין","dt":"תג - חנוכה","dp":"קראקא","b":"חתן ר אליעזר חיות (בן האפי רברבי). רב בקראקא. סידר את כתבי אביו לדפוס. קיבל מכתב מפורסם מארץ ישראל מאביו."},{"i":14648,"n":"הורביץ, יעקב משברשין","f":"אברהם מפרג","dt":"שפב - ג אייר","b":"אחיו של בעל השל\"ה. תלמיד אביו והמהר\"ל. עבר לשברשין. סייע בהדפסת ספר אביו \"יש נוחלין\". בניו: ר שבתי שפטל מהדיר \"ברית אברהם\" לזקנו, ר משה שעלה לארץ והיה שם נשיא, ר יואל מזולקוא (ע\"פ \"ענף עץ אבות\"), ר ישראל אב\"ד אוברניק (ע\"פ פרידברג)."},{"i":14649,"n":"הורביץ, יעקב משינאווא","f":"יוסף יוזפא הלוי","b":"רב בשינאווע-תק\"ל"},{"i":14650,"n":"הורביץ, יעקב עזריאל מברוד","f":"אריה ליב מסטניסלב","b":"דיין בברודי, ורבה של חבורת מוכרי הקמח בברודי. היה רב גם בברדיטשוב."},{"i":14651,"n":"הורביץ, יעקב שמואל","bt":"תרטו","dt":"תרצה - כה אב","b":"עלה לירושלים"},{"i":14652,"n":"הורביץ, יעקב שרגא מיריטשוב","b":"היגר לניו יורק."},{"i":14653,"n":"הורביץ, יצחק","k":"בעל הגירת אכרים לסיב","bt":"1862","bp":"וילנא","dt":"1924","b":"למד רפואה ומתמטיקה בפטרבורג. נאסר ונשלח לסיביר על פעילות מהפכנית, השתחרר והיגר לארה\"ב-1890. ערך עתון יהודי רוסי בשיקגו. חזר לרוסיה-1905 ונבחר ל\"דומה\" אך בחירתו בוטלה. חזר לארה\"ב והצטרף ל\"פועלי ציון\", ביקר ברוסיה-1922 וחזר לארה\"ב. ערך את תרגום הקפיטל של מרכס לאידיש. ?? לא באוצר ??"},{"i":14654,"n":"הורביץ, יצחק איזיק","f":"אהרן איש הורביץ","b":"נדד ברומניה. גביר באיזמאיל בזמן ר אלתר ברנדיס. הביא לדפוס \"מחזקי הדת\" - יאסי תרלא (תיווך במחלוקת אודות השו\"ב שם והשיג אישור לר אליהו מסאניוואץ - בספרו הביא מכתבי רבנים בענין)."},{"i":14655,"n":"הורביץ, יצחק איזיק מזולקוא","f":"נפתלי הרץ מזולקוא","dt":"תקכט - יא אלול","dp":"זולקוא","b":"מחכמי זולקוא."},{"i":14656,"n":"הורביץ, יצחק איזיק מפוטיק","k":"בעל שערי יצחק","b":"חתן ר מרדכי קאוולער. אב\"ד פוטיק וראב\"ד זלישטשיק. חיבר \"שערי יצחק\" בכתב יד. הובא על ידי נכדו ר ישעיה לנדמן אב\"ד אזיפולי - בספרו \"תבנא לדינגא\". ?? לא באוצר ??"},{"i":14657,"n":"הורביץ, יצחק איזיק מפרג","f":"יוסף","dt":"שף - שבט","b":"דיין בפרג"},{"i":14658,"n":"הורביץ, יצחק אסיא מוילנא","f":"יהודה אסיא מוילנא","dt":"תקפא - טו אדר","dp":"וילנא","b":"מחכמי וילנא."},{"i":14659,"n":"הורביץ, יצחק אריה מסלקט","b":"אב\"ד סקלט - תשובות אליו \"אמרי דוד\" - תרמה, \"צור יעקב\" - תרסה."},{"i":14660,"n":"הורביץ, יצחק הלוי מקרוז'","b":"רב בקרוז'-תקי בערך."},{"i":14661,"n":"הורביץ, יצחק יעקב מצישינוב","f":"חיים אריה","k":"בעל באר יצחק","bt":"תקל","dt":"תרכד - כד שבט","dp":"ירוסלב","b":"רב בציעשינוב, ברודי, אב\"ד ירוסלב-תריד. חיבר \"באר יצחק\" למברג תרלג, ונזכר ב\"שערי דעה\" - קלויזנבורג תרפח על הכוונה להדפיסו מחדש."},{"i":14662,"n":"הורביץ, יצחק מבארנוב","f":"אברהם שמחה","bt":"תרכד","dt":"תרצד - כא ניסן","b":"רב בברנוב-תרן. חתן דודו זקנו ר ראובן מדמביץ, ובזיוו\"ש חתן דודו רצ\"ה מרוזוודוב. בנו ר אביגדור מילא את מקומו כשעבר לכהן כרב בזאוויכווסט (ליד צוזמיר)."},{"i":14663,"n":"הורביץ, יצחק מבילקמין","b":"חתן ר צבי רוקח - נכד השר שלום. רבה של בילקמין. היה בוינה - תרעד-תרעח."},{"i":14664,"n":"הורביץ, יצחק מברוד ואה\"ו","f":"יעקב יוקל מבוליחוב","k":"איציקל המבורגר","bt":"תעה או תסה","dt":"תקכז - ו אייר","dp":"המבורג","b":"מחכמי ברודי, חברו של הנודע ביהודה גיסו של אחיו. חתן ר יעקב באב\"ד מברודי, בזיוו\"ש חתן ר יצחק באב\"ד - אחי אשתו המנוחה. רב בלעשנוב, הורחוב-תקט, גלוגא על מקום אביו, ברודי-תקך על מקום ר נתן נטע - אבי ר דוד טביל מליסא (זכה ברבנות כנגד הנודע ביהודה ור שלום מטיקטין שהציגו מועמדות). מתלמידיו המגיד מזלוטשוב ור יצחק חריף מסמבור. ממנו 400 נכדים גדולי תורה. רב באה\"ו על מקום ר יונתן איבשיץ. החרים את מחבר הספר \"ואבוא היום אל העין\" שיוחס לר יונתן איבשיץ. התרעם על ר\"י איבשיץ בגלל בנו וולף ותלמידו - המקובל השבתאי משה דוד מפודהייצא. חיבר \"מטעמי יצחק\" פיעטרקוב תרסד. חתם על כרוז כנגד השבתאים - ברודי תקיח, אלטונא על מקום ר יונתן איבשיץ-תקכה. בניו: ר מרדכי צבי מהורחוב, ר שמואל מאמשטרדם, ר אליעזר מזלוזיץ וברודי. חתניו - ר משלם איגרא מטיסמניץ, ר דובריש מהנובר, ר יעקבא לנדא-בן הנודע ביהודה ובזיוו\"ש ר מנחם נחום קצנלנבוגן מבירס, ר יונה יהושע מלוברטוב, ר חיים מראזדיל-בנו של בעל \"מרכבת המשנה\". היה במחלוקת עם ר יחזקאל לנדא \"הנודע ביהודה\" בנוגע למקרה של מגרש אישה בעל כרחה (בניגוד לחרם רבנו גרשום)."},{"i":14665,"n":"הורביץ, יצחק מברלין","f":"אהרן","b":"רב בברלין-תקלד. חיבר פירוש לחובות הלבבות, ונדפס יחד עם פירוש אחיו ר חיים חייקא - פפד\"א תקלד."},{"i":14666,"n":"הורביץ, יצחק מהוסיאטין","f":"משה","b":"היה בדין תורה עם אחיו על הרבנות בהוסיאטין על מקום אביהם אצל ר\"י ויידנפלד."},{"i":14667,"n":"הורביץ, יצחק מטשען","f":"מרדכי","bt":"תרם","dt":"תשב","b":"אב\"ד טשען על מקום אביו. חתן ר אליהו הורביץ מזילין, ובזיוו\"ש חתן ר נפתלי הורביץ מדמביץ."},{"i":14668,"n":"הורביץ, יצחק ממנוסטרישץ","f":"אברהם","b":"מכתב ממנו-תקעד לראז\"מ (בכת\"י רא\"א מרגליות)."},{"i":14669,"n":"הורביץ, יצחק ממעליץ","f":"נפתלי","k":"אדמור ממעליץ","bt":"תרנו","dt":"תשלח - כב תמוז","b":"חתן רבו ר שמואל הורביץ מדמביץ. אחיו של ר אלימלך ממעליץ, ור ברוך מליזנסק וארה\"ב, ור אברהם אביש מקראלע. רב באזעריאן וקיפוטשוב. היגר לארה\"ב-אחרי מלחה\"מ הראשונה, והיה רב בניו יורק וקליבלנד והיה האדמור ממעליץ. היה מפורסם בניגוניו. חיבר \"כבוד שבת\" ניו יורק תשב, \"ברכת יצחק\", ועוד."},{"i":14670,"n":"הורביץ, יצחק מסאסוב","b":"רב בסאסוב. תשובה אליו ב\"תפארת יוסף\"."},{"i":14671,"n":"הורביץ, יצחק מסטוטשין","f":"משה מרוזבודוב","k":"אדמור מרוזדווב","bt":"תרכב","bp":"דזיקוב","dt":"תש - כד אדר","dp":"סאנוק","b":"רב ואדמור בסטוטשין-תרמד. אדמור בטרנוב(=טורנא) על מקום אביו. חתן ר מנחם מנדל אייכנשטין מזידיטשוב, ובזיוו\"ש חתן הגביר ר יואל הירשפלד. אחיינו של ה\"אמרי נועם\". גיסו של ר יחזקאל הלשטוק מאוסטרובצה. רב בליזנסק, עבר לוינה. חיבר \"החכמה מאי\"ן\" בני ברק תשנו. (י\"א תאריך פטירתו - תרצה)"},{"i":14672,"n":"הורביץ, יצחק מפרג","f":"יוסף ישעיה הורביץ","dt":"שצט - אלול","b":"דיין בפרג-שס\"ט"},{"i":14673,"n":"הורביץ, יצחק מקלם","f":"אליקום גצל","b":"רב בקלם-תרן על מקום ר אליקים, והיה מחלוקת על רבנותו ובהתערבות ר ישראל סלנטר הוחלט שיהיה מו\"צ ואילו לרב התמנה ר אליעזר גורדון."},{"i":14674,"n":"הורביץ, יצחק מקראקא","f":"פנחס מקראקא","dt":"שצא - יז שבט","dp":"וינה","b":"פרנס ועד דד\"א בקראקא."},{"i":14675,"n":"הורביץ, יצחק משאוולאן וראדז","f":"ברוך שמריה הלוי","b":"חתן ר אליקום גצל הורביץ מאסטרין וקלם. רב בשאוולאן, ראדזיוילישיק(=ראדוילישוק)-פלך קובנא-תרמד על מקום ר מאיר מלץ. דור 8 מהשל\"ה. בנו ר אליקום גצל בעל \"כבוד חכמים\" על מקומו אחריו, ובספרו מביא את תולדות המשפחה."},{"i":14676,"n":"הורביץ, יצחק מתמיד","dt":"תשג","b":"רב בווענספילס"},{"i":14677,"n":"הורביץ, יצחק נתן נטע מברדיטשוב","f":"צבי-בן החוזה מלובלין","k":"אדמור מברדיטשוב","b":"נכד החוזה מלובלין. אדמור בברדיטשוב. גיסו - ר אלעזר מחנם מנדל מללוב."},{"i":14678,"n":"הורביץ, יצחק שמחה הלוי מארה\"ב","f":"דב יוסף","k":"בעל יד הלוי","bt":"תרכט","dt":"תרצו - ה טבת","b":"תלמיד ישיבת מיר, וולוזין. נסמך מאת הנצי\"ב, ור יצחק אלחנן מקובנא. רב בהרטפורד-קונטיקט-ארה\"ב-תרנב למעלה מ-40 שנה. עמד בקשרי שו\"ת עם גדולי דורו בליטא."},{"i":14679,"n":"הורביץ, יצחק שמשון ראה","f":"מייזלש-הורביץ, יצחק","b":"רב בטשרנוביץ ומדינת בוקובינה,זלקווא-תק\"מ"},{"i":14680,"n":"הורביץ, ירחמיאל מלמברג","f":"שמואל שמלקא בן צבי","dt":"תרלה - כה תמוז","dp":"לבוב","b":"חתן ר שלמה זלמן זוסמן מאוסטרהא (לפי מצבות קדש חתן ר יוסף צבי מיזיש). גביר מחכמי לבוב. נכד ר צבי הירש בעל \"מחנה לוי\"."},{"i":14681,"n":"הורביץ, ירמיה","k":"ר' ירמיה הגדול"},{"i":14682,"n":"הורביץ, ירמיה הלוי מבראהין","b":"נכד ר ירמיה הגדול. מקובל, רב בבראהין."},{"i":14683,"n":"הורביץ, ישכר בער זליג הלוי","f":"חזקיה הורביץ","dt":"תנ - יג חשון","b":"רב בפרג-תמד"},{"i":14684,"n":"הורביץ, ישכר דב בר מקראקא","f":"עקיבא","k":"ברישל בעל תשובה","bt":"תרל","dt":"תרצא","b":"מחכמי וצדיקי קראקא."},{"i":14685,"n":"הורביץ, ישעיה","f":"שבתי שפטל","dt":"שסז - טו כסלו","b":"נהרג על קדוש השם - ביום ו טו בכסלו - שסז."},{"i":14686,"n":"הורביץ, ישעיה הלוי מברוד","f":"מאיר הורביץ","b":"רב בברוד-תק\"ע"},{"i":14687,"n":"הורביץ, ישעיה הלוי מלבוב","f":"אברהם","dt":"תצב - כט טבת","dp":"לבוב","b":"ראב\"ד ומגיד בלבוב."},{"i":14688,"n":"הורביץ, ישעיה הלוי מפפד\"מ-הנכד","f":"שבתי שפטל מפרג","k":"בעל בית הלוי","bt":"שצב","bp":"פפדמ","dt":"תמט - כג אדר","dp":"פוזנא","b":"נכד השל\"ה. רב בפירט, שטייניץ-תיח, לייפניק-תכד, יונגבונצלויא(=בומסלא)-תלד, פפד\"מ-תלח ור שמואל בן צבי על מקומו אחריו, פוזנא-תמה. חתן ר שלמה ב\"ר מנחם מנדל מפוזנא. כתב הקדמה לספר השל\"ה. מתשובותיו בספרי חכמי דורו - תשובה ממנו על שם העיר פרנקפורט בגיטין. מבניו: ר קופל - נפטר בחיי אביו, ר אברהם."},{"i":14689,"n":"הורביץ, ישעיה הלוי מפרג","f":"פנחס הורביץ","dt":"תסג","b":"מחכמי פרג"},{"i":14690,"n":"הורביץ, ישעיה ליב מלבוב","f":"שמואל שמלקא","dt":"תרלה - ו אב","dp":"לבוב","b":"מצאצאי בעל ההפלאה. תלמיד אב\"ד לוביטש, גביר מחכמי לבוב ופעל למינוי ר צבי הירש אורנשטין לאב\"ד לבוב. בנו - ר שמואל שמקלא מלבוב."},{"i":14691,"n":"הורביץ, ישעיה מלמברג","b":"רב בלבוב"},{"i":14692,"n":"הורביץ, ישעיה מפרג","f":"משה (ולא יוסף)","k":"ישעיה מונקא","dt":"רעד","dp":"פרג","b":"אבי משפחת הורביץ. דיין בפרג. שר העיר הורוביץ. יש אומרים כי אביו היה ר אשר זלמן דיין בפרג. אחיו - הגביר ר זלמן. בניו: ר אהרן משולם זלמן, ר פנחס מפרג, ר מאיר מקעלין, ר יעקב, ר זליגמן מפרג, ר נתן (אולי אבי הקדושים ר אשר ור יעקב שנהרגו על קדוש השם), ר יחזקאל, ר יוסף, ר שבתי שפטל, ר ישראל מסטראקאניץ שנהרג על קדוש השם-שכט עם חתנו ר משה ב\"ר יואל)."},{"i":14693,"n":"הורביץ, ישעיה מקוסוב","b":"נכד השל\"ה. חתן הגביר מאיר יגרמן מקוסוב ועבר מסטניסלב לקוסוב. הדפיס זכרונותיו מקוסוב. עלה לארץ."},{"i":14694,"n":"הורביץ, ישעיה מקראקא - הנכד","f":"יעקב מקראקא","dt":"תנה-ח","dp":"פולין","b":"נכד השל\"ה, ור יצחק חיות. עבר מקראקא לבריסק-תיג ולמד אצל ר משה כץ, ר יעקב שור והחלקת מחוקק, עבר לוילנא, כשגלו יהודי וילנא עבר לפיררה-איטליה-תטו, מנטובה, וירונה. והדפיס שם \"בית הלוי\" ונציה תכו. נפטר בדרכו חזרה לפולין."},{"i":14695,"n":"הורביץ, ישראל דוד מוייסליץ","f":"מנחם מנדל מלינסק","b":"רב בוייסליץ בהשתדלות הדברי חיים. חתן ר משה אבא מליטוביסק (חתנו של היהודי הטוב מניישטט). בנו רנ\"צ נסע לטורונטו וכיהן שם כאדמור."},{"i":14696,"n":"הורביץ, ישראל דוד משנדישוב","f":"טוביה משנדישוב","k":"אדמור משאץ בארה\"ב","bt":"תרנט","bp":"שנדישוב","dt":"תשכז - יז טבת","b":"חתן ר מאיר מושקוביץ משאץ (מאדמורי זלוטשוב), בזיוו\"ש חתן ר איתמר רוזנבוים מנדבורנה. עבר לארה\"ב-תרפח והיה שם האדמור משאץ, בנו ר מאיר על מקומו אחריו."},{"i":14697,"n":"הורביץ, ישראל הלוי","f":"ישעיה הורביץ","dt":"שכט - כז כסלו","b":"עק\"ה יחד עם חתנו,רב בפרג"},{"i":14698,"n":"הורביץ, ישראל הלוי מלובלין","f":"החוזה מלובלין","k":"אדמור מלובלין","b":"רב-שנת תק\"צ. חתן ר אריה יהודה ליב הורביץ מואלטשיסק ולפי אלפסי חתן ר דוד אחיו של ר אברהם משה מפשוורסק. בנו ר משולם זושא - חתן ר יהודה ליב מזקליקוב."},{"i":14699,"n":"הורביץ, ישראל הלוי מפרג","f":"אהרן משלם זלמן מפרג","bt":"רס","bp":"פרג","dt":"שלג - יד תשרי","dp":"וינה","b":"מגדולי חכמי פרג, עבר אחרי גירוש פרג-שכ לוינה. בניו: ר יונה, ר ישעיה ש\"ץ בפרג, ר שמואל ש\"ץ בקראקא, ר פנחס מקראקא - גיסו של הרמ\"א, ר מנחם מנדל, ר אליעזר ליטמן, ר משולם זלמן, ר יעקב מפרג. (יש רושמים שם אביו - זלמן ישעיה)."},{"i":14700,"n":"הורביץ, ישראל יוסף מריגליץ","f":"אלתר אליעזר מריגליץ","bt":"תרן","dt":"תשכב-ח - כז אב","b":"אב\"ד ריגליץ על מקום אביו. חתן ר יצחק הורביץ מסטוטשין. אדמור באריק - גר בטורנא. עבר לארה\"ב-תרצב והיה אב\"ד באנווא."},{"i":14701,"n":"הורביץ, ישראל מאוסטרהא","f":"שלום שכנא מאוסטרהא","b":"פרנס באוסטרהא-שנות ה-תק'."},{"i":14702,"n":"הורביץ, ישראל מברנוב","f":"אליעזר מדזיקוב","bt":"תקעד או תקעט","dt":"תרל - א ניסן","b":"רבה הראשון של ברנוב-תרל וסירב לאדמורות. חתן ר דוד הגר מזבלטוב (קוסוב), ובזיוו\"ש חתן דודו ר אברהם חיים הורביץ מלינסק, ובזיוו\"ש חתן אלמנת ר דוד לייזער ברבז\"ו מטרנוב. בנו ר אברהם שמחה מילא את מקומו אחריו בברנוב. (יש רושמים תאריך פטריתו - ח תמוז תרלט)"},{"i":14703,"n":"הורביץ, ישראל מטורונטו","f":"שמעון","bt":"תרנז","bp":"נארעווקא-פלך גרודנא","b":"תלמיד ישיבות נוברדוק, סטוצין-פלך וילנא. נסמך מאת: ר יצחק הלוי שוסטר מסאקאלקע. חתן ר חיים יוסף לאבענדיג, רב בסאקאלקע לצד האב\"ד, סייע בארגון הקהלות החרדיות בביאליסטוק, גרודנא, בשליחות באמריקה לבקשת ר משה מרדכי אפשטין עבור ישיבת חברון, רב בטורונטו-תרפח בקהלת אנשי לידא, ו\"בית יהודה\". חיבר ספר על התנ\"ך. סייע לר השל פרבשטין-ראש המזרחי בפולין להיבחר לסיים בפולין."},{"i":14704,"n":"הורביץ, ישראל ממעליץ","f":"יהודה","k":"אדמור ממעליץ","bt":"תרי","dt":"תרס-ד - יט טבת","b":"רב ואדמור במעליץ. חתן ר מאיר הורביץ מדזיקוב. נפטר צעיר."},{"i":14705,"n":"הורביץ, ישראל ממעליץ","f":"חנינא מאולינוב","b":"חתן ר יהודה ממליץ, ובזיוו\"ש חתן ר מאיר מדזיקוב. לא זכה ברבנות מליץ (התמנה ר נפתלי) ופתח בית מדרש משלו."},{"i":14706,"n":"הורביץ, ישראל שלמה מברוד","f":"צבי הירש","k":"בעל תהלוכות עולם","bt":"תקצח","bp":"ברודי","dt":"תרסח","b":"נכד ר יצחק איש הורביץ מהמבורג, ונכד-אבי אמו ר שמחה הלוי מבוברקה. מחכמי ברודי ולמברג - לא שימש כרב ועסק במסחר. חיבר \"תהלוכות עולם\" למברג תרסב, פרסם גם ספורים וחוברות בעברית וגרמנית."},{"i":14707,"n":"הורביץ, לוי יצחק מבוליחוב","f":"מנחם מנדל","bt":"תקפב","dt":"תרסב","b":"חתן הנגיד ר יוסף ארנשטין מקריווטש. רב בבוליחוב-תרלט."},{"i":14708,"n":"הורביץ, לוי יצחק מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":14709,"n":"הורביץ, ליב מסטרי","b":"פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":14710,"n":"הורביץ, ליביש מזווירצה","f":"אליעזר מחנטשין","k":"אדמור מזווירצה","dt":"תש..","b":"מצאצאי החוזה מלובלין. חתן ר אברהם גנצוייך מזווירצה, רב ואדמור בזווירצה-תרעח על מקום חותנו. נספה בשואה."},{"i":14711,"n":"הורביץ, מאיר הלוי משעפס","f":"חיים יעקב מלאסק","dt":"תקסו","b":"אחיו של ר ראובן בעל \"דודאים בשדה\". רב בשעפס בהשפעת ר לוי יצחק מברדיטשוב. כיהן כאדמור וגם נסע אל החוזה מלובלין. מתולדותיו ב\"שבחי צדיקים\"."},{"i":14712,"n":"הורביץ, מאיר יוקל מפפד\"מ","f":"פנחס בעל ההפלאה","dt":"תקמה - כ אדר","dp":"פפד\"א","b":"מחכמי פפד\"א."},{"i":14713,"n":"הורביץ, מאיר מבוצאץ","f":"פנחס מזורובנא","k":"בעל דרשות נאות","bt":"תרלו","bp":"זורובנא","dt":"תשיח","b":"מחכמי בוצאץ, חתן הגביר ר ניסן נוימן מבוצאץ ועבר לשם, עבר לוינה ולמד שם רפואה. עלה לארץ-תרצט ושימש כרופא ומוהל. תשובות אליו כ-בן אחותי ב\"הרי בשמים\" - תרס. חיבר \"דרשות נאות\" ירושלים תשח. ?? לא באוצר ??"},{"i":14714,"n":"הורביץ, מאיר מברוד","f":"אריה ליב הורביץ","b":"רב בבראד"},{"i":14715,"n":"הורביץ, מאיר מטיקטין ובוליחוב","f":"שמואל שמלקא משנדישוב","bt":"שצו או תמג","dt":"תקג","b":"רב בבוליחוב, זלוטשוב, טיקטין-תעח. ר לוי יצחק מברדיטשוב נסע אליו לראות את הנהגותיו. נפטר בן 107 שנים. חתן הגביר ר מנחם מניס הכהן, ובזיוו\"ש חתן ר אפרים זלמן קצנלבויגן. למד שבע שנים נגלה בלבד ואח\"כ שבע שנים נסתר בלבד. בניו: ר יעקב יוקל מגלוגא, ר צבי הירש מצורטקוב, ר יהודה אריה ליב מהארקי ווילנא, ר נחום מלנצוט מתורתו ב\"פנים יפות\" ו\"קול יהודה\", ר חיים משריגרד, ר מנחם מאנש מטשאווש, ר דב בריש מקרמניץ, ר יהושע מבוסק, ר נפתלי מטיקטין על מקום אביו, ר ישעיה מפודקמין וברודי (נולד לאביו בגיל 73). חתנו - ר אברהם אשר. (באוצר הרבנים - נולד-תמג ונפטר-יח סיון תקן. אצל בובר מביא בשם ר\"י לוינשטין מסרוצק שחתנו - ר אשר אנשל בן משה מטיסמניץ גאליגור ולבוב."},{"i":14716,"n":"הורביץ, מאיר מלברטוב","f":"שמואל שמלקא","bt":"תקן","dt":"תרא - טו אלול","dp":"לבוב","b":"נכד ר צבי הירש בעל \"מחנה לוי\", ונינו של בעל ההפלאה. חתן ר סנדר סוליצר מוארשא. אב\"ד לברטוב, עבר ללבוב. תשובות ממנו ב\"בית אפרים\" לר אפרים זלמן מרגליות. נפטר ללא ילדים? (ויש אומרים שחתנו - ר מאניס מדובנא). הו\"ל \"פנים יפות\" לזקנו בעל ההפלאה יחד עם חתנו ועם רא\"ז מרגליות."},{"i":14717,"n":"הורביץ, מאיר מלינסק","f":"אברהם חיים מלינסק -ב","bt":"תרג-טו","dt":"תרפג","b":"חתן ר נפתלי צבי הורביץ מצאנז (חורגו של ה\"דברי חיים\") וישב 6 שנים אצל הדברי חיים - חותנו חורגו. תלמיד חבר של החבצלת. רב בלינסק על מקום אביו. ביזוו\"ש חתן ר אלימלך רובין מיברוב."},{"i":14718,"n":"הורביץ, מאיר מקעלין","f":"ישעיה מפרג"},{"i":14719,"n":"הורביץ, מאיר מרישא","f":"אלתר יחזקאל מדזיקוב","dt":"תשג","dp":"למברג","b":"חתן הגביר ר עביר אנגלנדר מקורסנא. ממנהיגי צא\"י ברישא. נספה בשואה."},{"i":14720,"n":"הורביץ, מיכאל מיכל מקראקא","f":"חיים אריה ליב מקראקא","k":"בעל עבודת הלוים","bt":"תרל","dt":"תש","b":"מחכמי קראקא, סירב לרבנות שם ועבר לאנטורפן ועסק במסחר. חיבר \"עבודת הלוים\" (2 ספרים האחד ממנו והשני מבעל \"תורה תמימה\") קראקא תרץ. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"בית המדרש החדש\" - גריבה תרפח, \"כרם בית שמואל\" - פיעטרקוב תרצב, \"המגיד\" - סטמר תרפח-תרצט., פרסם מאמרים ב\"הפרדס\" - צאנז תרצא, \"קובץ מפרשי התורה\" - מארגרטן תרצג, \"רבותינו שבגולה\" - פרשבורג תרעה."},{"i":14721,"n":"הורביץ, מיכל מירושלים","k":"בעל גדולי ציון","b":"מו\"צ בירושלים-תרע\"א."},{"i":14722,"n":"הורביץ, מנדל מלינסק","dt":"תשג","b":"רב בלינסק"},{"i":14723,"n":"הורביץ, מנחם דב בן ציון מפרשוי","f":"טוביה משנדישוב","dt":"תש..","b":"אב\"ד פראשעוויץ. חתן ר אלעזר מסאסוב (אלסק). נספה בשואה."},{"i":14724,"n":"הורביץ, מנחם מאניש מדובנא","f":"אביגדור מירושלים","dt":"תקמב","b":"מחכמי דובנא. בניו: ר אברהם אריה מלויצק, ר משה פרץ מדובנא."},{"i":14725,"n":"הורביץ, מנחם מנדל מדזיקוב","f":"אלתר הורביץ","dt":"תשג","b":"רב בדזיקוב"},{"i":14726,"n":"הורביץ, מנחם מנדל מדמביץ","dt":"תשג","b":"אב\"ד דמביץ. נספה בשואה."},{"i":14727,"n":"הורביץ, מנחם מנדל מלינסק","f":"אברהם חיים מלינסק","bt":"תקסה","dt":"תרכח - כח טבת","b":"מתלמידי החוזה. חתן ר נחום אנגלרד מפאשוב (או פארצוב) (וי\"א: ר נתן דוד רבינוביץ מפרציב). רבה של לינסק על מקום אביו. בנו ר ישראל דוד מוייסליץ.(אצל וונדר תאריך הפטירה כה טבת תרכה)"},{"i":14728,"n":"הורביץ, מנחם מנדל מלינסק","f":"מאיר מלינסק","k":"אדמור מלינסק","bt":"תרן","dt":"תשג - יא תשרי","b":"חתן ר אברהם שלום מסטרופקוב (צאנז). רב ואדמור בלינסק על מקום אביו. נספה בשואה והיה האחרון בשושלת שנמשכה 170 שנה."},{"i":14729,"n":"הורביץ, מנחם מנדל ממעליץ","f":"נפתלי","k":"אדמור מלינסק","bt":"תרמג","dt":"תשג","dp":"רדמישל","b":"חתן ר שמואל שמלקא עזריאל פרנקל תאומים מקלסני. רב במעליץ לצד אביו ואחר כך גם אדמור. נספה בשואה."},{"i":14730,"n":"הורביץ, מנחם מנדל משנדישוב","f":"אשר למל","bt":"תרעג","dt":"תשג","b":"רב בשנדישוב על מקום אביו. חתן ר יעקב ישכר בר רוזנבוים מסלוטפינה. נספה בשואה."},{"i":14731,"n":"הורביץ, מנחם מניש מזמיגרוד","f":"יעקב יוקל מבוליחוב","bt":"תעז","dt":"תקכה - יט שבט","dp":"לבוב","b":"גיסו של הנודע ביהודה. רב בזמיגרוד-תקיד, ר\"מ בלבוב על מקום ר אריה ליב רפפורט. חתן ר צבי הירש מאופוטשנא אב\"ד הילדסהיים וחתן ר דב בריש מקובל, ובובר מביא שהיה חתן ר יהודה סגל לנדא. בניו - ר יהושע השל (שהגט שנתן לאשתו בכפיה גרם למחלוקת גדולה ועל כך כתב גם הנודע ביהודה)."},{"i":14732,"n":"הורביץ, מנחם מנלי מקראקא","f":"שמואל שמלקא","k":"מנלי פינק","bt":"תקם","dt":"תרז - יד ניסן","b":"דיין בקראקא. חתם נגד אסיפת הריפורמים בברונשויג - ב\"תורת הקנאות\"."},{"i":14733,"n":"הורביץ, מנחם נחום מזברז'","f":"צבי הירש מצורטקוב","b":"אב\"ד זברז'-תקע, פרוסקורוב. אחיו - ר פנחס בעל ההפלאה."},{"i":14734,"n":"הורביץ, מנשה מזילין","f":"אליהו","bt":"תרם","dt":"תשלג - כג תשרי","dp":"ארה\"ב","b":"נכדו של \"הצדיק הפלאי\". חתן ר יהודה אונגר מסוקולוב. רב בזילין על מקום אביו. ניצל מהשואה ועבר לארה\"ב והיה שם זקן האדמורים."},{"i":14735,"n":"הורביץ, מנשה מפילזנא","f":"בצלאל מפילזנא","dt":"תש..","b":"רב בפילזנא-תרפב על מקום אביו. נספה בשואה."},{"i":14736,"n":"הורביץ, מנשה מרוזוודוב","f":"צבי הירש מרוזוודוב","k":"אדמור מרישא","bt":"תרם","dt":"תשב","dp":"למברג","b":"חתן ר אלעזר ב\"ר יהושע אב\"ד ריטיטש, וחתן הרב שפירא אב\"ד בלוזוב. רב ברוזוודוב על מקום אביו, רישא וליזנסק-תרץ. נספה בשואה."},{"i":14737,"n":"הורביץ, מרדכי איזיק מבראד","b":"חתן ר יוסף המרלינג משטרוויץ. תשובה אליו בשות מהרשם\"."},{"i":14738,"n":"הורביץ, מרדכי אריה ממאלד","f":"אברהם יעקב-צור יעקב","k":"בעל זכרון ישראל","bt":"תרמב","bp":"סאסוב","dt":"תשכח","b":"חתן ר חיים קצנלבויגן. רבה של מאלד-באנילה-תרסו. ניצל מהשואה ועלה לארץ-תשח. חיבר \"זכרון ישראל\" קלוז תרצז, ועוד. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב. הו\"ל ספר אביו \"צור יעקב\" עם תוספות ממנו."},{"i":14739,"n":"הורביץ, מרדכי דב בר מויטבסק","f":"משלם זוסמן הלוי","bt":"תריב-ז","dt":"תרפד","b":"נכד-אבי אביו ר אברהם בירך, ונכד-אבי אמו ר מאיר צוקרמן. רב בהראדשיץ(ליד לובביץ)-תרמו, ויטבסק-תרמג. נסמך מאת: ר זלמן לנדא, ר אברהם איטינגן."},{"i":14740,"n":"הורביץ, מרדכי דב מבצייקוב","f":"ישעיה","bt":"תרכה","b":"מצאצאי ר אהרן מקרלין, ואחיינו של ר מנחם מנדל בעל \"צמח צדק\". למד בירושלים. רב בבאניעוויץ-פלך מוהילוב-תרסג, בצייקעוו(=בציקוב)-פלך ויטבסק."},{"i":14741,"n":"הורביץ, מרדכי דוד מאלפין","f":"חיים יעקב מאולינוב","k":"בעל חיבור על פמ\"ג","bt":"תרכו","dt":"תשג","b":"נכד-אבי אמו ה\"דברי חיים\". חתן ר אליעזר ירוחם ברון-חתן הדברי חיים, ובזיוו\"ש חתן ר חנחום צבי מדרוהוביטש. אב\"ד אלפין, אולינוב. נספה בשואה. חיבר ספר על פרי מגדים (לא נדפס)."},{"i":14742,"n":"הורביץ, מרדכי הלוי משאמלוי","f":"צבי מוואראהל","k":"בעל פרשת מרדכי-תרכו","bt":"תקפט","bp":"וואראהל","dt":"תרמו - כ אייר","dp":"וינה - שאמלוי","b":"תלמיד ר אשר יונגרייז מטשענגער. מחכמי צ'נגר-תרי, רב בהאלמין-תריז, שאמלוי-תרכט. בנו ר צבי הירש מהרמאנשטדט הכין לדפוס את ספרו \"השיב מרדכי\" - אך לא נדפס."},{"i":14743,"n":"הורביץ, מרדכי זאב","f":"צבי-בן החוזה מלובלין","b":"נכד החוזה מלובלין. חתן ר משה אליקים בריעה מקוזניץ."},{"i":14744,"n":"הורביץ, מרדכי יצחק איז' מטבריה","f":"ישראל זאב מאויהל","dt":"תרסז - כב תמוז","dp":"טבריה","b":"רב באוהל (טיסא-פולגאר). עלה לארץ והתישב בטבריה."},{"i":14745,"n":"הורביץ, מרדכי יצחק מקראקא","dt":"תריח - כ כסלו","b":"דיין בקראקא. הספד עליו ב\"מימי הדעת\"."},{"i":14746,"n":"הורביץ, מרדכי מאוסטרהא","f":"שמעון","b":"נכד ר שלום שכנא הורביץ מאוסטרהא. דיין באוסטרהא ומחכמי הקלויז הגדולה. הסכים על \"עץ חיים\"-תקמב, ועוד."},{"i":14747,"n":"הורביץ, מרדכי מאוסציא","f":"דוד","bt":"תקל","dt":"תר","b":"רבה של אוסציא-זילונא-תקץ. חתן רא\"ל הראשן מסטניסלב."},{"i":14748,"n":"הורביץ, מרדכי מאטיל מפיעטרקוב","f":"משלם","b":"רב בפיעטרקוב. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא. גיסו - ר חיים אוירבך מלונטשיץ."},{"i":14749,"n":"הורביץ, מרדכי מבוליחוב","f":"יעקב יוקל מבוליחוב","dt":"תצז - כז אדר","b":"חתן הרב מסניאטין. רב בבוליחוב-תצה על מקום אביו. נדפס דרוש לשבועות מכתב ידו בכרם שלמה-תשמג."},{"i":14750,"n":"הורביץ, מרדכי מזמושט","dt":"תשג","b":"רב בזאמוטשט"},{"i":14751,"n":"הורביץ, מרדכי מטשען","f":"חנינא מאולינוב","bt":"תריב","dt":"תרצב","dp":"טשען","b":"אב\"ד טשרני-דונייץ-תרס, טשען. חתן ר משה אונגר מצאנז, ובזיוו\"ש ר יונה צינגוט מחסידי בובוב."},{"i":14752,"n":"הורביץ, מרדכי מלינסק","b":"רב בלינסק"},{"i":14753,"n":"הורביץ, מרדכי מקרוז'","b":"רב בקרוז'-תקע בערך. אחיו של ר יעקב מז'אזמיר, ודודו של ר יקותיאל עליון מז'אזמיר."},{"i":14754,"n":"הורביץ, מרדכי מקרמניץ וירושלים","f":"שמואל","dt":"תרד - לפני","dp":"ירושלים","b":"מחכמי פולין, עלה מקרמניץ בשנת תקעה לירושלים. בשנת תקץ יסד את עדת החסידים בירושלים והיה לרב הקהלה. הדפיס את ספר קרובו ר חיים הורביץ \"חיבת ירושלים\" והוסיף עליו הערות. חתנו היה ר אהרן משה מגזע צבי."},{"i":14755,"n":"הורביץ, מרדכי צבי הירש מהורחוב","f":"יצחק מאה\"ו","k":"בעל לחם מצה","bt":"תצח","dt":"תקע - כה כסלו","b":"רבה של הורחוב (חורחוב)-תקנו, ברודי-תקנח. רבו של המגיד מקוזניץ. חתן ר יוסף הלוי לנדא מאפטא, ובזיוו\"ש חתן ר משה מסטנוב. חיבר \"לחם מצה\" עם \"מטעמי יצחק\" לאביו. חתניו - ר צדוק פרנס בן דוד פרנס מדובנא, ר משלם זלמן פייגעס."},{"i":14756,"n":"הורביץ, מרדכי צבי סגל ממונקטש","b":"מחכמי מונקטש. תשובה אליו ב\"שם עולם\"-תרכג."},{"i":14757,"n":"הורביץ, מרדכי קלמן מפרשבורג","f":"שמואל הלוי מקאלוב","bt":"תקס","dt":"תקצט","dp":"ירושלים","b":"תלמיד החת\"ס. עלה מפרשבורג לטבריה-תקעג עם אמו שנפטרה שם, עבר לירושלים-תקצד. בשליחות בהונגריה-תקצט (והיה בדין תורה אצל החת\"ס עם השד\"ר ר אברהם וולפינזון)."},{"i":14758,"n":"הורביץ, משה אהרן מוואלקי","dt":"תשג","b":"חתן ר אשר אנשיל וייס מנאג'פאלו. רב בוואלקוי-תרצח, רב בית הכנסת הפולני בבודפשט-תשב. נספה בשואה. נזכר בשו\"ת מהרם בריסק, ובמבוא ל\"שמן למנחה\" לחותנו."},{"i":14759,"n":"הורביץ, משה אהרן מרינזוב","f":"יעקב יצחק","bt":"תרלה","dt":"תרסד","b":"חתן רב\"צ יצחק וסטריך מקנטשוגה. אב\"ד ריינזוב-תרנז."},{"i":14760,"n":"הורביץ, משה אליעזר מסקאלט","f":"שמריה הורביץ","b":"רב בסקאליט-ת\"נ"},{"i":14761,"n":"הורביץ, משה אלעזר מרימנוב","f":"צבי חיים מרימנוב","k":"אדמור מרימנוב","bt":"תרס","dt":"תשד","dp":"אושוויץ","b":"חתן ר אלעזר ב\"ר נפתלי ממעליץ (ולפי אלפסי חתן ר נפתלי ממעליץ). רב והאדמור האחרון ברימנוב על מקום אביו. נספה בשואה. פרסם מאמרים ב\"המפלפל\" - קראקא תרעג."},{"i":14762,"n":"הורביץ, משה ברוך","b":"מצאצאי בעל ההפלאה, והשל\"ה. רב במדינת זאמוט-תר\"כ ונחשב לצדיק נשגב. בנו ר יעקב מאיר מפינסק."},{"i":14763,"n":"הורביץ, משה ברוך מסיאד","b":"רב ודיין בסיאד-ליטא."},{"i":14764,"n":"הורביץ, משה הלוי מוילנא","f":"יצחק או ישראל","k":"בעל מועדי השם","bp":"קרוז'","dt":"תקפא - יז חשון","dp":"וילנא","b":"היה מלמד את בניו של הגר\"א, מגיד בוילנא ור יחזקאל פיבל על מקומו אחריו. בקי בתקופות ומולדות וחיבר ספר עברונות. בנו - ר חיים ונכדו ר אליעזר ליפמן. אולי הוא שאחיו - ר אריה ליב הו\"ל מכתביו את הספר מועדי השם."},{"i":14765,"n":"הורביץ, משה הלוי מלבוב","f":"דוד בן פנחס מפולדא","dt":"תעו-ז - יח אלול","dp":"לבוב","b":"מרביץ תורה בלבוב (אצל בובר תאריך פטירתו א אלול ת'."},{"i":14766,"n":"הורביץ, משה הלוי מליטא","f":"אהרן","k":"בעל ספר עקרונות","bt":"תקפא","bp":"קרוז'","dp":"וילנא","b":"בקי בחשבון ותכונה. רב באמדור, קרוז', נלקח לוילנא לשמש מורה לבניו של הגר\"א והיה מרואי פניו המעטים. דיין בוילנא על מקום ר דוד מקאמאי, ובהמשך גם מגיד מישרים בוילנא ור יחזקאל פיבל על מקומו אחריו. נקבר לצד בעל \"חיי אדם\" משל ממנו ב\"רשפי קשת\" לר אברהם מסטאויסק."},{"i":14767,"n":"הורביץ, משה חיים אפרים","dt":"תשד","b":"רב בווליע-מיכובה, מיהלוביץ. נספה בשואה."},{"i":14768,"n":"הורביץ, משה יהודה ממיהאלביץ","b":"מחכמי מיהאלביץ-תרכו. גיסו של ר מנחם א\"ש מאונגוואר. אביו של ר יונתן בנימין מאלשא-קובין."},{"i":14769,"n":"הורביץ, משה יהושע מקראקא","f":"שמואל שמלקא משנדישוב","dt":"תקכה","b":"נתייתם מאביו וגדל אצל ר שמואל שמלקא מרגליות אב\"ד עלקוש שנשא את אמו. חתן ר שלום מטיקטין. רב בצאנז, ירוסלב-תצז ור נפתלי הרץ חריף על מקומו אחריו (כך במוריה-?), והורדנא-תקיז. הסכים על 'הפרדס' לר אריה אפשטין, 'דרכי נועם' לר שמואל מקאלואריא (ונדפסה הסכמתו לפני הסכמת הגר\"א). בניו: ר אלעזר ממיר, ר אברהם מקראקא, ר פנחס מקראקא, ר שמואל שמלקא מקראקא. תמך בר יונתן איבשיץ ביריד ירוסלב-תקיד. ר אליעזר בן צבי הירש על מקומו אחריו (?)."},{"i":14770,"n":"הורביץ, משה מאדלסק ונ\"י","f":"אהרן יהודה","k":"בעל דרשות הרמ\"ה","bp":"קומן-ליד וולוזין","dp":"ניו יורק","b":"תלמיד הנצי\"ב, ור חיים סולוביציק. רב באדלסק-פלך גרודנא, ובליגום-תרסז, רוסלאוול-רוסיה ונאלץ לעזוב ע\"י הקומוניסטים אחרי המהפכה. היגר לארה\"ב וכיהן כרב בניו יורק. חיבר גם \"הסתכלות הרמ\"ה באמריקה\", ועוד. פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":14771,"n":"הורביץ, משה מבוסטון ונ\"י","f":"פנחס דוד מבוסטון","k":"אדמור - ניו יורק","bt":"תרע","bp":"ירושלים","dt":"תשמה - יד סיון","b":"דור שביעי לבעשט ודור שישי לר לוי יצחק מברדיטשוב. למד בירושלים ואצל ר אשר למיל בקירכדורף. אדמור מבוסטון בניו יורק על מקום אביו. חתן ר אברהם חיים אייכנשטין מזידיטשוב. מלחין."},{"i":14772,"n":"הורביץ, משה מהוסיאטין","f":"פנחס","bt":"תקף","dt":"תרנא","b":"חתן ר גרשון מסלאויטה (משם ברח בגלל המסירה הנודעת...). רב בהוסיאטין על מקום אביו, גם בנו ר פנחס רב בהוסיאטין. בנו בעל \"באר שרים\" מספר אודותיו."},{"i":14773,"n":"הורביץ, משה מוולוטשיסק","f":"אריה יהודה ליבוש","k":"בעל שושנת העמקים","bt":"תקל","bp":"צורטקוב","dt":"תקצד","b":"רב בוולוטשיסק-תקעג. בנו ר אפרים על כסאו אחריו. חיבר \"שושנת העמקים\" קארעץ תקעט."},{"i":14774,"n":"הורביץ, משה מוילנא","f":"ישראל","k":"בעל מועדי ה'","b":"הו\"ל מכתבי אחיו - ר משה - את הספר מועדי ה' עם הוספות ממנו."},{"i":14775,"n":"הורביץ, משה מירושלים","f":"יעקב סגל-אחי השל\"ה","b":"בן אחי השל\"ה, עלה לארץ ישראל בשנת ת', בנו ר יוזפא היה חתנו של ר מנחם מאנוש אב\"ד וילנא."},{"i":14776,"n":"הורביץ, משה מלבוב","f":"דוד","dt":"ת - ל אב","dp":"לבוב","b":"מרביץ תורה בלבוב. נזכר בשו\"ת מהר\"ם מלובלין."},{"i":14777,"n":"הורביץ, משה מסטניסלב","f":"דוד","bt":"תרמא","dt":"תשג","b":"חתן דודו ר אפרים פישל מריאמפול. רב במריאמפול-תרסג על מקום חותנו, קוזלוב-תרעב על מקום אביו (שעבר לסטניסלב), עבר לוינה, סטניסלב-תרצד. נסמך מאת: מהרש\"ם מברזען, ר בנימין אריה וייס מטשרנוביץ. נספה בשואה."},{"i":14778,"n":"הורביץ, משה מפלנטש","f":"אלעזר מגרודזיסק","b":"חתן ר יוסף הורביץ מקראס. רב בפלנטש על מקום אביו."},{"i":14779,"n":"הורביץ, משה מפשצלוב","f":"דוד","b":"רבה של פשצלוב-תרץ על מקום אביו."},{"i":14780,"n":"הורביץ, משה מקראס","f":"יוסף מקראס","b":"חתן ר אהרן הורביץ מבייטש."},{"i":14781,"n":"הורביץ, משה מראדיוואץ","f":"נפתלי ממיהאלני","bt":"תרכב","b":"נסמך מאת: ר צבי הירש אורנשטין, ר יצחק אהרן איטינגא מלבוב. רבה של ראדיוואץ-תרם, יבלונוב(=יאבלינוב)-גליציה-תרמו. סאניווץ-מיהאלען(=סינאוויטץ מיהאלעני)-רומניה-תרסט על מקום אביו."},{"i":14782,"n":"הורביץ, משה מרוזוודוב","f":"אליעזר מדזיקוב","k":"אדמור מרוזוודוב","bt":"תקפד","dt":"תרנד - י סיון","b":"חתן ר יקותיאל יהודה מסיגט בעל ה\"ייטב לב\". רב ואדמור ברוזוודוב ומייסד השושלת, וחסידיו קראו לעצמם \"חברת בני ר משה הורביץ\"."},{"i":14783,"n":"הורביץ, משה מרוזוודוב","f":"אפרים מרוזוודוב","k":"אדמור מרוזוודוב","bt":"תרס","dt":"תשב","b":"רב ברוזוודוב על מקום אביו יחד עם אחיו ר נפתלי שהיו במחלוקת על ירושת הרבנות. חתן ר אלעזר מגרודזיסק. נספה בשואה (קפץ ללהבות עטוף בטלית)."},{"i":14784,"n":"הורביץ, משה משלם מקראקא","f":"פנחס","k":"בעל תפארת למשה","bt":"תקף","bp":"קראקא","dt":"תרן","b":"רב במארזן (מולדביה), למברג, אושיצין (אושביץ)-תרמא, לונדון וקראקא. בשליחות במערב אירופה לגיוס כספים. חיבר \"תפארת למשה\" למברג תרכב."},{"i":14785,"n":"הורביץ, משה סגל","f":"יעקב הורביץ","b":"עלה לא\"י ונבחר לנשיא א\"י-שנת ת'"},{"i":14786,"n":"הורביץ, משה צבי מצשינוב","f":"אביגדור מקמינקא","b":"רב בצעשינוב-תר\"י"},{"i":14787,"n":"הורביץ, משה שמואל מבלבירישוק","k":"בעל ידי משה","b":"רב בבלבירישוק-תרמד - תרנד על מקום ר שמואל מאיר אש."},{"i":14788,"n":"הורביץ, משה שמואל שמלקא מקראקא","b":"דיין בבית דינו של ר שאול לנדא בקראקא."},{"i":14789,"n":"הורביץ, משה שמעלקע מירושלים","b":"ממונה חסידי עסטרייך בירושלים-תרטז."},{"i":14790,"n":"הורביץ, משלם (שלום) מרייטץ","dt":"תקע","b":"דרשן, רב ברייטץ, ור יצחק איזיק ליב על מקומו אחריו-תקעד."},{"i":14791,"n":"הורביץ, משלם זוסיא(זושא) הלוי","f":"ישראל","b":"חתן רי\"ל בעל \"לקוטי מהרי\"ל\". רב-שנת ת\"ר. בנו - ר יעקב יצחק."},{"i":14792,"n":"הורביץ, משלם זלמן מקראקא","f":"יצחק הורביץ","b":"דומ\"צ בקראקא-ת\"י"},{"i":14793,"n":"הורביץ, משלם ישכר מטרנוב","f":"פנחס מרודשין","b":"מחכמי טרנוב. תשובה אליו \"בית דוד\". ממשתתפי \"אספת חכמים\" - תרעב."},{"i":14794,"n":"הורביץ, משלם ישכר מסטניסלב","f":"אריה ליב","k":"בעל כלי חמדה","bt":"תקסה","bp":"סטניסלב","dt":"תרמה - כ חשון","b":"מתנגד לחסידות. חתן הנגיד ר צבי הירש מנדלסבורג מקוזמיר, (באבני בית היוצר מופיע שאשתו של ר משלם היתה נכדת ר משלם איגרא-בת בתו). רב בזלוזיץ-תקפז, סטניסלב-תרה לצד אביו, טיסמניץ-תרב, סטניסלב על מקום אביו. חיבר \"כלי חמדה\" פרמישלא תרמה, ועוד."},{"i":14795,"n":"הורביץ, משלם ממוסט","b":"אב\"ד מוסט-תרסט."},{"i":14796,"n":"הורביץ, משלם פיבוש מקרמניץ","f":"דב בריש מקרמניץ","k":"בעל משנת חכמים","dt":"תקמו - בערך","b":"רב בקרמניץ-תקל על מקום אביו. מחותנו של המגיד ממזריטש. (בגניזת חרסון מצוי זיוף מכתב ששלח אליו המגיד אודות פירושו למשניות טהרות!). חיבר \"משנת חכמים\" אוסטרהא תקנו."},{"i":14797,"n":"הורביץ, נח גבריאל סגל מטיסא","f":"שמואל הלוי מקאליב","b":"תלמיד החת\"ס. כתב סידור תפלה עם כוונות הארי. רב בטיסא-ליק."},{"i":14798,"n":"הורביץ, נח פנחס ממגרוב ברודי","f":"יעקב דוד בן צבי יהוש","k":"אדמור ממגרוב","dt":"תרלה - כז אייר","dp":"טבריה","b":"מצאצאי ר שמואל שמלקא מניקלשבורג. חתן ר יוסף הכהן ממגרוב. עלה לצפת וכיהן כאדמור ממגרוב."},{"i":14799,"n":"הורביץ, נחום מניימרקט","dt":"תרצט או תשג","b":"חתן רד\"ב שטרויך מניימרקט, רב בניימרקט על מקום חותנו. נספה בשואה."},{"i":14800,"n":"הורביץ, נחום צבי הלוי מריגליץ","b":"חתן ר טוביה גוטמן מריגליץ. אדמור בריגליץ על מקום חותנו. וגיסו - ר אברהם אבא כיהן כאב\"ד בריגליץ."},{"i":14801,"n":"הורביץ, נחמן מליסיעץ","f":"דוד","dt":"תשג","b":"חתן ר יהושע השל באב\"ד מפודוולוטשיסק. אב\"ד קוזלוב-תרפב, רב בליסיעץ, הליטש. נספה בשואה."},{"i":14802,"n":"הורביץ, נפתלי הרץ מזולקוא","f":"מרדכי","dt":"תקיז","dp":"זולקוא","b":"חתן ר דוד בן ישראל הלפרין מאוסטרהא. רב בזולקוא-תעז, חתם-תקיא על החרם הגדול, הסכים על \"לוחות העדות\", \"קול יהודה\", \"מקור ברוך\", ועוד הרבה. בנו - ר יצחק איזיק מזולקוא."},{"i":14803,"n":"הורביץ, נפתלי חיים מדזיקוב","f":"מאיר מדזיקוב","k":"בעל מנחה חדשה","dt":"תרנה - י תשרי","dp":"ירושלים","b":"מצאצאי ר נפתלי מרופשיץ, אביו היה רב בדזיקוב, חתנו של ר משה אונגאר (דומברובא). היה סמוך על שלחנו של ר חיים מצאנז שהיה סב אשתו. חתן ר משה אונגר חתנו של ה\"דברי חיים\". סירב לשמש כרב וכאדמור, עלה לצפת, ומשם לירושלים, וסירב לצאת לחו\"ל לכהן כאדמור אחר פטירת אביו. חי בפרישות כל ימיו. חיבר \"מנחה חדשה\" ירושלים תרלט."},{"i":14804,"n":"הורביץ, נפתלי חיים מקראס","f":"יוסף מקראס","bt":"תרמא","bp":"קראס","dt":"תרצה","b":"חתן ר משה פנט מדעש, וכיהן שם כרב."},{"i":14805,"n":"הורביץ, נפתלי מבודשט-מארמרוש","f":"אברהם אביש מקרולה","b":"חתן ר יוסף פאנט מאילאנדא. רב בבודשט-מארמרוש. נספה בשואה."},{"i":14806,"n":"הורביץ, נפתלי מדמביץ","f":"ראובן מדמביץ","k":"אדמור מדמביץ","bt":"תרלג","dt":"תשג","b":"נכד האדמור ר אליעזר מדזיקוב. רב ואדמור בדמביץ על מקום אביו. חתן ר מוטלה וינברג מדוקלא. הגיע לארה\"ב-תרפא, וחזר לדמביץ-תרצד. נספה בשואה."},{"i":14807,"n":"הורביץ, נפתלי מזבלטוב","f":"אהרן","b":"רב בזבלטוב, פריסטיק, עבר מחכמי פרמישלא-תרץ. סידר לדפוס \"שארית יעקב\" לר יעקב פריינד."},{"i":14808,"n":"הורביץ, נפתלי ממיהאלני","b":"רב במיהאלני-תר\"מ"},{"i":14809,"n":"הורביץ, נפתלי ממעליץ","f":"יהודה ממעליץ","k":"אדמור ממעליץ-קדושת נ","bt":"תרה","dt":"תרעו - יח תשרי","dp":"וינה","b":"נכד ר נפתלי מרופשיץ. רב ואדמור במעליץ(=מיעליטץ)-תרן על מקום אביו. תלמיד הדברי חיים, ור יוסף ברוך \"היהודי הטוב\" מניישטאט. חתן ר מאיר נתן בן ר חיים מצאנז, ובזיוו\"ש חתן הגביר ר אביש קנר מסאנוק. חיבר \"קדושת נפתלי\" ניו יורק תשי, רוב כתביו אבדו בשואה. בניו ר יצחק, ר אלימלך-רב לצדו במעליץ, ר ברוך מלינסק, ר אברהם אביש. חתנו - ר סיני הלברשטם מזמיגרד. ברח לוינה במלחה\"ע ה-I."},{"i":14810,"n":"הורביץ, נפתלי מניו יורק","f":"ישראל יוסף","k":"בעל פון ארץ ישראל","bt":"תרע","dt":"תשכה","b":"ברח בזמן השואה והגיע לארה\"ב-תשו דרך שנחאי. ר בניו יורק. חיבר \"פון ארץ ישראל אוצר\" ניו יורק תשט, ועוד."},{"i":14811,"n":"הורביץ, נפתלי מסאניויץ","f":"יהודה אהרן","b":"רבה של סאניוואץ-מיהאלען על מקום אביו, בנו ר משה על כסאו אחריו. במנויי תפילה למשה - תרם. אודות המשפחה ב\"נחלת צבי\" - תשנד."},{"i":14812,"n":"הורביץ, נפתלי מפוקשיבניצה","f":"יחיאל מפוקשבניצה","bt":"תרל","bp":"פקשיבניצה","dt":"תרצב - יד חשון","dp":"טרנוב","b":"חתן ר יעקב יצחק אונגר מזבנא. נכד האמרי נועם. רב בפקשיבניצה-תרסט על מקום אביו, יחד עמו היה רב של המחנה שהתנגד לו. רב בטרנוב על מקום אביו (לפי אלפסי - כיהן קודם בטרנוב)."},{"i":14813,"n":"הורביץ, נפתלי מקרולי","f":"אברהם אבוש מרעמיט","dt":"תשד","b":"נכד ה\"חקל יצחק\". חתן ר יוסף פנט מאילנדה ודעש. רב בבודעשט-מרמורוש בהשתלדות זקנו. נספה בשואה."},{"i":14814,"n":"הורביץ, נפתלי מרוזוודוב","f":"אפרים מרוזוודוב","bt":"תרן","dt":"תשב","dp":"למברג","b":"חתן ר אהרן אלימלך שניאור זלמן טברסקי מקראס (קרוסני). רב ברוזוודוב על מקום אביו יחד עם אחיו ר משה - שהיו במחלוקת על ירושת הרבנות. נספה בשואה. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":14815,"n":"הורביץ, נפתלי מריבטיטש","b":"רב בריבטיטש-תרמג."},{"i":14816,"n":"הורביץ, נפתלי צבי","f":"טוביה משנדישוב","dt":"תש..","b":"חתן ר יצחק מסטוטשין. נספה בשואה."},{"i":14817,"n":"הורביץ, נפתלי צבי מדעש","f":"יוסף מקראס","k":"אדמור מדעש.","bt":"תרמא-ג","bp":"קראס-גליציה","dt":"תרצה - טז אד\"א","b":"נכד רנ\"צ מרופשיץ. חתן ר משה פנט מדעש. מגיד ואדמור בדעש-תרס."},{"i":14818,"n":"הורביץ, נפתלי צבי מקראקא","f":"ישראל","k":"אדמור מלינסק טורונטו","b":"נכד האדמור ר מנחם מנדל הורביץ מלינסק. עבר מקראקא לטורונטו והיה לאדמור הראשון שם."},{"i":14819,"n":"הורביץ, נתן","f":"משלם מפיעטרקוב","dt":"תרסה - כו אב","b":"אביו היה בנו של ר יעקב יוקל מגלוא ואה\"ו. אחיו של הגביר ר מרדכי צבי. חתנו - הגביר ר משה אהרן זוסמן מאוסטרהא בן ר אפרים זלמן מאוסטרהא."},{"i":14820,"n":"הורביץ, נתן הלוי מפלוצק","b":"רב בפלוצק-תקע, מזקני חסידי חב\"ד - חסיד בעל התניא, בנו והצמח צדק."},{"i":14821,"n":"הורביץ, נתן מארה\"ב","f":"יעקב יצחק מריגליץ","k":"בעל חמשה שערים","bt":"תרעה","bp":"וינה","dt":"תשסא","b":"גדל בוינה אצל סבו ר חיים ירוחם מאלטשטט. ברח מהשואה והגיע לארה\"ב-תשב דרך צרפת. ראש ישיבה בניו יורק ומונסי. הדפיס את ספר זקנו \"מאורות נתן\" ניו יורק תשד. חתן ר ישכר בריש רובין מדולינא. רב במונסי. חיבר \"משה שערים\" נדפס עם ספר זקנו - ניו יורק תשמח."},{"i":14822,"n":"הורביץ, נתן מהליטש","dt":"תשג","b":"רב בהעליטש"},{"i":14823,"n":"הורביץ, נתן משדה לבן ודובנא","f":"יצחק מברודי","dp":"דובנא","b":"חתן דודו ר נפתלי הרץ מקובל. רב ביאלופולה(=שדה לבן)-תקסד, דובנא על מקום גיסו ר זאב וולף הלברשטט. נפטר ללא ילדים."},{"i":14824,"n":"הורביץ, נתן נטע הלוי","f":"ירמיה מבראהין","b":"רב בנארווילע-פלך מינסק-תרל."},{"i":14825,"n":"הורביץ, סנדר מסטניסלב","b":"רב בסטניסלב ולפני כן בדולינא. תשובה אליו שו\"מ-תריג."},{"i":14826,"n":"הורביץ, עזריאל הלוי מלובלין","k":"ר' עזריאל ראש ברזל","bt":"תקיז","dt":"תקעא - כב חשון","b":"חתן ר בנימין בושקא. רב בקראשניק, לובלין. נזכר ב\"ברית אברהם\", ועוד. בניו: ר דוד, ר שאול אפרים פישל. חתניו - ר משה ליב בן ישראל איסר אב\"ד ריצוויל, ר נתן נטע (נטיל הגדול) בן שלום בן אשר משארשוב."},{"i":14827,"n":"הורביץ, עקיבא מפרג","f":"שבתי שפטל מפרג","k":"בעל נשמת שבתי","bt":"שכו","bp":"פרג","b":"רופא תלמיד חכם ומקובל. חיבר פירוש לרמ\"ק \"אזנים לפרדס - שפע טל\" - האנוי שעב, \"נשמת שבתי הלוי\" פרג שעו, ועוד. ?? לא באוצר - מופיע בשם שבתי בן עקיבא ??"},{"i":14828,"n":"הורביץ, פישל מקוזלוב","dt":"תשג","b":"רב בקוזלוב"},{"i":14829,"n":"הורביץ, פנחס אליהו מקראקא","f":"מאיר","k":"בעל ספר הברית","bt":"תקכה","bp":"למברג או וילנא","dt":"תקפא - יח ניסן","dp":"קראקא","b":"מקובל מחכמי וילנא. נדד בערים שונות וביניהם למברג, האג, אויבן, פרשבורג. חיבר \"ספר הברית\" ברין תקנז - נדפס בעילום שמו ותורגם גם ללדינו, \"מצוות טובים\", \"מטמוני סתרים\". בנו - ר שמואל."},{"i":14830,"n":"הורביץ, פנחס בעל ההפלאה","f":"צבי הירש מצורטקוב","k":"בעל ההפלאה","r":"אב\"ד ור\"מ פרנקפורט","bt":"תץ","dt":"תקסה - ד תמוז","b":"חתן הגביר ר יואל הלפרין מלעשנוב. אחיו של ר דוד מאוסטרהא. יש אומרים שבצעירותו למד אצל הגר\"א. התקרב למגיד ממזריטש, אחיו ר נחום ובעל התניא. רב בויטקוב, לכוביץ, רב בפרנקפורט-תקלב. היה רבו של החתם סופר. חיבר \"תוכחת מוסר\" פפדמ תקמב,\"המקנה\", \"גבעת פנחס\", ועוד. בניו ר מאיר יעקב-נפטר בחיי אביו, ר צבי הירש מפרנקפורט בעל \"מחנה לוי\". חתניו - ר צבי יהושע בן אחיו - ר שמלקי, ר אברהם חיים מזלוטשוב בן ר גדליה מזולקווא (ולפי ברוורמן-אנשי שם - ר גדליה הוא החתן).","bk":[["הפלאה",""],["פנים יפות – עה\"ת , הפלאה , המקנה",""],["המקנה",""],["פנים יפות – עה\"ת",""]]},{"i":14831,"n":"הורביץ, פנחס דוד הלוי מבוסטון","f":"שמואל שמלקא מירושלים","k":"אדמור מבוסטון","bt":"תרלו","bp":"ירושלים","dt":"תשב - ז כסלו","dp":"בוסטון - ירושלים","b":"מצאצאי ר שמואל שמלקא מניקלשבורג. חתן ר אהרן ברנדוין מפלשטין (שושלת אליק), ובזיוו\"ש חתן ר יחיאל מיכל ברנדויין מטורקא-סטרטין. תלמיד דודו ר דוד צבי שלמה מללוב בצפת. בתרעג בשליחות ולמד שם בחברותא עם ר אהרן רוקח האדמור מבלז. בגלל מלחמת העולם הראשונה לא יכל לחזור ונסע לניו יורק-תרעה. עבר לבוסטון והיה לאדמור מבוסטון. ביקר את בנו בירושלים-תרצד. עבר לוילימסבורג. בנו ר לוי יצחק היה אדמור מבוסטון אחריו. לפי אלפסי - ברח מהשלטון התורכי בירושלים-תרעו והגיע לארה\"ב."},{"i":14832,"n":"הורביץ, פנחס זאב הלוי","f":"אריה יהודה מואלטשיסק","b":"חתן ר נחמן מברסלב."},{"i":14833,"n":"הורביץ, פנחס זלמן מקראקא","f":"יחיאל מיכל דוד","k":"בעל אהבת תורה","bt":"תר","dt":"תרסו","b":"מחכמי קראקא. חיבר \"אהבת תורה\" פאדגורזע תרסה."},{"i":14834,"n":"הורביץ, פנחס מביסטריץ","f":"אריה ליב-הרי בשמים","b":"חתן הגביר ר אלעזר שאיוביץ מביסטריץ ועבר לשם ועסק במסחר. סירב לרבנות על מקום אביו בסטרי ובסטניסלב. רב בביסטריץ (הונגריה). נדבן, ביבליוגרף ובעל ספריה גדולה. נספה בשואה. בנו ר משולם ישכר - נספה בשואה."},{"i":14835,"n":"הורביץ, פנחס מברודשין","f":"שאול-בשמים ראש","k":"בעל תקנות ישיבת...","bt":"תרכה-ז","bp":"אוסציא","dt":"תרף - ח ניסן","b":"תלמיד אחיו ר חיים אריה בעל \"חיי אריה\". נסמך מאת ר דב בעריש רפפורט בעל \"דרך המלך\", מהרשד\"ם מברעזן, ר בנימין אריה וייס בעל \"אבן יקרה\". חתן הגביר ר משה קונסטנטין מסקול ועבר לשם. אב\"ד ברודשין וראש ישיבה שם-תרנט על מקום ר פיבל בעל \"גדולי הקדש\". הוכר על ידי הממשלה בוינה כאחד מעשר הרבנים המוסמכים להנפיק תעודת רבנות. מתורתו בספר אחיו? \"חיי אריה\". חיבר \"תקנות ישיבת ברודשין\" תרסט, \"עין דמעה\" - תרמח, מאמרים ב\"רבותינו שבגולה\" - פרשבורג תרעה, \"דרכי ציון\", \"אהל מועד\", \"אסיפת חכמים\". ועוד כתבים בכתב יד. חתניו: ר שלמה זלמן גולדשוטף מקראקא, ר גרשון פרייליך מקראקא. ?? לא באוצר ??"},{"i":14836,"n":"הורביץ, פנחס מהוסיאטין","f":"משה","bt":"תר","dt":"תרעה","b":"חתן ר ישראל שטרן מאוסטיטשקא. רבה של סוכוסטוב-תרכו, הוסיאטין-רוסיה-תרל, והוסיאטין-גליציה-תרנב על מקום אביו."},{"i":14837,"n":"הורביץ, פנחס מוואלא-מיכובע","f":"מניס מרימנוב","dt":"תרעה","b":"אב\"ד וואלע-מיכובע (ליד דינוב)-תרנט. בנו ר משה חיים אפרים כיהן על מקומו אחריו."},{"i":14838,"n":"הורביץ, פנחס מזורובנא","f":"חיים צבי","bt":"תרך","dt":"תרף","b":"נכד ר יצחק שחיבר ספר על הרי\"ף. חתן ר יצחק הורביץ מזורובנא-תרמח. רב בזורובנא על מקום חותנו שעבר לסטניסלב, בנו ר מאיר מבוצאץ על מקומו אחריו. בנו ר ישעיה שמתורתו ב\"ועד חכמים\" ועוד."},{"i":14839,"n":"הורביץ, פנחס מירושלים","f":"נתן נטע","dt":"תשנב","b":"חסיד זוויהל. תלמיד בחיי עולם. נכד אדמורים."},{"i":14840,"n":"הורביץ, פנחס מליזנסק","b":"רב בליזנסק. תשובה אליו ב\"הרי בשמים\" - תרמב."},{"i":14841,"n":"הורביץ, פנחס מפולדא ופרג ג","dt":"תיד - יג חשון","dp":"פרג","b":"נכד ר אהרן משולם זלמן הורביץ. תלמיד הסמ\"ע. אב\"ד פולדא, רב בפרג. פסק ע\"פ הרא\"ש וחלק על הרמ\"א. חתן ר בצלאל חריף מקעלן בן המהר\"ל, בזיוו\"ש חתן ר אברהם גומפלד מפרג. בניו: ר דוד רב במעהרין, ר ישעיה."},{"i":14842,"n":"הורביץ, פנחס מפרג א","f":"ישעיה מפרג","dt":"שז"},{"i":14843,"n":"הורביץ, פנחס מפרג ב","f":"ישראל מפרג או זלמן","k":"בעל בית פנחס","bt":"רצה","bp":"פרג","dt":"שעח","b":"אולי שם אביו ר זלמן ישעיה (לפי צונץ - עיר הצדק). חתן ר יהושע שמלקיס (בנו של הגביר חותן המהר\"ל ר שמואל שמלקא מפרג) ועבר אליו לפרמישלא, ובזיוו\"ש חתן ר ישראל איסרלס והיה גיסו של הרמ\"א. עבר לקראקא והיה פרנס וד\"א ומנהיג המדינה. פגש את ר ישראל סרוק מגורי הארי כשעבר שם. חיבר \"בית פנחס\" פיעטרקוב תרסט. בניו - ר יהודה ור יצחק מוינה, חתנו - ר מאיר מענצליז אוירבך. אחיו - הגביר ר אהרן משלם (שבנה ביהכ\"נ בפרג). ?? לא באוצר - מופיע בשם פנחס בן צבי הירש ??"},{"i":14844,"n":"הורביץ, פנחס מקומורנא","f":"יעקב יהושע מזלוזיץ","b":"רב בקומרנא."},{"i":14845,"n":"הורביץ, פנחס מקראקא","f":"משה","k":"ר' פנחס הקדוש","dt":"תלו - יט אייר","dp":"לובלין","b":"רב בקראקא. נהרג עק\"ה בלובלין לאחר שהואשם שקנה מגנב כלי קודש שנגנבו בכנסיה בטומשוב. חתנו - ר מאיר קצנלנבוגן."},{"i":14846,"n":"הורביץ, פנחס פיבל מפאפא","b":"רב בפאקש, פאפא-תרא. כינס אסיפת רבני הונגריה בפאקש-תקצח, ובפאפא-תרד - למצוא דרך לפשרה בין החרדים ובין התובעים תיקונים בדת. (בקי בהונגרית ונואם מוכשר - נאם בעת הכתרת הרוזן אסטרהאזי למושל האזור - וכתוצאה מכך נתמנה לרב בפאפא - שהייתה אחת מאחוזות הרוזן)."},{"i":14847,"n":"הורביץ, פסח מקלצק","dt":"תשג","b":"רב בקלצק"},{"i":14848,"n":"הורביץ, צבי אלימלך מדמביץ","f":"שמואל מדמביץ","k":"אדמור מדמביץ","bt":"תרס","dt":"תשג","dp":"מעליץ","b":"רב ואדמור בדמביץ על מקום אביו. חתן ר יהושע שפירא מריכטיטש. נספה בשואה. היה האדמור האחרון לבית דמביץ."},{"i":14849,"n":"הורביץ, צבי הירש מאנגליה","f":"שמואל הלוי","k":"בעל תפארת צבי","bt":"תרכד","bp":"וילנא","b":"תלמיד ישיבת מייליס בוילנא, ר יחזקאל איוויער מוילנא, ר איצעלע בן ר סנדר מוילנא, ר משה דנישבסקי, קיבוץ איישישוק. נסמך מאת: ר יצחק אלחנן מקובנא, ר מאיר יונה מסויסלץ בעל ביאור על העיטור. רב ביעזנא-תרמח, קשדארי(=קאשעדארי)-פלך קובנא-תרנ, סנדרלנד-אנגליה-תרסג והקים שם ישיבה, לידס-תרעא. חיבר \"תפארת צבי\" - בכת\"י."},{"i":14850,"n":"הורביץ, צבי הירש מארה\"ב","k":"בעל מגלה תעלומה","b":"רב בארה\"ב-תרפד."},{"i":14851,"n":"הורביץ, צבי הירש מבקשביץ","f":"יעקב יוקל","k":"בעל שם דרך","bt":"תקע","dt":"תרם","dp":"זורובנא","b":"אחיו של הרב מבלחוב. חתן ר הנגיד ר אלכסנדר סנדר לנדא מברודי. רב בברודי, אב\"ד בקשביץ-תקסט, סנוק, זורובנא. חיבר \"שם דרך\" בילגוריא תרצז. ?? לא באוצר ??"},{"i":14852,"n":"הורביץ, צבי הירש מברוד","f":"יעקב יהושע","k":"בעל לקוטי צבי","bt":"תקע","dt":"תרלג","b":"תלמיד מהרש\"ק. מחכמי ברודי-תרך וסטניסלב. נפטר ללא ילדים. חיבר \"לקוטי צבי\" זולקווא תרכב, ועוד."},{"i":14853,"n":"הורביץ, צבי הירש מדרזדן","f":"חיים אריה ליב מקראקא","k":"בעל כתבי הגאונים","bt":"תרלב","bp":"קראקא","dt":"תשה - י אדר","dp":"ניצא-צרפת","b":"חתן ר יצחק ברל ויעטשנער מדוקלא. רבה של מחז\"ה לפליטי גליציה בברין. רב בשוינינגן (הולנד). רב בדרזדן-תרעט. חיבר \"כתבי הגאונים\" פיעטרקוב תרפח, \"לקורות הקהלות בפולין\" לודז תרצח, ועוד. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"המגיד\" - סטמר תרפח-תרצט, \"בית ועד לחכמים\" - סטמר תרפב, \"שערי ציון\" - ירושלים תרפא, \"אוצר החיים\" - דעווא תרפה. בין מאמריו: \"עיר ירוסלב ורבניה\", \"עיר דעסוי ורבניה\", \"עיר בומסלא ורבניה\", \"עיר העלישוי ורבניה\"."},{"i":14854,"n":"הורביץ, צבי הירש מהרמנשטט","f":"מרדכי משאמלוי-פרשת מ","bt":"תריט או תרכט","dt":"תרצד - כט אייר","b":"תלמיד חכם ובעל השכלה כללית. רב בהרמאנשטדט-תרן, פרסם בעתוני זמנו בעיקר \"המגיד\", \"וילקט יוסף\". תרגם והו\"ל \"צל ואור\" לנפתלי צבי עלנברגר מבודפשט. בגלל התנגדות חוגים חרדים בקהלה חדל לפרסם בעתונות העברית ופרסם רק דברי תורה בכתבי עת תורניים ובהם \"וילקט יוסף\" ועוד."},{"i":14855,"n":"הורביץ, צבי הירש מוישניצא","f":"יעקב מקטלבורג","bt":"תקכ","dt":"תקפג","dp":"וישניצא","b":"חתן ר שמואל פלקנפלד מפוזנא. השם הורביץ אומץ על ידי אביו בגלל חותנו. רב בוישניצא."},{"i":14856,"n":"הורביץ, צבי הירש מזאמושט","f":"יהושע משה אהרן סגל","k":"בעל גאון צבי","dt":"תמט - א טבת","b":"מראשוני הרבנים בזאמוט, וראש ישיבה ראשון שם. רב בשלש קהילות - קידאן, וויזון ובירז וישב בקידאן. רב בזבלודובה. השתתף בועד הארץ בלובלין, כנציג יהודי ליטא. חיבר גם \"אספקלריא המאירה\"."},{"i":14857,"n":"הורביץ, צבי הירש מסעבען","f":"מרדכי משימלויא","b":"חתנו - ר יקותיאל יהודה גרינולד מקולמובוס."},{"i":14858,"n":"הורביץ, צבי הירש מצורטקוב","f":"מאיר מטיקטין","bt":"תמ","dt":"תקיד - טו חשון","b":"חתן ר מרדכי מלוצק.רב בזבורוב, צורטקוב-תפו. היה מתנגד לבעש\"ט עד שפגשו בצורטקוב ומאז התידדו - הבעשט שלחו להתברך מר חיים צאנזר - ונולדו לו ארבעה בנים: ר פנחס בעל ההפלאה, ר שמואל שמלקא, ר נחום, ר יהושע השל מריצוויל ולובלין. חתן ר מרדכי אב\"ד לוצק."},{"i":14859,"n":"הורביץ, צבי הירש מרוזוודוב","f":"משה מרוזבדוב","k":"אדמור מרוזוודוב","bt":"תרט","dt":"תרעט - י חשון","b":"רב בסטוטשין, רב ואדמור מרוזוודוב-תרנד על מקום אביו. חתן ר יחיאל וגשל מפריסטיק-נכד ר אלימלך מליזנסק, ובזיוו\"ש חתן ר משה זילברפרב. בזמן מלחה\"ע ה-I עבר לוינה, ואח\"כ לרישא. בנו ר שמחה מוישנא-נספה בשואה. חתניו: אב\"ד בארנוב, ר יעקב בן ר ליב מאוזרוב."},{"i":14860,"n":"הורביץ, צבי הירש משקלוב","f":"אריה ליב הורביץ","k":"ר' הירש מילכיגר","b":"פרוש,מגדולי חכמי שקלאב-תק\"צ"},{"i":14861,"n":"הורביץ, צבי הלוי מוואראהל","bt":"תקם","bp":"בוהמיה","dt":"תרי - י אדר","b":"תלמיד ר סיני למדן מליפטו, ור מרדכי בנעט מניקלשבורג. חתן הגביר ר וולף באדער. רב בשמלוי, רבה הראשון של וואראהל(=וארול)-תקסב. בנו ר מרדכי בעל \"פרשת מרדכי\". הניח כתבים בכת\"י."},{"i":14862,"n":"הורביץ, צבי חיים מרימנוב","f":"אשר ישעיה מרימנוב","k":"אדמור מרימנוב","bt":"תרם","dt":"תרצט - ה סיון","dp":"רימנוב - בני ברק","b":"רב ברימנוב-תרפב על מקום אביו (שעבר לקראקא). חתן דודו ר ישראל הגר מויזניץ - האדמור מויזניץ. התמנה לאדמור על מקום (לפי וונדר אביו) זקנו-ר יוסף האדמור מרימנוב-תרצה."},{"i":14863,"n":"הורביץ, צבי יהודה מבאניא","f":"משה שמעון מליופטו","bt":"תקפה","dt":"תרנה - טו תמוז","b":"מצד אמו מצאצאי ר לוי יצחק מברדיטשוב, לאחר שנתייתם גדל אצל ר אהרן דוד דייטש בעל גורן דוד. ובעל התניא. רבה הראשון של נאג'י-באניא-תרטו כ-40 שנה."},{"i":14864,"n":"הורביץ, צבי יהושע מטרנוב","f":"שמואל שמלקא מניקלשבו","k":"בעל חדושי הריבש","bt":"תק","dt":"תקעז - כה חשון","b":"חתן דודו \"בעל ההפלאה\". אב\"ד יעמניץ-תקלט, טרייביטש-תקמז, פרוסניץ-תקס-ט על מקום ר אהרן שפיץ, אב\"ד טרנוב-תקעו. חיבר גם \"סמיכת משה\"."},{"i":14865,"n":"הורביץ, צבי מאטיניא","b":"אב\"ד אטיניא-תריז."},{"i":14866,"n":"הורביץ, צבי מלובלין","f":"החוזה מלובלין","dt":"תקצא - כג אב","dp":"רימנוב","b":"חתן ר אריה יהודה ליב מואלטשיסק, ובזיוו\"ש חתן ר נ תן נטע מחלם. הכתיר את ר חיים מקוסוב לאדמור על מקום אביו ר מנחם מנדל. נסע לפני פטירתו אל ר צבי הירש מרימנוב."},{"i":14867,"n":"הורביץ, צבי מרימנוב","f":"אשר הורביץ","dt":"תשג","b":"אדמו\"ר ברימאנוב-תרצ\"ה"},{"i":14868,"n":"הורביץ, צדוק הלוי","b":"רב-שנת תק\"מ"},{"i":14869,"n":"הורביץ, צדוק מפלונגיאן","f":"שמואל","bt":"תרכט","b":"מצאצאי המהרש\"א. תלמיד ישיבת ראדין-אצל החפץ חיים, ותלמיד ר מנחם שפירא משאט, תלמיד כולל קובנא. רב בפלאנגן-קורלנד-תרנח, וואראמינשטינע-פלך מוהילוב, דשקאווקא-פלך מוהילוב."},{"i":14870,"n":"הורביץ, קלונימוס קלמן מסטריזוב","f":"חיים יהודה","bt":"תרס","dt":"תשג","b":"חתן דודו ר יוסף חיים פרנקל משנדישוב. רב בסטריזוב, ברח ללמברג ורוהטין אחר מלחמת העולם הראשונה, ומשם ארגן חבילות סיוע לבני עירו בסיביר."},{"i":14871,"n":"הורביץ, קלונימוס קלמן מפאריצק","f":"ישראל מלובלין","dt":"תרמה - כד אב","dp":"ירושלים","b":"נכד החוזה מלובלין. חתן ר נח מפאריצק, עלה לירושלים. יש הרושמים תאריך פטירתו - יד ניסן תרנא."},{"i":14872,"n":"הורביץ, ראובן הלוי מזרנובצא","f":"חיים יעקב מלאסק","k":"בעל דודאים בשדה","b":"נכד ר נחום מלאסק. תלמיד ר שמואל שמלקא מניקלשבורג, ור אלימלך מליזנסק, ומזקני תלמידי החוזה מלובלין. רב בגוטמן-גרמניה ועזב בגלל המשכילים, רב בנאויפולא, זרנובצא. אדמור משנת תקעה. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":14873,"n":"הורביץ, ראובן מאוליק","f":"ליבל","bt":"תרנט","bp":"טרנופול","dt":"תשג","b":"חתן הרב קולינר מאוליק, רב באוליק. עבר מ\"אגודת ישראל\" ל\"מזרחי\" ונטש את הרבנות. השתתף כלוחם במרד גיטו וארשא ונהרג בקרב."},{"i":14874,"n":"הורביץ, ראובן מאילינוב","dt":"תשג","b":"רב באילינוב"},{"i":14875,"n":"הורביץ, ראובן מדזרנואצע","f":"יעקב חיים הורביץ","dt":"ל שבט","b":"רב בדזרנווצע-תק\"ע"},{"i":14876,"n":"הורביץ, ראובן מדמביץ","dt":"תשג","b":"רב בדמביץ"},{"i":14877,"n":"הורביץ, ראובן מדמביץ","f":"אליעזר מדזיקוב","k":"אדמור מדמביץ","bt":"תקף","dt":"תרמה","b":"חסיד צאנז ובלז. חתן ר מנשה מרופשיץ, ובזיוו\"ש חתן ר איסר מרוזבדוב, התעשר מבית חותנו השלישי. רבה של דמביץ-תרם, והיה שם אדמור, התפרסמו ריקודיו בשבת קודש שבה לא ישן בכלל. בנו ר נפתלי מדמביץ-חתן ר מוטלה וינברג מדוקלא - נספה בשואה."},{"i":14878,"n":"הורביץ, ראובן מלמברג","k":"עורך אור תורה","b":"מחכמי למברג, הו\"ל \"הנצח\" - לבוב תרפז, מעורכי \"אור תורה\" - לבוב תרפו. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":14879,"n":"הורביץ, ראובן מקוזמיר","dt":"תשג","b":"רב בקוזמיר. (אולי הוא ר ראובן אונגר)"},{"i":14880,"n":"הורביץ, ראובן נתן נטע מירושלים","f":"שמואל שמלקא מירושלים","dt":"תשכו - כג ניסן","b":"מצאצאי ר שמואל שמלקא מניקלשבורג. מחכמי ירושלים. חתן ר משה אייזנבך (פעסטער)."},{"i":14881,"n":"הורביץ, רפאל מקולומיאה","f":"אלתר אליעזר-אברהם שמ","k":"אדמור מקולומיאה בנ\"י","bt":"תרנו","dt":"תשלא - י כסלו","b":"חתן ר ישראל הגר (מבתו החורגת - שהיתה בתו של ר אליעזר ניסן הורביץ מצפת). היגר לארה\"ב והיה לאדמור מקולומיאה בניו יורק. (לפי אלפסי הוא בנו של ר אברהם שמחה מבארנוב - ולא נכדו כמופיע אצל וונדר)."},{"i":14882,"n":"הורביץ, רפאל מקראקא","f":"בנימין","dt":"תשמג","b":"חסיד גור. בשנות השואה היה בשוויץ והעסק בהצלה וחנוך ילדים. עלה לארץ והתישב בבני ברק-תשי."},{"i":14883,"n":"הורביץ, שאול אפרים פישל מלובלי","f":"עזריאל הלוי מלובלין","dt":"תקפח - יט אייר","dp":"לובלין","b":"מחכמי לובלין."},{"i":14884,"n":"הורביץ, שאול הלוי","b":"חריף,רב-שנת תק\"נ"},{"i":14885,"n":"הורביץ, שאול חיים מדומברובנה","f":"אברהם הלוי","k":"בעל מצפה שאול","bt":"תקף -באוצר תקפח","bp":"וילנא","dt":"תרעו","dp":"ירושלים","b":"מחכמי וילנא ולמד אצל ר ישראל סלנט, חתן ר דוד טבלי ממינסק בעל \"בית דוד\". רב בדוברובנא-תרכה, היה חשוך בנים. בשנת תרמג עלה לירושלים וכיהן כרבה של \"מאה שערים\" הקים את ישיבת \"מאה שערים\" ועמד בראשה. חיבר \"כלילת שאול\" וילנא תרלט, על ספרו הסכימו המלבים, ר יצחק אלחנן ועוד. הוציא לאור ספרי חותנו ושל אביו חלקם עם תוספות שלו."},{"i":14886,"n":"הורביץ, שאול מטיסמניץ","f":"משלם ישכר","k":"בעל בשמים ראש","bt":"תקצא","bp":"זלוזיץ","dt":"תרעג - כח תשרי","b":"חתן הגביר ר יעקב נפתלי לונדון מבראד, ובזיוו\"ש נכדת רא\"ס מרגליות ואחר כך חתן ר יעקב הגר מזבלטוב. רבה של אוסציא-זילונא(=אוסצאזיעלאנע)-תרטו. טיסמניץ-תרמד. חיבר \"בשמים ראש\" (החדשות) למברג תרלה. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז. בניו: ר חיים אריה בעל \"חיי אריה\", ר פנחס מבראדשין. חתניו: ר שמואל גולדברג, ר נתן נטע מיכלסון."},{"i":14887,"n":"הורביץ, שאול מטרנופול","b":"פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":14888,"n":"הורביץ, שאול מקומרנא","f":"אריה ליב מסטרי","b":"חתן ר שמעון רפפורט מטרנוב. מחכמי קומרנא-תרמח וסירב לרבנות."},{"i":14889,"n":"הורביץ, שבתי שפטל הלוי מוילהן","f":"ישעיה - בעל בית הלוי","dt":"תמט","b":"רב בווילהן"},{"i":14890,"n":"הורביץ, שבתי שפטל הלוי מפרג","f":"עקיבא הורביץ","k":"בעל שפע טל","bt":"שכו","dt":"שעט","b":"מקובל,רופא,מגדולי חכמי פרג"},{"i":14891,"n":"הורביץ, שבתי שפטל מפרג","f":"ישעיה מפרג","dt":"שטו","b":"רבה של פרג. חתן ר עקיבא כץ מאובן (שהיה בנקאי של המלך ונקרא נשיא היהודים)."},{"i":14892,"n":"הורביץ, שבתי שפטל מקליעא","b":"רב בקליעא-בסרביה, עלה לארץ-תרנה ובנו ר אליהו חיים יוסף על מקומו אחריו."},{"i":14893,"n":"הורביץ, שלום אלתר מטויסט","f":"אלעזר","bt":"תריח","bp":"רוהטין","dt":"תרמו","b":"למד אצל סבו ר משולם ישכר מסטניסלב. רבה של טויסט-תרמא."},{"i":14894,"n":"הורביץ, שלום יקותיאל יחיאל","f":"אריה יהודה מואלטשיסק"},{"i":14895,"n":"הורביץ, שלום מחנטשין","f":"חיים שמואל מחנטשין","k":"אדמור מקילץ","dt":"תרפ - יח חשון","b":"מצאצאי החוזה מלובלין. אדמור בחנטשין-קילץ-תרעז על מקום אחיו ר אליעזר - כחצי שנה."},{"i":14896,"n":"הורביץ, שלום מטיסמניץ","f":"אברהם צבי מבייטש","k":"אדמור מבייטש-ניויורק","dt":"תשנו","b":"אדמור בייטש-ניו יורק על מקום אביו."},{"i":14897,"n":"הורביץ, שלום שכנא מאוסטרהא","dt":"תקטו - כב כסלו","dp":"אוסטרהא","b":"פרנס באוסטרהא יחד עם ר יצחק הלפרין הרופא. נזכר בפנקס ח\"ק וגם חתם שם כמה פעמים. מבניו: ר שמעון הורביץ מאוסטרהא, ר ישראל פרנס באוסטרהא."},{"i":14898,"n":"הורביץ, שלמה זלמן מגלינא","b":"רבה של סווירז, גלינה. תשובה אליו בשו\"מ-תרטז."},{"i":14899,"n":"הורביץ, שלמה זלמן מיאנוב","f":"אהרן מיאנוב","k":"בעל בית אהרן","bt":"תרסז","bp":"יאנוב","b":"חסיד אדמורי רוזין. תלמיד ר משולם ראטה. חתן דודו ר אברהם שכטר מאוזירן ועבר לשם. רב בפוטיק-גליציה (והיה מחלוקת עם חתן הרב הקודם - ר ברוך צייגר שהיה חתן הרב הקודם ר אברהם יהודה שוורץ), ניצל מהשואה, ואחריה רב בחאטין, פרגא-תשה. חתן ר שמעון קופל צרוסקי מפשדבורז. רב במחנה הנוביל (ליד פריז). גיסו של ר יצחק אורלנסקי (שהיה רב המחנה). והגיע לניו יורק-תשט וכיהן כרב. חיבר \"בית אהרן\" ניו יורק תשנה. בנו ר שמואל - גבאי האדמור מבובוב."},{"i":14900,"n":"הורביץ, שלמה זלמן מליטא","f":"דוד בן יהודה","k":"בעל רחובות עיר","bt":"תרך","bp":"וילנא","dt":"תרסב","b":"בילדותו למד אצל ר שלום ברי\"ט, תלמיד קרובו ר יקותיאל ליב עליאן. חתן הגביר ר אלכסנדר סנדר חיים בן ר שלמה זלמן זעטיל. חיבר \"רחובות עיר\" - תוספות ל\"עיר גבורים\" - על רבני וילנא, \"תולדות גדולי גרודנא\" ובו בקורת על הספר \"עיר גבורים\" לפרידנשטין. פרסם מאמר בקורת על הספר \"תולדות אנשי שם\" לדוד טבלי אפרתי, הערות לספר \"מגילת ספר\" ליעבץ ב\"המליץ\", ועוד."},{"i":14901,"n":"הורביץ, שלמה זלמן ממינסק","f":"יעקב","b":"גביר נדבן במינסק-תר בערך."},{"i":14902,"n":"הורביץ, שלמה זלקינד","bt":"תצח","bp":"זעמלין-פלך קובנא","dt":"תקעב","dp":"פאריס","b":"תלמיד השאגת אריה במיץ, למד מדעים ושפות. חיבר ספרים ומאמרים ובהם ספר בצרפתית על הדרכים להיטיב את מעמד היהודים. אחראי על קטלוג כתבי יד בספריה הצרפתית. התחבר לחוגים מהפכניים אחרי המהפכה."},{"i":14903,"n":"הורביץ, שלמה מסטריופקע","k":"בעל כחה דהיתרא","b":"מחכמי סטריופקע (ליד זברז') מחובבי ציון. חיבר \"כחה דהיתרא\" טרנופול תרן. ?? לא באוצר ??"},{"i":14904,"n":"הורביץ, שלמה מצפת","b":"שו\"ב בצפת-תרסה."},{"i":14905,"n":"הורביץ, שלמה מקרליפקה","b":"מחכמי קרליפקה-תרכו. תשובה אליו \"בית שלמה\"."},{"i":14906,"n":"הורביץ, שלמה מרישא","f":"צבי הירש מרוזוודוב","k":"אדמור מרישא","bt":"תרס","dt":"תשג","b":"חתן ר אלעזר וייסבלום מרישא (משושלת ליזנסק). אדמור על מקום חותנו. נספה בשואה."},{"i":14907,"n":"הורביץ, שמואל","f":"שלמה זלמן","b":"חתן ר טוביה בן יוסף הלפרין - נכדו של ר פיבש מברזאן. ניצל מהשואה עם אביו. גבאי של האדמור מבובוב."},{"i":14908,"n":"הורביץ, שמואל","f":"פנחס אליהו","b":"הדפיס עם אביו חומש מכלל יופי-פפד\"א תקמג."},{"i":14909,"n":"הורביץ, שמואל הלוי","f":"חיים חייקא מהורדנא","b":"רב שנת תלא. מתורתו בספר \"גאון צבי\" לבן דודו - ר צבי הירש הורביץ."},{"i":14910,"n":"הורביץ, שמואל הלוי","b":"רב-שנת תר\"ל"},{"i":14911,"n":"הורביץ, שמואל הלוי מיעליסואטגר","f":"נתן נטע מנארווילע","bt":"תרכא","b":"מצאצאי השל\"ה. רב ביעליסווטגרד(=יעליסאוועטגראד)-פלך חרסון-תרסו. במשפחה ידוע על שושלת של 34 דורות של רבנים. נסמך מאת: ר מרדכי דב מהורנסטייפל, ר חיים ברלין, ר זאב מרחמיסטריווקא."},{"i":14912,"n":"הורביץ, שמואל מאמשטרדם","f":"יצחק מאה\"ו","b":"רב באמשטרדם-תקל."},{"i":14913,"n":"הורביץ, שמואל מארה\"ב","f":"אברהם שמעון","k":"בעל לב רגש","b":"רב בארה\"ב-תרפב."},{"i":14914,"n":"הורביץ, שמואל מדובנא","f":"אהרן הלוי","dp":"לומבלא","b":"רב בלוצק, דובנא-שפה (אולי על מקום קרובו בעל השל\"ה), לומבעלא(=לובמלא)-שצ."},{"i":14915,"n":"הורביץ, שמואל מדמביץ","f":"ראובן מדמביץ","k":"אדמור מדמביץ","bt":"תרכט או תרכה","dt":"תרפא-ג -כב תמוז","b":"חתן ר יחיאל וגשל מפריסטיק-נכד ר אלימלך מליזנסק, רב בפריסטיק. רב ואדמור בדמביץ-תרסד על מקום אחיו - ר אלתר ישעיה. בנו ר שמחה מוישנא-נספה בשואה."},{"i":14916,"n":"הורביץ, שמואל מורחנובקא","f":"משה הלוי","dt":"תרד - יא אייר","b":"נכד-מצד אמו של ר פיבש מקרמניץ בעל \"משנת חכמים\". תלמיד ר שלום שכנא מפרוהוביטש, ומקורב לבנו ר ישראל מרוזין. אחר פטירת רבו עלה לארץ ואחרי 10 שנים התישב ביאס."},{"i":14917,"n":"הורביץ, שמואל ממיילאט","b":"רב במיילאט"},{"i":14918,"n":"הורביץ, שמואל מצפת","f":"מרדכי","k":"הו\"ל חבת ירושלים","b":"מחכמי צפת וירושלים, עלה לארץ ישראל בשנת תקעז ולצפת בשנת תקצב, ואחר כך לירושלים, הוציא לאור את ספר קרובו ר חיים הורביץ \"חבת ירושלים\" ירושלים תרד. ?? לא באוצר ??"},{"i":14919,"n":"הורביץ, שמואל מקראקא","f":"פנחס הלוי","dt":"שפב - יג תמוז","b":"רב בקראקא (ערך בסוגריים את רשימת המקורות ברמ\"א על השולחן ערוך"},{"i":14920,"n":"הורביץ, שמואל מקרטינגן","b":"מו\"צ בקראטינגן(קרטינגה)-תרל. חתנו ר שאול ידידיה שוחט."},{"i":14921,"n":"הורביץ, שמואל שלמה ממינסק","b":"גביר מחכמי מינסק ומראשי הקהלה-תרמג."},{"i":14922,"n":"הורביץ, שמואל שמלקא","f":"פנחס - בעל ההפלאה","b":"חתן ר שאול מאמשטרדם. מחכמי פפד\"מ. נפטר צעיר בחיי אביו."},{"i":14923,"n":"הורביץ, שמואל שמלקא","f":"משלם זלמן","b":"חתן ר זאב וולף ואהל. רב בסנוק ופשמישל. הוציא לאור את ספרי זקניו ובהם \"נזיר משה\" ו\"סמיכת משה\"."},{"i":14924,"n":"הורביץ, שמואל שמלקא מירושלים","f":"אלכסנדר יצחק ממגרוב","dt":"ז ניסן","b":"מצאצאי ר שמואל שמלקא מניקלשבורג. מחכמי ירושלים. חתן ר אלעזר מנחם מנדל האדמור מללוב."},{"i":14925,"n":"הורביץ, שמואל שמלקא מלמברג","f":"צבי הירש","bt":"תקכה","dt":"תקצה","b":"רב בפפדמ, למברג ובריסק. בנו - ר ישעיה ליב מלבוב."},{"i":14926,"n":"הורביץ, שמואל שמלקא מניו יורק","f":"משה הכהן","dt":"תשנא","b":"נכד סמבור, רופשיץ ובלז. רב בלונג ביץ'."},{"i":14927,"n":"הורביץ, שמואל שמלקא מניקלשבורג","f":"צבי הירש מצורטקוב","k":"בעל דרכי ישרים","bt":"תפו","dt":"תקלח - א אייר","b":"אחיו של בעל ההפלאה. (י\"א שלמד עם אחיו אצל הגר\"א). תלמיד המגיד ממזריטש. חתן ר יהושע מרישא בן ר מרדכי ראש מדינה בטיסמניץ. רב בריטשוואל-תקיד, שינאווא-תקכב, ניקלשבורג-תקלב, רב מדינת מורביה-תקלה. עמד בראש ישיבה והיו לו תלמידים רבים. חיבר \"דרכי ישרים\" רוסיה-פולין תקף בערך, \"דרכי שמואל\" למברג תרכב, \"אמרי שמואל\", ועוד. לתולדותיו ב\"שמן הטוב\"."},{"i":14928,"n":"הורביץ, שמואל שמלקא מרומאן","f":"מנחם מנדל רובין מלינ","bt":"תקלז","dt":"תקע","dp":"לינסק","b":"חתן נכדת ר איציקל מאה\"ו ובזיוו\"ש חתן ר חיים מטשרנוביץ בעל \"באר מים חיים\". רב ברומאן - מולדביה-תקף, ואחר כך בבאר."},{"i":14929,"n":"הורביץ, שמואל שמלקא משנדישוב","f":"יהושע ארוך מפרמישלא","k":"דער הויכער ר שמלקא","bt":"שעה","dt":"תעג או תנו-אלול","b":"בזיוו\"ש חתן ר משה דיין מקראקא בן ה\"מגיני שלמה\". רב בשנדישוב, טורנא-תלג. על מצבתו נחקק \"וישפוט שמואל את העם ארבעים שנה\". הבטיח שיענה לבניו כשיבואו לציונו - ור נפתלי מרופשיץ שהיה מצאצאיו נהג לעלות על קברו. בניו: ר מאיר מטיקטין, ר יהודה אריה ליב אב\"ד ירוסלב, ר אהרן - אבי ר מרדכי מקראקא, ר מרדכי - אבי ר יוסף מיאלי, ר משה יהושע מצאנז וירוסלב."},{"i":14930,"n":"הורביץ, שמחה","dt":"תשג","b":"רב בפשעצלברישא"},{"i":14931,"n":"הורביץ, שמחה הלוי מקרוז'","bt":"תקץ","dt":"תרנה","b":"רב בקראז(=קרוז'),שאדובה, ליאחוביץ. הצטיין בפעולותיו הציבוריות מ\"חובבי ציון\" וחבר ב\"חברת התמיכה\". דיין מקובל שגם נוצרים באו להתדיין לפניו. הספד עליו ב\"לוח אחיאסף\"-תרנו. חיבר ספרים וחלקם נדפסו בחייו."},{"i":14932,"n":"הורביץ, שמחה מוישנא","f":"צבי הירש","k":"אדמור מוישנא","bt":"תרנג","dt":"תשג","b":"חתן ר יעקב משה ספרין מקומורנא. אדמור בוישנא-תרץ. נספה בשואה."},{"i":14933,"n":"הורביץ, שמעון","f":"אברהם חיים מלינסק","b":"רב-שנת תר\"ע. חתן ר אליעזר מאוזיפולי (סטרטין). חתנו - ר ישכר דב רוקח מבלז."},{"i":14934,"n":"הורביץ, שמעון מאוסטרהא","f":"שלום שכנא מאוסטרהא","dt":"תקלו - כב תשרי","dp":"אוסטרהא","b":"מחכמי אוסטרהא. מבניו: ר מרדכי מאוסטרהא."},{"i":14935,"n":"הורביץ, שמעון מלייפציג","f":"שאול הלוי","k":"בעל מהלומות לגו כסיל","bt":"תקע-ף","bp":"שקוד","dt":"תרס","dp":"לייפציג","b":"רב וראש ישיבה בזאגר-חדש, עסק במסחר ומשירד מנכסיו, כיהן כדיין בלייפציג ורב הקהלה האורטודוכסית שם. חיבר הערות ל\"הפלאה שבערכין\" לישעיהו ברלין, \"ביאור מהרש\"ה\", הערות למסכת ברכות מתלמוד ירושלמי, ועוד. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":14936,"n":"הורביץ, שמעון מרופשיץ","b":"רב ברופשיץ-תרפה."},{"i":14937,"n":"הורביץ, שמעון צבי מירושלים","k":"בעל שם משמעון","dt":"תשז - א תשרי","b":"תלמיד ישיבת המקובלים \"בית אל\", ותלמיד ר בכור ששון פרסיאדו בעל \"שמן ששון\". ר\"מ בקהל חסידים בירושלים-תרמ, מגדולי המקובלים בירושלים-תרע, יסד עם ר חיים יהודה ליב אוירבך את ישיבת שער השמים, קהל חסידים. נסע להודו כדי לחפש את עשרת השבטים ועל מסעו כתב בספרו \"קול מבשר\". חתנו ר שמעון גולדמן הקים על שמו ישיבת \"זכרון שמעון\" שנסגרה לאחר זמן."},{"i":14938,"n":"הורביץ, שמריה הלוי מבולטימור","k":"בעל דרשות מהר\"ש","bt":"תרמג","dt":"תרצח - יט טבת","dp":"מגדולי חכמי שאלוניקי-ש\"פ","b":"רב בבולטימור-תרסח. פרסם מאמרים ב\"היהודי\" - נ\"י תרצו, \"המגיד\" - סטמר תרפח-תרצט. \"פרח לבנון\" - תרעח. ?? באוצר ??"},{"i":14939,"n":"הורביץ, שמריה ליב מארה\"ב","k":"בעל חגים וזמנים","bt":"תרלח","dt":"תרצח - יב סיון","b":"רב ביקטרינוסלב, ניו יורק-תרסו, חיבר גם \"אוצר המשנה\", \"דיני ישראל ומנהגיו\" נ\"י תרפד, \"יסודי היהדות\"."},{"i":14940,"n":"הורביץ, שמריה מלבוב","f":"ישעיה הורביץ","dt":"תכט-צט - יט אדר","dp":"לבוב","b":"ראב\"ד בלבוב, חתם-תז? עם ר אברהם גראפין, ר יהושע פאלק שור, ר ישעיה מלויצק, חתם-תעג עם ר משה מזאמושט, חתם-תפא עם ר יהוש פאלק שור ור ישכר בר טארניפאלר, ועוד. (יש בעיה עם התאריכים - פעם תז ופעם תץ - לדעת בובר יש טעות בנוסח המצבה ושנת פטירתו צ\"ל תצט)."},{"i":14941,"n":"הורביץ, שניאור זלמן מאונסדורף","dt":"תשד","b":"רב באונסדורף"},{"i":14942,"n":"הורביץ, שניאור זלמן ממינסק","f":"יעקב הלוי","bt":"תקעט","dt":"תרמז - ח אדר","dp":"מינסק","b":"גביר מחכמי מינסק. בנו - הגביר ר דוד ממינסק."},{"i":14943,"n":"הורביץ, שרגא פיבל","f":"ברוך הורביץ","bt":"תרנח-ס","bp":"אלקסוט","dt":"תשא - א תמוז","dp":"סלובודקה","b":"תלמיד דודו ר משה מרדכי אפשטין, וישיבות סלובודקה וקלם. חתן ר ליב רובין מוילקומיר. ראש הישיבה האחרון בסלובודקה. נספה בשואה."},{"i":14944,"n":"הורביץ, שרגא פיבל מפאפא","dt":"תרל","b":"רב בפאקש-תקצ\"ו,פאפא,נפטר בעת נאום שהוכרח לשאת בשפה זרה"},{"i":14945,"n":"הורביץ, שרגא פיבש מקראקא","f":"אברהם בן יהושע מקראק","dt":"תקפא - טז חשון","dp":"קראקא","b":"שו\"ב בקראקא."},{"i":14946,"n":"הורביץ-וינוגרד, אליהו שלמה","f":"משה יצחק הלוי","dt":"תרלח - כד אייר","dp":"וארשא","b":"מצאצאי ר שמעלקי מניקלשבורג. חתן ר יצחק יהודה ליב בן שמריהו רבינוביץ מוילנא. נזכר ב\"נחלת עולמים\"."},{"i":14947,"n":"הורביץ-ליפשיץ, חיים מאיר","b":"רב בויליפולי-תרס. ממשתתפי \"אהל מועד\" - תרנט."},{"i":14948,"n":"הורביץ-רובין, מ' מנדל מלינסק","f":"יעקב","dt":"תקסד - כב תשרי","b":"רב בלעשנוב,לינסק-תקמ\"ב"},{"i":14949,"n":"הורביץ-שחור, שמואל סגל","f":"יהודה","k":"ר' שמואל שחור שוורצר","b":"חתן ר יוסף בן משה מוילנא. מגדולי דורו, מרבני ועד דד\"א בפולין-שפ\"א. גיסו - ר יהושע בעל \"מגיני שלמה\"."},{"i":14950,"n":"הורביץ-שטרנפלד, ברוך קלונימוס","f":"אליעזר מחנטשין","k":"אדמור מפילץ-חנטשין","bt":"תרמה","dt":"תש..","b":"מצאצאי החוזה מלובלין. חתן ר פנחס לבקוביץ. רב בסלופיא-תרסט, פילץ-תרעח. נספה בשואה. בנו ר יוסף-חתן ר יצחק מנחם מאלכסנדר."},{"i":14951,"n":"הורביץ-שטרנפלד, יהודה ליב","dt":"תשג","b":"רב בזאוויערצע"},{"i":14952,"n":"הורביץ-שטרנפלד, יהושע אשר מפור","f":"מרדכי זאב","k":"אדמור מפוריסוב","bt":"תרכז","dt":"תשא","b":"מצאצאי החוזה מלובלין. חתן ר פנחס מקינצק (פשיסחא). תלמיד זקנו ר יעקב צבי מפוריסוב, ודודו ר מאיר שלום מקאלושין, ובנו ר יהושע אשר מפוריסוב-אוטואצק (פשיחסא). אדמור בפוריסוב-תרצו אל מקום רבו - ע\"י חלק מהחסידים. נספה בשואה. הו\"ל ספר דודו \"נהר שלום\", וספר זקנו \"זאת זכרון\"."},{"i":14953,"n":"הורביץ-שטרנפלד, יוסף הלוי","f":"אדמור מפילץ","b":"פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":14954,"n":"הורדנר, צבי","f":"דניאל","b":"דיין בווילנה-תק\"צ"},{"i":14955,"n":"הורודנר, יחיאל מיכל מסטרטין","f":"שמעון","bt":"תרך","dt":"תרץ","b":"חתן ר יהודה צבי לנגנר מסטרטין. רבה של סטרטין-תרס על מקום חותנו (וגיסו ר יצחק נתמנה לאדמור מסטרטין). ממשתתפי \"ועד חכמים\"."},{"i":14956,"n":"הורודנר, יצחק מוינה","f":"ישראל שלמה","b":"מחכמי וינה-תרס, הוציא לאור \"מחצית השקל\" מכתב יד."},{"i":14957,"n":"הורודצקי, מאיר","f":"דוד לאה'קס מבאר","b":"חתן ר מרדכי מטשרנוביל. אביו של ר דוד."},{"i":14958,"n":"הורודצקי, מנחם מנדל מהורודישץ","f":"שמואל דב","bt":"תרכז","b":"תלמיד ישיבת מיר, וולוזין. רב בהורודישץ(=האראדישץ, הראדיזסק)-פלך פולטובה-תרנה. נסמך מאת: ר חיים יהודה סוסניצר מסמרגון, ר הלל מאמסטיסלאוו."},{"i":14959,"n":"הורודצקי, שמואל אבא","k":"בעל החסידות והחסידים","b":"מחכמי ברדיטשוב. חוקר חסידות. חיבר גם \"אבל יחיד\" - ברדיטשוב תרנה - הספד על ר אברהם דובער מאנאזאניק מברדיטשוב.","bk":[["שם משמואל","תולדות המהרש\"א"]]},{"i":14960,"n":"הורודצקי, שרגא פיבל מקרסטשוב","f":"אהרן הכהן","bt":"תרלב","b":"רב בקראסטשוב-פלך קיוב-תרנב."},{"i":14961,"n":"הורכשטין, יצחק מאיר","bt":"תרכט","dt":"תרצה","b":"רב בסובוטה,סלופצה-תרנ\"ה,לונדון-תרפ\"ב,בריסל-תרפ\"ג"},{"i":14962,"n":"הורן, אברהם","b":"חמיו של ר חיים רוזנברג מקרליפקה-תרפז. תשובה אליו \"פרי החיים\". עורך \"יבנה\" - לבוב תרפט."},{"i":14963,"n":"הורן, יוסף בנימין","b":"מראשי חסידות צורטקוב, חתם-תרצד על מכתב בקשת עזרה של ראשי החסידות עם ר נתן נטע לייטר, ר מרדכי שלמה שכטר מזלישטשיק, ר ישלמה שפינדל."},{"i":14964,"n":"הורן, צבי הירש","bt":"תרס","dt":"תשג","b":"רב פעלים,רב ביאבוזנה-תר\"צ,ביאלא-פודלסקה-תרצ\"ח"},{"i":14965,"n":"הורנבלס, פתחיה מוארשא","f":"יצחק","k":"בעל פתחי עזרה","bt":"תרז","b":"רב בוארשא-תרלב. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"שערי תורה\" - וארשא תרסג. חיבר גם \"פתחי שערים\"."},{"i":14966,"n":"הורנברג, שמואל מחרסקוב","b":"רב בחרסקוב, עלה לצפת-תרץ והיה שם רב."},{"i":14967,"n":"הורשובסקי, אברהם יעקב","f":"אורי פיבל","bt":"תקם","bp":"דרוהוביטש","dt":"תרא - כז טבת","b":"חתן הגביר ר יחיאל איכל רוזנפלד מרוה-רוסקה. רב ביוזפוף, אוהניב, דרוהוביטש-תקפה. מחדושיו בספרי בנו ר אליהו שישב על כסאו אחריו. אחיו של ר דב בר אב\"ד ליביטשוב."},{"i":14968,"n":"הורשובסקי, אליהו מדרוהוביטש","f":"אברהם יעקב","k":"בעל פני אליהו","bt":"תקסא","dt":"תרמד-ח - ג חשון","b":"תלמיד מובהק לר יוזפא שטרן שנעזר רבות בתלמידו. רב באוהנוב-תקפה על מקום אביו שעבר לדרוהוביטש, רב בדרוהוביטש על מקום אביו. חיבר \"פני אליהו\" דרוהוביטש תרמה, \"אזור אליהו\" למברג תרמט. רוב חדושיו אבדו."},{"i":14969,"n":"הורשובסקי, אריה ליב מהיבניב","f":"אליהו","bt":"תקף","dt":"תרן","b":"רבה של היבניב(=הובניב), מחותנו של ה\"דברי חיים\". חתן ר משה אלבוים מליזנסק."},{"i":14970,"n":"הורשובסקי, דב בר מלובטשוב","f":"אברהם יעקב","b":"אב\"ד לובטשוב-תרכט, חתנו ר יקותיאל שור על מקומו אחריו."},{"i":14971,"n":"הורשובסקי, ישראל מדרוהוביטש","f":"אריה ליב","bt":"תר","dt":"תרס","b":"מחכמי דרוהוביטש, היתה מחלוקת בנושא מינויו לרב שם."},{"i":14972,"n":"הורשובסקי, מנחם מנדל מהולשיץ","b":"מחכמי הולשיץ. תשובה אליו \"חבצלת השרון\"."},{"i":14973,"n":"הורשובסקי, פיבל מדרוהוביטש","f":"משה","b":"מחכמי דרוהוביטש."},{"i":14974,"n":"הורשובסקי, שמעון מהיבניב","f":"אריה ליב","bt":"תרה","dt":"תרסה","b":"אב\"ד היבניב-תרס."},{"i":14975,"n":"הורשובסקי, שרגא פיבל מניו יורק","dt":"תשל","dp":"ניו יורק","b":"נכד ר אברהם יעקב מדרוהוביטש ור אורי יצחק קדיש מירושלים בעל \"פתורא דאבא\" (ירושלים תרסה). היגר לניו יורק ומשם תמך בישיבות נפטר ללא בנים."},{"i":14976,"n":"הושטט, יצחק ממרוקו ואלגיר","f":"משה","bt":"קצ","dt":"רס","b":"רב בתאפיללת-מרוקו, ווהארן-אלגיר. שאלות ממנו לר צמח בן הרשב\"ש."},{"i":14977,"n":"הושע בן בארי הנביא","dt":"ז סיון"},{"i":14978,"n":"הושעיא","k":"בעל חדושים לשס","b":"מחכמי ספרד, מתלמידי הרמב\"ן, נזכר בשו\"ת ר משה אלשקר."},{"i":14979,"n":"הושפל, מנחם מנלי מדולינא","b":"מחכמי דולינא. תשובה אליו \"אבן יקרה\"."},{"i":14980,"n":"הזאבי, ש'","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":14981,"n":"הזנהפט, צבי","b":"רב בטוקום, מיטאוי-תר\"ע"},{"i":14982,"n":"הזנלויף, צבי הירש מפודגורזע","f":"שרגא פיבל","k":"בעל חדושי מהרץ","bt":"תר","dt":"תרס","b":"רב בדומברובה, פודגורזע-תרסא. חיבר \"חדושי מהר\"ץ\" קראקא תרמב."},{"i":14983,"n":"החנוכי, יהודה מצ'כנוביץ","b":"רב בניישטט-צ'כנוביץ-תרנה. חתם עם ר אליהו ברוך קמאי על בוררות בענין רבנות קהלת סמיאטיץ."},{"i":14984,"n":"היבנר, יחיאל מיכל מניזנוב","f":"ישראל משה","k":"בעל משכנות הרועים","bt":"תקצד","bp":"ניזנוב","dt":"תרסז","b":"גדל על ברכי דודו שהיה גם אביו חורגו (נשא את אמו אחר פטירת אביו) ר יצחק גדליה הכהן כץ. חתן דודו הנ\"ל. רב בניזנוב-תריב (למעלה מחמשים שנה). מחסידי סטרטין ומקורב להרבה אדמורים ובהם ר חיים מקוסוב ובנו ר מנחם מנדל מויזניץ. חיבר \"משכנות הרועים\" למברג תרכה, ועוד רבים. התפרנס ממכירת ספרים. הסכים על \"אהל יצחק\" - סטמר תרסג."},{"i":14985,"n":"היבנר, ישראל משה מניזנוב","f":"יחיאל מיכל","bt":"תרכד","b":"דברי תורה ממנו בספרי אביו (\"שער בת רבים\" ועוד) שהיה אב\"ד ניזנוב."},{"i":14986,"n":"היבנר, שמואל מנדבורנה","f":"יקותיאל זלמן חיים","k":"בעל נימוקי שמואל","bt":"תרנב","bp":"נדבורנה","dt":"תשמג","b":"למד בישיבת ברודשין וברלין. בתש\"ח היגר לניו יורק ושימש שם כרב. חיבר \"נימוקי שמואל\" ירושלים תשלט, ועוד בכתב עת."},{"i":14987,"n":"היבנר, שמשון מנדבורנה","b":"מחכמי נדבורנה."},{"i":14988,"n":"היבשר, יעקב מברלין","k":"בעל בית יעקב","b":"רב בברלין. השתתף במועצת גדולי התורה-תרצז."},{"i":14989,"n":"היגר, מיכאל מיכל מניו יורק","k":"בעל אוצר הברייתות","bt":"1898","bp":"רוגובה-ליטא","dt":"1952","b":"תלמיד ישיבות ליטא, היגר לארה\"ב ולמד באוניברסיטת ניו יורק, הסמינר התיאולוגי היהודי. פרסם מהדרות בקורתיות של הספרות התלמודית ובהם \"אוצר הברייתות\". פרסם מאמרים ב\"היהודי\" - נ\"י תרצו."},{"i":14990,"n":"הידלברג, זלקין מפפד\"מ","b":"מראשי קהילת פפד\"מ, ומבין 12 מחברי תקנות הקהילה-תקיג."},{"i":14991,"n":"הידלברג-אופנהים, שמואל","b":"גביר שעסק בפדיון שבוים-תמו יחד עם ר צבי הירש לאזלש."},{"i":14992,"n":"הידלסהיים, אהרן מפפד\"מ","f":"שמואל","dt":"שצט - ב שבט","dp":"פפד\"מ","b":"מראשי קהילת פפד\"מ - בעל תואר \"מורנו\"."},{"i":14993,"n":"היזלברג, יצחק מיברוב","f":"יוסף משה","k":"בעל הלכתא למשיחא","bt":"תרי","dt":"תרע","b":"מחכמי יברוב חיבר \"הלכתא למשיחא\" ירוסלב תרסח."},{"i":14994,"n":"היזלר, יוסף מטבריה","b":"ממונה כולל קוסוב בטבריה-תרנח."},{"i":14995,"n":"היזלר, יוסף שמחה מקוסוב","f":"יצחק","k":"בעל משירי יוסף","b":"חיבר \"משירי יוסף\" - בסוף ספר התקנות של מנין המזרחי בקוסוב - בילגורי תרצב. ?? לא באוצר ??"},{"i":14996,"n":"היטנר, מרדכי זאב וולף מקראקא","k":"בעל חיבור על טהרות","bp":"קראקא","dt":"תש","b":"חסיד גור. תלמיד האבני נזר עם ר יהודה יודל אוסטרובצר. מחשובי חסידי בויאן בקראקא. הכין לדפוס חיבור על טהרות. תלמידו ר שלמה גולדשטוף חתן רד\"ב מטשבין."},{"i":14997,"n":"היטר, אהרן מסטרי","b":"מחכמי סטרי, הדפיס ספר \"משה ואהרן\"."},{"i":14998,"n":"הייגרלך, משה מקראקא","b":"מגדולי חכמי קרקא-ר\"צ"},{"i":14999,"n":"היידא, משה מפרג","b":"דרשן בפרג-שנת ת'"},{"i":15000,"n":"היידא, שמואל ממירוויץ","f":"משה היידא","dt":"תמה - כט אייר","b":"מקובל,דיין במירוויץ","bk":[["זיקוקין דנורא - תנא דבי אליהו",""]]},{"i":15001,"n":"הייטלר, ישראל שלמה","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":15002,"n":"היילבוט, אברהם מאלטונא","f":"ליב","k":"בעל כף נחת","dt":"תקלו - יב סיון","dp":"אלטונא","b":"חתן ותלמיד ר אפרים הקשר. שו\"ב מחכמי אלטונא-תקל, וחזן אצל היעב\"ץ, ועמד לצדו בזמן המחלוקת עם ר יונתן איבשיץ והיה זה שפתח קמע של ר יונתן והראה ליעב\"ץ, עבר עם היעב\"ץ לאמשטרדם. חיבר גם \"בינה רבה\", \"מראה מלוטש\"."},{"i":15003,"n":"היילבוט, יוסף מהמבורג","f":"וולף","k":"בעל ביתה יוסף","dt":"תקסח - ו אב","dp":"אלטונא","b":"חתן ר שמואל ורבורג. מגדולי חכמי המבורג. חיבר \"ביתה יוסף\" - בכת\"י."},{"i":15004,"n":"היילבוט, משה מהמבורג","dt":"תקמג - טז","dp":"אלטונא","b":"דיין בהמבורג."},{"i":15005,"n":"היילבוט, שמואל מהמבורג","f":"יוסף","dt":"תקכד - כט אב","dp":"המבורג","b":"חתן ר בער חזן, ובזיוו\"ש חתן ר יונה הדיין. דיין בהמבורג אצל ר יחזקאל קצנלנבוגן. עמד לצדו של ר יונתן איבשיץ בזמן המחלוקת. פסק עם חבריו כנגד ר מרדכי הקשר. בנו - ר יוסף."},{"i":15006,"n":"היילברום, יהודה מטשאנד","f":"יצחק היילברום","dt":"תרלב","b":"רב בטושנאד"},{"i":15007,"n":"היילברום, יעקב מאדא","f":"יצחק היילברום","bt":"תקע","dt":"תרט - שבט","b":"עק\"ה,רב באדא"},{"i":15008,"n":"היילברום, יצחק מזענטא","b":"רב בזענטא-תקצ\"ג"},{"i":15009,"n":"היילברון, ליב מפולדא","b":"מלמד בפולדא-תקץ. מתלמידיו - ר אשר אנשל שטרן מהמבורג."},{"i":15010,"n":"היילינגמן, אברהם קדיש מארה\"ב","dt":"תרפה - יב תמוז","dp":"ניו יורק","b":"מחכמי נעשויז-פלך מינסק, היגר לארה\"ב. עסקן צבור בג'רזי סיטי."},{"i":15011,"n":"היילפרין, אהרן","f":"יחיאל","k":"בעל יסודי המקרא והתל"},{"i":15012,"n":"היימליך מנחם יוסף בן נחום","bt":"1890","dt":"תשד","b":"רב במישקולץ","bk":[["שלשה ספרים נפתחים",""]]},{"i":15013,"n":"היימליך, אהרן זאב","b":"תלמיד השב\"ס, תשובה אליו ב\"שבט סופר\"."},{"i":15014,"n":"היימליך, יואל מעגשייד","k":"בעל אמרי יואל","b":"רב בועגשייד, מונטריאול."},{"i":15015,"n":"היימליך, ישראל מקאבא","b":"פרסם מאמרים ב\"מגד ירחים\" - סיגט תרנח."},{"i":15016,"n":"היימליך, משה מברגסאס","b":"תלמיד החת\"ס. חתן ר אהרן שוורץ משאראש-פאטאק. רב בברגסאס-תרכו."},{"i":15017,"n":"היימליך, נחום מקעמעטשע","f":"משה מברגסאז","dt":"תרץ - ז ניסן","dp":"בודפשט","b":"שו\"ב בקעמעטשע."},{"i":15018,"n":"היימליך, שמואל בנימין","f":"משה מברגסאז","dt":"תרפט - ח אד\"ב","dp":"וולטרסדורף"},{"i":15019,"n":"היימן, אברהם יהודה מטרנוב","f":"מרדכי","k":"בעל הזכרון והשכחה","bt":"תקצב","bp":"טרנוב","dt":"תרעב","b":"מחכמי טרנוב. חיבר \"הזכרון והשכחה\" קראקא תרמז, \"סדרים והתרכזות\" קראקא תרסד. ?? לא באוצר - הזכרון והשכחה ??"},{"i":15020,"n":"היימן, אהרן מלונדון","f":"מרדכי","k":"בעל התורה הכתובה","bt":"תרכב-ז","bp":"סלוצק","dt":"תרצז","dp":"ארץ ישראל","b":"תלמיד ישיבת בוברויסק אצל ר זלמן ר עקיבא'ס, ר מרדכי צבי בנווהרדוק, ישיבת וולוזין, ותלמיד ר חיים צבי ברוידא מזאגר ישן. חתן נכדת ר צבי לפידות מוילנא. דיין ומו\"צ בלונדון-תרמה, עלה לארץ-תרץ. ממיסדי ישיבת \"עץ חיים\" בלונדון. חיבר \"התורה הכתובה והמסורה\" תל אביב תרצז, \"בית ועד לחכמים\" לונדון תרסב, \"בית ועד לחכמים\" - נ\"י תרסג, ועוד."},{"i":15021,"n":"היימן, אליעזר","f":"יצחק","k":"בעל אברהם מאפו","bt":"1910","bp":"קוברסק-ליטא","dt":"1944","dp":"קובנא","b":"סופר, מזכיר החברה ההיסטורית בליטא, ופעיל בקבוצת הסופרים היהודים בליטא. חיבר סיפורים בעברית ובאידיש מחיי הכפר והעיירה בליטא. נספה בשואה. ?? לא באוצר ??"},{"i":15022,"n":"היימן, אלכסנדר סנדר","b":"תשובה אליו בשו\"מ-תריג."},{"i":15023,"n":"היימן, אפרים מאיר מקאליש","b":"רב בקאליש. פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר. פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":15024,"n":"היימן, דב צבי מארה\"ב","f":"משה אהרן בן ישראל של","bt":"תרסב","bp":"ריטעווע-פלך קובנא","b":"תלמיד ישיבות טלז, סלובודקה, חברון. נסמך מאת: ר משה מרדכי אפשטין, ר אליהו קלצקין מלובלין, ר איסר זלמן מלצר. חתן ר יעקב רבינוביץ ממיניאפוליס. היגר לארה\"ב-תרצא, וכיהן כרב קהלת \"כנסת ישראל\" במניאפוליס, ר\"מ בישיבת חפץ חיים בבולטימור-תשו. חבר אגודת הרבנים באמריקה, ותנועת המזרחי. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":15025,"n":"היימן, מאיר מהמבורג","f":"שמואל","b":"שמש ונאמן קהלת המבורג-תרטו."},{"i":15026,"n":"היימן, צבי נחמן מבנדין","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר, \"כרמנו\" - אלכסנדר-לודז תרצג, \"נהור שרגא\" - אלכסנדר תרצט."},{"i":15027,"n":"היימן, רפאל שלמה מניו יורק","f":"מיכל","k":"בעל חדושי ר שלמה","r":"ראש ישיבת רמיילס בוילנא, ואחר כך בתורה ודעת באמריקה","bt":"תרנ\"ב","bp":"פאריץ-פלך מינסק","dt":"תשה - יז כסלו","dp":"ניו יורק","b":"תלמיד ישיבות לוסק אצל ר ברוך בר ליבוביץ, ראדין. נסמך מר ברוך בר ליבוביץ, ר חיים עוזר גרודזינסקי. חתן ר אברהם מוולוזין, גיסם של ר שמחה זיסל, ר נחמיה מבוצלאוו, ר אליעזר יצחק ברמן. ר\"מ בקרמנצוג, ר\"מ בסמילוביץ, - לבקשת החפץ חיים, ברנוביץ-תרפג, ראש ישיבת רמיילס בוילנא-תרפח. היגר לניו יורק-תרצה וכיהן כראש ישיבת \"תורה ודעת\" בניו יורק. פרסם מאמרים ב\"אהל תורה\" - ברנוביץ תרפד, \"כנסת ישראל\" - וילנא תרץ, \"המתיבתא\" - נ\"י תשג. מראשי אגודת ישראל בארה\"ב,","bk":[["חידושי רבי שלמה",""],["חדושי ר' שלמה [היימן]","מפרשי ש\"ס - אחרונים"],["חידושי רבי שלמה היימן",""],["חידושי רבי שלמה - שיעורים וחידושים",""]],"e":"תרנ\"ב-תש\"ה"},{"i":15028,"n":"היימן, שמואל דוד מדווה","f":"אהרן צבי","k":"בעל זכרון שמואל-תשא","bt":"תרכח","b":"תלמיד בישיבת ר יהודה ליכטנשטין בבעטלען. חתן ר יצחק אלתר שטיגליץ מאונסדורף. מחכמי כפר גארבוי-ליד קלויזנבורג. חסיד בלז ושינאווא. רב בדווה(=דיווא) ונחשב לצדיק ופועל ישועות יחד עמו כיהן ר פישל קליין. חתנו ר אברהם יצחק פרידמן הו\"ל את ספרו."},{"i":15029,"n":"היימן-חרלפ, א.","b":"פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג."},{"i":15030,"n":"היימנסון, יצחק מקאנדאוי","b":"מו\"צ בקאנדאוי."},{"i":15031,"n":"היינה, שלמה זלמן","bt":"תקכז","bp":"הנובר","dt":"תרה - יג טבת","dp":"המבורג","b":"גביר בהמבורג, עשיר גדול, נדבן גדול. בנו - הגביר קרל היינה. אחיינו (בן אחותו) - המשורר המומר היינריך היינה."},{"i":15032,"n":"היינה, שמואל שמריהו מאוסטרובצא","k":"בעל זכרון שמואל","bt":"תקיח","dt":"תרז - כט סיון","b":"תלמיד החוזה מלובלין, המגיד מקוזניץ, והיהודי הקדוש מפשיסחא. רב באוסטרובצא-תקנז כ-50 שנה. ?? לא באוצר ??","bk":[["זכרון שמואל - תורה, וליקוטים על כמה מסכתות בדרך פלפול",""]]},{"i":15033,"n":"היינמן, ירמיה הלוי מברלין","f":"מיינסטר","b":"מזכירו של ר ישראל יעקבסון-תקסח. הו\"ל כתב עת \"ידידיה איינע רעליגיאזע\", הו\"ל ותרגם ספרים רבים."},{"i":15034,"n":"היינריך, צבי הירש","b":"רב בשטול-ויסבורג-תרע\"ד"},{"i":15035,"n":"הייסינסקי, ישראל","f":"יצחק הייסינסקי","b":"רב בסטאוויטש-תר\"י"},{"i":15036,"n":"הייסינסקי, רפאל","f":"יצחק הייסינסקי","b":"רב-שנת תר\"כ"},{"i":15037,"n":"הייקרל, מנדל","b":"רב בלובלין"},{"i":15038,"n":"היכיני, אברהם מקושטא","f":"פתחיה","k":"בעל הוד מלכות","bt":"שעא (אות תיא)","bp":"קושטא","dt":"תמב","dp":"איזמיר","b":"דיין, מגדולי חכמי קושטא, מעתיק ספרים (גם עבור ורנר - אספן ספרים הולנדי). חיבר גם \"אשל אברהם\". לדברי ר יעקב ששפורטש היה שבתאי וכך לדברי רוזניס. אחיו (לא ידוע שמו) נסע לדמשק כדי להפיץ את האמונה בש\"ץ."},{"i":15039,"n":"הילאי גאון סורא"},{"i":15040,"n":"הילביץ אלטר","bt":"1908","dt":"ה'תשנד 1994","bk":[["ללשונות הרמב\"ם",""]]},{"i":15041,"n":"הילדהיימר, עזריאל מברלין-הנכד","f":"מאיר","b":"ראש ביהמ\"ד לרבנים בברלין על מקום אביו וזקנו, עלה לארץ-תרצד."},{"i":15042,"n":"הילדסהיים, זליג מברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":15043,"n":"הילדסהיים, יצחק","b":"חבר ב\"סנהדרין\" בפריז, עם חברו ר שלמה טריר מפפד\"מ."},{"i":15044,"n":"הילדסהיים, מאיר מלאסק","f":"אליקים גץ מהילדסהיים","bt":"תמו","dt":"תצח - יא ניסן","dp":"לוסק","b":"תלמיד ר אברהם ברוידא בפרג, ר דוד אופנהיים בפרג. חתן ר ישראל מליסא בן אברהם וארטיר-נכדו של ר מרדכי יפה בעל הלבוש ועבר אל חותנו ולמד עם ר אפרים מליסא. רב בליסא-תעד, לאסק(=לוסק)-תפה ופיעטרקוב (ישב בלוסק ומצודתו בפיעטרקוב). הו\"ל ספר אביו \"אבן השהם\" עם הקדמה והוספות ממנו. בניו - ר אליקום, ר אברהם."},{"i":15045,"n":"הילדסהיים, מרדכי משה גומפל","f":"נפתלי הרץ","dt":"תקפג - כז טבת","dp":"אלטונא","b":"ר\"מ בהמבורג, ברח לאלטונא בזמן מלחמת נפוליאון-תקעא."},{"i":15046,"n":"הילדסהיים, שלמה זלמן מברלין","b":"מראשי הקהילה בברלין. חתם על הסכם ויתור מס הקהילה ממשה מנדלסון-תקכג."},{"i":15047,"n":"הילדסהיים-אשכנזי, יש'","b":"מגדולי חכמי קרקא-ת\"י"},{"i":15048,"n":"הילדסהיימר, חיים מהילדסהיים","f":"עוזר מאשכז וירושלים","dp":"ירושלים","b":"נכד (או נין) ר אברהם חיים שור והו\"ל את ספר זקנו \"צאן קדשים\" והוסיף עליו מחידושיו. חתן ר יוסף מאיר פרידברג-אב\"ד הנובר, תלמיד בעל \"ברכת הזבח\". רב בהילדסהיים-תפט, ואחר מיושבי ביהמ\"ד של ר לעמלי ראגיינום במנהיים. בנו - ר עוזר מאלטונא."},{"i":15049,"n":"הילדסהיימר, ליב גליא מהלברשטט","dt":"תקצב","b":"תלמיד ר פנחס הורביץ בעל ההפלאה. דיין בגלידינגן, מלמד תורה בהלברשטט. מתורתו בספרי בנו - ר עזריאל."},{"i":15050,"n":"הילדסהיימר, מאיר מברלין","f":"עזריאל מברלין","bt":"תרלא","bp":"ברלין","b":"תלמיד ביהמ\"ד לרבנים בברלין, בעל תואר ד\"ר. רב בברלין-תר על מקום אביו בקהלת החרדים. בנו - ר עזריאל."},{"i":15051,"n":"הילדסהיימר, עוזר מאלטונא","f":"חיים בן עוזר","dt":"תקיז - ח שבט","dp":"אלטונא","b":"מצאצאי ר אברהם חיים שור, נכד ר יוסף מאיר פרידברג מהנובר. מקובל, מגדולי חכמי אלטונא. בזמן מחלוקת היעב\"ץ ור יונתן איבשיץ היה לצדו של היעב\"ץ ונזכר בספרו."},{"i":15052,"n":"הילדסהיימר, עזריאל מברלין","f":"ליב גליא מהלברשטט","r":"רב בהלברשטט, אייזנשטאט, עדת ישראל בברלין","bt":"תקפ","bp":"הלברשטט-איזנשטט","dt":"תרנט - ד תמוז","dp":"ברלין","b":"תלמיד ר יעקב עטלינגר בעל \"ערוך לנר\", ר יצחק ברנייס מהמבורג, ובעל תואר ד\"ר לפילוסופיה מאונ' ברלין. גדול בתורה ומדע,מחנך,מרביץ תורה, בשיטת תלמוד תורה ודרך ארץ. רב באייזנשטט-תריא - והיה מחלוקת כנגדו כשניסה לשלב לימודים כלליים בביה\"ס - גם מצד החרדים וגם מצד המתבוללים, בין המתנגדים - ר הלל מקולומיאה וחתנו ר עקיבא שלזינגר, ניסה להקים בימ\"ד לרבנים אך בגלל המחלוקת עבר לברלין-תרכט וכיהן כרב וראש ביהמ\"ד לרבנים. היה בקשר עם גדולי הדור והיה מראשי אגודת ישראל. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא, \"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב, \"המסדרונה\" - פפד\"מ-ירושלים תרמה, \"פליטת סופרים\" - וילנא תרכג, \"שומר ציון הנאמן\" - אלטונא תרו-תרטז.","bk":[["רבי עזריאל הילדסהיימר","שו\"ת - אחרונים"],["חידושי רבי עזריאל",""],["מידות בית המקדש של הורדוס",""],["שו\"ת רבי עזריאל",""],["רבי עזריאל הילדסהיימר [שו\"ת וחי']",""],["נתיבות עולם",""],["שאלות ותשובות רבי עזריאל",""],["רבי עזריאל הילדסהיימר (א",""]],"e":"תק\"פ-תרנ\"ט","rb":"אייזנשטט, ברלין","co":{"b":"51.895833,11.046667"}},{"i":15053,"n":"הילדסהיימר, שלמה נתן מאלטונא","dt":"תעט - ו טבת","dp":"אלטונא","b":"דיין באלטונא על מקום ר משה רוטנבורג."},{"i":15054,"n":"הילדסהים, שמואל מפפד\"מ","f":"יוסף","b":"רב בפרנקפורט-שעח, על מקום השל\"ה - שעבר לפרג, ור פתחיה על מקומו אחריו."},{"i":15055,"n":"הילזום מאמשטרדם","b":"ראש בית עקד ספרים רוזנטאלישע באמשטרדם."},{"i":15056,"n":"היליג, שמואל מפשמישל","b":"רב בפשמישל. תשובה אליו \"השיב משה\"-תקמט."},{"i":15057,"n":"הילמן דוד צבי","bt":"1926","dt":"ה'תשע 2010","bk":[["אגרות בעל",""],["בית אהרן - אגרות הרמ\"ה","אגרות הרמ\"ה - קובץ תורני"]]},{"i":15058,"n":"הילמן, אורי פיבל מליסא ברלין","f":"שמואל הילמן","dt":"תקל - ז אלול","dp":"מיץ","b":"רב בהענא, ליסא, ר\"מ בברלין, בונא, קלוניא ומינסטר. מחותן עם ה\"נודע ביהודה\"."},{"i":15059,"n":"הילמן, חיים מאיר מירושלים","k":"בעל בית רבי","b":"חיבר ביוגרפיה של אדמורי חב\"ד-תרסב. בשליחות קהלת ירושלים, תעודה-תרסד בחתימת רבני ירושלים המקנה לו את הזכות לטפל בכל עניני מסחר האתרוגים שהכנסותיו מוקדשים לעניי ירושלים ולבנית הישוב היהודי בירושלים."},{"i":15060,"n":"הילמן, טוביה גוטמן","f":"שמואל","k":"בעל זבחי טוביה","b":"מדקדק-שנות ה-ת'. חיבר \"זבחי טוביה\" ונדפס עם \"לוח הדקדוק\" - אמשטרדם תמג."},{"i":15061,"n":"הילמן, יהודה ליב מפוניבז וירוש","f":"משה","k":"בעל לחות העדות","b":"עלה לירושלים-תרלו. חיבר ספר על תריג מצוות בשם \"לחות העדות\" - תרסו."},{"i":15062,"n":"הילמן, ירוחם פישל מדובלען","f":"אליעזר","bt":"תקצט","b":"מו\"צ בדובלן(=דבלן)-פלך ליפלנד-תרם."},{"i":15063,"n":"הילמן, מרדכי מפושויטין","b":"רב בפושויטין(=פאסייעטין)."},{"i":15064,"n":"הילמן, משה מגלינא","f":"שמואל הילמן","b":"רב בגלינא-תק\"מ"},{"i":15065,"n":"הילמן, שמואל יצחק משאדובה ואנג","f":"אברהם חיים","k":"בעל אור הישר","bt":"תרכח","bp":"שאדובה","dt":"תשיג - יח סיון","dp":"ירושלים","b":"תלמיד דודיו ר מרדכי מפושוויטין, ור נח יעקב מפוסבול. רב בברזין-פלך מינסק-תרנז, גלזגו-סקוטלנד-תרסח, לונדון-תרעד, פעיל במפעל העזרה למען יהודי בלגיה בזמן מלחמ\"ה ה-I. עלה לירושלים-תרצד וכיהן כראש ישיבת \"אהל תורה\" ברחביה - מיסודו של חתנו ר יצחק הלוי הרצוג. פרסם מאמרים ב\"אהל תורה\" - ירושלים תרצט, \"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"המאור\" - תל אביב תרצה, \"קול תורה\" - ירושלים תשז.","bk":[["אור הישר","מפרשי רמב\"ם"]]},{"i":15066,"n":"הילף, עזרא מסערדאוהל","f":"נתן חזן ממטרסדורף","b":"לאחר שנתייתם גדל בבית החת\"ס. חתן ר נחמיה מסערדאוהל, מחכמי סערדאוהל, פרשבורג."},{"i":15067,"n":"הילפור, אברהם מברוד","b":"דיין בברודי-תקסז."},{"i":15068,"n":"הילר, זאב שמואל","f":"אהרן דוד","bt":"תרסח","bp":"וישניצה","dt":"תש..","b":"מתלמידי ישיבת בובוב בוישניצא. נספה בשואה."},{"i":15069,"n":"הילר, יצחק איזיק מיהלפאלווא","b":"פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":15070,"n":"הילר, יצחק אריה ליב מהמבורג","b":"מחכמי המבורג-תקעח. הערות ממנו על ספר מגן דוד - רובם בעניני קבלה וחשבונות הגאולה. חיבר ספרים בכת\"י (לא ידועים)."},{"i":15071,"n":"הילר, יצחק מסטריסוב","b":"מחכמי סטריסוב, תשובה אליו ב\"אמרי דוד\"-תרצא."},{"i":15072,"n":"הימל, אברהם אליעזר מבוברקא","b":"שו\"ב בסוואליווע."},{"i":15073,"n":"הימלזון, נחום מפטרבורג","b":"רב בפטרבורג. אחיהם של ר משה לרנבלאט מראדין, ר פיבל מממל, ר דוד מרגליות."},{"i":15074,"n":"הימלזון, פיבל מממל","b":"רב בממל. אחיהם של ר משה לרנבלאט מראדין, ר נחום הימלזון מפטרבורג, ר דוד מרגליות."},{"i":15075,"n":"הימלפרב, אברהם מלובלין","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":15076,"n":"הימלפרב, יעקב מקאלק","f":"מאיר","bt":"תרי","b":"רב בקאלק-ווהלין-תרנא."},{"i":15077,"n":"הימנז"},{"i":15078,"n":"הינדלס, אברהם משטמפן","f":"משה","b":"סופר קהלת שטמפן-תקז, יחד עם ר שמואל בר\"מ, ור נתן ליב גיירינג, ור יוסף הרש נ\"ש."},{"i":15079,"n":"הינדלס, מאיר משטמפן","b":"מחכמי שטמפן, חתם בפנקס הקהל-תריב."},{"i":15080,"n":"הינדלס, משה מאזוס משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":15081,"n":"הינדלס, פנחס משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":15082,"n":"הינדס, אליהו מוילנא","f":"מרדכי בן יעקב ישראל","k":"אליהו הינדעס","dt":"תקפט - כד תמוז","dp":"וילנא","b":"אחיינו-בן אחותו של ר שמעון פרגר (המכונה הגדול) מוילנא. סו\"ד בוילנא, מסדר הגיטין. כתובת מצבתו נכתב בידי אד\"ם הכהן. אחיהם של ר ישראל, ר שאול מאסטרין, ר ירחמיאל."},{"i":15083,"n":"הינדס, יחיאל דב בר מקונסטנטינג","f":"זלמן","bt":"תרלה","b":"תלמיד ישיבת מיר, סלובודקא. רב בקונסטנטינוגרד-פלך פוטובה-תרסג על מקום חותנו. נסמך מאת: ר חיים יהודה סוסניצר מסמרגון, ר מרדכי מסלונים, ר בנימין זקהיים מיקטרינסלב, ר אברהם יצחק צימרמן מקרמנצוג, ר אברהם קרלינסקי מאליזבטגרד."},{"i":15084,"n":"הינדס, שרגא פיבל מגרודנא","k":"חתן ר' שמעון שקאפ","bt":"תרלח","dt":"תרצו - יג אב","b":"חתן ר שמעון שקופ. תלמיד ישיבות טלז וסלובודקה וכונה בשם 'העילוי מסלוצק'. ראש ישיבת 'תורת חסד' בלודז', ר\"מ בישיבת בריינסק אצל חותנו, ועבר עמו לגרודנא. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":15085,"n":"הינה יהודה אריה ליב","bt":"1907","dt":"ה'תשמט 1989","bk":[["ליקוטי יהודה",""]],"e":"תשמ\"ט [פטירה]"},{"i":15086,"n":"היניץ, אברהם אהרן מארה\"ב","f":"יעקב משה","bp":"סטרבין-פלך סלוצק","b":"תלמיד ישיבות סלוצק, מיר. נסמך מאת: ר איסר זלמן מלצר, ר אברהם קאמאי. היגר לארה\"ב-תרפג. ר\"מ בישיבה \"תורה ודעת\" בניו יורק, רב ודרשן ביהמ\"ד \"אהבת אחים\" בניו יורק."},{"i":15087,"n":"הינשפרג, משה הכהן מקישניוב","f":"יצחק איזיק","bt":"תרל","b":"רב ומו\"צ וראש הדיינים בקישינוב(=קעשנוב)-תרנג וראש ישיבה."},{"i":15088,"n":"היסטר, שלמה מפשמישל","f":"מיכאל","bt":"תרן","dt":"תשב","b":"מנהיג צא\"י בשפמישל ודיין. נספה בשואה."},{"i":15089,"n":"היערניק,בנימין יצחק מפדבורז","b":"מחכמי ישיבת חכמי לובלין-תרצז."},{"i":15090,"n":"היצהרי - משפחה","b":"משפחה מגירונה-ספרד, מבניו ר זרחיה הלוי"},{"i":15091,"n":"היצהרי, אנדוראן","k":"מתתיה","b":"דיין בסרגוסה"},{"i":15092,"n":"היצהרי, יצחק הלוי מפרובנס","f":"זרחיה הראשון מפרובנס","k":"בעל מגילת הנחמה","b":"נכד ר שם טוב הלוי בן דורו של רש\"י. אביו של הרז\"ה בעל המאור ור ברכיה. חברו של ראב\"ד השני. ?? לא באוצר ??"},{"i":15093,"n":"היצהרי, מתתיהו מספרד","f":"משה","k":"בעל הלכות טריפה","b":"תלמיד ר חסדאי קרשקש. מחכמי ספרד בדור שאחר הריב\"ש. ממשתתפי הויכוח בפני האפיפיור-קעג. חיבר גם ספר ויכוחים נגד הנצרות, ופירושים לתורה."},{"i":15094,"n":"הירוקי, שמואל מספרד","b":"מחכמי ספרד בדור שלפני הרשב\"ץ, רב בפורמיסיקו, ומלמד לתלמידים."},{"i":15095,"n":"הירושלמי לוי יצחק","bt":"1927","dt":"ה'תשסז 2007","bk":[["שבתות בירושלים",""]]},{"i":15096,"n":"הירחי, אברהם מלוניל","f":"שלמה","b":"תוכן וחכם-ה'קן. חיבר פירוש לאוקלידס - כת\"י. נזכר בהקדמת \"מנוח הלבבות\" שהחזיק בספרו."},{"i":15097,"n":"הירחי, אברהם מלוניל וספרד","f":"נתן","k":"ראב\"ן - בעל המנהיג","bp":"אויניון-פרובנס","b":"מגדולי הראשונים והפוסקים, מגדולי חכמי לוניל-ד'תתקנ, דיין בטולידו-ד'תתקע בזמן ר מאיר אבולעפיה-הרמ\"ה, ור יצחק מיגאש וחתמו ביחד כמה פעמים."},{"i":15098,"n":"הירחי, אריה יהודה הפייטן","f":"לוי","b":"פייטן-שנות ה-ק'-ר'. חיבר פיוט \"באו ימי פקודתכם\", ועוד."},{"i":15099,"n":"הירחי, דוד","b":"בועד בית דין הגדול בתונס-תש\"ב"},{"i":15100,"n":"הירחי, נסים מתונס","bt":"תרח - בערך","dt":"תרפח - טז אדר","b":"רב ראשי בתונס על מקום ר משה שתרוג-תרפח. חתם בענין פתיחת חנויות קפה בשבת-תרמא. משמו \"ירחי\" נראה שהיה מהמשפחה שמוצאה בעיר לוניל בצרפת."},{"i":15101,"n":"הירטנשטין, אברהם צבי מסנט גרוד","b":"רב בסענט-גרוד. חתן ר מרדכי יפה מרגליות שלזינגר מבודפשט."},{"i":15102,"n":"הירירה, אברהם דוד משלוניקי","dt":"תקטו","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":15103,"n":"הירירה, אברהם הכהן","k":"בעל שער השמים","bt":"שב או של","dt":"שצא-ט","b":"ממשפחת אנוסים ונולד כשר ספרדי ואחד מקרוביו היה השר פרדינדד גונזלו מקורדובה שכבש את נפולי, הוא היה בשליחות מלכות מאסאקוי בעיר קדיימי ונפל בשבי האנגלים, וכשנשתחרר נסע לאמשטרדם וחזר ליהדות. תלמיד ר' ישראל סרוק בקבלה, מגדולי המקובלים, רב באמסטרדם. חיבר גם \"בית אלקים\" בספרדית, ספריו תורגמו לעברית בידי ר יצחק בן מתתיה אבוהב ונדפס בשם \"בית אל\", \"שער השמים\"."},{"i":15104,"n":"הירירה, אברהם מונציה","f":"בנימין","bt":"1790","dt":"תרכא - יב","b":"גביר בונציה, בנקאי ובעל בית חרושת לזכוכית, ומקורב לשלטון. קונוסל תורכיה בונציה. מראשי הקהלה בונציה."},{"i":15105,"n":"הירירה, אברהם משלוניקי","b":"מחכמי שלוניקי. הו\"ל \"צמח דוד\"-תקלא, ו\"עבודת השם\"-תקלא מאת הרב בעל \"חמדת ימים\" על סדר עבודת יוה\"כ."},{"i":15106,"n":"הירירה, אברהם משלוניקי","b":"דיין בשלוניקי-תקעח."},{"i":15107,"n":"הירירה, אברהם משלוניקי","b":"גביר בשלוניקי-תרנח, יסד ישיבה \"בית יצחק\", סייע עם חבריו בהדפסת \"עין משפט\"."},{"i":15108,"n":"הירירה, בכור יצחק משלוניקי","dt":"תרמח","dp":"שלוניקי","b":"דרשן ומלמד תורה בשלוניקי."},{"i":15109,"n":"הירירה, גדליה בכור משלוניקי","dt":"תקצא","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":15110,"n":"הירירה, יצחק בכור משלוניקי - א","f":"משה","dt":"תקמב","dp":"שלוניקי","b":"נכד(-אבי אמו) ר יצחק ן שנג'י. רב ודיין בשלוניקי. הגיה 7 ספרים וכתב כמה הקדמות. הניח חדושים בכת\"י."},{"i":15111,"n":"הירירה, יצחק משלוניקי - ב","f":"אברהם","b":"מחכמי שלוניקי. הגיה \"תורת הבית\"-תקנו."},{"i":15112,"n":"הירירה, משה אברהם משלוניקי","bt":"תרלז","dt":"תשיח","dp":"תל אביב","b":"ר\"מ בביהמ\"ד לרבנים \"אור החיים\" בשלוניקי, עלה לארץ וכיהן כדיין בתל אביב-תרץ."},{"i":15113,"n":"הירירה, משה משלוניקי","f":"יוחנן","dt":"תקכב - יח תמוז","dp":"שלוניקי","b":"רב בשלוניקי-תקטו, בזמן ר משה שלמה הירירה, וממלא מקום הרב הראשי. פסק לטובת ר יצחק אמאריליו בדינו נגד הגבירים. נשא ונתן עם ר בנבנשטי גאטיניו. נספד ע\"י ר יוסף נחמולי. בניו ר יצחק הדיין ור אברהם."},{"i":15114,"n":"הירירה, שלמה משלוניקי","dt":"תץ","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":15115,"n":"הירמעס, אברהם פסח מארה\"ב","f":"ישראל","bp":"פרען","b":"תלמיד ישיבת רבי יצחק אלחנן בניו יורק. רב באטלנטה. ממיסדי הקהלה החרדית בניו יורק."},{"i":15116,"n":"הירנשטין, יקותיאל","bt":"תקלט","dt":"תרט - יג טבת","b":"רב בוואראשדין-תקע\"ג"},{"i":15117,"n":"הירציג, רפאל מקרלסבד","b":"רב בקרלסבד. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":15118,"n":"הירצקס, אברהם","f":"הירצקיס מלבוב","b":"רב בלבוב"},{"i":15119,"n":"הירש","b":"הרב הראשון בקהילת לובמעלא"},{"i":15120,"n":"הירש בעקער מוילנא","b":"ממיסדי ותומכי ישיבת מייליס בוילנא."},{"i":15121,"n":"הירש חזן מפרשבורג","b":"חתן ר חיים טרביטש מפרשבורג. חתנו - ר יהודה ליטש-רוזנבוים."},{"i":15122,"n":"הירש יוכבד'ש","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":15123,"n":"הירש יצחק חנוך מטאלדעש","f":"אלעזר מטאלדש","b":"רב בטאלדעש, בודפשט."},{"i":15124,"n":"הירש ליב מצפת","dt":"תרטו - יג שבט","dp":"ירושלים","b":"מחכמי צפת, ירושלים."},{"i":15125,"n":"הירש מלובלין","f":"אברהם מאפטא","dt":"תח - כה אייר","dp":"לובלין","b":"רב בלובלין ור\"מ בכמה קהילות. נזכר ב\"פני יהושע\" ו\"משאת בנימין\". כנראה אחיו של ר יצחק איזיק מהורדנא (לדעת ר יוסף לוינשטין מסערוצק). חתנו - ר משה ונכדו - ר יהודה יודל אב\"ד חוץ לעיר לבוב-תיב."},{"i":15126,"n":"הירש ר מנליש מלובלין","b":"מחכמי לובלין. דיין בקראקא, הסכים על \"מקור חיים\" לר חיים קרוכמל-תנח."},{"i":15127,"n":"הירש, אבא חייא מסערעד","f":"צבי הרש רוזנבוים","k":"בעל כתבי רבי אח\"ה","r":"ראב\"ד סערעד","bt":"תקפא","dt":"תרנג-ד -כח אלול","dp":"סערעד","b":"אביו - רב בטאפיא-ביטשקע. רב בסאלוק-תרה, שומלו-וועטשע-תרז, פאפא-תריא, ראבא-טשאנאק-תרטז, טשארנא-תריט, פרשבורג-תרלד, דיין בסערעד-תרלח וחתנו - ר דוד ועסלי על מקומו אחריו. חיבר \"כתבי רבי אח\"ה\". פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד.","bk":[["כתבי רבי אח\"ה",""]]},{"i":15128,"n":"הירש, אברהם יעקב הלוי מבאניא","b":"חתן הכת\"ס. מחכמי באניא, ולפני כן בקאווטש - שם התארח חותנו הכת\"ס וחתם משם על \"פועל צדק\" לר שבתי הכהן בעל הש\"ך."},{"i":15129,"n":"הירש, אברהם יעקב מנאדי באניא","b":"חתן רבו הכת\"ס. מחכמי קאוואטש-תרכד, נאדי באניא."},{"i":15130,"n":"הירש, אברהם שלמה מברגסאז","f":"יצחק חנוך מטאלדעש","dt":"תשד - כה אייר","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור שלמה זלמן ארנריך משימלויא. חתן ר שלמה סופר מברגסאז - בן הכת\"ס. ניהל את ישיבת חותנו בברגסאז בחיי חותנו, ורב שם-תרץ על מקום חותנו אחריו. נספה בשואה."},{"i":15131,"n":"הירש, אליעזר ליפמן מסאבאדקא","f":"יעקב מטימישואר","bt":"תקסד","bp":"טימישואר","dt":"תרכא - ו אדר","b":"תלמיד החת\"ס, ור צבי הרש אופנהים מטימישואר. חתן ר יוסף רוזנפלד מגרוסורדין ועבר לשם-תקפו. רב בסאבאדקא-תקצג. תשובות אליו ב\"חתם סופר\"."},{"i":15132,"n":"הירש, אליעזר מטאלדש","bt":"תקפד","dt":"תרלז - כ אלול","b":"רב בטלדאש"},{"i":15133,"n":"הירש, אליעזר מטלג'ש","bt":"תקפב","dt":"תרלו - ב אלול","b":"רבה הראשון של טלג'ש. נזכר בשו\"ת מהר\"י אסאד."},{"i":15134,"n":"הירש, אמיל משיקגו","bt":"1852","bp":"לוקסמבורג","b":"היגר עם הוריו לארה\"ב ולמד בפילדלפיה, גרמניה. רב ריפורמי בקהילת \"הר סיני\" בבולטימור-1877, קהילת \"סיני\" בשיקגו-1880, ופרופ' באוניברסיטה שם."},{"i":15135,"n":"הירש, דוד עזרא מגאלאנטא","f":"אבא חייא מסערד","b":"חתנו - ר מאיר גרוס משארקאד"},{"i":15136,"n":"הירש, יהודה יוליוס מפפד\"מ","f":"הרש\"ר מפפד\"מ","b":"עסק במסחר. חיבר פירוש לספר ישעיה על דרך פירושי אביו."},{"i":15137,"n":"הירש, יוסף אהרן מבעקלאן","b":"מדפיס בבעקלאן, הדפיס כתב העת \"עמוד התורה\" - תרצב."},{"i":15138,"n":"הירש, יוסף מקראקא","f":"זאב צבי","k":"בעל דברי יוסף","bt":"תרסא","bp":"קראקא","dt":"תשכא","b":"חתן ר שמחה פ\"ת אב\"ד סקאווין, רב בקראקא, איבד את משפחתו בשואה ואחריה - רבה של טרנוב וחתן ר אהרן יהודה הלוי קרטגנר מקראקא. התיר מאות עגונות. דיין בפריס, ולבסוף רב בארה\"ב. חיבר \"דברי יוסף\" ניו יורק תשך, \"ארץ צבי\", ועוד."},{"i":15139,"n":"הירש, יעקב הלוי מוינה","f":"צבי ממטרסדורף","k":"בעל המור דרור","bt":"תקעה","bp":"מטרסדורף","dt":"תרסג - בערך","dp":"מטרסדורף","b":"תלמיד החת\"ס, ור אליעזר ליפשיץ ממטרסדורף. חתן ר גבריאל טרביטש ממטרסדורף. רב במטרסדורף-תקצח, זעכסהויז (ליד וינה)-תרכב. חיבר \"עטרת תפארת\" ועוד. (מתאר את המחלוקת שהיה במטרסדורף בין מהר\"ם אלמאש ור אליעזר ליפשיץ - ואת פעולתו של החת\"ס בענין)."},{"i":15140,"n":"הירש, יעקב יוקל מגורליץ","f":"מרדכי זאב","k":"בעל ברכת יעקב","bt":"תקע","bp":"למברג","dt":"תרם","b":"תלמיד הדברי חיים מצאנז. רב בגורליץ, ניימרקט-תרכב, חתן בזיוו\"ש של ר יצחק וייס מגורליץ. חיבר \"ברכת יעקב\" למברג תרלט."},{"i":15141,"n":"הירש, יצחק הלוי","b":"רב בקהל גרים בוזודאויפאלו-תר\"פ"},{"i":15142,"n":"הירש, יצחק הלוי מבזד אויפאלו","dt":"תש..","b":"רב קהילת הגרים בכפר בזד-אויפאלו כ-50 שנה, ותרגם להם להונגרית דינים ומנהגים, בשנת תרס ביקר שם ר יחזקאל פאנט ודרש בפניהם באידיש כשר יצחק מתרגם להם סימולטנית. (על קהילת הגרים - יהודה מארטון - פנקס הקהלות רומניה כרך ב). נספה בשואה."},{"i":15143,"n":"הירש, יצחק חנוך מטלג'ש","b":"רב בטלג'ש בסוף המאה ה-19. מודעה ממנו בדבר שוחט ב\"אלגעמינע יידישע צייטונג\"-תרס. נזכר ב\"באר חיים מרדכי\" על נסיון לערער על חזקת הרבנות שלו."},{"i":15144,"n":"הירש, יצחק יחיאל הלוי","dt":"תשד","b":"רב בערדאטלק"},{"i":15145,"n":"הירש, ישראל חיים מבאדישל ונ\"י","k":"בעל אור וחיים לישראל","b":"רב באדישל, ניו יורק. ?? לא באוצר ??"},{"i":15146,"n":"הירש, מיכאל מהמבורג","f":"מנחם מנדל מאלטונא","b":"אביו היה רבה של אלטונא, אחיו - ר רפאל אריה-אביו של הרש\"ר הירש."},{"i":15147,"n":"הירש, מנדל מפפד\"מ","f":"שמשון רפאל מפפד\"מ","k":"מנדל ד\"ר הירש","b":"חתנו - ר הלל קליין מליבאוי המכונה ד\"ר קלוין."},{"i":15148,"n":"הירש, מנחם הלוי","k":"בעל אוצר פירות עץ חי","b":"חיבר \"אוצר פירות עץ חיים\" - מפתח לקובץ \"פרי עץ חיים\" מאמשטרדם - שיצא לאור ע\"י ישיבת \"עץ חיים\" באמשטרדם."},{"i":15149,"n":"הירש, מרדכי עמרם מהמבורג","f":"יצחק צבי מטיסא בעא","k":"בעל דברי שלום ואמת","bt":"תקצג","bp":"טיסא-בעא","dt":"תרסט","dp":"המבורג","b":"תלמיד ר אברהם ארינשטין מטיסא-בעא, ר אפרים בראון מטשאבא, ר ש\"י רפפורט בפרג. רב בקארצאג-מחוז יאס נאגי קון סולנוק-תרטו (הקהילה היתה ניאולוגית), טיסא-בעא, אויבן(=בודפשט)-תרכא וראש ישיבה שם - ניסה לפשר בין החרדים למחדשים, פרג-תרמ, המבורג-תרמא. חתן ר יחזקאל משה ליפשיץ פישמן ממישקולץ. פרסם מאמרים ב\"אהל יצחק\" סטמר - תרסג - תרעד. נתמנה כבורר מטעם המלכות במחלוקת בקאשוי (ועל כך ב\"דברי שלום ואמת\"). היה מתומכי הסטטוס קוו בקונגרס הרבנים. חיבר ספרים ומאמרים בשפות שונות."},{"i":15150,"n":"הירש, משה מסאבאטיטש","dt":"תשד","b":"רב בסאבאטיטש"},{"i":15151,"n":"הירש, משה צבי מראב","f":"אבא חייא הירש מסערעד","bt":"תרט","bp":"שמולו-וועטשע","b":"תלמיד הכת\"ס. חתן ר בנימין זאב וולף זוסמן סופר מבודפשט. רב בראב."},{"i":15152,"n":"הירש, משה. ברון","b":"קיבל את הזכיון לבנית מסילת ברזל מתורכיה לאירופה. תרם הרבה גם לקהלה בשלוניקי-אחרי השריפה-תרן ונקראה שכונה על שמו."},{"i":15153,"n":"הירש, עקיבא הלוי מנאדי-באניא","f":"אברהם יעקב -חתן הכתס","bt":"תרלו","bp":"קאוואטש","dt":"תשד - יא סיון","dp":"אושוויץ","b":"נכד הכת\"ס. חתן בית שטרן מפילדעש. מחכמי נאדי-באניא ועמד בראש הקהלה."},{"i":15154,"n":"הירש, צבי יחיאל הלוי מערדא","b":"רב בערדא-טעלעק. חתן ר מנחם גליק מערלוי(=אויהל)."},{"i":15155,"n":"הירש, צבי מטלג'ש","f":"אליעזר מטלג'ש","dt":"תרנ.. - בערך","b":"רב בטלג'ש על מקום אביו."},{"i":15156,"n":"הירש, רפאל","f":"מנחם מנדל","b":"אביו של ר שמשון רפאל הרש\"ר."},{"i":15157,"n":"הירש, שאול ליב","f":"יואל משה","b":"אחיו של ר יעקב יוקל."},{"i":15158,"n":"הירש, שמעון יוסף מהולנד","b":"רב בזבאלי-הולנד-תרע, מחבר ועד הקונסיסטואר."},{"i":15159,"n":"הירש, שמשון רפאל מפפד\"מ","f":"רפאל בן מנחם מנדל פר","k":"הרש\"ר הירש","r":"רב בפארנפורט על נהר מיין","bt":"תקסח","dt":"תרמט - כו טבת","b":"נכד ר מנחם מנדל פרנקפוטר-שפירא מאה\"ו. תלמיד ר נתן נטע עלינגן בהמבורג. הקים עולה של תורה בגרמניה,מחנך ומשפיע,רב באולדנבורג,אנריך,אזנבריק,ניקלסבורג-תר\"ז,פפד\"מ-תרי\"א. בנו - יהודה-יוליוס, ר מנדל ד\"ר הירש, חתנו - ר שלמה ברויאר. בתו - שרה מחברת בת רחמה יחד עם מאיר להמן.","bk":[["רש\"ר הירש","מפרשי תורה"],["אגרות צפון - יט אגרות על היהדות",""],["במעגלי שנה",""],["המצוות כסמלים",""],["חורב - על טעמי המצוות הנוהגות בזמן הזה, דיניהן, ושורשיהן",""],["יסודות החינוך - שיחות פדגוגיות",""],["מתנה טובה - הגיונות ליום השבת",""],["עטרת צבי - אבות",""],["ענג שבת - מאמר",""],["פירוש רש\"ר הירש - על התורה, תהילים, סידור",""],["אגרות צפון",""],["דאס סאציאלע לעבען פון די יודען לויטן תלמוד",""],["השבת",""],["חורב",""],["חמש חנכות",""],["כתבי הרב הירש",""],["מיטב הגיון",""],["ענג שבת",""],["שבת של ישראל",""],["אוסף כתבי רש\"ר הירש",""],["חומש רש\"ר הירש",""],["מסכת אבות - עם פירוש רש\"ר הירש",""],["סידורעם פירוש רש\"ר הירש",""],["שמש מרפא",""],["תהילים עם פירוש רש\"ר הירש",""]],"e":"תקס\"ח-תרמ\"ט"},{"i":15160,"n":"הירש, שרה","f":"שמשון רפאל-רש\"ר הירש","k":"בעל בת רחמה","b":"חיברה ספר עם מאיר להמן."},{"i":15161,"n":"הירש-רוזנבוים, צבי הרש מטאפיא","f":"משה נחום רוזנבוים","dt":"תקצט","b":"תלמיד החת\"ס. אחיו - ר עמרם חסידא מהעדילא-מאדע, ר אליעזר דוד הירשלר מבאטש. רב בטרנטשין-תקעה, טעליקע-תקפ, טאפיא-ביטשקע-תקפו. בניו - ר אבא חייא הירש מסערעד, ור יחזקאל רוזנבוים-שטיינר מטעט."},{"i":15162,"n":"הירשביין, פרץ","k":"בעל דרמות","bt":"1880","bp":"קלישצאל-פלך גרודנא","dt":"1948","dp":"לוס אנגלס","b":"תלמיד ישיבות בריסק, וילנא. פרסם שירים ומחזות בעתוני התקופה. היגר לארה\"ב-1911. חיבר ספרי מחזות, סיפורי ילדים וסיפורי מסע בעקבות מסעותיו בא\"י, הודו, דרום אפריקה, ועוד. חיבר גם \"הודו\" - ת\"א תרצא."},{"i":15163,"n":"הירשברג חיים זאב","bt":"1903","dt":"ה'תשלו 1976","bk":[["יחס האגדה להלכה",""]]},{"i":15164,"n":"הירשברג, אברהם מארה\"ב","bp":"סינסינטי-אוהיו","b":"תלמיד ביהמ\"ד לרבנים בסינסינטי. רב ריפורמי בשיקגו."},{"i":15165,"n":"הירשברג, חיים בן ציון מירושלים","f":"אליעזר דב","bt":"תרכג","bp":"ירושלים","dt":"תרץ - כט שבט","dp":"ירושלים","b":"תלמיד ישיבת עץ חיים בירושלים."},{"i":15166,"n":"הירשברג, ליבש מפילץ","k":"ליבש פילצער","b":"חתן ר דודל שרה'ס. גיסו של ר שמואל בירנבוים בעל \"מעשה חושב\". רב בפילץ-תר\"י. חתנו ר נתן בן ברוך שפירא מפילץ."},{"i":15167,"n":"הירשהורן, יהושע הלוי ממונטריאו","f":"סנדר הירשהורן","bt":"תרנד","bp":"קרילוביץ-אוקראינה","b":"תלמיד ישיבת מוהילוב, וישיבות ליטא. נסמך מאת: בעל \"אלף המגן\" מויניצא, ר ליב ברוידא בעל \"מצפה אריה\", ר אברהם פרלמוטר מוארשא. רב בקרילוביץ, סטנוב על מקום זקנו ר משלם זוסיא, מונטריאול. חיבר מאמרים ב\"הבאר\" - זאמושץ-וארשא תרפד, \"בית ועד לחכמים\" - סטמר תרפב, \"מרכז התורה\" - מונטריאול תשב. חיבר שו\"ת - בכת\"י. נזכר ב\"פרדס הרמונים\" לר יואל כץ מערדער, ועוד."},{"i":15168,"n":"הירשהורן, משלם זוסיא","b":"רב בסטאנוב-תרל. נזכר בשו\"ת מהרש\"ם מברזאן."},{"i":15169,"n":"הירשהורן, סנדר הלוי","f":"משלם זוסיא","b":"רב-שנת תרס. נזכר ב\"אמרי יושר\" לר מאיר אריק."},{"i":15170,"n":"הירשהורן, צבי מיבורוזנה","f":"שמואל","bt":"תרס","bp":"קמינקא","dt":"תשג","dp":"גיטו לבוב","b":"תלמיד ר פסח פרוסקין בקוברין ונסמך ממנו. מלמד תורה בלמברג חתן ר נחום פלוהר. רב ביבורוזנה-תרץ, ביאלה פודלסקה-תרצח, מגיד שיעור בקלויז זידיטשוב בלבוב. נשיא צא\"י בפולין-תרצב. נספה בשואה. פרסם מאמרים ב\"הנצח\" - לבוב תרפז, \"תלפיות\" - טרנוב תרצח."},{"i":15171,"n":"הירשוביץ, אברהם אליעזר מארה\"ב","f":"יצחק איזיק","k":"בעל מנהגי בית יעקב","bp":"קובנא","b":"רב בפיטסבורג. חיבר \"מנהגי בית יעקב\" וילנא תרנט. פרסם מאמרים ב\"פרח הלבנון\" - וארשא תרעח."},{"i":15172,"n":"הירשוביץ, אברהם מברנוביץ","dt":"תשג","b":"ר\"מ בברנוביץ"},{"i":15173,"n":"הירשוביץ, אברהם מקאמאי","f":"יונה","bt":"תרכא","b":"מצאצאי ר אברהם שמואל מאיישישוק. תלמיד ישיבות וולוזין, איישישוק, קובנא. רב בקאמאי-פלך קובנא-תרמד, ריבינשק, סקידיל-פלך גרודנא-תרע. נסמך מאת: ר יצחק אלחנן מקובנא, ר ראובן מדווינסק, ר רפאל שפירא מוולוזין."},{"i":15174,"n":"הירשוביץ, אברהם עבר מארה\"ב","f":"שמואל שלמה","k":"בעל בית אברהם","bt":"תר","bp":"שילעל-זאמוט","dt":"תרפה","dp":"ירושלים","b":"נסמך מאת ר יצחק אלחנן מקובנא. רב במלבורן-אוסטרליה-תרנא, ובשנת תרנד בניו יורק, סן פרנציסקו, עלה לירושלים-תרפב. חיבר גם \"מדרש שמואל\". חתנו - ר משה סטאל מניו יורק.","bk":[["בית אברהם",""],["בית מדרש שמואל",""]]},{"i":15175,"n":"הירשוביץ, אברהם שמואל","f":"יצחק איזיק אליעזר","bt":"תרנה","dt":"תשא","dp":"שקודוויל","b":"ר\"מ בישיבת \"תורת חסד\" בברנוביץ, סלונים. נספה בשואה עם תלמידיו בשקודוויל."},{"i":15176,"n":"הירשוביץ, בנימין אליהו ממוהילו","b":"דיין במוהילוב, חתם-תרלט עם ר משה יצחק הכהן רבינוביץ, ור בנימין ביינש בריז\"ל (ראווינסקי?) על מכתב לר שמואל סלנט בענין גט."},{"i":15177,"n":"הירשוביץ, זאב מדרום אפריקה","b":"רב בדרום אפריקה. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":15178,"n":"הירשוביץ, יוסף ליב","f":"יהושע","k":"בעל האשכול","bt":"תרלה","bp":"רוגצו'ב","dt":"תרצה - יד אדר","dp":"ברלין","b":"נולד למשפחת רבנים. תלמיד ישיבת וולוזין והוסמך לרבנות ע\"י הרב ריינס. רב באסטרכן. חזר לליטא אחרי מלחה\"ע ה-I והתישב בפוניבז, עבר לקובנא והתפרנס ממסחר. פעיל ב\"המזרחי\". חיבר גם חוברות לנוער.","bk":[["האשכול - בבא קמא",""]]},{"i":15179,"n":"הירשוביץ, יצחק איזיק אליעזר","f":"אריה ליב","k":"בעל מיטב הגיון","bt":"תרלא","bp":"ליבאו-לטביה","dt":"תשא - כז אלול","dp":"וירבאלן","b":"חתן ר אליעזר גורדון מטלז. תלמיד ישיבת טלז, וולוזין, באקשט. רב בטילסן(=טאלסן)-קורלנד-תרסו. גלה למינסק-בזמן מלחה\"ע ה-I, ואחריה בסמולוביץ-פלך מינסק ולימד שם במחיצת החפץ חיים-שעבר לשם עם ישיבת ראדין בזמן המלחמה, ובהמשך עזב החפץ חיים והפקיד בידיו וביחד עם ר אלחנן וסרמן את מקצת תלמידיו. רב באיהומן-ליד סמולוביץ על מקום ר יהונתן ירושלימסקי והקים שם ישיבה, ברח בזמן הקומוניסטים עם ישיבתו לפולין והגיעו לטלז. מנהל ישיבת סלובודקה, ביהמ\"ד למורים בטלז, רבה האחרון של וירבאלן. נספה בשואה עם בני עדתו. מבניו: ר אברהם שמואל מברנוביץ, ר נחמן מיאלוק ואטיאן, ר אריה ליב מישיבת טלז - נספו בשואה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז. בנו - ר ליבר - תלמיד ישיבת חברון.","bk":[["הליכות עם עולם",""]]},{"i":15180,"n":"הירשוביץ, ליב","dt":"תשג","b":"רב בנימונייץ"},{"i":15181,"n":"הירשוביץ, נחמן מיאלוק ואוטיאן","f":"יצחק איזיק אליעזר","bt":"תרסב","dt":"תשא-ג","b":"חתן ר שמואל יעקב רבינוביץ מיאלוק. רב ביאלוק על מקום חותנו, אוטיאן. נספה בשואה."},{"i":15182,"n":"הירשוביץ, צבי","dt":"תשג","b":"רב בדאבייק"},{"i":15183,"n":"הירשוביץ, שמואל ליב","b":"נספד ב\"תל תלפיות\" - ירושלים תשא."},{"i":15184,"n":"הירשוביץ, שניאור זלמן מראגובה","f":"אברהם","k":"בעל אבן בחן","r":"רב בעיר גולדינגן כחמישים שנה","bt":"תקעח","bp":"ליטא","dt":"תרסד - ג-ד סיון","dp":"גולדינגן","b":"מצאצאי אדמורי ליובאויטש. תלמיד ישיבת וולוזין, ישיבת אנטאקאליע בוילנא אצל ר יצחק גרוזנסקי שירוינטר. תלמיד חבר לר ישראל סלנטר. רב בראגובה, בויסק, גולדינגן-קורלנד-תריא כ-50 שנה. הו\"ל דרושיו וחדושיו של ר ישראל סלנטר בשם \"אבן ישראל\" עם \"אבן בחן\" ממנו. חדושיו על הרי\"ף נדפסו בש\"ס וילנא בשם \"גליון אלפס\". חיבר כתבים נוספים ואבדו בשואה. בנו - ר יוסף, חתנו - ר חיים מאיר גרין מגרובין.","bk":[["אבן בוחן - חידושים (נדפס יחד עם ספר אבן ישראל להגר\"י סלנטר)",""],["גליון אלפס - על הרי\"ף",""]]},{"i":15185,"n":"הירשזון, יהודה מפרוינבורג","f":"משה","k":"בעל צלצל כנפים","bp":"שאווילן-קורלנד","dt":"תרסב","b":"בזיוו\"ש חתן ר יחזקאל יעקובזון מקליקול. רב בפרוינבורג-תרלא."},{"i":15186,"n":"הירשזון, ישראל מוארשא","f":"צבי הירש","dt":"תקעט","b":"גביר ובעל צדקה בוארשא. חתנו - ר שלמה איגר בנו של ר עקיבא איגר שהיה עמו בקשרי ידידות. נספד מאת ר יצחק בנו של המגיד מדובנא (ההספד מופיע בספר קול נגידים למגיד מדובנא)."},{"i":15187,"n":"הירשטל, ישראל מקראקא","b":"מחכמי קראקא, תשובה אליו ב\"מחזה אברהם\"."},{"i":15188,"n":"הירשטל, שלמה שמואל מויליצקה","b":"מחכמי ויליצ'קה, ממשתתפי \"אהל מועד\"-תרנט. הוא או בנו ראש מועצת ויליצקה."},{"i":15189,"n":"הירשל, אברהם זאב צבי מצאנז","f":"אלתר מאיר","k":"בעל זרע אברהם","b":"היגר לארה\"ב. חיבר \"זרע אברהם\" ניו יורק תרפז."},{"i":15190,"n":"הירשל, משה מאנגליה","dt":"תרד","b":"רב הכולל לבריטניה"},{"i":15191,"n":"הירשלם, משלם זלמן מאיטליה","b":"מגדולי חכמי איטליה בויניציאה-של\"ח"},{"i":15192,"n":"הירשלר, אברהם צבי מטופלשטין","f":"זאב וולף תרצה'ס","b":"דומ\"צ בטאפאלשטיין-תר\"מ (אולי הכוונה לר ישראל משה צבי)."},{"i":15193,"n":"הירשלר, איגנץ","bt":"תקפג","bp":"פרשבורג","b":"נשיא הקונגרס היהודי בפעשט מחוגי הניאולוגים. לאחר שנדחתה דרישת החרדים להכיר בשו\"ע כבסיס לארגון הקהילות עזבו הצירים החרדים את הקונגרס והקימו ארגון חרדי מקביל - וכך נוצר הפיצול בין הקהילות בהונגריה."},{"i":15194,"n":"הירשלר, בונם זבולון מוינה","f":"משה נחום מוינה","b":"חתנו - ר שמעון הירשלר ממאדרן."},{"i":15195,"n":"הירשלר, בונם זבולון מלונדון","f":"שמעון ממאדרן","b":"נכד ר בונם זבולון הירשלר מוינה. תלמיד הדעת סופר. רב בלונדון."},{"i":15196,"n":"הירשלר, בנימין זאב וולף תרצה'ס","f":"צבי","k":"בעל תפארת שבת","bt":"תקמה","bp":"מטרסדורף","dt":"תרכה - יב אייר","b":"תלמיד החת\"ס. התייתם בילדותו וגדל אצל ר טוביה הכהן כץ מגיסינג. רב במטרסדורף-תקסח, והקים שם ישיבה-תקפב. רב בגיסניג-תקפד, טאפאלטשן-תקצח, בנו ר ישראל משה צבי על מקומו אחריו."},{"i":15197,"n":"הירשלר, יעקב ליב מבעלעד","b":"תלמיד השב\"ס. שו\"ב בגליל בעלעד-תרן."},{"i":15198,"n":"הירשלר, ישראל משה צבי","f":"בנימין וולף תרצה'ס","b":"דיין בטאפאלטשאן. חיבר מאמרים וביאורים לתורה. (אולי הוא המופיע באוצר הרבנים כ-ר אברהם צבי)."},{"i":15199,"n":"הירשלר, מאיר מפרשבורג","b":"מחכמי פרשבורג. חתן ר דוד ניימן-לקנברך מפרשבורג. חתנו - ר יוסף פרקש מפפדמ."},{"i":15200,"n":"הירשלר, משה נחום מוינה","b":"מחכמי וינה. חתן ר יוסף גינז-שלזינגר מוינה."},{"i":15201,"n":"הירשלר, פסח מלונדון","f":"שמעון ממאדרן","b":"תלמיד הדעת סופר. מחכמי לונדון."},{"i":15202,"n":"הירשלר, שמעון ממודרן","f":"בונם זבולון מוינה","k":"בעל הגיוני מוהרש\"ה","bt":"תרמח","bp":"וינה","dt":"תרצג - י טבת","dp":"פרשבורג","b":"תלמיד השב\"ס, ור מנחם מנדל דייטש מטאפלטשן. ועוד. חתן ר ישראל פרנקל משטמנסדורף ועבר לשם וכיהן כר\"מ. רב במודרן-תרעא, רב ודיין בפרשבורג-תרעט. היה מקורב לחוגי המזרחי אך בהמשך הצטרף ל\"אגודת ישראל\". נואם מוכשר בגרמנית ודרשותיו בפרשבורג משכו קהל רב. היה במחלוקת עם ד\"ר מרגליות בענין הציונות והדברים הגיעו לבית המשפט, ביקר בארץ-תרפו ואחרי הביקור התקרב שנית לציונות. בניו - ר בונם זבולון מלונדון ור פסח מלונדון. ?? לא באוצר ??"},{"i":15203,"n":"הירשמן, חיים מרישא","f":"שמואל","bt":"תרלז","bp":"רישא","dt":"תשכד","dp":"ירושלים","b":"עלה לירושלים-תרנג. מחסידי צאנז. רב בישיבת חיי עולם."},{"i":15204,"n":"הירשנזון, חיים מהובוקן-ארה\"ב","f":"יעקב מרדכי מקרלין","k":"בעל מלכי בקדש","bt":"תרטו-יז","bp":"צפת","dt":"תרצה-ח -יז אלול","dp":"הובוקן (ניו ג'רסי)","b":"למד בישיבת סוכת שלום בירושלים ואצל אביו ר יעקב מרדכי הירשנזון. ר\"מ בבריסק-תרלט, חזר לירושלים ועסק בקבלה, ר\"מ בישיבת שנות אליהו בירושלים-תרמט על מקום אביו, רב בראסקוי?, היגר לארה\"ב וכיהן כרב בהובאקן-ניו ג'רסי, וחבר בועד הרבנים באמריקה. חיבר באור לכת\"י הגר\"א על אסתר שמצא בבריינסק. \"איזו היא משנה\" ירושלים תרן, \"אלה דברי הברית\" ירושלים תרפז. עורך המסדרונה. פרסם מאמרים ב\"אפריון\" - בודפשט תרפד, \"קול תורה\" - פאביאניץ תרפו, \"שערי ציון\" - ירושלים תרפא, \"ירושלים\" - ירושלים תרמב-תרעט. הו\"ל \"המסדרונה\" - פפד\"מ-ירושלים תרמה, והקים בית דפוס בירושלים שם הדפיסו - תרמו.","bk":[["ברורי המדות",""],["תורת ארץ ישראל",""]]},{"i":15205,"n":"הירשנזון, יעקב מרדכי מקרלין","f":"צבי","k":"בעל דבר השמיטה","dt":"תרמט באוצ' תרנג","dp":"ירושלים","b":"מחכמי קרלין, עלה לירושלים. מחכמי צפת וירושלים, יסד ישיבה בירושלים בשם \"שנות אליהו\". חיבר \"דבר השמיטה\", \"קדושת ארץ ישראל\" ירושלים תרמה, ועוד. בניו - ר יצחק, ר חיים בעל \"המסדרונה\"."},{"i":15206,"n":"הירשנזון, יצחק","f":"יעקב מרדכי הירשנז","b":"מחכמי ירושלים-תר\"ס"},{"i":15207,"n":"הירשעל שמחה'ס מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":15208,"n":"הירשפלד, יצחק אריה","f":"ברוך מויסוקי","bt":"תרלד","bp":"ויסאקי-מאזאויצקי","b":"מצאצאי אחר מ\"ארבע החיות\" מבארקי. תלמיד ישיבת סלובודקא, קעלם. חתן ר אפרים פישל ציקערט מגראעווא. רב ברוטקי-פלך לומזה-תרסד. נסמך מאת: ר יצחק בלזר, הרידב\"ז, ר שמעון דב משדליץ. הניח חדושים בהלכה ואגדה - בכת\"י."},{"i":15209,"n":"הירשפלד, מאיר מוויצען","f":"יהודה ליב","bt":"תרח","bp":"וויצען","dt":"תרעא - יז כסלו","dp":"וויצען","b":"תלמיד הכת\"ס. חתן ר דוד דב הרמן מוויצען, ועבר לשם. מהעסקנים הפעילים בעת יסוד הקהלות האורטודוכסיות בהונגריה, וממייסדי ת.ףת והישיבה בוויצען. מחדושיו בכתב העת \"תל תלפיות\"."},{"i":15210,"n":"הירשפלד, מתתיהו","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":15211,"n":"הירשפלד, עוזר צבי מרישא","b":"פרסם מאמרים ב\"הירדן\" - רישא תרץ."},{"i":15212,"n":"הירשפלד, צבי יצחק מאסאד","dt":"תרכד - כ סיון","b":"חתן ר אשר אנשל וינר ממישקולץ. רב באסאד."},{"i":15213,"n":"הירשפלד, שלמה","b":"תשובה אליו \"מנחת אברהם\"."},{"i":15214,"n":"הירשפלד, שמואל מפרוינבורג","b":"ממיסדי חברא קדישא בפריונבורג-תרלא."},{"i":15215,"n":"הירשפלד, שמואל צבי מביליץ","f":"יעקב","bt":"תרנב","bp":"פשמישל","dt":"תשב","b":"חתן ר אליהו צבי פרידמן מויליצ'קה.רב ביאלא-ביליץ-תרפו. נספה בשואה."},{"i":15216,"n":"הירשפרונג, אברהם צבי מבובוב","f":"זאב וולף","k":"בעל מגילת יוחסין","bt":"תרסה","dt":"תרצד","b":"תלמיד ר בן ציון מבובוב. חתן ר חיים שיף אב\"ד בובוב. חיבר \"מגילת יוחסין לאדמורי בובוב\" - תרפח, \"שם עולם\" שהוציא לאור מכתב יד המחבר - ר דניאל טירני. ?? לא באוצר ??"},{"i":15217,"n":"הירשפרונג, זאב וולף","b":"חתן ר אברהם יוסף יעקב גלרנטר בעל \"רביד הזהב\". נסמך מאת: ר חיים ליב הורוביץ מקראקא, המהרש\"ם מבראזן."},{"i":15218,"n":"הירשפרונג, חיים מדוקלא","f":"יצחק יהודה","bp":"קראקא","b":"מחכמי דוקלא, חתן ר דוד צבי זעהמן מדוקלא בעל \"מנחת סולת\". הוציא לאור \"מעשה רוקח\" לר יהודה ממגנצא. נספה בשואה. בנו - ר פנחס ממונטריאול."},{"i":15219,"n":"הירשפרונג, יואל מפודגורזע","f":"זאב וולף","k":"בעל זמירות יואל","bt":"תרעא","bp":"קראקא","dt":"תשמט","b":"מחכמי פודגורזע-תרעב. חסיד בובוב. שרד בשואה ועלה לארץ. חיבר \"זמירות יואל\" ירושלים תשסג."},{"i":15220,"n":"הירשפרונג, מרדכי מארה\"ב","f":"זאב וולף","bp":"קראקא","b":"תלמיד זקנו (אבי אמו) ר אברהם יוסף יעקב גלרנטר בעל \"אמרי יאי\". היגר לארה\"ב ולמד בישיבת רבי יצחק אלחנן בניו יורק, ר\"מ בישיבה. נסמך מאת: ר הלל ד\"ר קליין, רש\"א יפה, רמ\"ז מרגליות, ר אהרן קוטלר, ר אברהם יאפאהן. חתן ר אליקים חנוך אלפנביין. רב בקהלת \"תפארת מזרחי\" בניו יורק, סאבאנא-ג'ורג'יה-תרפח, קנטון - אוהיו-תרפט ואב\"ד מדינת אוהיו, קהלת \"אגודת אחים\" בקולומבוס-תרצב, דמוין-אייווה-תשי. ציר בקונגרס היהודי. עורך שבועון באנגלית. פסם מאמרים ב\"הפרדס\", ועוד. חבר אגודת הרבנים באמריקה, ותנועת המזרחי."},{"i":15221,"n":"הירשפרונג, משה מלמברג","f":"יצחק יהודה","bp":"קראקא","dt":"תשב","b":"חסיד צורטקוב. חתן הגביר ברייטבלט (או בנימין הרמעלע) ממליץ. מחכמי למברג והתמחה ברפואה. מראשי אגודת ישראל בגליציה. נספה בשואה. פרסם בעתונות האגודאית ובירחונים רפואיים."},{"i":15222,"n":"הירשפרונג, פנחס מדוקלא","f":"חיים","k":"בעל פון נאצישן יאמער","bt":"תרעב","bp":"דוקלא","dt":"תשנח","b":"נכד-אבי אמו ר דוד צבי זעהמן מדוקלא בעל \"מנחת סולת\". תלמיד המהר\"ם שפירא בלובלין ור\"מ בישיבתו. ברח לשנחאי ומשם לקנדה והיה רב קהלת \"עדת ישראל\" במונטריאול-תשא, ראש ישיבות \"מרכז התורה\" ולובאויטש. נשיא כבוד של אגודת הרבנים באמריקה. חיבר \"פון נאצישן יאמערטאל\" מונטריאול תשה, \"פרי פנחס\" מונטריאול תשנט. עורך הירחון \"אהל תורה\" בדוקלא וקראקא תרפח (בגיל 16!), \"אור תורה\" - לבוב תרפו, \"שערי תורה\" - קראקא תרפה. חיבר \"פרי פנחס\" בגיל 13. ?? לא באוצר - המחבר קיים ??"},{"i":15223,"n":"הישראלי - משפחה","b":"משפחה עתיקה בספרד. אחד מראשוני המשפחה - ר יצחק ישראלי מהמגרב בעל ספר היסודות, בן זמנו של ר סעדיה גאון שהכתב עמו."},{"i":15224,"n":"הישראלי, יצחק מהמגרב - א","k":"בעל ספר היסודות","b":"רב במגרב בזמן ר סעדיה גאון שהתכתב אתו בהיותו בפאיום."},{"i":15225,"n":"הישראלי, יצחק מטולידו","f":"יוסף","k":"בעל יסוד עולם","dt":"צא - בערך","dp":"ספרד","b":"תלמיד הרא\"ש. מחכמי טולידו-ה'ע ובקי בתכונה, אחיו של ר ישראל הישראלי בעל פירוש לאבות. חיבר ספרים בתכונה שלא נדפסו."},{"i":15226,"n":"הישראלי, יצחק מטולידו - ג","f":"שלמה","bt":"ק","b":"מצאצאי ר ישראל הישראלי מטולידו שחיבר פירוש על מסכת אבות. מחכמי טולידו. תלמיד קרובו ר ישראל ואביו ר יצחק הישראלי. חיבר פירוש למסכת אבות-קכח, פירוש לאיוב ועוד. זקנו ר יצחק חיבר פירוש להגדה."},{"i":15227,"n":"הישראלי, יצחק מקירואן","f":"שלמה","k":"בעל פירוש לתורה","bt":"ד'-תקצב-תרי","bp":"מצרים","dt":"ד'תשי (950)","b":"רב רופא ופילוסוף בצפון אפריקה, רופא השר בקירואן. חיבר ספרי רפואה, \"גן הפילוסופיה\", ופירוש על התורה (והראב\"ע יצא כנגדו וכתב כנגדו בזלזול). חי מאה שנה ולא נשא אישה"},{"i":15228,"n":"הישראלי, ישראל מטולידו","f":"יוסף","dt":"פז - כז חשון","b":"תלמיד הרא\"ש, והעתיק בשבילו את פירוש המשניות לרמב\"ם מערבית. גדול בתכונה ודקדוק, מרביץ תורה בטוליטולא(=טולידו). חיבר פירוש לתנ\"ך, ופירוש למסכת אבות בערבית. אולי הוא שחיבר פירוש לעשרת הדברות וחתם \"ישראל בן ישראל\". אחיו - ר יצחק בעל \"יסוד עולם\"."},{"i":15229,"n":"הכהן בן ארדוט, אברהם","b":"מחכמי שלוניקי-תר\"מ. חיבר ספרים בלדינו."},{"i":15230,"n":"הכהן חסיד","k":"משפחה","b":"משפחה ותיקה בשלוניקי."},{"i":15231,"n":"הכהן חסיד, אלעזר משלוניקי","dt":"תמט","dp":"שלוניקי","b":"מחכמי שלוניקי, תלמיד בישיבת נתן העזתי בשלוניקי-תלז - אחרי המרתו של ש\"ץ."},{"i":15232,"n":"הכהן חסיד, אלעזר משלוניקי","b":"דיין בשלוניקי-תקץ, אחיו ר חננאל גם הוא דיין בשלוניקי."},{"i":15233,"n":"הכהן חסיד, חיים חננאל משלוניקי","b":"מחכמי שלוניקי-תרף. חתנו - ר משה הירירה."},{"i":15234,"n":"הכהן חסיד, חיים יצחק משלוניקי","f":"יוסף","k":"בעל אהל יצחק","bt":"תקז - בערך","dt":"תקפז","dp":"שלוניקי","b":"נכד-אבי אמו - ר אלעזר נחמיאש. רב בשלוניקי, מפקח על קופת \"ביקור חולים\" (היה אחראי לצוות לרופאים לבקר את החולים). חתנו - ר יהושע פרחיה הכהן משלוניקי. חיבר \"אהל יצחק\"-שלוניקי תקסא (ויתכן שנשלמה ההדפסה-תקפד - על כך בהערה 16 בזכרון שלוניקי-117).","bk":[["אהל יצחק","מפרשי רמב\"ם"],["אהל יצחק [שו\"ת, חי' על הרמב\"ם ודרשות]",""],["אהל יצחק – רמב\"ם",""]]},{"i":15235,"n":"הכהן חסיד, חיים משלוניקי","dt":"תרטז - ה סיון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":15236,"n":"הכהן חסיד, חננאל יצחק משלוניקי","dt":"תרסט","dp":"שלוניקי","b":"דיין בשלוניקי. הגיה \"גן נעול\"-תרכז."},{"i":15237,"n":"הכהן חסיד, חננאל משלוניקי","f":"יצחק","dt":"תקצה","dp":"שלוניקי","b":"דיין בשלוניקי-תקפד - עוד בחיי אביו. אחיו ר אלעזר-דיין בשלוניקי. חתם-תקפד עם ר דוד קרסו ור חיים שמואל גטניו."},{"i":15238,"n":"הכהן חסיד, יהודה הכהן מירושלים","dt":"תרם - י תשרי","dp":"ירושלים","b":"גביר מחכמי ירושלים, סייע בהדפסת \"כפי אהרן\" לר אהרן עזריאל."},{"i":15239,"n":"הכהן חסיד, יצחק בכור משלוניקי","dt":"תקפ-ז","dp":"שלוניקי","b":"גביר בשלוניקי. אולי הוא שנספד מאת ר יעקב רפאל מנשה בשנת תקפז."},{"i":15240,"n":"הכהן חסיד, יצחק חננאל משלוניקי","dt":"תשג","b":"רב בשלוניקי. נספה בשואה יחד עם חבריו הדיינים ר מרדכי בן אברהם ברכה, ור דוד שאלתיאל, ור יצחק בן עמנואל ברודו. בנו החזן ר חננאל."},{"i":15241,"n":"הכהן חסיד, יצחק משלוניקי","k":"בעל גן נעול","dt":"תרכז","dp":"שלוניקי","b":"מחכמי שלוניקי, חיבר \"גן נעול\"-תרכז ובו פירוש על רש\"י, דרושים ועוד, וכן חיבר פירוש על \"נחל קדומים\" לחיד\"א - בכת\"י."},{"i":15242,"n":"הכהן חסיד, מנחם הכהן משלוניקי","f":"שם טוב","dt":"תרעא - כ ניסן","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים, החזיק ישיבה בביתו, ממיסדי ביה\"ח \"משגב לדך\". חיבר דרשות - בכת\"י."},{"i":15243,"n":"הכהן חסיד, שם טוב מנחם","f":"מנחם","k":"בעל שם טוב","bp":"שלוניקי","dt":"תרמח - א תמוז","dp":"ירושלים","b":"מצאצאי ר יעקב הכהן חסיד בעל \"וערך הכהן\". מחכמי שלוניקי, עלה לירושלים-תרך ונודע בשם \"החסיד\", והיה מחכמי \"בית אל\". בניו ר מנחם הכהן חסיד מגדולי ירושלים, ור שלמה שהיה עסקן צבור חשוב בירושלים וממיסדי בית החולים \"משגב לדך\". חתנו ר יצחק בן שלום משה חי גאגין - נכד הרב אג\"ן."},{"i":15244,"n":"הכהן חסיד, שמואל מירושלים","dt":"תרכג - א כסלו","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":15245,"n":"הכהן חסיד, שמואל משלוניקי","dt":"תרטו","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":15246,"n":"הכהן יהונתן, (בן) ציון מלוב","f":"יעקב","k":"בעל בני ציון","bt":"תרנה","dt":"תשלב - ד כסלו","b":"רב בזוארה-לוב-תרפו עד תשיא, עלה לארץ-תשטז והתישב באשקלון. חיבר \"בני ציון\", ועוד."},{"i":15247,"n":"הכהן יהונתן, אהרן מאלגיר","dt":"תקנו","b":"מקובל, משורר, דיין באלגיר. מפיוטיו לפורים אלגיר לשנת תקלה - בקרוב\"ץ אלגיר. תשובות ממנו ב\"זרע יעקב\" לר יעקב בן נאיים. חתם עם רבני אלגיר והסכים על \"מטה יהודה\", \"קול יהודה\", ועוד."},{"i":15248,"n":"הכהן יהונתן, בן ציון מג'רבה","k":"בעל שערי ציון","bt":"תרלב","bp":"ג'רבא","dt":"תרצא - כו אב","b":"דרשן, מרביץ תורה, דיין בג'רבא-תרנ\"ז, אב\"ד-תרע\"ב, חיבר \"שערי ציון\"","bk":[["שערי ציון",""]]},{"i":15249,"n":"הכהן יהונתן, כמוס מג'רבה","k":"בעל כמוס שדי","dt":"תשלג","b":"תלמיד ר דידו הכהן מג'רבא. מחכמי ג'רבא, עלה לישראל והתישב בנתיבות."},{"i":15250,"n":"הכהן יהונתן, שלום מג'רבה","k":"בעל דרכי שלום","bt":"תרס","bp":"ג'רבא","dt":"תשכט","dp":"נתיבות","b":"רב בג'רבא, תלמיד ר דוד דידו הכהן מג'רבא, עלה לארץ והתישב בנתיבות. פעיל בועד \"אור תורה\" בג'רבא."},{"i":15251,"n":"הכהן מרדכי בן חנוך חיים","bt":"1906","dt":"ה'תשלב 1972","bk":[["זכר למצות הקהל",""],["על התורה",""]]},{"i":15252,"n":"הכהן, אברהם אשר מג'רבה","b":"פרסם מאמרים ב\"הירח\" - ג'רבה תשח."},{"i":15253,"n":"הכהן, אברהם מאנגליה","f":"יעקב","k":"בעל משלי יהודים הקדמ","bt":"תרמז","b":"תלמיד ביהמ\"ד לרבנים בלונדון, ור משה אביגדור חייקין בלונדון. רב במנצסטר-אנגליה-תרסט. חיבר ערכים באנציקלופדיה \"אוצר ישראל\", חיבר חוברת \"משלי יהודים הקדמונים\"."},{"i":15254,"n":"הכהן, אברהם מזאמושץ","f":"ראה אברהם הכהן מזמוש"},{"i":15255,"n":"הכהן, אברהם מתונס וירושלים","bt":"תרעה","bp":"ג'רבא","dt":"תשנד - כד ניסן","dp":"ירושלים","b":"רב ראשי בצפאקס(תוניסיה), מו\"צ בתלפיות(ירושלים)","bk":[["מלל לאברהם",""]]},{"i":15256,"n":"הכהן, אליאב"},{"i":15257,"n":"הכהן, אלימלך מראחוב","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":15258,"n":"הכהן, בן ציון","b":"תלמיד ישיבת וויצען. פרסם מאמרים ב\"הפלפול\" - שאפראן תרצח.","bk":[["שערי ציון","על הש\"ס"]]},{"i":15259,"n":"הכהן, בן ציון מהונגריה","b":"בהיותו בחור פרסם מאמרים ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":15260,"n":"הכהן, חנניה מג'רבה","b":"רב בג'רבא-תר\"ס"},{"i":15261,"n":"הכהן, יוסף גרשון מקשטיוקוביץ","f":"יעקב","bt":"תקצה","b":"רב בקאשטיוקאויץ-פלך מוהילוב-תרמא."},{"i":15262,"n":"הכהן, יעקב פנחס","k":"ראה: פנחס יעקב","b":"פרסם מאמרים ב\"הכרם\" - וארשא תרפז."},{"i":15263,"n":"הכהן, מנחם מנדל","f":"ליבוש הכהן","b":"רב בווינגוויזדוב-תר\"ס"},{"i":15264,"n":"הכהן, פנחס יהודה מאוסטרליה","f":"זאב יעקב","k":"בעל קול רנה ותודה","bt":"תרכג","bp":"אנגליה","b":"תלמיד ביהמ\"ד לרבנים בלונדון. חתן ר מרדכי הוסט מלונדון בעל \"עבודת הקדש\". נסמך מאת: ר נפתלי אדלר, ר אביגדור חייקין, ר זוסמן כהן, ר משה חיימזון, ר אשר פלדמן. רב בדבלין-אירלנד, לונדון, סידני-אוסטרליה-תרסה ורב צבאי באוסטרליה. חיבר גם \"שירי כנסת ישראל\", מאמרים בנושאי מוזיקה באנגלית, צרפתית ולשון אשכנז."},{"i":15265,"n":"הכהן, פנחס יעקב מלונדון לייפצי","k":"הו\"ל חזקה רבה","b":"רב בלייפציג, פרשבורג, לונדון. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד, \"מגד ירחים\" - סיגט תרנח, \"הכרם\" - וארשא תרפז. פרסם \"רשימת ספרים ומאמרים לכבוד מונטיפיורי\" - סיני תשיג."},{"i":15266,"n":"הכהן, פנחס מטאלאש","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":15267,"n":"הכהן, רפאל חיים מפרס וירושלים","f":"אהרן","k":"בעל שיר ושבחה","bt":"תרמה","bp":"שירז-פרס","b":"מדפיס בירושלים, מראשי העדה הפרסית בירושלים. הו\"ל שיר ושבחה - ירושלים תרסה."},{"i":15268,"n":"הכהן, רפאל מתונס","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":15269,"n":"הכהן, שלמה יהודה ליב מזעגרש","f":"שלום צבי הכהן","dt":"תשג","b":"רב בזעגרש. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":15270,"n":"הכהן, שמואל ישראל","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":15271,"n":"הכולשי, אהרן","b":"מרבני אנדרופלה-טורקיה-ש'. נזכר בהקדמת ר שלמה עתרא לפירושו לתהלים."},{"i":15272,"n":"הכט, ישי מבלז","f":"אריה","bt":"תרסט","bp":"בלז","dt":"תשכב","dp":"ניו יורק","b":"חתן ר אליעזר פיש מביקסאד מסטמר. ניצל מהשואה ועבר לאוסטריה, כיהן כרב בעיר האהנעמס-ברעגענץ. חתן בזיוו\"ש לר נחום עזיראל מילר מקאלין. היגר לארה\"ב-תשיב ושימש כרב בניו יורק."},{"i":15273,"n":"הכט, מאיר מיונקרס-ארה\"ב","k":"בעל ישראל בעמים","bt":"תריא","dt":"תשג","b":"רב ביונקרס-ארה\"ב-תרס."},{"i":15274,"n":"הכט, משה מבאלהאש","b":"רב בבאלהאש-ת\"ר"},{"i":15275,"n":"הכט, נתן מירוסלב","f":"שמואל","bt":"תקכ","dt":"תקף","b":"דיין בירוסלב-תקנו. על פי צוואת אביו טיפל בהדפסת ספרו \"שם משמואל\"."},{"i":15276,"n":"הכט, צבי אלימלך משינאווא","f":"אפרים פישל משיניבה","bp":"שיניבה","dt":"תרצח","b":"נשלח לארה\"ב-תרן ע\"י האדמור משיניבה להיות גבאי צדקה (בסמכו עליו שישאר יהודי נאמן). בניו ר יהושע - חסיד בוסטון - נפטר תשיג, ר אפרים פישל."},{"i":15277,"n":"הכטמן, חיים משה מסארני","dt":"תשב - יד אלול","b":"רב בסרנה(=סארני)."},{"i":15278,"n":"הכטמן, משה חיים מדרובילא","b":"רב בדרובליע-תרע\"ה"},{"i":15279,"n":"הכטמן, משה יום טוב מרוביליא","b":"תלמיד ישבת סלוצק (היה מ-14 התלמידים שהביא עמו ר איסר זלמן מלצר - כשהקים את הישיבה). רב ברובליא-תר\"ס"},{"i":15280,"n":"הלבורט, יואל מדובנא"},{"i":15281,"n":"הלבמונד, יצחק מפפד\"מ","dt":"תכה","b":"מראשי קהילת פפד\"מ-תא, בזמן ר שבתי הורביץ-בנו של השל\"ה."},{"i":15282,"n":"הלברד, גרשון משה מטוריסק","f":"חיים יהודה אריה","bt":"תרל","b":"רב בסטרבין-פלך מינסק-תרס, טימקוביץ-פלך מינסק."},{"i":15283,"n":"הלברטל, דב בריש מלנצהוט","f":"יהושע יהודה","bt":"תקם","dt":"תרט","b":"רבה של לנצהוט, בנו ר משה על מקומו אחריו."},{"i":15284,"n":"הלברטל, דוד בריש מברוד","f":"[יוסף]","b":"מחכמי ברודי. ממשתתפתי \"אהל מועד\"-תרנח."},{"i":15285,"n":"הלברטל, זאב וולף מברוד","f":"יהושע יהודה","bt":"תקלה","dt":"תרח","b":"מחכמי ברודי. אביו של ר יוסף שרשם את יחוס המשפחה בספר \"מגן דוד\"."},{"i":15286,"n":"הלברטל, זלמן (שלמה) מברוד","b":"תלמיד חכם בברודי. תשובה אליו בשו\"מ."},{"i":15287,"n":"הלברטל, זלמן מזלוטשוב","b":"גביר בזלוטשוב. תשובה אליו בשו\"מ."},{"i":15288,"n":"הלברטל, יהושע השל מזמיגרוד","f":"נפתלי הרץ מדובנא","b":"עבר משינבה לכהן כרב בזמיגרוד. אחיו של רד\"ב מטיטשין."},{"i":15289,"n":"הלברטל, יוסף מברוד","f":"זאב וולף","bt":"תקעה","dt":"תרמה","b":"ההדיר את ספר \"מגן דוד\" לר דוד מטולנא למברג תרם. הוסיף הקדמה ובה סדר יחוסו."},{"i":15290,"n":"הלברטל, מנחם מוניש מריינזוב","dt":"תש..","b":"גבאי א\"י עד השואה. נספה בשואה."},{"i":15291,"n":"הלברטל, מנחם מליינץ","b":"רב בריינזוב-תרץ."},{"i":15292,"n":"הלברטל, מנחם צבי מלמברג","f":"משה חיים","bt":"תרלח","bp":"ברודי","dt":"תשיח","b":"מחכמי זלוטשוב וברודי, עבר ללמברג-תרפח. ניצל בשואה ופעל אחריה לשיקום חיי היהודים בקראקא. עבר לאנטורפן-תשו והיה מחשובי חסידי בלז שם. ההדיר את ספר זקנו \"מעשה רוקח\" לר אלעזר רוקח."},{"i":15293,"n":"הלברטל, משה חיים מחורוסטקוב","f":"יהושע יהודה","bt":"תקמה","dt":"תרטו","b":"בנו של אב\"ד פרוסקורוב. רבה של חורוסטקוב."},{"i":15294,"n":"הלברטל, משה מלנצהוט","f":"דוב בריש","bt":"תקס","dt":"תרטז - כב סיון","b":"רבה של לנצהוט-תרט על מקום אביו."},{"i":15295,"n":"הלברטל, נפתלי מאולינוב","k":"בעל בן המדתא","b":"מחכמי אולינוב-תרלז, תשובה אליו בשות מהרשם. חיבר \"בן המדתא\" למברג תרנא (נגד בחירת ד\"ר יוסף שמואל בלוך לפרלמנט)."},{"i":15296,"n":"הלברטל, שלמה דב בריש מברוד","f":"משה חיים","bt":"תר","dt":"תרעא","b":"חסיד בלז מחכמי ברודי."},{"i":15297,"n":"הלברטשם, יחזקאל מסוסנוביץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":15298,"n":"הלבריך, שלמה צבי מסוקוליבקה","f":"שמואל","bt":"תקץ","dt":"תרסה","b":"חסיד בלז מחכמי סוקוליבקה וראש הקהל מעל חמישים שנה. חתן המהרש\"ק."},{"i":15299,"n":"הלברשטט","f":"מרדכי ליכטנשטיין","k":"ראה: איזנשטט","dt":"תשב - כא אלול","b":"דרשן,רב בלחוואי"},{"i":15300,"n":"הלברשטט, אברהם מהלברשטט","b":"רב בהלברשטט-ת\"נ"},{"i":15301,"n":"הלברשטט, אברהם מראויטש","f":"צבי הירש הלברשטט","b":"רב בראוויטש"},{"i":15302,"n":"הלברשטט, אליעזר הלוי מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט. בנו - ר יוסף ונכדו ר אלעזר לאזי-אב\"ד באה\"ו."},{"i":15303,"n":"הלברשטט, אריה ליב מדובנקא","f":"צבי הירש אשכנזי","b":"חתן ר יחיאל מהורדנא. רב בדובנקא. בנו - ר מאיר ספרא ודיינא בלובלין ואפטין."},{"i":15304,"n":"הלברשטט, בנדיט","b":"בנו - ר שמואל זנויל הלברשטט מברלין."},{"i":15305,"n":"הלברשטט, דב בריש ממזריטש וטוט","f":"נפתלי הרץ מדובנא","b":"נכד-אבי אביו ר צבי הירש מהלברשטט. רב במזריטש, טוטשין. אחיו של ר זאב וולף מדובנא. בנו ר יצחק צבי הלברשטם מאוסטרהא."},{"i":15306,"n":"הלברשטט, זאב וולף מדובנא","f":"נפתלי הירץ מדובנא","bt":"תקה","bp":"ברודי","dt":"תקס","dp":"דובנא","b":"חתן ר נחמן הלפרין(15980). רב בראדיוויל, אב\"ד דובנא רבתי-תקמו-תקנא על מקום אביו, ובנו ר חיים יעקב אשכנזי על מקומו אחריו. אחיו של ר דב בריש אב\"ד מזריטש וטוטשין. בנו - ר יצחק צבי הירש מאיוויניץ ומינסק, ר חיים יעקב."},{"i":15307,"n":"הלברשטט, זנויל מברלין","f":"בנדיט","b":"דיין מראשי הקהילה בברלין-תע עם ר מרדכי טאקלעס-הראב\"ד, והיה מתומכי ר מרדכי ראנבאך בזמן המחלוקת אודות ביהכ\"נ בברלין. תשובה ממנו ב\"מנחת כהן\" לר שבתי בן משה הכהן. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":15308,"n":"הלברשטט, חיים מאוסטרהא","f":"צבי יעקב מפודקמין","k":"חיים פעסיס","dp":"מזריטש","b":"נכד ר נפתלי הרץ מדובנא, ונינו של ר צבי הירש בעל \"עטרת צבי\". חתן ר אריה ליב בן משלם זלמן אשכנזי מאוסטרהא. מחכמי אוסטרהא-תקסה. נפטר כשנסע לבקר את בתו במזריטש."},{"i":15309,"n":"הלברשטט, יהודה ליב מברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":15310,"n":"הלברשטט, יהודה ליב מפיורדא","dt":"תקצא","b":"תלמיד ה\"פני יהושע\". דיין בפיורדא וראש הישיבה יחד עם ר וולף מהמבורג. מתלמידיו הרב במברגר מוירצבורג."},{"i":15311,"n":"הלברשטט, יהושע יהודה","f":"משה הלברשטט","b":"רב בברסטיצקי-תר\"מ"},{"i":15312,"n":"הלברשטט, יואל מברלין","f":"זנויל","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":15313,"n":"הלברשטט, יוזל מהמבורג","dt":"תקיג","dp":"אלטונא","b":"חזן ושמש ה\"קלויז ישן\" בהמבורג - שנוסד ע\"י ר יונתן איבשיץ."},{"i":15314,"n":"הלברשטט, יוסף חיים מהורדנא","f":"שמחה","dt":"תקצב - כו אד\"ב","dp":"הורדנא","b":"מצאצאי ר צבי הירש הלברשטט, נכד ר יצחק מאיווניץ. מחכמי הורדנא. חתן בנו של ר בנימין ברוידא-אב\"ד הורדנא."},{"i":15315,"n":"הלברשטט, יוסף מליסא","f":"צבי הירש אשכנזי","b":"ר\"מ בליסא. חתם על מכתב רבני ליסא לפפד\"מ בענין מתן רשות לר אברהם ממפד\"מ לשוב לליסא, ונזכר ב\"מגן דוד\"."},{"i":15316,"n":"הלברשטט, ישראל משה מדובנה","dt":"תרלב","b":"רב בדובנה, אושפול-ליטא."},{"i":15317,"n":"הלברשטט, מינקי","b":"תלמיד ר יונתן איבשיץ. דיין וראב\"ד בהלברשטט-תקל."},{"i":15318,"n":"הלברשטט, משה","f":"יהודה ליב מפיורדא"},{"i":15319,"n":"הלברשטט, משה מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":15320,"n":"הלברשטט, משה מסטנוב","f":"נפתלי הרץ","dt":"תרח - ד חשון","b":"רב בסטאנוב"},{"i":15321,"n":"הלברשטט, נפתלי הירצל מלמברג","f":"מאיר מאפאלין ומוהליב","b":"מצאצאי ר צבי הירש הלברשטט בעל \"תפארת צבי\", נכד ר יחיאל מרגליות מהורדנא. תלמיד החוזה מלובלין, והיהודי הקדוש מפשיסחא - שהיה גם מחותנו - חתנו היה בן רבו - ר יהושע אשר רבינוביץ מפורישוב."},{"i":15322,"n":"הלברשטט, נפתלי הרץ מדובנא","f":"צבי הירש מהלברשטט","dt":"תקלז - י אייר","b":"חתן ר יעקב באבד מברודי. אחיו של ר שלמה דב בריש מגלוגא. רב בקאוולי, דובנא על מקום ר שאול שעבר לאמשטרדם, ובנו ר זאב וולף על מקומו אחריו. (לפי אוצר הרבנים היה גם רב בקאוולי). תשובות ממנו ב\"מים חיים\" לר חיים רפפורט, \"אור ישראל\",ועוד. נזכר ב\"נודע ביהודה\". הסכים על ספרים רבים ובהם \"תוספות שבת\" ברוד תקכד, ועוד. תלמידו - ר שלמה יואל דובנא - חברו של משה מנדלסון - ובהשפעת רבו התרחק ממנו. בנו גם - ר דב בער."},{"i":15323,"n":"הלברשטט, צבי","k":"בעל ארץ צבי","b":"רב-שנת ת\"ק"},{"i":15324,"n":"הלברשטט, שמואל זנויל","f":"בנדיט","b":"דיין בברלין-תן. ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט, ועל מינוי ר יעקב יהושע אחריו. בנו - ר מאיר ונכדו ר נח חיים צבי ברלין-אב\"ד אה\"ו."},{"i":15325,"n":"הלברשטט, שמואל מברדיוב","dt":"תשד","b":"רב בברדיוב"},{"i":15326,"n":"הלברשטט, שמואל מהגנוי","f":"צבי הירש הלברשטט","b":"רב בהגנוי ומדינת אלזס, דיין בהלברשטט-תק. אגרת ממנו ב\"לוחות עדות\"."},{"i":15327,"n":"הלברשטט, שמחה מדעסוי","f":"צבי הירש","dt":"תקמו - יא כסלו","b":"רב בלענטשנא-תקטו, סקאהל-תקכא על מקום אביו, דעסוי-תקכח על מקום ר דוד ברלין שעבר לאה\"ו. חתם בברודי-תקטו על החרם על השבתאים. חיבר הגהות לש\"ס ונדפסו בש\"ס וילנא (נמסרו למדפיסים ראם ע\"י נינו - שזח\"ה)."},{"i":15328,"n":"הלברשטט-הרצפלד, ש'ד'ב","f":"צבי הלברשטט","dt":"תקמה - ג תמוז","b":"בקי,רב בלאקאטש-תקי\"ג,לאביטש-תקכ\"א,גלוגא-תקכ\"ז (כנראה טעות בשם אביו בעל \"עטרת צבי\" - הוחלף עם ר שמחה מדעסוי)"},{"i":15329,"n":"הלברשטם שלמה זלמן חיים בן יצחק","f":"יצחק","bt":"תקצב","bp":"קראקא","dt":"תרס","b":"התיישב בביאלא-ביליץ ונמנה על חשובי החוקרים בחכמת ישראל. רשימת הספרים בספרייתו בספר \"קהילת שלמה\" וינה תרן. פרסם מאמרים רבים בספרי זכרון וכתבי עת. ההדיר ספרים רבים וכתב להם מבואות והערות. וביניהם \"תשובות הגאונים\" ליק תרכד.","bk":[["אגרת בקורת",""],["ספר השטרות",""]]},{"i":15330,"n":"הלברשטם, אביגדור מדוקלא","f":"אריה ליבוש","bt":"תקפח","bp":"פשמישל","dt":"תרלז","b":"גדל אצל אחיו ה\"דברי חיים\" אחר פטירת אביו. חתן ר אברהם חיים הורביץ אב\"ד לינסק. רב בבובוב, ודוקלא. חתנו ר אריה ליבוש הלברשם על כסאו אחריו. הסכים על \"זכרון צבי מנחם\"-תרלג."},{"i":15331,"n":"הלברשטם, אביגדור מוישניצא","f":"מנחם מנדל מפריסטיק","dt":"תרעה - כסלו","b":"חתן דודו זקנו ר נפתלי רובין מוישניצא-חתנו של הדברי יחזקאל משינאווא. צאצאיו נספו בשואה."},{"i":15332,"n":"הלברשטם, אביגדור צבי מצאנז ובר","f":"יחיאל נתן מברדיוב","bt":"תרמד","dt":"תשב","b":"חתן דודו ר אריה ליבוש ה\"ש אב\"ד גריבוב. אב\"ד צאנז ישן-תרסד על מקום אביו שעבר לברדיוב, רב בברדיוב על מקום אביו. סירב לאדמורות. נספה בשואה."},{"i":15333,"n":"הלברשטם, אברהם אביש מטשחויב","f":"יעקב שמשון מטשחויב","k":"אדמור מטשחויב חיפה","bt":"תרנד","dt":"תשמד - כט חשון","b":"חתן ר מרדכי יוסף משה מסוליצא (שושלת זלוטושוב). אדמור ביאס-תרפט, ניצל מהשואה ואחריה עבר לבוקרשט, עלה לארץ דרך קפריסין-תשח והתישב בחיפה. חיבר \"אהל קדושים\". בנו ר חיים יוסף משה - מנהל בית מדרשו."},{"i":15334,"n":"הלברשטם, אברהם אביש מסטמר","f":"סיני מזמיגרוד","bt":"תרנד","dt":"תשא","b":"נכד ר ברוך מגורליץ ונינו של ה\"דברי חיים\" מצאנז. חתן ר חנוך בן אברהם יהושע פריינד מנאסוד. מחכמי סטמר. גורש לפולין ונספה בשואה."},{"i":15335,"n":"הלברשטם, אברהם חיים מקרמניץ","dt":"תשא","b":"רב בקרמניץ"},{"i":15336,"n":"הלברשטם, אברהם מרודניק","f":"צבי הירש","k":"אדמור מרודניק","bt":"תרסג","dt":"תשא","b":"רב ואדמור ברודניק על מקום אביו. חתן ר אליהו בצלאל טייטלבוים אב\"ד טעטש. נספה בשואה."},{"i":15337,"n":"הלברשטם, אברהם נפתלי מסטמר","f":"מנחם מנדל מסטרופקוב","k":"הו\"ל דברי יחזקאל","dt":"תש..","b":"חתן ר חיים הלברשטם מסטמר. רב בסטמר, ההדיר בפעם השלישית את הספר \"דברי יחזקאל\". נספה בשואה."},{"i":15338,"n":"הלברשטם, אברהם שלום מסטרופקוב","f":"יחזקאל שרגא משינואוו","k":"אדמור מסטרופקוב","r":"רב בסטרופקוב ואדמו\"ר שם","bt":"תרטז-יז","bp":"שינווא(=שינא)","dt":"תש - ו סיון","b":"רב ואדמור בסטרופקוב-תרנח על מקום אביו ובנו ר מנחם מנדל על מקומו אחריו. רב באונגואר, קאשוי-תרפט. חתן ר אברהם חיים הורביץ מלינסק ובזיוו\"ש חתן ר דוד שליכטר מקומרנא. חיבר \"דברי שלום\" מישקולץ תשד. מבניו ר יום טוב יוזפא.","bk":[["דברי שלום (סטראפקוב)",""],["דברי שלום",""]]},{"i":15339,"n":"הלברשטם, אהרן מאשיעק","f":"סיני","bt":"תרנו","dt":"תשב","b":"חתן ר חיים ברוך רובין אב\"ד וישניצה. רבה של אשיעק-תרצו. נספה בשואה."},{"i":15340,"n":"הלברשטם, אהרן מביאלא-ביליץ","f":"יוסף זאב","k":"בעל מגד ארץ","bt":"תרכה","bp":"צאנז","dt":"תשב - כו סיון","b":"נכד ה\"דברי חיים\" מצאנז. חתן ר אלתר מאיר הלוי רוטנברג האדמור מוולברום ובזיוו\"ש ר יהושע יצחק קליגר מגריידינג. לא נהג אדמורות. רבה של ביאלא-ביליץ-תרמט במשך כחמישים שנה. חיבר גם \"פרי נאה\", ועוד. ?? לא באוצר ??"},{"i":15341,"n":"הלברשטם, אהרן מגורליץ","f":"אלישע מגורליץ","k":"אדמור מגורליץ","bt":"תרנה","b":"חתן ר שמואל שמלקא פרנקל תאומים מקלסני ויליצ'קה. ניצל מהשואה ואחריה היגר לארה\"ב וכיהן כאדמור מגורליץ-ויליצקה."},{"i":15342,"n":"הלברשטם, אהרן מזמיגורד","f":"סיני הלברשטם","dt":"תשג","b":"רב בז'מיגרד"},{"i":15343,"n":"הלברשטם, אהרן מצאנז","f":"חיים - הדברי חיים","bt":"תקפו","bp":"רודניק","dt":"תרסג - א אב","b":"חתן הגביר ר יעקב ויינברגר מדוקלא. תלמיד מובהק לר צבי הירש מרימנוב, ומקורב לגדולי האדמורים. רב מחוז צאנז-תריז בחיי אביו ורב העיר צאנז על מקומו אחריו, סירב לנהוג אדמורות. שרף את חדושיו לפני פטירתו, קטעים פזורים בספרי חכמי דורו. מבניו: ר שמואל שמלקא מדוקלא, ר שלום מפיקעלע."},{"i":15344,"n":"הלברשטם, אורי ממושינא","f":"משה הלברשטם","b":"רב במושינא-תר\"ע"},{"i":15345,"n":"הלברשטם, אלישע מגורליץ","f":"ברוך מגורליץ","k":"אדמור מגורליץ","bt":"תרך-ל","dt":"תשא - טו ניסן","dp":"יאקוטסק-סיביר","b":"נכד הדברי חיים, חתן דודו ר מרדכי דוב טברסקי מהורנוסטייפל בעל \"חבור לטהרה\". היה רב לצד חמיו. אב\"ד קרוסנו-תרסא, ראב\"ד בגורליץ-תרסז על מקום אביו ואחיו ר צבי הירש ובנו ר נפתלי חיים על מקומו בחייו. לא נהג אדמורות. בניו יורק-תרצב ואולי היה שם כאדמור, וחזר לגורליץ. נפטר בסיביר בזמן השואה. בניו - ר מנחם מנדל, ור דוד משה."},{"i":15346,"n":"הלברשטם, אלתר מאיר","f":"חיים מסטמר","b":"נכד ר שלום אליעזר מראצפרט. חתן האדמור מדעש ר יוסף פאנט מאילאנדא. דיין בסטמר-תשא על מקום אביו. נספה בשואה."},{"i":15347,"n":"הלברשטם, אלתר מאיר דוד מסטמר","f":"חיים מסטמר","bt":"תרעח","bp":"סטמר","dt":"תשד","b":"חתן ר יוסף פנט מאילנדא ודעש. רב בסטמר-תשא על מקום אביו. נספה בשואה."},{"i":15348,"n":"הלברשטם, אפרים","f":"מרדכי זאב מגריבוב","b":"חתן ר משה מברדיוב."},{"i":15349,"n":"הלברשטם, אפרים אביגדור מברדיוב","dt":"תשד","b":"רב בברדיוב"},{"i":15350,"n":"הלברשטם, אפרים דוד מישליסק","f":"יחיאל נתן מברדיוב","k":"אדמור ממישלניץ","bt":"תרמה","dt":"תשב","b":"חתן דודו ר מנחם מנדל הלברשטם מפריסטיק. אב\"ד ישליסק ואדמור במישלניץ. נספה בשואה."},{"i":15351,"n":"הלברשטם, אריה ליב מזמיגראד","f":"סיני מזמיגרוד","k":"אדמור מזמיגרוד","bt":"תרסט-עג","dt":"תשסז","b":"ברח לסיביר בזמן השואה ואחר כך עלה לארץ, וכיהן כאדמור בפתח תקוה, יפו, בני ברק, ואחר כך רב בארה\"ב. חתן ר יהודה צבי ברנדויין, ובזיוו\"ש ר מנחם מנדל בורנשטיין נכד ה\"אבני נזר\". חיבר \"אריה שאג\" תל אביב תשל."},{"i":15352,"n":"הלברשטם, אריה ליב ממושינא","f":"משה מברדיוב","k":"אדמור ממושינא","bt":"תרל","dt":"תשב","b":"חתן ר שמואל רוקח אב\"ד סקול, רב בסקול לצד חותנו. רב בברדיוב-תרנח, אב\"ד ואדמור במושינא-תרסד. בניו: ר מנחם מנדל אדמור בקראקא, ר יהושע. נספה בשואה."},{"i":15353,"n":"הלברשטם, אריה ליבוש מגלוסק","f":"נפתלי צבי הירש","bt":"תרם","dt":"תרצה","b":"אב\"ד בגלוסק ופיקעלי על מקום אביו. חתן דודו ר משה מקשאנוב."},{"i":15354,"n":"הלברשטם, אריה ליבוש מגריבוב","f":"אהרן מצאנז","k":"בעל בני תורה צאנז","bt":"תריב","dt":"תרצה -כא-ד אד\"א","b":"נכד ה\"דברי חיים\" מצאנז. חתן ר משה הורביץ מרוזוודוב, ובזיוו\"ש חתן ר יצחק קנר. רב בגריבוב-תרלא-מא או תרמו, אב\"ד צאנז חדש(=סאנדז)-תרסג על מקום אביו והקים שם ישיבה ובראשה ר אברהם יצחק פרידמן ור נתן בוקסבוים. נספה בשואה. חיבר \"בני תורה צאנז\" ניו יורק תשט. בניו: ר מרדכי זאב על מקומו אחריו, ר משה מצאנז, ר אפרים מברדיוב, ר צבי, ר פנחס שמעיה - כלם נספו בשואה."},{"i":15355,"n":"הלברשטם, אריה ליבוש מדוקלא","f":"אביגדור הלברשטם","b":"רב בדוקלא"},{"i":15356,"n":"הלברשטם, אריה ליבוש מדוקלא","f":"דוד מקשנוב","k":"אדמור מדוקלא","bt":"תקצח","dt":"תרסח - אד\"א","b":"נכד ה\"דברי חיים\" מצאנז. חתן דודו זקנו ר אביגדור הלברשטם מדוקלא (אחי ה\"דברי חיים\"). רב בדוקלא-תרס על מקום חותנו, בנו ר מנחם מנדל מפריסטיק על מקומו אחריו בדוקלא."},{"i":15357,"n":"הלברשטם, אריה ליבוש מטורנא","f":"יחזקאל שרגא","k":"אדמור מטורנא","bt":"תרך","dt":"תרץ","b":"חתן אחיו ר משה משינאווא, ובזיוו\"ש חתן ר נחום לנגנר מהוסקוב-חתנו של ר יוסף מבלז. רב ואדמור חסידי צאנז בטורנא(=טרנוב)."},{"i":15358,"n":"הלברשטם, אריה ליבוש מטרניגרד","f":"שמחה","bt":"תקל","dt":"תקצא-ח -טו תמוז","b":"מחכמי ברודי שהפך לחסיד של משה סופר מפשוורסק. רב בטרניגרד, דיין בפרמישלא."},{"i":15359,"n":"הלברשטם, אריה ליבוש מרדכי","f":"משה משינאווא","bt":"תרלב","dt":"תרצא - כז חשון","b":"חתן ר ישראל יעקב יוקל מוולובה ואולי גם חתן ר נחום לנגויר מגרודזיסק. רב בשינאווא, וקראקא-תרפב."},{"i":15360,"n":"הלברשטם, אריה מגורליץ","f":"משה","bt":"תרמח","dt":"תשג","b":"חתן רמ\"מ פרנס מגורליץ. נשיא קהילת גורליץ. נספה בשואה."},{"i":15361,"n":"הלברשטם, אשר מאיר שלום","f":"יוסף זאב","k":"אדמור מבוכניה","bt":"תריח","dt":"תרצג-ה","b":"נכד ר דוד הלברשטם מקשנוב-בן ה\"דברי חיים\" מצאנז. רב בצאנז ישן-תרלו בחיי זקנו ה\"דברי חיים\", רב ואדמור בבוכניה-תרמג."},{"i":15362,"n":"הלברשטם, בן ציון אריה ליבוש","f":"שלמה","bt":"תשטז","b":"רב ור\"מ בישיבת בובוב. חתן ר משה צבי וקסמן."},{"i":15363,"n":"הלברשטם, בן ציון מבובוב","f":"שלמה מבובוב","k":"אדמור מבובוב","bt":"תרלג-ד","bp":"בוקובסק או צאנז","dt":"תשא - ד אב","b":"חתן ר נפתלי הורביץ ממעליץ, ובזיוו\"ש חתן דודו זקנו ר שלום אליעזר ה\"ש מרצפערד. ראש ישיבה בוישניצה-תרם אצל אביו, רב בבובוב לצד אביו. רב ואדמור בובוב-תרסה על מקום אביו. הקים רשת של ל\"ב ישיבות \"עץ חיים\" בכל רחבי גליציה. היה בעל ניגון חשוב וממנהיגי הצבור בדורו - הקים-תרפח את \"ארגון רבני מערב גליציה\". גלה מבובוב לטשבין-תרצב. נספה בשואה. חיבר \"קדושת ציון\", \"אגרת הקודש\" קראקא תרצט, ועוד. רוב כתביו אבדו בשואה.","bk":[["קדושת ציון (באבוב)",""]]},{"i":15364,"n":"הלברשטם, ברוך מגורליץ","f":"אלישע מגורליץ","k":"אדמור מגורליץ","bt":"תרעא","dt":"תשמב - טו אב","b":"חתן ר ישכר שלמה טייכטל מפישטיאן. תלמיד ישיבת חכמי לובלין. ניצל מהשואה ברח לסיביר ואחר כך עלה לארץ והתישב בבני ברק והקים בית כנסת גורליץ. סירב לנהוג באדמורות. בנו ר אלישע רב בבני ברק."},{"i":15365,"n":"הלברשטם, ברוך מגורליץ","f":"חיים - הדברי חיים","k":"אדמור מגורליץ","bt":"תקפט","bp":"רודניק","dt":"תרסו - א אדר","b":"נכד הברוך טעם. חתן ר יקותיאל יהודה בעל ה\"ייטב לב\", ובזיוו\"ש חתן ר שמואל שפירא מלנצהוט. רב בגורליץ-תרטז אך ויתר בהוראת אביו, רודניק-תרך, ושוב בגורליץ-תרנב. היה נחשב מאוד בעיני חכמי דורו ושימש כבורר בפרשות סבוכות. ספרו \"אמרי ברוך\" בתוך ספר \"עטרת חיים\" לנכדו ר יעקב מטשקובה, \"דברי ברוך\" ע\"י נכדו ר אהרן אליעזר זילברמן - ניו יורק תשנט. מבניו: ר שלום מניסקא. מתורתו ב\"קהילת יעקב\" - זבארוב-סלובקיה תרפה.","bk":[["דברי ברוך -",""]]},{"i":15366,"n":"הלברשטם, ברוך מגריבוב","f":"מרדכי זאב מגריבוב","bt":"תרסג","dt":"תשג - ג תשרי","b":"חתן ר שמואל הורביץ מדמביץ. רבה של גריבוב על מקום אביו שעבר לצאנז. נספה בשואה."},{"i":15367,"n":"הלברשטם, ברוך מזקליקוב","f":"סיני","bt":"תרס","dt":"תשב","b":"תלמידו וחתנו של רד\"ב ויידנפלד מטשבין. רב בזקליקוב-תרצה. נספה בשואה. פרסם מאמרים ב\"תלפיות\" - טרנוב תרצח."},{"i":15368,"n":"הלברשטם, ברוך מטשחויב נ\"י","f":"יעקב שמשון מטשחויב","bt":"תרנה","dt":"תשיג - ד תמוז","b":"חתן ר שלום בן אהרן מפיקעלע וצאנז. רב בטשחויב-תרפה, רב ואדמור בצאנז על מקום חותנו. ניצל מהשואה והגיע לבוכרה, היגר לארה\"ב-תשיג."},{"i":15369,"n":"הלברשטם, ברוך מקשאנוב","f":"משה","bt":"תרלה","dt":"תרעז - יא תשרי","b":"חתן ר אברהם חיים הורביץ מלינסק."},{"i":15370,"n":"הלברשטם, דוד (לברר איזה)","b":"בשנת תשא שלח מכתב לשוייץ מכפר קסטעלפערוס ובו מבקש עזרה בויזה לארה\"ב."},{"i":15371,"n":"הלברשטם, דוד אריה מפריסטיק","f":"חיים ברוך","bt":"תרסה","dt":"תשב","b":"חתן ר יוסף אריה פרישרמן האדמור מטומשוב. רבה של פריסטיק-תרפו על מקום אביו - שנהיה לאדמור."},{"i":15372,"n":"הלברשטם, דוד יהושע מסוסנוביץ","f":"חיים מטשיחוב","bt":"תרס","dt":"תשג","b":"חתן ר יצחק רובין מסוסנוביץ שהסב שמו לגליקמן. רב בסוסנוביץ-ישן עד שנספה בשואה."},{"i":15373,"n":"הלברשטם, דוד מדברא","dt":"תשג","b":"רב בדאברא"},{"i":15374,"n":"הלברשטם, דוד מטשבין","f":"מנחם מנדל מפריסטיק","k":"אדמור מטשבין","bt":"תרנב","dt":"תשב","b":"רב ואדמור בישליסק, טשבין. חתן דודו זקנו ר אלעזר רוזנפלד מאושפיצין. נספה בשואה עם אשתו ועשרת ילדיו."},{"i":15375,"n":"הלברשטם, דוד מסוסנוביץ","f":"סיני","bt":"תרנה","dt":"תשב","b":"חתן \"כנסת יחזקאל\" מרדומסק. רב בסוסנוביץ. נספה בשואה. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ."},{"i":15376,"n":"הלברשטם, דוד מסוקולוב","f":"משה משינאווא","bt":"תרלו","dt":"תשב","b":"נינו של ה\"דברי חיים\" מצאנז, ונכד ר יחזקאל שרגא משינאווא. חתן ר אברהם אבלי אינגבר מרישא. רב בסוקולוב-תרס, תשובה ממנו ב\"תשובה כהלכה\" בענין מחלוקת כולל \"חיבת ציון\" - שבו תמך, ל\"כולל קאסוב וויזניץ\". עבר לוינה בזמן מלחמת העולם ה-I, ואחריה עבר לניו יורק. חתנו ר אהרן ירוחם בן ר חיים יצחק ירוחם מאלטשטאט. חתנו ר אהרן ירוחם כותב בספרו \"אהל רחל\" שנספה בשואה - לפי אלפסי נפטר - תרצה."},{"i":15377,"n":"הלברשטם, דוד מקרזמיר","b":"רב בקרזמיר-תק\"י"},{"i":15378,"n":"הלברשטם, דוד מקשאנוב","f":"ברוך","k":"אדמור מקשנוב","bt":"תרנז","bp":"לינסק","dt":"תשמו","b":"חתן ר חיים יצחק ירוחם. רב בוינה, ניצל מהשואה והיגר לארה\"ב-תשב בעזרת רא\"א ארנברג, וכיהן כאדמור מקשנוב."},{"i":15379,"n":"הלברשטם, דוד מקשאנוב","f":"חיים - הדברי חיים","k":"אדמור מקשנוב","bt":"תקעח","bp":"רודניק","dt":"תרנג -ח-כה אלול","b":"חתן ר יוסף זאב מטרניגרד שהיה דור שישי לעכסה בת האר\"י (שעברה לפולין), ובזיוו\"ש חתן נכדת בעל \"יד קטנה\". תלמיד ר צבי הירש מרימנוב, ור דב בער מרדושיץ. רב בקשנוב(=קראשנוב)-תריא, ממנו ועליו \"דרכי דוד\" לנכדו ר אורי בלום - ניו יורק תשסא. בניו: ר יוסף זאב מקשנוב, ר אריה ליביש מדוקלא, ר נפתלי מקשנוב, ר משה."},{"i":15380,"n":"הלברשטם, דוד משה מדינוב","f":"אלישע","k":"אדמור מדינוב","bt":"תרן","dt":"תשלא","b":"חתן ר יוסף שפירא מדינוב. רב בדינוב, ניצל מהשואה והגיע לארה\"ב. כיהן כאדמור מדינוב בניו יורק. נפטר ללא ילדים."},{"i":15381,"n":"הלברשטם, זלמן יהודה משינאווא","dt":"תשג","b":"רב בשינעווע-סאנדז"},{"i":15382,"n":"הלברשטם, חיים","f":"מרדכי הלברשטם","b":"רב-שנת תר\"י"},{"i":15383,"n":"הלברשטם, חיים ברוך מפריסטיק","f":"מנחם מנדל","bt":"תרמז","dt":"תשב","b":"אב\"ד פריסטיק-תרצו על מקום אביו. חתן ר יעקב קופל פרנס. כל ילדיו נספו בשואה."},{"i":15384,"n":"הלברשטם, חיים דב בריש מברדיוב","f":"שמואל","k":"אדמור מברדיוב","bt":"תרנא","dt":"תשלא","b":"הגיע לארה\"ב ושימש כאדמור מברדיוב בניו יורק. חתן ר יוסף שפירא מברטש."},{"i":15385,"n":"הלברשטם, חיים יהודה מאושפיצין","f":"סיני","bp":"אושפיצין","dt":"תשג","b":"חסיד בובוב. חתן ר יהושע פנחס בומבך מאושפיצין. ראב\"ד באושפיצין-תרפא על מקום חותנו. נספה בשואה."},{"i":15386,"n":"הלברשטם, חיים יהושע מבובוב","f":"בן ציון","bt":"תרעג","dt":"תשג","dp":"טשקנט","b":"חתן ר ברוך הלברשם מקשאנוב. ברח לרוסיה במלחמה והוגלה לסיביר - שם שימש כרב הפליטים בקזחסטן."},{"i":15387,"n":"הלברשטם, חיים יצחק מסלטפינה","f":"יהושע מדולינא","bt":"תרנט","dt":"תשד - א סיון","dp":"אושוויץ","b":"חתן רבו ר בעל \"עצי חיים\" מסיגט. רבה של סלטפינה-תרפה, ועמד בראש ישיבה בשם \"מחנה חיים\" ע\"ש חותנו. נספה בשואה. מתורתו בספר \"עיר חנוך\" לחתנו - ניו יורק תשסא."},{"i":15388,"n":"הלברשטם, חיים מטשחוב","f":"יצחק ישעיה מטשחויב","k":"אדמור מטשחויב","bt":"תרמב","bp":"בלז","dt":"תשטז","b":"חסיד בלז. חתן ר מנשה מרילוס מדובצק ורופשיץ. היגר לארה\"ב-תרפד וכיהן כרב בניו יורק וכאדמור מטשכוב. בניו ר דוד יהושע ור שמעון - נספו בשואה."},{"i":15389,"n":"הלברשטם, חיים מסטמר","f":"שלום אליעזר מרצפרט","bt":"תרמה","dt":"תשב - יט כסלו","dp":"סטמר","b":"נכד ה\"דברי חיים\" מצאנז ור מרדכי דב טברסקי מהרנסטופול - שהזכירו בספרו \"עמק החכמה\". חתן ר אברהם שלום פנחס רוטנברג מוולברום האדמור מטשנסטוכוב, ובזיוו\"ש ר ברוך רובין מברוזדוביץ. דיין בסטמר. נפטר בחיי אביו. תשובות ממנו בספרי חכמי דורו."},{"i":15390,"n":"הלברשטם, חיים מצאנז","f":"אריה ליבוש מטרניגרד","k":"אדמור מצאנז-דברי חיי","r":"אדמו\"ר מצאנז","bt":"תקנז","bp":"טרניגרד","dt":"תרלו - כה ניסן","b":"נכדו של החכם צבי. מחסידי ר נפתלי מרופשיץ. חתן ר ברוך פ\"ת מלייפניק בעל \"ברוך טעם\", ובזיוו\"ש חתן ר יחיאל צבי הירש מטורנא, ובזיוו\"ש חתן ר אלימלך טורם-נכד האדמור מרימנוב. תלמיד ר משה יהושע השל אורנשטין בעל \"ים התלמוד\", ור שלמה זלמן הלר מפרמישלא, וחותנו בעל \"ברוך טעם\". חסיד ר נפתלי צבי מרופשיץ, ונסע אל גדולי האדמורים. רב ברודניק-תקנז, רב בזלין, צאנז-תקפח ואדמור-תקץ - היה מגדולי האדמורים בדורו. חיבר \"דברי חיים\" למברג תרלה, ועוד. בפטירתו הלכו אחר מיטתו קרוב למאה רבנים מיוצאי חלציו.","bk":[["דברי חיים","שו\"ת - אחרונים"],["דברי חיים – עה\"ת גיטין, מקוואות, ב\"מ, ושו\"ת",""],["דברי חיים [הלברשטאם] (שו\"ת)",""],["תוצאות חיים (צאנז)",""]],"e":"תקנ\"ז-תרל\"ו"},{"i":15391,"n":"הלברשטם, חיים מרידיק","f":"יחזקאל","b":"רבה של רידיק-תרצו, במקום אביו האדמור."},{"i":15392,"n":"הלברשטם, חיים משה מדולינא","b":"רבה של דולינא-תרעב."},{"i":15393,"n":"הלברשטם, חיים נחום ממושציסק","f":"משה בן דוד מקשנוב","bt":"תרם","dt":"תרפא - יב ניסן","b":"מצאצאי הדברי חיים מצאנז. נסמך מאת ר יצחק שמלקיס בעל \"בית יצחק\", המהרש\"ם מברזן ובעל \"עצי בשמים\".. חתן ר יעקב משה ספרין מקומרנא. אב\"ד מושציסק-תרסה. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא, \"כרמנו\" - אלכסנדר-לודז תרצג, \"רבותינו שבגולה\" - פרשבורג תרעה. נפטר צעיר ואלמנתו נישאה לאדמו\"ר מנחם מנדל גוטרמן מראדזמין שגידל את בניו - ר מנחם מנדל, ור שניאור זלמן."},{"i":15394,"n":"הלברשטם, חנה אלחנן מקולשיץ","f":"מנחם מנדל מפריסטיק","k":"אדמור מקולשיץ","r":"אב\"ד קאלאשיץ ואח\"כ ברישא","bt":"תרמ-ד","bp":"שינאווא","dt":"תשג - יח תשרי","dp":"יאסלו","b":"נכד ר אריה ליבוש הלברשטם מדוקלא, ונכד(-אבי אמו) ר יחזקאל משינאווא בעל \"דברי יחזקאל\". חתן ר משה בן ברוך הלברשטם מברדיוב. רב בקולשיץ, רב ואדמור בקאשוי על מקום דודו האדמור מצעשינוב, רישא-תרפג והקים בה ישיבת \"זרע קודש\". נספה בשואה. חיבר \"בינה ודעת\" ו\"נהר פרת\" קראקא תרפז (בעילום שמו), \"דברי חנה\" ניו יורק תשיב. .","bk":[["דברי חנה ובו ג' קונטרסים א. בין השמשות ב. תורת מקוה ג. דברי תורה",""]]},{"i":15395,"n":"הלברשטם, חנה מבוכניה","dt":"תשג","b":"רב בבוכניע"},{"i":15396,"n":"הלברשטם, חנניה יום טוב ליפא","f":"יחזקאל שרגא מציעשנוב","dt":"תשב","b":"נספה בשואה"},{"i":15397,"n":"הלברשטם, טוביה מרדיוב","f":"יצחק","bt":"תרע","b":"ניצל מהשואה ועבר לניו יורק ושימש כרב - היתה לו תכנית ברדיו של ניו יורק בנושא חסידות. הדפיס \"תורת בני ישכר\" לזקנו - ברוקלין תשלד."},{"i":15398,"n":"הלברשטם, יהושע","f":"אריה ליב ממושינא","b":"נקרא ע\"ש אבי זקנו - ר יהושע מבלז."},{"i":15399,"n":"הלברשטם, יהושע מבוכניה","f":"שלום אשר מאיר","bt":"תרם","dt":"תשג","b":"רבה של בוכניה על מקום אביו. חתן ר ישכר בלויגרונד מקלוואריה. נספה בשואה."},{"i":15400,"n":"הלברשטם, יהושע מדולינא","f":"משה מברדיוב","bt":"תרלח","dt":"תשג","b":"נכד ר ברוך מגורליץ ונינו של ה\"דברי חיים\" מצאנז. חתן ר יהודה צבי איכנשטין האדמור מדולינא, רב ואדמור בדולינא-תרסט על מקום חותנו, בזמן מלחה\"ע ה-I עבר להאלמין-הונגריה, וחזר לדולינא-תרפב. הצטיין בתפילותיו. נספה בשואה - ביקש מהתליין שיניחו להתפלל, התעטף בטלית ואמר \"נשמת\" בנוסח זידיטשוב."},{"i":15401,"n":"הלברשטם, יהושע מקולושיץ","b":"רב בקולושיץ"},{"i":15402,"n":"הלברשטם, יוסף אלימלך מקשאנוב","f":"משה","bt":"תרכט","dt":"תרסז - ח טבת","b":"חתן ר אברהם אבא אינגבר. רב בקשאנוב-תרף על מקום סבו יחד עם דודו ר נפתלי."},{"i":15403,"n":"הלברשטם, יוסף זאב מקשאנוב","f":"דוד מקשנוב","bt":"תקצז","dt":"תרסב - כג אלול","b":"נכד ה\"דברי חיים\" מצאנז. רב בקשנוב-תרנה. חתן ר מנחם מנדל רובין מגלוגוב."},{"i":15404,"n":"הלברשטם, יוסף מבוכניה כנראה","f":"הכוונה לאשר מאיר"},{"i":15405,"n":"הלברשטם, יוסף משה מלמברג","f":"שמחה","b":"נכדו של ר משה יוסף מזבורוב אחי ה\"דברי חיים\". מחשובי חסידי שינאווא בלמברג. עלה לירושלים עם חורגו ר אריה מרדכי וקסלשטיין."},{"i":15406,"n":"הלברשטם, יחזקאל דוד מפקשביץ","f":"בן ציון","k":"אדמור מפאקשוויץ","bt":"תרעד","dt":"תשלח","b":"חתן ר אברהם הורביץ מפקשיבניצה. שרד מהשואה ועלה לארץ, עבר לניו יורק והיה שם האדמור מפאקשעויץ."},{"i":15407,"n":"הלברשטם, יחזקאל שרגא מבוכניה","dt":"תשג","b":"רב בבוכניע"},{"i":15408,"n":"הלברשטם, יחזקאל שרגא מגורליץ","f":"אלישע מגורליץ","k":"אדמור מגורליץ","b":"אדמור מגורליץ בארה\"ב. חתן ר שמואל שפירא אב\"ד רעדים."},{"i":15409,"n":"הלברשטם, יחזקאל שרגא מדוקלא","f":"מנחם מנדל","k":"אדמור מדוקלא","bt":"תרן","dt":"תשב","b":"רב ואדמור בדוקלא על מקום אביו. חתן ר יצחק רובין אב\"ד צפת. נספה בשואה."},{"i":15410,"n":"הלברשטם, יחזקאל שרגא מוארנוב","b":"רב בווראנוב(=וארנוב)"},{"i":15411,"n":"הלברשטם, יחזקאל שרגא מוישניצא","b":"רב בוישניצא-תרפט."},{"i":15412,"n":"הלברשטם, יחזקאל שרגא מלמברג","dt":"תשג","b":"רב בלמברג"},{"i":15413,"n":"הלברשטם, יחזקאל שרגא ממארוש","bt":"תרס","dt":"תשג","b":"רב בטריבישוב-סלובקיה, רב ואדמור במארוש-וואשארהי. נספה בשואה."},{"i":15414,"n":"הלברשטם, יחזקאל שרגא ממישלניץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":15415,"n":"הלברשטם, יחזקאל שרגא מפודגורזע","b":"מחכמי פודגורזע-קראקא. תשובה אליו ב\"מנחת יחיאל\", \"תורת העולות\"."},{"i":15416,"n":"הלברשטם, יחזקאל שרגא מפשמישל","f":"אריה ליביש מטורנא","dt":"תשג","b":"חתן ר יהושע הלברשטם מבוכניה. רב ואדמור בפרמישלא בחיי אביו."},{"i":15417,"n":"הלברשטם, יחזקאל שרגא מצשינוב","f":"שמחה ישכר דב","k":"אדמור מצשינוב","bt":"תרסא","bp":"ציעשינוב","dt":"תשב - ג שבט","dp":"כפר דאחנוב","b":"חתן ר חיים צבי מסיגט בעל \"עצי חיים\" שאצלו למד. רב ואדמור בציעשינוב-תרפג על מקום אביו. נספה בשואה."},{"i":15418,"n":"הלברשטם, יחזקאל שרגא מקראקא","f":"יצחק ישעיה מטשחויב","bt":"תרסה","dt":"תשא - ד אב","b":"חתן ר בן ציון מבובוב. דיין בקראקא-טשחוב. נספה בשואה."},{"i":15419,"n":"הלברשטם, יחזקאל שרגא מרידיק","f":"סיני","k":"אדמור מרידיק","bt":"תרנח","dt":"תשב","b":"חתן ר פנחס נתן ספרין מרידיק. אדמור ברידיק על מקום חותנו. נספה בשואה. בנו ר חיים היה רבה האחרון של רידיק."},{"i":15420,"n":"הלברשטם, יחזקאל שרגא משינאווא","f":"אריה ליבוש מרדכי","k":"אדמור משינאווא","bt":"תרן","dt":"תשב","b":"חתן ר יהושע הלברשטם מבוכניה. רב ואדמור משינאווא (או פרמישלא) בעת שאביו היה בקראקא."},{"i":15421,"n":"הלברשטם, יחזקאל שרגא משינאווא","f":"חיים - הדברי חיים","k":"אדמור משינאווא-דברי","bt":"תקעא-ה","bp":"טרניגרד","dt":"תרנט - ו-ט טבת","b":"חתן בעל \"אריה דבי עילאי\", ובזיוו\"ש חתן גיסו ר מרדכי זיבלברשטיין מהולשיץ חתן ה\"אריה דבי עילאי\", ובזיוו\"ש חתן ר יהודה צבי הירש איכנשטין מרוזדול(=רוזלא). ובזיוו\"ר חתן רצ\"ה רמר\"ז מלעשנוב, ובזיוו\"ח חתן ר אברהם גבירצמן מגורליץ-נכד ר אלימלך מליזנסק. תלמיד ר צבי הירש מרימנוב, ועוד. רב ברודניק, אב\"ד רוזדול-תרט על מקום חותנו, רב ואדמור שינאווא-תרטז בחיי אביו, סטרופקוב-תרכח, צאנז על מקום אביו שנה אחת ושב לסטרופקוב לטובת אחיו, ושוב לשינאווא-תרמא. ביקר בארץ-תרכט. חיבר \"דברי יחזקאל\", \"אור החמה\" ירושלים תרלו, ועוד. מבניו: ר נפתלי שנפטר בחייו, ר משה, ר אברהם שלום, ר אריה ליב, ר שמחה ישכר דב. חתניו - ר מנחם מנדל, ר נפתלי רובין, ר פנחס פרנקל-תאומים.","bk":[["דברי יחזקאל [החדש] (שינאווא)",""]]},{"i":15422,"n":"הלברשטם, יחיאל מיכל צבי מרישא","f":"יוסף אלימלך","bt":"תרן","dt":"תש","b":"רב ברישא. חתן ר אברהם חנוך הניך זילביגר מציעשינוב. נספה בשואה."},{"i":15423,"n":"הלברשטם, יחיאל נתן מברדיוב","f":"משה מברדיוב","bt":"תרכה","dt":"תרצד - ז ניסן","b":"נכד הדברי חיים. חתן דודו ר אריה ליבוש מדוקלא. אב\"ד צאנז ישן-תרמה, מושינא, רב ואדמור בברדיוב-תרסד. מתורתו בסוף \"גן דוד\" לר דוד שליסל. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד, \"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":15424,"n":"הלברשטם, יעקב ישראל מציעשינוב","f":"משה מקשאנוב","b":"רב בציעשינוב, ירוסלב."},{"i":15425,"n":"הלברשטם, יעקב מטשקובה","f":"סיני מזמיגראד","k":"אדמור מטשקובה","bt":"תרסב","dt":"תשכח - ד חשון","dp":"ניו יורק","b":"חתן ר שלום מושקוביץ האדמור משאץ-לונדון. אב\"ד טשקובה(=שטשאקאוע)-תרפג, עלה לירושלים-תרצה והקים את ישיבת דברי חיים. הגיע לניו יורק-תש ונשאר שם - פעיל בועד ההצלה בזמן השואה. חיבר \"תפלה לכל צרה\" נ\"י תשג, \"תפלה צו בעטען..\" ניו יורק תשיא. מבניו: ר מאיר מבני ברק, ר משה - רב בירושלים, ר חכם צבי מבני ברק."},{"i":15426,"n":"הלברשטם, יעקב מסטריזוב","f":"יחיאל נתן","dt":"תש..","b":"רב בסטריזוב-תרפה. נספה בשואה."},{"i":15427,"n":"הלברשטם, יעקב צבי מסוכא","f":"יצחק ישעיה מטשחויב","bt":"תרנו","dt":"תשג","b":"חתן דודו ר אלעזר רוזנפלד מאושפיצין. הקים ישיבות \"דברי חיים\" בנשיאות אביו. רבה של סוכא-תרפג. נספה בשואה."},{"i":15428,"n":"הלברשטם, יצחק ישעיה מטשחויב","f":"חיים - הדברי חיים","bt":"תרכד","dt":"תשג - ג אלול","b":"התחנך אצל אחיו ר\"ד מקשאנוב ורי\"ש משינאווא. חתן ר יחיאל השל האדמור מקריליביץ, ובזיוו\"ש חתן ר יעקב צבי האדמור מפוריסוב. אב\"ד טשכוב-תרמג, סטמר-תרנג, קראקא-תרי. עבר ללבוב-תש, בוכניה. נספה בשואה. מבניו: ר יעקב צבי מסוכא, ר יחזקאל שרגא."},{"i":15429,"n":"הלברשטם, יצחק מברוקלין","f":"משה מברדיוב","bt":"תרם","dt":"תשד","b":"רב בברדיוב לצד אביו. חתן ר יהושע שפירא מריבטיטש. היגר לניו יורק-תרעט."},{"i":15430,"n":"הלברשטם, יצחק מקראקא","f":"חיים","k":"הו\"ל חדושי הריטבא","bt":"תקע","bp":"ברודי","dt":"תרם","b":"חתן הגביר ר זלמן בורנשטיין מויליצקה. התיישב בקראקא. עסק בניהול הבנק של המשפחה ואף ישב ולמד בכל יום, שלט בשפות רבות. ההדיר \"חדושי הריטבא\" וינה תרכח מתוך כתב יד שהיה ברשותו. חיבר \"שיח יצחק\" למברג תרמב."},{"i":15431,"n":"הלברשטם, יצחק צבי מאוסטרהא","f":"דב בריש ממזריטש","dt":"תריא - יט אד\"ב","dp":"אוסטרהא","b":"חתן הגביר ר אברהם אבלי הכהן בן פסח מאוסטרהא. מחכמי אוסטרהא ומחברי הח\"ק. בנו ר יוקא-חתן ר מאיר לנדא מברוד, חתנו ר נפתלי הרץ בן חיים משה בן אהרן שמואל מאוסטרהא סטפאן וימופלי."},{"i":15432,"n":"הלברשטם, יקותיאל יהודה מברדיוב","f":"שמואל","k":"אדמור מנייטרא","bt":"תרס","dt":"תשל - תשרי","b":"רב בברדיוב, אדמור בנייטרא. חתן דודו ר יחיאל נתן מברדיוב. היגר לניו יורק אחרי השואה."},{"i":15433,"n":"הלברשטם, יקותיאל יהודה מגורליץ","f":"יחיאל נתן מברדיוב","k":"אדמור מגורליץ","b":"רב ואדמור בגורליץ-תרפ"},{"i":15434,"n":"הלברשטם, יקותיאל יהודה מדולינא","f":"משה","k":"בעל שומר שבת","bt":"תרס","dt":"תשב","b":"חתן ר יהושע הלברשטם אדמור מדולינא. היה רב בדולינא ליד חותנו. חיבר \"שומר שבת\" עם \"מנחת שבת\" בילגוריי תרצג, \"הנהגות אדם\" עם \"ארחות חיים\" בילגוריי תרצו. ?? לא באוצר ??"},{"i":15435,"n":"הלברשטם, יקותיאל יהודה משינאוא","f":"אריה ליבוש מרדכי","k":"אדמור משינאווא","bt":"תרנג","dt":"תשג","b":"חתן ר שמואל שפירא מרעדים או ר יהושע מבוכניה (לפי אלפסי). אדמור משינאווא-תרצב על מקום אביו שעבר לקראקא. גר בצאנז. נספה בשואה."},{"i":15436,"n":"הלברשטם, ישראל דוד מדונהסדהאלי","dt":"תשג","b":"רב בדונאסעדאהעלי"},{"i":15437,"n":"הלברשטם, ישראל מזמיגרוד","f":"סיני מזמיגרוד","k":"אדמור מזמיגרוד","bt":"תרעא","dt":"תשמא","b":"חתן ר שמשון אהרן פולונסקי מטפליק. ניצל מהשואה, היה בסיביר ועלה לארץ דרך טהרן והיה קשור בפרשת ילדי טהרן. עבר לניו יורק ומכהן שם כאדמור מזמיגרוד. בניו: ר סיני מזמיגראד-נ\"י, ר ברוך שמשון מרודניק-נ\"י."},{"i":15438,"n":"הלברשטם, ישראל מסקוהל","b":"רב בסקאהל-תקמ\"ו"},{"i":15439,"n":"הלברשטם, מאיר מברלין","f":"זלמן","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":15440,"n":"הלברשטם, מאיר מטשקובה בני ברק","f":"יעקב מטשקובה","k":"אדמור מטשקובה","bt":"תרפז","bp":"טשקובה","b":"עלה לארץ-תרצה, למד בקראקא ובזמן השואה הגיע לסיביר. הצליח להגיע לארץ-תשב. חתן ר אהרן יוסף לוריא. עזר לחותנו בפעילותו בטבריה. עבר לנתניה לבקשת האדמור מצאנז לסייע בהקמת קרית צאנז."},{"i":15441,"n":"הלברשטם, מאיר נתן מצאנז","f":"חיים - הדברי חיים","bt":"תרטו - טו אב","dt":"תרלו - טו אב","b":"חתן ר אליעזר מדזיקוב - אשתו בילא קיבלה פתקאות בזקנותה. נפטר בחיי אביו."},{"i":15442,"n":"הלברשטם, מיכל מרישא","dt":"תשג","b":"רב ברישא"},{"i":15443,"n":"הלברשטם, מנחם בנימין מוודיסלב","f":"אהרן מביאלא ביליץ","k":"אדמור מוידיסלב","bt":"תרמא","bp":"וולברום","dt":"תשיז - כג ניסן","b":"גדל אצל זקנו (אבי אמו) האדמור ר אלתר מאיר רוטנברג מוולברום. נקרא גם בשם חותנו - רוטנברג. חתן ר מרדכי זאב שטרנפלד-הורביץ מפוריסוב, ובזיוו\"ש חתן ר אברהם חיים רוטנברג מווידסלב. מקורב לאדמור ר מאיר שלום מקאלושין (שושלת פשיסחא), ואדמורי בעלז. רב בצאנז. רב ואדמור בוולברום, ביליץ, ואדיסלב. עבר לניו יורק-תרפב."},{"i":15444,"n":"הלברשטם, מנחם מנדל","f":"חיים נחום ממושציסק","dt":"תש..","b":"נכד(-אבי אמו) ר יעקב משה ספרין מקומרנא. לאחר שנתייתם גדל אצל האדמור ר אהרן מנחם מנדל גוטרמן מראדזמין. חתן האדמור ר יצחק מנחם מנדל דנציגר מאלכסנדר. נספה בשואה עם משפחתו. תשובה ממנו בשו\"ת \"מקדשי השם\"."},{"i":15445,"n":"הלברשטם, מנחם מנדל מדוקלא","f":"אריה ליבוש מדוקלא","bt":"תרל","dt":"תרפו","b":"חתן דודו זקנו האדמור ר יחזקאל משינאווא. אב\"ד פריסטיק-תרנה ובנו ר חיים ברוך על מקומו אחריו, דוקלא-תרסח על מקום אביו. לא נהג אדמורות ובניו ובהם ר חנא מקולשיץ, ר דוד מטשעבין, ר יחזקאל שרגא מדוקלא היו אדמורים."},{"i":15446,"n":"הלברשטם, מנחם מנדל מוארשא","b":"פרסם מאמרים ב\"דגל הרבנים\" - וארשא תרפו."},{"i":15447,"n":"הלברשטם, מנחם מנדל ממושינא","f":"אריה ליב הלברשטם","dt":"תשג","b":"רב במושינא"},{"i":15448,"n":"הלברשטם, מנחם מנדל ממושציסק","b":"רב (אדמור?) במושציסק. רב בזויערץ. פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":15449,"n":"הלברשטם, מנחם מנדל מסטרופקוב","f":"אברהם שלום-דברי שלום","k":"אדמור מסטרופקוב","r":"האדמו\"ר מסטרופקוב","bt":"תרלג-ה","dt":"תשיד - ו אייר","dp":"ניו יורק - ירושלים","b":"תלמיד זקנו האדמור ר יחזקאל שרגא משינאווא בעל \"דברי יחזקאל\". חתן ר יעקב קופל פרנס, ובזיוו\"ש חתן ר שלמה ברוך פרגער מפעטראוועסלא-נכדו של המהר\"ם שיק. רב בסטרופקוב-תרף לצד אביו, אדמור על מקום אביו-תש, ניצל מהשואה וברח לשוויץ, עבר לניו יורק-תשז, וכיהן כאדמור מסטרופקוב. הוציא לאור \"דברי יחזקאל\" תרפב. חיבר \"דברי מנחם\" ירושלים תשיז.","bk":[["דברי מנחם - עה\"ת",""]]},{"i":15450,"n":"הלברשטם, מנחם מנדל מקראקא","f":"אריה ליבוש","bt":"תרן","dt":"תשב","b":"חתן ר יצחק ישעיה מטשכויב. רב בקראקא. נספה בשואה."},{"i":15451,"n":"הלברשטם, מנחם מנדל מקשאנוב","f":"נפתלי","bt":"תרם","dt":"תשג","b":"רב בקשאנוב-תרפא על מקום אביו. נספה בשואה."},{"i":15452,"n":"הלברשטם, מנחם מנדל מראדזמין","b":"חסיד אלכסנדר. חתן האדמור מאלכסנדר. רב בראדזמין. פרסם מאמרים ב\"בית ישראל\"-\"בית שמואל\" - לודז תרץ, \"כרם בית שמואל\" - פיעטרקוב תרצא."},{"i":15453,"n":"הלברשטם, מרדכי דב מגורליץ","f":"אלישע מגורליץ","k":"הו\"ל ברוך שאמר","bt":"תרסה","dt":"תשלט","dp":"ניו יורק","b":"נכד האדמור ר מרדכי דב מהורונסטיפל. ניצל מהשואה, עלה לירושלים, מחסידי טשבין. הוציא לאור ספרי זקניו \"ברוך שאמר\" ושות עמק שאלה מרמ\"ד מהורנוסטייפל."},{"i":15454,"n":"הלברשטם, מרדכי זאב מגריבוב","f":"אריה ליב מגריבוב","bt":"תרמב","dt":"תשב - כו סיון","b":"נכד ה\"דברי חיים\" מצאנז. חתן ר חיים מאיר אפשטין מניישטט. רבה של גריבוב-תרסד, אב\"ד צאנז-תרצה על מקום אביו ובנו ר ברוך על מקומו אחריו בגריבוב. נספה בשואה. עוד מבניו: ר אפרים, ר צבי, ר פנחס שמעיה. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח."},{"i":15455,"n":"הלברשטם, מרדכי זאב מצאנז","dt":"תשג","b":"רב בסאנדז"},{"i":15456,"n":"הלברשטם, מרדכי מדיסלדורף","k":"בעל מאמר מרדכי","b":"רב בדיסלדורף-תק\"י"},{"i":15457,"n":"הלברשטם, מרדכי מקומרנא","f":"שמחה","bt":"תקד","dt":"תקפז - כ טבת","b":"חתן רא\"ל ברנשטין רב המדינה. רבה של קומרנא, רב בברודי"},{"i":15458,"n":"הלברשטם, מרדכי מקמפנא","f":"אריה ליב","bt":"תרסב","dt":"תשכה","b":"חתן דודו ר אריה הלברשטם מגורליץ. רבה של קמפנא-פרוסיה, היגר לארה\"ב."},{"i":15459,"n":"הלברשטם, משה אהרן מבובוב","f":"בן ציון","bt":"תרף","dt":"תשא","b":"בן ואח של האדמור מבובוב. נספה בשואה. כתביו אבדו בשואה. ב\"כרם שלמה\" תשלח - תולדותיו ודברי תורה ממנו."},{"i":15460,"n":"הלברשטם, משה אהרן מברדיוב","dt":"תשד","b":"רב בברדיוב"},{"i":15461,"n":"הלברשטם, משה אהרן מסטרופקוב","f":"יחיאל נתן מברדיוב","b":"חתן ר מנחם מנדל הלברשטם בעל \"דברי מנחם\". כיהן כרב בסטרופקוב ליד חותנו."},{"i":15462,"n":"הלברשטם, משה אהרן מקולושיץ","f":"חנה מקולשיץ וריישא","bt":"תרסד","dt":"תשב","b":"חתן ר דוד דב מייזלש באויהל. רב בפודגורזע, קולושיץ-תרצו. נספה בשואה. פרסם דברי תורה ב\"בית ועד לחכמים\"."},{"i":15463,"n":"הלברשטם, משה אריה מנאסאד","f":"אברהם אביש","k":"הו\"ל מאור יהושע","b":"ניצל מהשואה ועבר לארה\"ב, מכהן כאב\"ד נאסאד. הוציא לאור ספר זקנו \"שות מאור יהושע\" ירושלים תשכז - עם הערות והקדמה (הספר היה מוכן לדפוס בשנת תשג בשם מאור יהושע)."},{"i":15464,"n":"הלברשטם, משה יוסף מזברז","f":"אריה ליב הלברשטם","b":"רב בזבארז-ת\"ר"},{"i":15465,"n":"הלברשטם, משה לאזאר","k":"בעל גחלי אש-תרצח","dt":"תש..","b":"נכד צדיקי בית שינאווא-צאנז. חתן ר ישראל פריינד מהוניאד. מחכמי הוניאד, עבר לקלויזנבורג. נספה בשואה."},{"i":15466,"n":"הלברשטם, משה מברדיוב","f":"ברוך מגורליץ","k":"אדמור מברדיוב","bt":"תרי","dt":"תרסד - א אלול","b":"נכד הדברי חיים. תלמיד ר נתן גולדברג מלימנוב. חתן דודו ר אהרן מצאנז ונולדו לו 21 ילדים. רב ברדיוב(=ברטפלד)-תרלד על מקום ר חיים אברהם אורנשטין, ור זלמן ליב הלברשטם על מקומו אחריו. (אצל אלפסי תאריך פטירתו - יט תשרי, ואצל מורשת הונגריה התאריך - תרצב). הו\"ל ספר זקנו \"דברי חיים\"."},{"i":15467,"n":"הלברשטם, משה מירושלים","f":"יעקב","bt":"תרצב","bp":"טשאקאווא","b":"עלה לירושלים בגיל 3 עם אביו. חתן ר הלל שלזינגר. עמד בראש ישיבת \"דברי חיים\" ומראשי כולל \"חיבת ירושלים\" לעדת גליציה."},{"i":15468,"n":"הלברשטם, משה מקשאנוב","f":"דוד מקשנוב","bt":"תר","dt":"תרעה - ה אדר","b":"רב בקשנוב (קרשנוב). נכד הדברי חיים, חתן ר ישראל אלימלך אונגר מזבנא, ובזיוו\"ש חתן ר מרדכי שניאור זלמן שניאורסון מזיטומיר והיה גיסו של \"אחד העם\". לא שימש באדמורות."},{"i":15469,"n":"הלברשטם, משה משינאווא","f":"יחזקאל שרגא משינואוו","k":"אדמור משינאווא","bt":"תרג","dt":"תרעט - יב חשון","b":"נכד הדברי חיים. לאחר שנתייתם גדל אצל דודו ר משה אונגר בצאנז. חתן הגביר ר מאיר צבי הירש טננבוים מבריגל. רב ואדמור בשינאווא על מקום אביו, עבר לצאנז-תרסד. בנו ר דוד מסוקולוב. חתניו: ר יעקב שמשון קנר מטשחוב, ר אלימלך בינדיגר משינאווא."},{"i":15470,"n":"הלברשטם, משלם זושא יצ' מרצפרט","f":"שלום אליעזר מרצפרד","bt":"תרמד","dt":"תשד - כג אייר","dp":"אושוויץ","b":"רב ברצפרט. חתן ר נפתלי ט\"ב אבד ניר באטור, ובזיוו\"ש חתן ר יהודה ארליך. דברי תורה ממנו ב\"בית ועד לחכמים\". נספה בשואה."},{"i":15471,"n":"הלברשטם, נחום אפרים מאושפיצין","dt":"תשג","b":"רב באושפיצין"},{"i":15472,"n":"הלברשטם, נחום אפרים מטורנא","f":"אריה ליבוש","k":"אדמור משיניבא-טורנא","bt":"תרם","dt":"תשב","b":"אדמור שיניביא בטורנא על מקום אביו. חתן דודו ר נפתלי רובין מוישניצא. נספה בשואה."},{"i":15473,"n":"הלברשטם, נפתלי חיים מגורליץ","f":"אלישע מגורליץ","bt":"תרמה","dt":"תשד - י שבט","dp":"יאקוצק-סיביר","b":"חתן ר אלטר זאב הורביץ מסטריזוב. אב\"ד גורליץ בחיי אביו. הוגלה לסיביר ונפטר שם. בנו ר אלתר זאב מברוקלין."},{"i":15474,"n":"הלברשטם, נפתלי חיים מטרנוב","dt":"תשג","b":"רב בטארנאוו"},{"i":15475,"n":"הלברשטם, נפתלי מגריבוב","f":"ברוך מגריבוב","k":"אדמור מגריבוב-צאנז","bt":"תרפה","b":"ניצל מהשואה, הגיע לניו יורק. משמש כאדמור מגריבוב-צנז בברוקלין. הקים \"מכון יוחסין\" לבירורי משפחות."},{"i":15476,"n":"הלברשטם, נפתלי מטשקאווא","f":"יעקב מטשאקוב","bt":"תרפח","bp":"טשקאווא","b":"עלה לירושלים-תרצה. חתן ר חיים שמואל שמעלקא גינסברג מאוריענעש-מעדיאש. ראש מערכת הכשרות של בד\"ץ בירושלים. פרסם בבטאונים שונים דברי תורה וחתם \"יעקבזאהן, אידלזון\"."},{"i":15477,"n":"הלברשטם, נפתלי מטשרקאס","f":"יחזקאל שרגא משינאווא","k":"בעל אילה שלוחה","bt":"תקצח","bp":"אויהל","dt":"תרכד - כא כסלו","b":"נכד הדברי חיים. חתן ר אהרן מרופשיץ, ובזיוו\"ש חתן ר מנחם נחום שניאורסון מניעזין (בן האדמור האמצעי). רב בברדיטשוב. נפטר ללא ילדים. חיבר \"אילה שלוחה\" פשעמיש תרנה.","bk":[["אילה שלוחה – חידושי תורה",""]]},{"i":15478,"n":"הלברשטם, נפתלי מקשנוב","f":"דוד מקשנוב","bt":"תרי","dt":"תרפג -כז-ט תמוז","b":"נכד הדברי חיים מצאנז. חתן ראי\"ה קצנלנבוגן מטלוסט, ובזיוו\"ש ר משה הגר מרדוביץ. אב\"ד קשאנוב(=קרשאנוב) (לאחר מחלוקת עם חסידי רדומסק)."},{"i":15479,"n":"הלברשטם, נפתלי צבי הירש מגלוסק","f":"יוסף זאב","bt":"תרכב","dt":"תרף","b":"חתן ר משה רוקח מקארוב. אב\"ד גליסק, ואחר כך פיקעלע - (פרבר של צנז). בנו ר אריה ליבש על מקומו אחריו בפיקעלי."},{"i":15480,"n":"הלברשטם, נפתלי צבי מבובוב","f":"שלמה","bt":"תרצא","b":"ניצל מהשואה והגיע לירושלים. (את בר המצוה עשה בבונקר בגרוסורדין). עבר לניו יורק אל אביו, ולימד בישיבת בובוב שם. חתן ר יוסף פאנעט אדמור מדעש."},{"i":15481,"n":"הלברשטם, סיני מברוקלין","f":"אריה ליבוש","bt":"תשה","b":"חתן ר משה אריה הלברשטם אב\"ד נאסאד בברוקלין. רב בברוקלין."},{"i":15482,"n":"הלברשטם, סיני מזמיגראד","f":"ברוך מגורליץ","k":"אדמור מזמיגרוד","bt":"תרל","dt":"תשא - כו תמוז","dp":"סיביר","b":"נכד הדברי חיים. חתן ר נפתלי הורביץ ממעליץ. רב בגורליץ ליד אביו, אב\"ד קולשיץ, רבה של זמיגרוד-תרסז, עבר לקראקא, יאסלו. הוגלה לסיביר בזמן השואה ונפטר שם. מבניו: ר ברוך מזקליקוב, ר חיים יהודה מאושפיצין, ר אברהם אביש מסטמר, ר דוד מסוסנוביץ, ר אהרן מזמיגראד, ר יחשראל שרגא מרידיק - כלם נספו בשואה."},{"i":15483,"n":"הלברשטם, פנחס שמעיה","f":"מרדכי זאב מגריבוב","b":"חתן ר נפתלי ממעליץ."},{"i":15484,"n":"הלברשטם, צבי","f":"מרדכי זאב מגריבוב","b":"חתן ר טביל מדוקלא."},{"i":15485,"n":"הלברשטם, צבי אלימלך מברוקלין","f":"יקותיאל יהודה","k":"אדמור מקלויזנבורג נת","bt":"תשיג","bp":"ניו יורק","b":"רבה של קרית צאנז בנתניה. חתן ר שמואל אלכסנדר אונדסדורפר ממונטריאול. אדמור מצאנז קלויזנבורג על מקום אביו."},{"i":15486,"n":"הלברשטם, צבי הירש מסטמר","f":"אריה ליבוש מטורנא","bt":"תרמה","dt":"תשד","b":"נכד ר יחזקאל שרגא משינאווא. חתן ר מאיר הורביץ מלינסק. רב ואדמור בסטמר. סייע ליהודים בזמן השואה ורבים ישבו על שלחנו. נספה בשואה."},{"i":15487,"n":"הלברשטם, צבי הירש מרודניק","f":"אברהם מרודניק","k":"אדמור מרודניק","bt":"תרפה","dt":"תשמא - כב תמוז","b":"הצליח לעלות לארץ-תשג בעלית ילדי טהרן. היגר ללוס אנגלס וכיהן כאדמור מרודניק בלוס אנגלס ובנו ר אברהם על מקומו אחריו. חתן ר חיים יצחק בן יהושע הלברשטם מסלטפינא."},{"i":15488,"n":"הלברשטם, צבי הירש מרודניק","f":"ברוך מגורליץ","k":"אדמור מגורליץ","r":"רב בניסקא ואחר כך ברודניק ומתרס\"ו גם אדמו\"ר","bt":"תריא","dt":"תרעח - טו אב","b":"חתן ר ישראל הורביץ מברנוב, ובזיוו\"ש חתן ר מאיר משולם שפירא מלנצהוט. רב בניסקא, רב ברודניק על מקום אביו ובחיי אביו. אדמור מגורליץ-תרסו על מקום אביו. בזמן מלחה\"ע ה-I ברח להונגריה. יש רושמים תאריך פטירתו - תרפח.","bk":[["עטרת תפארת צבי - על",""]]},{"i":15489,"n":"הלברשטם, צבי יעקב מפודקמין","dt":"תקצ - ז טבת","b":"רב בפודקמין"},{"i":15490,"n":"הלברשטם, צבי מנחם מנדל מגורליץ","f":"אלישע","k":"אדמור מגורליץ-רופשיץ","bt":"תרם","dt":"תשכז","b":"חתן ר מנשה מרילוס מדובצק. ניצל מהשואה והיגר לניו יורק והיה שם האדמור מגורליץ-רופשיץ."},{"i":15491,"n":"הלברשטם, שלום אליעזר מרצפרט","f":"חיים - הדברי חיים","bt":"תרכב","bp":"צאנז","dt":"תשד - טז סיון","dp":"אושוויץ","b":"חתן גיסו ר מרדכי דב טברסקי מהורנוסטייפל. ישב בשינאווא, טורנא, טעגלאש, עבר לרצפרט-תרנט והיה מנהיגם של חסידי צאנז בהונגריה. ניסה לעלות לארץ-תרצט בעזרת החסיד ר שמואל אהרן ועבר - ולא הסתייע. היה בגיטאות נירדהאז, ואריו-לאפוש, שימאפוסטא. נספה בשואה."},{"i":15492,"n":"הלברשטם, שלום יחזקאל שרגא מנ\"י","k":"אדמור מטומשוב נ\"י","b":"אדמור מטומשוב-ציעשנוב בניו יורק-תשכח. חיבר \"פנת יקרת\" נ\"י תשכח."},{"i":15493,"n":"הלברשטם, שלום מגליסק","dt":"תשג","b":"רב בגליסק"},{"i":15494,"n":"הלברשטם, שלום מניסקא","f":"ברוך מגורליץ","bt":"תרטו","dt":"תרצט - בערך","b":"חתן ר משה יוסף ט\"ב אב\"ד אויהעל. רב ברודניק על מקום אחיו רצ\"ה, רב בניסקא-תרן כחמישים שנה. נספה בשואה."},{"i":15495,"n":"הלברשטם, שלום מפיקעלע","f":"אהרן מצאנז","bt":"תרטו","dt":"תרצא-ד","b":"נכד ה\"דברי חיים\" מצאנז. חתן ר מאיר הורביץ מדזיקוב. אב\"ד פיקעלה, ראב\"ד בצאנז."},{"i":15496,"n":"הלברשטם, שלום מצאנז","b":"ראב\"ד בצאנז-תר\"נ"},{"i":15497,"n":"הלברשטם, שלמה מבובוב","f":"מאיר נתן","k":"אדמור מבובוב","bt":"תרז","bp":"דזיקוב","dt":"תרסה - א תמוז","b":"נכד האדמור מדזיקוב ו\"דברי חיים\" מצנאז, וגדל אצלם לאחר פטירת אביו. חתן ר יהושע הלוי רוזנפלד מקמינקא, ובזיוו\"ש חתן ר מנשה בן נחום צבי מדרוהוביטש (שושלת אויהל). רב בבוקובסק-תרכד במינוי זקנו האדמור מצאנז, אושפיצין-תרלט, וישניצא-תרם והחל לנהוג באדמורות והקים ישיבה גדולה. עבר לבובוב-תרנב והתחיל להיקרא האדמור מבובוב.","bk":[["עטרת שלמה [קובץ ליקוטים] (באבוב)",""]]},{"i":15498,"n":"הלברשטם, שמואל דוד מניו יורק","f":"יקותיאל יהודה","k":"אדמור מקלויזנבורג ני","bt":"תשטז","bp":"ניו יורק","b":"חתן ר אהרן ווידר אב\"ד לינץ. אדמור מקלויזנבורג בארה\"ב."},{"i":15499,"n":"הלברשטם, שמואל מברדיוב","f":"משה","bt":"תרכו","dt":"תשד","b":"חתן ר מאיר ליפשיץ מיאנוב. הביא לדפוס את שו\"ת דברי חיים-תרסב. נספה בשואה."},{"i":15500,"n":"הלברשטם, שמחה ישכר בער מציעשי","f":"יחזקאל שרגא משינאווא","k":"אדמור מצשינוב","bt":"תרל","bp":"סטרופקוב","dt":"תרעד - כ טבת","b":"נכד ה\"דברי חיים\" מצאנז. חתן ר יהושע מבלז. רבה של ציעשינוב-תרנג. חיבר \"דברי שמחה\" קראקא תרצב. חתניו: ר ליב, ר משלם זוסיא בן ר יהודה ליב מהורנסטיפל. ?? לא באוצר ??","bk":[["דברי שמחה – עה\"ת",""]]},{"i":15501,"n":"הלברשטם, שמחה מברוד","f":"משה הלברשטם","b":"מגדולי חכמי ברוד-ת\"ר"},{"i":15502,"n":"הלברשטם, שמלקא מדוקלא וצאנז","f":"אהרן מצאנז","b":"נכד ה\"דברי חיים. חתן ר קלונימוס קלמן בן ר יוסף \"היהודי הטוב\" מניישטאט. רב בצאנז-תרע, דוקלא."},{"i":15503,"n":"הלברשטם, שניאור זלמן","f":"חיים נחום ממושציסק","b":"נכד(-אבי אמו) ר יעקב משה ספרין מקומרנא. לאחר שנתייתם גדל אצל האדמור ר אהרן מנחם מנדל גוטרמן מראדזמין. חתן קרובו האדמור ר יהושע מגורליץ."},{"i":15504,"n":"הלברשטם-קנר, ברוך","dt":"תשטו - שבט","dp":"ארה\"ב","b":"רב בסאנדז,טשחוב"},{"i":15505,"n":"הלברשטם-רוטנברג, יצחק שלום","f":"מנחם בנימין בן ציון","bt":"תרעא","dt":"תשלד","b":"רב בניו יורק. פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":15506,"n":"הלד, שמואל יוסף מפשמישל","b":"רב בפשמישל-תרכה."},{"i":15507,"n":"הלואה, אברהם","b":"מו\"צ לספרדים בלונדון-תקפ\"ה"},{"i":15508,"n":"הלוי אליעזר","bt":"1809","dt":"ה'תרמח 1888","bk":[["משא אליעזר",""]]},{"i":15509,"n":"הלוי יוסף צבי בן אברהם","bt":"1874","dt":"ה'תשכ 1960","bk":[["הוראות שעה",""],["השקפה לברכה",""],["זרע הארץ",""],["חובת גידולי הארץ",""],["טיב קידושין",""],["לחם הארץ",""],["נטע הארץ",""],["תורת השביעית",""]]},{"i":15510,"n":"הלוי נפתלי הירץ","bt":"1852","dt":"ה'תרסב 1902","bk":[["ברית עולם חלק ב",""]]},{"i":15511,"n":"הלוי סג\"ל לאוי ב\"ר מרדכי","r":"אדמו\"ר מטאהש בקנדה","bt":"ג ניסן תרפא","dt":"כז אב תשעה","bk":[["עבודת עבודה",""]]},{"i":15512,"n":"הלוי, אברהם אהרן מפרג וירושלים","b":"פרסם מאמרים ב\"זהב הארץ\" - ירושלים תרסט."},{"i":15513,"n":"הלוי, הנרי מצרפת ואלגיר","dt":"תשב","b":"רב באלמעסכר-אלגיר - תרסח-תרעג מטעם הקונסיסטואר בצרפת. נספה בשואה."},{"i":15514,"n":"הלוי, יוחנן מצרפת ואלגיר","b":"רב בסוק-אראץ-אלגיר, קצמטינא מטעם הקונסיסטואר. הסכים על \"כגן הירק\", \"פתשגן הכתב\"."},{"i":15515,"n":"הלוי, יוסף טוביה מטורקא","b":"רב קהילת הספרדים בטורקא. פרסם מאמרים ב\"קבוצי אפרים\" - יאסי-בוקרשט תרעד."},{"i":15516,"n":"הלוי, יוסף מאדרינופול","b":"מורה באדרינופול. פרסם שיר ב\"הלבנון\" - ירושלים-פאריס תרכג-תרמב."},{"i":15517,"n":"הלוי, יוסף מראשון לציון","f":"נפתלי הירץ הלוי","k":"בעל יקר הערך","bt":"תרל","dt":"תשט - ח כסלו","b":"מרביץ תורה בראשון לציון. פרסם מאמרים ב\"הדביר\" - ירושלים תרעט."},{"i":15518,"n":"הלוי, ישעיה ממנטובה","b":"רב במנטובה-תרנז, ואחראי על ספרית הקהלה."},{"i":15519,"n":"הלוי, מנחם מנדל מביאלא","b":"פרסם מאמרים ב\"אהל מועד\" - איזביצא - בילגוריי - תרפו."},{"i":15520,"n":"הלוי, צפניה מירושלים","f":"מיכאל","k":"בעל צדה לדרך"},{"i":15521,"n":"הלחמי, אברהם ממקנאס","bp":"מראקש","b":"סגינהור. רב ומרביץ תורה במקנאס, פאס. בניו: ר יהודה ור מרדכי."},{"i":15522,"n":"הלחמי, דוד חיים ממצרים","b":"תלמיד ר אברהם הלוי ממצרים. רב במצרים בזמן ר דוד גרשון, רודוס על מקום ר משה די בושאל, ואצלו הדיינים ר משה ן ארדוט ור יוסף נחמיאש. נזכר ב\"גנת ורדים\"."},{"i":15523,"n":"הלחמי, דוד מרודוס","b":"רב ברודוס-שנות ה-ת' ור אליהו ן ארדיט על מקומו אחריו."},{"i":15524,"n":"הלחמי, עזרא חייא ידידיה","f":"שלום מחלב","k":"בעל שערי עזרא","bp":"מצרים","b":"מחכמי ירושלים, בשליחות בצפון אפריקה, מלמד בת\"ת במצרים-[תרס]. חיבר גם \"זכור לעבדך\", \"תורת משה\", ועוד. ?? לא באוצר ??"},{"i":15525,"n":"הלחמי, שלום מטבריה","k":"בעל משפט שלום","b":"מחכמי טבריה, בשליחות במרוקו וסוריה. תשובות ממנו בספרו \"משפט שלום\" גם מהעיר אסטיף-מרוקו, ועין טב-סוריה, בזמן שליחותו."},{"i":15526,"n":"הלטובסקי, אהרן מירושלים","b":"מראשי חסידי קרלין בירושלים-תשה."},{"i":15527,"n":"הלטובסקי, יהושע השל מירושלים","b":"מראשי חסידי קרלין בירושלים-תשה."},{"i":15528,"n":"הלטובסקי, מאיר יוסף מירושלים","b":"ר\"מ בישיבת \"חיי עולם\" בירושלים."},{"i":15529,"n":"הלטרכט, דוד אלכסנדר מליסא","f":"נח מליסא ולוברנץ","k":"בעל מזבח חדש","b":"הוא או אביו - ידידו של ר עקיבא איגר מפוזנא."},{"i":15530,"n":"הלטרכט, ישכר דב מלוברנץ","f":"נח מליסא ולוברנץ","k":"בעל חזות קשות","b":"רב בלוברנץ."},{"i":15531,"n":"הלטרכט, משה","f":"נח מליסא ולוברנץ"},{"i":15532,"n":"הלטרכט, נח מליסא ולוברנץ","k":"בעל תולדות נח","bp":"ליסא?","b":"תלמיד ישיבת פוזנא והיה ידידו של ר עקיבא איגר, פיורדא אצל ר צבי הירש מפיורדא, פרג אצל ר יחזקאל סגל. רב בבאנאווא (במינוי ר דוד טעבלי מליסא), בלאשקי, לובראנץ. בניו - ר דוד אלכסנדר בעל \"מזבח חדש\", ר משה, ר ישכר דב בעל \"חזות קשות\", ר יצחק."},{"i":15533,"n":"הליגיה, יום טוב","b":"מגדולי דור-שנת ת'"},{"i":15534,"n":"הליטש, יוסף מסטריזוב","b":"רב בסטריזוב. תשובה אליו ב\"קנאת סופרים\"."},{"i":15535,"n":"הליטשר, אהרן יצחק מהאליטש","k":"בעל בית אהרן","b":"רב בהאליטש, רכניץ-תקמב, עלה לא\"י"},{"i":15536,"n":"הלימן, מרדכי מפסווטין","b":"רב בפסווטין-תר\"נ"},{"i":15537,"n":"הלין, אברהם הרופא","f":"יעקב","b":"רופא בפפד\"מ. חתם-תטז על תקנון הרופאים בזמן ר מנדל בס מפפד\"מ."},{"i":15538,"n":"הלין, אברהם מגלוגא","f":"יעקב משה","k":"בעל זרע אברהם","bp":"תפו - יז טבת","dp":"וינה","b":"רב בווארט, ראב\"ד בגלוגא-תסה, התיישב בוינה."},{"i":15539,"n":"הלין, אלחנן (ורטהימר)","f":"אברהם","k":"בעל מגילת וינץ","b":"מחכמי פרנקפורט-שעב. חיבר \"שיר וינצנץ\" ונדפס בשמות שונים ותורגם ללשון אשכנז, מגילת וינץ הנקרא \"דברי השירה הזאת\" על גירוש פפד\"מ."},{"i":15540,"n":"הלין, יוסף","f":"אברהם","b":"חתן הקדוש ר רפאל שפיץ מוילנא. רב-שנת תפה."},{"i":15541,"n":"הלין, ליב","f":"משה יעקב הלין","b":"רב-שנת ת\"ק"},{"i":15542,"n":"הלין, מנחם מנלי","b":"רב-שנת ת\"ע"},{"i":15543,"n":"הלין, נתן מפפד\"מ","f":"אברהם","dt":"שפח - כא אלול","dp":"פפד\"מ","b":"מחכמי פפד\"מ. אחיו של ר אלחנן בעל \"שיר וינצנץ\". הסכים על ספר הכוונות לאר\"י."},{"i":15544,"n":"הלין-אשכנזי, משה יעקב","f":"אברהם","k":"בעל ידי משה","b":"רב-שנת ת\"מ. בנו - ר אברהם בעל \"זרע אברהם\" הו\"ל ספר אביו \"ידי משה\"."},{"i":15545,"n":"הלל בן שחר מקנדיא","b":"רב בקנדיא-כרתים-שנות ה-ת'. (זהו כינויו ולא שמו המלא)."},{"i":15546,"n":"הלל הגדול מדובנא","b":"אבי משפחת פריזר שהדפיסו ספר יוחסין - ליביטשוב תרנז."},{"i":15547,"n":"הלל הזקן מערפורט","dt":"קפו","b":"מגדולי חכמי אשכנז,פוסק,רב בערפורט"},{"i":15548,"n":"הלל החזן","f":"ישועה","b":"חכם הקהלה בטבריה בשנת ד תשפ (1020)- תתי (1050), נמצא מכתב ששלח מטבריה אל החבר ר אפרים העזתי בפוסטט."},{"i":15549,"n":"הלל הכהן מסאמוש-אויוואר","f":"יצחק יוסף מסאמוש","bt":"תרנז","bp":"סאמוש-אויוואר","dt":"תשד - ו סיון","b":"תלמיד בעל \"קרן לדוד\" באויבר-ווישיווה, ור שמאול זלמן וינברגר במארגרטן. חתן גיסו ר אברהם שלמה אליאש מסאמוש-אויוואר. ויתר על רבנות סאמוש-אויוואר לטובת גיסו-חותנו, משגיח כשרות בקלויזנבורג, מקורב לאדמור מויזניץ, נתמנה לרב בית הסהר הארצי-תשא שבו נאסרו יהודים רבים. נספה בשואה."},{"i":15550,"n":"הלל הלוי מוילנא","f":"מנחם מנדל הלוי","dt":"תקפא - יז ניסן","dp":"וילנא","b":"חתן ר נחום שוחט מוילנא. דיין בוילנא. הסכים על חומשים עם תרגום. בנו ר אליהו אלץ-גוט דיין בוילנא."},{"i":15551,"n":"הלל הלוי מלבוב","f":"מרדכי מ' אברהם מקראק","dt":"תסג - ג כסלו","dp":"לבוב","b":"נכד מוהר\"ר יושע, ונכד ר אברהם הלוי-חתנו של בעל מגיני שלמה. מחכמי לבוב, נהרג במפולת יחד עם רבים מבני הקהלה."},{"i":15552,"n":"הלל מאמציסלב","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":15553,"n":"הלל מאניקשט","f":"הרץ","b":"רב באניקשט"},{"i":15554,"n":"הלל מארץ ישראל","f":"אברהם","b":"חי בזמן רבנו תם, עלה לארץ -תתקעב (1212) בערך. חיבר ספר מסע ממנו שרדו ארבע שורות. לדעת שטיינשניידר הוא ר הלל בן אליקים שחי בארץ יון או איטליה וחיבר פירוש על ספרא ומובא בתוספות סוטה דף טו ודף לה. וכן חיבר פירושים נוספים והובא על גדולי ישראל במהלך הדורות."},{"i":15555,"n":"הלל מארץ ישראל - ב","f":"אברהם","b":"בשנת רסט חתם על התקנה לפטור תלמידי חכמים ממס."},{"i":15556,"n":"הלל מבונא","f":"יעקב מבונא","b":"פייטן באשכנז, רב בבונא-ד'תתקל. חיבר \"אמוני שלומי ישראל\" על קדושי בלוייש-צרפת שנהרגו עק\"ה-ד'תתקלא. אחיו - ר אפרים מבונא - וכונו \"שני בני היצהר\". אולי הוא ר הלל הנזכר בראב\"ן."},{"i":15557,"n":"הלל מבלשויץ","b":"רב בבאלשוועץ-תק\"ס"},{"i":15558,"n":"הלל מבריסק והמבורג","f":"ישראל","dt":"תפא","dp":"אלטונא","b":"מחכמי בריסק, עבר להמבורג."},{"i":15559,"n":"הלל מברנוב","b":"תלמיד ר מנחם מנדל מקוצק. אב\"ד ברנוב."},{"i":15560,"n":"הלל מוילנא","f":"שמואל","b":"דיין בוילנא, חתם-תקי עם היסו\"ד."},{"i":15561,"n":"הלל מוילנא קידאן ואה\"ו-אשכני","f":"נפתלי הרץ מזולקווא","k":"בעל בית הלל","bt":"שעה","bp":"בריסק","dt":"תן - אב","dp":"זולקוא","b":"בן למשפחה ליטאית שעברו לגליציה. תלמיד ר הירש דרשן בבריסק, ובעל \"חלקת מחוקק\" בוילנא, ור השל שהיה דודו(-בעל דודתו) (ולפי בובר-זולקוא לא היה תלמידו). דיין בוילנא אצל בעל \"חלקת מחוקק\", ורב בכמה קהילות בליטא, רב בקידאן על מקום ר יהודה זונדל בן עוזר, ור אליקום גצל הלוי מברוידא על מקומו אחריו, רב באלטונא-תל, אה\"ו-תלא עד תמ, ור משלם זלמן מירלש-חותן ה\"חכם צבי\" על מקומו אחריו, זולקווא, וחבר בועד הרבנים בירוסלב ובזולקווא. בנו - ר משה דרשן הו\"ל את ספרו \"בית הלל\" -תנא. בניו: ר משה דרשן מקעמפן וילנא, ר אברהם, ר אהרן זליג מאלטונא וזולקווא, חתנו - ר ר יהודה ליב בן ישראל חריף מוילנא?. הסכים על \"אור חדש\" לר חיים בוכנר, \"דברי שמואל\" לר שמואל זנויל מלובלין. (באוצר הרבנים תאריך פטירתו - כב טבת)"},{"i":15562,"n":"הלל מוירונה","f":"שמואל בן אלעזר","k":"בעל תגמולי הנפש","bt":"ד'תתקפ","dt":"נא","b":"תלמיד רבנו יונה .מחכמי ספרד ואיטליה. רופא, פילוסוף, רב ברומא, קפואה, פורלי. היה מתומכי הרמב\"ם ופנה לחברו ר יצחק בן מרדכי-רופא האפיפיור לסייע בעד בני משפחת הרמב\"ם להגן על ספריו, ע\"י יסוד אספה באלכסנדריה ושליחת שליחים לאשכנז. היה במחלוקת עם ר זרחיה בן שאלתיאל הלוי אודות פרשנות \"מורה נבוכים\"."},{"i":15563,"n":"הלל מזולקוא","f":"שלמה","b":"ראש העדה בזולקוא-תץ, חתם-תקיא על החרם הגדול עם ר נפתלי הרץ הורביץ, חתם-תקכא עם ר שמשון מייזלש, ר ישראל מרדכי בן ברוך, ר גדליה בן בנימין וולף, ור מרדכי בן יוסף."},{"i":15564,"n":"הלל מזרחי","b":"שליח ירושלים במזרח אירופה בשנת תקמב-תקמח ביחד עם ר אברהם הכהן. פנקס שליחותו התפרסם בספר \"כי ביצחק\" לר יצחק בדהב ירושלים תרפח."},{"i":15565,"n":"הלל מחעלמא ווילנא","f":"יונה הלוי","dt":"תסו - כב טבת","dp":"וילנא","b":"נכד ר אליעזר אשכנזי בעל \"מעשה ה'\". חתן ר יוסף. רב בחעלמא-תמז, וילנא על מקום ר משה קרמר. הסכים על \"מגני ארץ\" דירנפורט תנב. בניו: ר יונה מלובמלא, ר יוסף גבאי בוילנא. מצאצאיו משפחת גרשטין בוילנא."},{"i":15566,"n":"הלל ממודנא","f":"אהרן ברכיה","b":"רב במודנא על מקום אביו."},{"i":15567,"n":"הלל ממודניא","b":"מגדולי חכמי איטליה במודנא-ש\"מ"},{"i":15568,"n":"הלל מנאמושץ","b":"מקובל,רב בנאמושץ-תק\"י"},{"i":15569,"n":"הלל מספרד","f":"יצחק","b":"מחכמי ספרד, מתלמידי ר' אברהם אבן עזרא, חיבר פירושים לתנ\"ך"},{"i":15570,"n":"הלל מפאריטש (מאליסוב)","k":"בעל פלח הרימון","dt":"תרכד - יא אב","b":"התפרסם בילדותו כ\"עילוי מחומץ\". תלמיד ר אברהם דב מאווריטש, ר מרדכי מטשרנוביל, בעל התניא, ובנו. רב בחרסון, פאריטש(=פאריץ), בוברויסק-תרי. חיבר פירוש ל\"קונטרס ההתפעלות\" לאדמור ר דובער, \"פלח הרימון\", \"אמרי נועם\" ועוד. בנו ר זלמן-נפטר בחיי אביו. חתנו ר רפאל מרדכי - בן ברוך שמואל בן חיים אברהם בן בעל התניא.","bk":[["אמרי נעם",""],["מאמרי השטתחות",""],["פלח הרימון - בראשית שמות ויקרא שיר השירים",""]]},{"i":15571,"n":"הלל מפעצעל","b":"רב בפעצעל-ת\"ר"},{"i":15572,"n":"הלל מקפוסט","f":"אהרן","k":"בעל חן טוב","b":"רב בקאפוסט-תקל. חיבר \"חן טוב\" - קוריץ תקם."},{"i":15573,"n":"הלל מקראקא","dt":"תקמה - ד סיון","b":"דיין בקרקא"},{"i":15574,"n":"הלל מרומאניא","f":"אליקים","b":"מגדולי הראשונים בארץ יון-ד'תתק\"ע. חיבר פירוש לספרא."},{"i":15575,"n":"הלל מרוצקי","k":"בעל הילל בן שחר","b":"דרשן,מג\"מ בראצקי-תק\"מ"},{"i":15576,"n":"הלל משטמפן","f":"ליב","k":"הו\"ל בינה לעתים","b":"תלמיד ר יונתן איבשיץ בפרג, ר שלמה גומפרץ. מחכמי שטמפן-תקמ. הו\"ל ספר רבו \"בינה לעתים\" עם הקדמה ממנו."},{"i":15577,"n":"הלל, אברהם מבגדד","f":"משה","bt":"תרא","bp":"בגדד","dt":"תרף - יז טבת","dp":"בגדד","b":"דיין בבגדד-תרל, חכם באשי-תרעא, ראב\"ד-תרנה."},{"i":15578,"n":"הללויה, מהללאל מאנקונא","k":"בעל קדש הילולים","b":"רב באנקונא-תך בזמן מהר\"י פרימו. חיבר גם \"הלל גמור\", ועוד."},{"i":15579,"n":"הלמן, אריה ליפא מזלין.","b":"רב בזלין-תרמט."},{"i":15580,"n":"הלמן, דב בר מיאנוביץ","f":"משה מדרויא-פלך וילנא","b":"תלמיד ישיבת בוברויסק, מינסק, וילנא, וולוזין. חתן ר ברוך ברלין מיאנוביץ(=יאנאיויטש)-פלך ויטבסק. רב בקאזמירוב-פלך מינסק-תרסג, יאנוביטש(=יאנוביץ,יאנאוויטש)-פלך ויטבסק-תרע על מקום חותנו. נסמך מאת: ר שמריה נח, ר שמואל משה שפירא מבוברויסק, ר שלמה הכהן מוילנא."},{"i":15581,"n":"הלמן, משה","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":15582,"n":"הלמן, משה מדרויא","f":"אברהם שמואל","bt":"תרכג","b":"מצאצאי ר שמואל הילמן ממיץ. רב בדרויא-פלך וילנא-תרס. נסמך מאת: ר שלמה הכהן מוילנא, ר מרדכי מסלונים. בנו - ר דובער מיאנוביץ."},{"i":15583,"n":"הלמן, משה מנמירוב","bp":"נמירוב","dt":"תש..","b":"רב באושפיצין, רב בשאץ ובין תלמידיו שם - מהר\"ם שפירא מלובלין. רב בקריסנפולי. נספה בשואה."},{"i":15584,"n":"הלמן, שאול קריזשופיל","f":"שמלקא","bt":"תרכח","b":"מצאצאי ר שמלקא הורביץ מניקלשבורג, ור פנחס-גיסו של הרמ\"א. תלמיד כולל קובנא. רב בטרנובקה-פודוליה-תרנט, קירזופול(=קריזשאפיל)-פודוליה-תרסז."},{"i":15585,"n":"הלפנבין, מרדכי אריה מטרנופול","f":"יצחק","k":"בעל מתת אלקים","bt":"תקי","dt":"תר","b":"רב בטרנופול, וברודי. חיבר \"מתת אלקים\" למברג תקפה."},{"i":15586,"n":"הלפנד, אברהם משה מביסטריץ","f":"אהרן","bt":"תרט","dt":"תרפז","b":"רב בביסטריץ-פלך וילנא-תרמג."},{"i":15587,"n":"הלפנד, חיים יעקב - א. ליטבק","k":"בעל וואס געווען","bt":"1874","bp":"וילנא","dt":"1932","dp":"ניו יורק","b":"ממיסדי הבונד. עתונאי ויסד עתון \"זארגאנישן קאמיטעט\". גלה לסיביר וחזר. יצחק מלערב אירופה, היגר לארה\"ב וערך את \"נייע וועלט\", ועוד. חזר לרוסיה-1917 וערך את \"באגינען\", ועוד. נאלץ לעזוב וחזר לארה\"ב דרך פולין. ספרו תורגם לעברית בשם \"מה שהיה\" ת\"א תשה."},{"i":15588,"n":"הלפר (גלפר), דבורה אסתר","bt":"1817","bp":"ליטא","dt":"1907","b":"הקימה גמ\"ח בוילנא שתמך בלומדי תורה ובנצרכים, הקימה גם קלויז בוילנא. היתה דמות נערצת ונשים היו באות להשתטח על קברה של \"אם כל נצרך וגלמוד\" בוילנא. נפטרה ללא ילדים. מונוגרפיה עליה מאת יהושע בודזון."},{"i":15589,"n":"הלפר, בן ציון","bt":"1884","dp":"1924","b":"תלמיד ישיבות ליטא. עבר לגרמניה, אנגליה ולמד באוניברסיטת לונדון. נשלח למצרים לעבודת מחקר. הגיע לארה\"ב-1911 ועבד שם עם שלמה שכטר על הגניזה מקהיר. מרצה בדרופסי קולג'. הו\"ל מתוך הגניזה \"ספר המצוות\" לר חפץ בן יצליח. תרגם מערבית \"שירת ישראל\" לר משה ן עזרא. חיבר מאמרים על משקל השירה העברית."},{"i":15590,"n":"הלפרט, אברהם מארה\"ב","bp":"קובנא","b":"סופר ועסקן ציבור בבוסטון."},{"i":15591,"n":"הלפרט, יוסף מטשעטש","f":"שלום","bt":"תרכז","b":"רב בטשעטשע(=צעצא)-תרסו. נסמך מאת: ר צבי וינברגר ממרגארטן, ר\"מ פולק מבוניהאד, ר שמואל ברייער מפאפא."},{"i":15592,"n":"הלפרט, ליבוש בער מבורשא","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":15593,"n":"הלפרט, מרדכי דב מארד","f":"חיים שבתי","k":"בעל יד מרדכי","bt":"תרטו","b":"מצאצאי רא\"ל אפשטין מקניגסברג. תלמיד ישיבת סלונים. רב בארלאווא-תרלו, מארד, סוויסלוץ(=סויסלאוויטש-פלך מינסק-תרן. נסמך מאת: ר יוסף רוזין-רוגצובר בסלונים, ר אברהם עזרא מאמדור, ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\". חיבר גם \"בנין דוד\", \"חמד מרדכי\", ועוד. חתניו: ר שמעון יעקב גליקסברג מאודסה, ר שלום שטילבנס מדראגאנאווא."},{"i":15594,"n":"הלפרט, נפתלי מסיגט","b":"חתנו - ר משה סופר נכד הכת\"ס."},{"i":15595,"n":"הלפרין (היילפירסאהן), דב בער","f":"מרדכי קלמן מזסלב","b":"נכד(-אבי אמו) ר ישראל הלפרין-רב דחייטים בזסלב. חתן ר חיים רפפורט בעל מים חיים."},{"i":15596,"n":"הלפרין - משפחה","b":"מקור השם הילברון ושונה להלפרין, הילפרין, הילפרן, הלפרן, היילפרין. מצאצאי ר אלחנן ב\"ר יצחק הזקן ב\"ר שמואל מויטרי ב\"ר שמחה מויטרי בעלי התוספות. שושלת רבני ברזן בת כב דורות (למעשה ישנם כפילויות ויש פחות דורות). שושלת מהשר רבי שמשון ורטהימר. מספר מגלות יוחסין חוברו במהלך השנים."},{"i":15597,"n":"הלפרין יחיאל מיכאל","f":"אליהו זלמן","bt":"1860","bp":"וילנא","dt":"1919","dp":"צפת","b":"נכד המלבי\"ם. קיבל ירושה גדולה מאביו והקים בכספו בי\"ס למלאכה בסמולנסק. חזר לוילנא וחילק 80 מכונות סריגה לנערות עניות בוילנא. אחרי פרעות 1880 הצטרף ל\"חיבת ציון\" ונשבע בביכ\"ס להקדיש את שארית הונו לארץ ישראל. עלה לארץ-1885 והיה ממיסדי נס ציונה ויסוד המעלה. הצטיין בגבורתו ואומץ לבו. ממיסדי ארגון \"השומר\".","bk":[["דאס יודענטהום",""]]},{"i":15598,"n":"הלפרין ישראל","bt":"1910","dt":"ה'תשלא 1971","bk":[["תקנות מדינת מעהרין",""]]},{"i":15599,"n":"הלפרין מאיר","bt":"1850","dt":"ה'תרפג 1923","bk":[["הנוטריקון, הסימנים והכנוים",""]]},{"i":15600,"n":"הלפרין, אברהם אבלי מזולקווא","f":"מרדכי ר ליבשס-ליבושס","k":"נכד הט\"ז","dt":"תעה - ב תמוז","dp":"זולקווא","b":"חתן ר יצחק בן שמואל זנויל מזולקווא. רב בברעסטיצקא, זולקווא-תנט-תצג. הסכים על \"בית לחם יהודה\" תצג, \"ברכת יעקב\" תקמו, \"טעמי מסורה\", ועוד. גיסם של ר אלכסנדר סנדר בעל \"תבואות שור\", ר יצחק הכהן מאוסטרהא. חתנו - ר אביגדור מירושלים (בן ר דוד מדובנא - נכד הט\"ז). מחותן עם ר חיים יהודה איטינגא מלבוב."},{"i":15601,"n":"הלפרין, אברהם אשכנזי מלבוב","f":"משה","k":"בעל אהבת ציון","bt":"שלח","dt":"תט - יט טבת","dp":"לבוב","b":"רב בלבוב (ולפי איתן האזרחי רב בקרוטושין). חתן דודו ר שמואל יהודה קצנלבויגן. דודו גם - המהרש\"א. בניו - ר אליעזר ליפמן-חתן המהר\"ם מלובלין, ר בן ציון (על שמו חיבר האבא - \"אהבת ציון\")."},{"i":15602,"n":"הלפרין, אברהם אשר מאליק ונארול","f":"ישראל איסרל מבריסק","b":"נכד ר אברהם אבא מארי מנוברדוק. חתן ר מאיר הורביץ. רב באליק-תקיז, נארול. בנו - ר הירץ מנווהרדוק. חתניו - ר אברהם הורביץ, ר יצחק שמשון מייזלש. אחיו - ר אברהם שמואל ממוהילוב וטשוואס."},{"i":15603,"n":"הלפרין, אברהם זרח אריה יהודה","f":"חנינא יוסף","bt":"תץ","dt":"תקסח - טז טבת","b":"רבה של ברזאן על מקום אביו."},{"i":15604,"n":"הלפרין, אברהם זרח אריה יהודה","f":"משלם שרגא פיבש","k":"אדמור מברזאן-אמת יהו","bt":"תרח-יא","bp":"ברזאן","dt":"תרפט - י אד\"א","dp":"למברג - ברזן","b":"נכד-אבי אמו ר אשר ישעיה מרופשיץ. בנו של האדמור מברזאן. רב בברזאן(=ברעזן), פרג-במלחה\"ע ה-I, עבר ללמברג. חתן ר יואל מושקוביץ משאץ. חיבר \"אמת יהודא\", \"אמרי יהודה\" ניו יורק תשנט. בניו: ר משלם פיבש מזאביע, ר אהרן מברעזן, ר מתתיה חיים מדאבשיטץ.","bk":[["אמרי יהודה - על התורה",""]]},{"i":15605,"n":"הלפרין, אברהם מאפטא","f":"בנימין וולף פרנס","b":"נינו של מהר\"ם מלובלין. רב באפטא. חתם-תנח בפנקס קהלת אפטא."},{"i":15606,"n":"הלפרין, אברהם מדולינא","b":"רב בדולינא-תריג."},{"i":15607,"n":"הלפרין, אברהם מהורדנא","f":"יום טוב ליפמן-קדושת","b":"בנו - ר חיים שיינזון מהורדנא."},{"i":15608,"n":"הלפרין, אברהם מלובלין","f":"אליעזר ליפמן מטיקטין","k":"ר אברהם ר ליפמנש","dp":"תס\"ה כז כסלו","b":"חתן המהר\"ם מלובלין (הראשון). פרנס ועד ארבע ארצות. רב בלובלין, ואולי אב\"ד פוזנא. אולי הוא נכדו של המהרש\"ל (אבי אמו). (מכונה בר\"ת - ר\"א ר\"ל - ר אברהם ר ליפמן). הסכים על \"בית יעקב\"-תנג. בניו: ר משה, ר צבי, ר מאיר מאפטא ולובלין, ר אברהם מאפטא, ר פנחס מלובלין. חתנו - ר חיים בן שמואל מלובלין."},{"i":15609,"n":"הלפרין, אברהם מפומורן","f":"אלחנן","bt":"תפ","dt":"תקן","b":"רבה של פמורן על מקום אביו. חתן ר ארי הליבש מדובענקי."},{"i":15610,"n":"הלפרין, אברהם מקאוולי ודובנא","b":"מצאצאי ר אלחנן בעל התוספות. חתן ר יחיאל מיכל אפשטין-חתן בעל הלבוש. רב בדובנא-תך ור נחמן רפפורט על מקומו אחריו, קאוולי-תכב. בנו - ר ישראל (11892)."},{"i":15611,"n":"הלפרין, אברהם מרדכי מזולקווא","f":"ישראל חריף מזסלב","bt":"תנה","dt":"תקמא -ז-יז תמוז","dp":"ברודי","b":"חתן הגביר ר יעקבקי מברוד, וגיסו של ר יחזקאל לנדא בעל נודע ביהודה. רב בווראניק-תעה, זולקווא-תקכג, עבר לברודי. מתורתו ב\"ברכת אברהם - זולקווא תקי. הסכים על \"שם יעקב\" לגיסו ר יעקב הלוי מזלוטוב, \"עטרת צבי\", \"נטיעה של שמחה\", \"חסדי אבות\", ועוד. אחיו: ר יצחק מטרטקוב, ר דוד מזסלב, ר יעקב מסוקהאל. בנו - ר ישראל מזסלב. חתנו - ר יוסף בן יהודה ליב מפינטשוב. גיסו(-בעל אחותו) - ר דוד בן פתחיה בן דוד לידא."},{"i":15612,"n":"הלפרין, אברהם צבי מוילנא","f":"גרשון","k":"בעל ארץ חפץ","bt":"תקפה","bp":"וילנא","dt":"תרעה","dp":"וילנא","b":"תלמיד ר ישראל סלנטר שהטיל עליו להפיץ את תורתו בין המוני העם. דרשן מחונן. ארגן את בעלי המלאכה בוילנא ב\"חברת הפועלים\", והיה מלמד אותם בשבתות \"חיי אדם\" וספרי מוסר. מספר החברים בחברה הגיע ל-500, והקימו לעצמם קלויז גדול. המשיך ויסד חברות דומות במינסק, ביאליסטוק, וגרודנה. פעל כ-70 שנה בהפצת תורה בין המוני העם. ?? לא באוצר ??"},{"i":15613,"n":"הלפרין, אברהם שבח מזזורובנא","f":"אלחנן","bt":"תקלה","dt":"תר","b":"חתן ר יצחק כץ מזורובנא. רב בזורובנא, ואחר כך לברודי."},{"i":15614,"n":"הלפרין, אברהם שלום שמשון","f":"יעקב יוסף שלמה מואסל","b":"נכד האדמור ר שלום הלפרין מואסלוי, ומצאצאי ר ישראל מרוזין. חתן ר יהושע השל ברים ראש ישיבת רוזין. רב בבני ברק, עמנואל."},{"i":15615,"n":"הלפרין, אברהם שלמה מהמבורג","dt":"תקכב - ג אדר","b":"רב בהמבורג"},{"i":15616,"n":"הלפרין, אברהם שלמה מרוהטין","f":"אברהם זרח אריה","bt":"תקכה","dt":"תקצה","b":"לדעת עוד יוסף חי - היה בנו של ר טוביה יחיאל מיכל. רבה של רוהטין, רב בהמבורג. חתן ר יעקב מבורשטין."},{"i":15617,"n":"הלפרין, אהרן מברזאן","f":"אברהם זרח אריה מברעז","bt":"תרם","dt":"תרפה - יד אדר","b":"חתן דודו ר מאיר מושקוביץ משאץ-לונדון."},{"i":15618,"n":"הלפרין, אהרן מטרמבובלה","f":"נתן נטע","k":"בעל שם אהרן","bt":"תס","dt":"תקל","b":"חתן הנגיד רמ\"מ מנרול. ישב בטרמבובלה ובגלל שהיה חשוך בנים בנה מכספו בית מדרש עם ספריה גדולה. חיבר \"שם אהרן\" זאלקוא תקטו, \"מחנה ארון\" אלקסניץ תקכח."},{"i":15619,"n":"הלפרין, איזיק"},{"i":15620,"n":"הלפרין, איסר חריף מלידא","k":"נכד \"סדר הדורות\"","b":"רב בלידא"},{"i":15621,"n":"הלפרין, אלחנן (משה) מזלוטשוב","f":"טוביה יחיאל","bt":"תנה","dt":"תקי","b":"רב בירמליניץ, זלוטשוב, פמורן, שריגארד. חתן ר נתן נטע מפולנאה, ובזיוו\"ש חתן הפרנס ר נתן מזולקיב אב\"ד יריטשוב. חתנו ר שמאי מאוסטרהא."},{"i":15622,"n":"הלפרין, אלחנן מפרימישלן","f":"אברהם זרח אריה יהודה","bt":"תקי","dt":"תקצג","b":"חתן ר יעקב הלפרין אב\"ד טרמבובלה. רבה של פרימישלן, נתקבל לרבנות אמשטרדם ביום פטירתו."},{"i":15623,"n":"הלפרין, אלחנן משקולישוק","dt":"תרצו - כב ניסן","b":"רב בטשוקלישוק"},{"i":15624,"n":"הלפרין, אליהו גרשון מוילנא","f":"אברהם צבי מוילנא","bt":"תרכד","bp":"וילנא","dt":"תשא","b":"תלמיד ישיבת וולוזין. רב בקאנא-ליד וילנא, וליסקובה-פלך גרודנא, עבר לוילנא ועזר לאביו בהנהלת חברת \"פועלי צדק\", דרשן ור\"מ בישיבת הקצבים \"זובחי צדק\", וכשהתאחדה עם ישיבת מייליס כיהן כר\"מ בישיבה המאוחדת. מקורב לתנועה הציונית. מגיד ודרשן בוילנא על מקום ר מנחם קרקובסקי."},{"i":15625,"n":"הלפרין, אליהו דב מוארשא","f":"ישראל דוד","k":"בעל המהפכה בשמים","bt":"1860","bp":"וילקומיר","b":"התגורר בוארשא. חיבר גם \"נשמת חיים\" - הספד על ר חיים סולוביציק, ועוד."},{"i":15626,"n":"הלפרין, אליהו מוילנא","f":"יואל מוילקוביסק","k":"אליהו זלמנ'ס","dt":"תרכה - יט אייר","dp":"וילנא","b":"חתן ר זלמן גלאבוס, ובזיוו\"ש חתן המלבי\"ם. גביר מחכמי וילנא. מחדושיו ב\"ארצות החיים\" למלבי\"ם. הגהות ממנו בספר חותנו \"התורה והמצוה\"."},{"i":15627,"n":"הלפרין, אליהו נח מאורלה","f":"יעקב ישראל הלפרן","bt":"תרמו","dt":"תשג - ה אד\"א","b":"רב בלבידוב, מלניק, אורלה(=אורלי-פאדליאסקי)-תרפא. הסכים על חקר שמואל לר שמואל ליאצקי מאורלי יחד עם חברו של מרדכי שמעון סלוצקי."},{"i":15628,"n":"הלפרין, אליעזר","f":"דוב בער הלפרן","k":"בעל דמשק אליעזר"},{"i":15629,"n":"הלפרין, אליעזר לוי משערשוב","k":"בעל ביאורי מהרא\"ל","b":"רב בשארשוב. חתנו - ר שאול יחזקאל שיינפינקל מקרלין."},{"i":15630,"n":"הלפרין, אליעזר ליזר חריף ממזרי","f":"מרדכי מירוסלב","k":"בעל שיח הסעודה","dt":"תסא - כ תשרי","b":"תלמיד מחותנו ר שאול קצנלבויגן מפינטשוב. חבר של ה\"סמיכת חכמים\". רב במזריטש, טומשוב, פיורדא-תס. חתן ר הירש בוסקר מסטנוב. חיבר \"שיח הסעודה\"."},{"i":15631,"n":"הלפרין, אליעזר ליפא ממזיבוז","f":"ישראל חריף","b":"רב במזיבוז-תק\"כ"},{"i":15632,"n":"הלפרין, אליעזר ליפמן","b":"רב מפורסם. בניו ר אברהם מלובלין, ור יעקב."},{"i":15633,"n":"הלפרין, אליעזר ליפמן","f":"אברהם מלמברג","b":"חתן ר נתן נטע כהנא מאוסטרהא. בניו - ר ישראל אב\"ד קרוטושין, ר יצחק איזיק אב\"ד טיקטין, ר משה יהודה זלקי - דרשן בפוזנא, ועל מקומו בנו ר אברהם."},{"i":15634,"n":"הלפרין, אליעזר ליפמן","b":"חתן ר שמעון וולף אוירבך. אביו של ר זאב וולף מאליק"},{"i":15635,"n":"הלפרין, אליעזר ליפמן (זוסמן)","f":"אריה ליב כץ מלובלין","b":"נכד(-אבי אמו) מהר\"ם מלובלין. חתם בפנקס זולקוא-תסד על תקנת הקהלה."},{"i":15636,"n":"הלפרין, אליעזר ליפמן מאוסטרהא","f":"מרדכי","b":"מחכמי אוסטרהא."},{"i":15637,"n":"הלפרין, אליעזר ליפמן מזברז'","f":"אברהם מרדכי","b":"רבה של זברז'-תקנא, אב\"ד טרמבובלה."},{"i":15638,"n":"הלפרין, אליעזר ליפמן מחעלמא","f":"ישראל מקרוטושין","b":"רב בחעלמא-תן, חתן ר ישראל איסרל מפינסק. אחיו של ר שמואל הילמן ממיץ."},{"i":15639,"n":"הלפרין, אליעזר ליפמן מטיקטין","f":"משה מלבוב -אהבת ציון","k":"לייזר חריף פיחאויטשר","b":"רב בטיקטין-תיב. חתן המהרש\"ל, ובזיוו\"ש חתן ר נפתלי הירש שור. בניו: ר כתריאל - אבי ר שלמה מלברטוב, ר יעקב מלובלין, ר יצחק איזיק על מקום אביו בטיקטין, ר אברהם, ר אליעזר ליפמן מטיקטין."},{"i":15640,"n":"הלפרין, אליעזר ליפמן מטרניגרד","f":"יצחק איזיק מטיקטין","b":"רב בטרניגרד-תפו. חתן ר יעקב שור מלוצק ובריסק. מובא בספר \"לחם הפנים\"."},{"i":15641,"n":"הלפרין, אליעזר מפיעסק","b":"מצאצאי ר יחיאל בעל סדר הדורות. רב בפיעסק. נפטר צעיר."},{"i":15642,"n":"הלפרין, אלתר שלמה יצחק","f":"זאב הלוי מסטרי","bp":"דיסבורג","dt":"תשסא","b":"עבר ללונדון. חתן ר משה שניידר ומילא את מקומו כראש ישיבת תורת אמת."},{"i":15643,"n":"הלפרין, אפרים זלמן מארה\"ב","f":"אלחנן דב","k":"בעל שומר אמונים","bt":"תרלב","bp":"[פרימישלן]","dt":"תשכא","dp":"ירושלים","b":"היגר לארה\"ב-תרסו, רב בדנוור, עלה לירושלים-תרצח. חיבר \"שומר אמונים\" ניו יורק תשיג, צואה - \"וזאת אשר צויתי\" ירושלים תשט."},{"i":15644,"n":"הלפרין, אריה ליב חריף מאפטא","k":"בעל חדושי מהר\"א","b":"תלמיד המגיד ממזריטש. מתלמידיו \"היהודי הקדוש\" מפשיסחא, ור ישעיה מפשדבורז. רב בפשדבורז-תק\"ל,אפטא,סוכטשוב"},{"i":15645,"n":"הלפרין, אריה ליב כץ מלובלין","f":"אברהם בן משה","b":"חתן המהר\"ם מלובלין?. בנו - ר אליעזר ליפמן מלובלין וזולקוא."},{"i":15646,"n":"הלפרין, אריה ליבוש מפמורן","b":"רבה של פמורן-תר\"ט."},{"i":15647,"n":"הלפרין, אשר ישעיה מדמבניק","f":"מתתיהו חיים","bt":"תרנט","dt":"תשנה","b":"חתן דודו ר יעקב פ\"ת אב\"ד פודגורזע. רב בסאלא, ובדמבניק-קראקא - תרעט. ניצל מהשואה וברח לבוכרה. אחר כך רב בניו יורק."},{"i":15648,"n":"הלפרין, בנימין וולף פרנס מלובל","f":"אברהם - ר\"א ר\"ל מלוב","b":"רב בלובלין-תן. נכד(-אבי אמו) המהר\"ם מלובלין (הראשון). בניו - ר מאיר מחעלמא, ר אברהם מאפטא, ר פנחס מלובלין, ועוד. פרנס ועד ארבע ארצות. י\"א שהיה חתן הט\"ז. הסכים על \"בית יעקב\" לר שמואל מצוזמיר - תנג."},{"i":15649,"n":"הלפרין, בצלאל","f":"יום טוב ליפמן מקאפול"},{"i":15650,"n":"הלפרין, ברוך מסקאהל","f":"צבי הירש","k":"בעל מצות השם","dt":"תקנא","b":"רב בסקול-תקם. חיבר \"מצות השם\" למברג תקנג."},{"i":15651,"n":"הלפרין, ברוך מסקליבקה","f":"ישראל אריה מפרעמישלן","b":"אדמו\"ר בסקליבקה"},{"i":15652,"n":"הלפרין, גדליה מארה\"ב","f":"יחיאל מסלונים","bp":"קאזלושטשינא-ליד סלונים","b":"חתן ר ליב וינשטין מרפעניץ-ליד דרעטשין. מ\"מ בסלונים, היגר לארה\"ב וכיהן כרב בטולדו-אוהיו, פורט-וורט-טקסס,סיאטל-וושינגטון-תרסו. נסמך מאת: ר יוסף רוזין בעל \"פורת יוסף\", ר יוסף שלופר."},{"i":15653,"n":"הלפרין, דב בר מניו יורק","f":"מרדכי","bt":"תרכ","bp":"נעשויז","b":"רב בניו יורק-תרמז."},{"i":15654,"n":"הלפרין, דב בריש מלובלין","k":"בעל דבש תמרים","dt":"תקפד - ז טבת","b":"ראב\"ד ומ\"מ בלובלין. ממתנגדי החוזה מלובלין."},{"i":15655,"n":"הלפרין, דב בריש מסטניסלב","dp":"צפת","b":"חתן ר משולם שרגא הלפרין האדמור מברזאן. עלה לצפת."},{"i":15656,"n":"הלפרין, דב בריש מפרימישלן","f":"אלחנן","bt":"תקם","dt":"תרא","b":"רב בפרימישלן בחיי אביו. בנו ר יעקב שלמה על כסאו אחריו."},{"i":15657,"n":"הלפרין, דב בריש מרוהטין","f":"אברהם שלמה","bt":"תקמה","dt":"תרא","b":"חתן ר מרדכי זאב מלמברג, ובזיוו\"ש חתן ר יהודה יודל ברודא בעל \"זכרון יהודה\". אב\"ד רוהטין, וברזאן."},{"i":15658,"n":"הלפרין, דב יעקב מבאלחוב","dt":"תקעא - כח כסלו","b":"רב בבאלחוב"},{"i":15659,"n":"הלפרין, דוד","k":"חתן ר' ישראל מרוזין","b":"רב-שנת תר\"כ"},{"i":15660,"n":"הלפרין, דוד אשכנזי מצפת","f":"יוסף","b":"מחכמי צפת בשנת שפב חתם על ההזמנה לר ישכר בר מאיילינבורג. יתכן שהוא ר דוד שחתם במכתב רבני ירושלים לפדובה, ויש ר דוד שחתם על כתב שליחות ר נחום יפה בשנת תיז. ויתכן שכלם זהים."},{"i":15661,"n":"הלפרין, דוד זאב מפמורן","f":"הלר, דוד זאב מפמורן","b":"רב בפמורן ובסקול."},{"i":15662,"n":"הלפרין, דוד יחיאל מיכל מבורשטש","bt":"תקץ","dt":"תרסז","b":"רב בפמורן, אב\"ד בורשטשוב-תריב במשך כיובל שנים."},{"i":15663,"n":"הלפרין, דוד יעקב מבוליחוב","f":"יצחק איזיק","b":"רבה של בוליחוב-תקסו. בנו על כסאו אחריו."},{"i":15664,"n":"הלפרין, דוד מברדיטשוב","f":"יעקב יוסף","dt":"תרמד","b":"חתן ר ישראל מרוזין. בנו - ר שלום יוסף מואסלי."},{"i":15665,"n":"הלפרין, דוד מדובשיץ","f":"מתתיהו חיים","bt":"תרנז","bp":"פודגורזע","dt":"תשה","b":"אב\"ד דובשיץ-תרצג על מקום אביו. חתן ר שמואל ענגיל. נספה בשואה."},{"i":15666,"n":"הלפרין, דוד מזסלב ואוסטרהא","f":"ישראל חריף מזסלב","k":"בעל דרכי ציון -צוואה","r":"אב\"ד אוסטראה וזסלאב","dt":"תקכה - טז תמוז","dp":"אוסטרהא","b":"חתן ר חיים בן ר בנימין בעל \"עיר בנימין\". רב באוסטראה-תצז על מקום אביו (ביניהם היה ר משה בן אליהו מפינסק) ורב הקלויז היה ר אברהם משלם זלמן בן החכם צבי. תלמיד הבעשט. היה מחלוקת בינו לר אברהם משלם אודות הרבנות ועזב בפקודת הבעשט ועבר לזסלב, רב בזסלב - ושם בקרו הבעשט. בצוואתו \"דרכי ציון\" הוריש הרבה לר צבי בן הבעשט ועוד מגדולי החסידות (הרב מפולנאה, המגיד ממזריטש, המגיד מזלוטשוב, ר פנחס מקורץ, ר וולף קיציס ממזבוז, ועוד). בניו ר ישכר בעריש, ר יצחק איזיק-נזכר בשבחי הבעשט, ר ישראל. חתניו ר נפתלי הרץ בן מרדכי הורביץ מזולקוא אחיו של ר מרדכי הלפרין מזסלב וקרמניץ, ור מנחם מנדל הלפרין-זקנו של האדמור ר מנחם מנדל מקוצק. צוואתו נדפסה עם צוואת בנו ר ישכר בריש בשם \"דרכי ציון\".","bk":[["דרכי ציון - צוואה",""]]},{"i":15667,"n":"הלפרין, דוד מליזנסק","f":"שלמה יצחק","bt":"תקי","dt":"תקעה","b":"רבה של ליזנסק. מכונה גם בשם וינגרטן."},{"i":15668,"n":"הלפרין, דוד מקאשוי","dt":"תשד","b":"רב בקאשוי"},{"i":15669,"n":"הלפרין, זאב וולף מאליק","f":"אליעזר ליפמן","b":"נכד ר שמעון וולף אוירבך מלובלין ופרג. רב באליק."},{"i":15670,"n":"הלפרין, זאב וולף מזווניץ","f":"יעקב חריף","k":"בעל ספר זכרון על שוע","bt":"תפג","dt":"תקם","b":"רבה של זוואניץ-תק על מקום אביו. חתן הנגיד ר אליעזר מקמניץ. נפטר ללא בנים. כתב ספר זכרון על שו\"ע - לא נדפס."},{"i":15671,"n":"הלפרין, זאב וולף מסוכסטוב","f":"טוביה יחיאל מיכל מבל","bt":"תס","dt":"תקכה","b":"רבה של סוכסטוב. חתן הפרנס רצ\"ה מיזלוביץ."},{"i":15672,"n":"הלפרין, זאב מליטא ירושלים ומרו","bt":"תרי","bp":"שרבשוב","dt":"תרצד - טו באב","dp":"ירושלים","b":"עלה לירושלים, הגיע ללונדון ומשם למרוקו - שם הקים תלמודי תורה וישיבות בסגנון ליטאי - והשפיע רבות על עולם התורה במרוקו, והיה מחלוקת עם חוגי \"אליאנס\". חזר לירושלים"},{"i":15673,"n":"הלפרין, זיידא מברעזאן","dt":"תשג","b":"רב בברעזאן"},{"i":15674,"n":"הלפרין, זלמן מזסלב","f":"ישראל מזסלב ואוסטרהא","b":"חתן הגאון דק\"ק פינסק. רב בזסלב על מקום אביו שעבר לאוסטרהא."},{"i":15675,"n":"הלפרין, חיים דב מוואסלוי","f":"שלום מוואסלוי","k":"אדמור מוואסלוי","bt":"תרלו","bp":"בוהוש","dt":"תשיז - כב סיון","b":"נינו של ר ישראל מרוזין. חתן ר דוד מסאווראן. אדמור בוואסלוי עבר לבוקרשט. ניצל מהשואה, ואחריה עליה לארץ-תשי, והתישב בחיפה."},{"i":15676,"n":"הלפרין, חיים יונה מרישא","f":"אלכסנדר שמואל מלבוב","bt":"תרך","dt":"תרפז","b":"חתן ר נחום ראובן פלסקר מרישא. ראב\"ד רישא-תרפז. נסמך מאת: ר יוסף שאול נתנזון, ר יצחק שמלקיש, ר יואל אשכנזי מזלוטשוב. בניו: ר נחום ראובן, ר ישכר בעריש. חתניו - ר אלעזר ויסבלום, ר אריה ליב טיטלבוים בן ר יחיאל מקלבאשוב."},{"i":15677,"n":"הלפרין, חיים יעקב מרישא","f":"יוסף","bt":"תרמח","dt":"תשכד","b":"חתן ר אברהם אהרן דלמן. עבר לאמשטרדם ולוינה, ועסק שם במסחר בספרים עתיקים, נדד עם שותפו בצפון אפריקה ספרד ואיטליה שם רכשו ספרים וכתבי יד. רכש את אדמות זכרון מאיר בבני ברק. עלה לארץ-תרצג."},{"i":15678,"n":"הלפרין, חיים יצחק איזיק מבוטוש","f":"מנחם נחום מקונסטנטין","bt":"תקמג","dt":"תרכד-ח -טו תשרי","b":"נכד ר חיים צאנזר מברוד. תלמיד ר ברוך ממזבוז, ור יוסף מיאמפולי (זלוטשוב). רב בבוטושאן-תקעח כ-40 שנה. עלה לצפת-תריח."},{"i":15679,"n":"הלפרין, חיים מביאליסטוק","f":"רפאל יו\"ט ליפמן","b":"רב בביאליסטוק"},{"i":15680,"n":"הלפרין, חיים מברזאן","f":"משלם שרגא פיבוש","bt":"תרס","dt":"תשב","b":"רבה של ברזאן בחיי אביו האדמור מברזאן. חתן ר נחום רוקח ממגרוב. נספה בשואה."},{"i":15681,"n":"הלפרין, חיים מפאקשן","b":"רב בבוקרשט-תקעה. תלמיד החת\"ס שהשיב לו בספרו."},{"i":15682,"n":"הלפרין, חיים משערשוב","b":"חתן ר יצחק מסקידל בעל \"בית יצחק\" (איזה?). גביר מחכמי שארשוב."},{"i":15683,"n":"הלפרין, חיים נפתלי הרץ מביאליס","f":"יום טוב רפאל-עונג יו","bt":"תרא","dt":"תרעט - ו אייר","b":"רב בביאליסטוק על מקום אביו. פרסם מאמרים ב\"הועד\" - פיעטרקוב תרעד, חיבר הקדמה לספר אביו. חתנו: ר אריה ליב שפירא-בן ר רפאל מוולוזין."},{"i":15684,"n":"הלפרין, חנוך הניך מגלינא","f":"יחזקאל הלוי","k":"בעל חורבן גליניאני","bt":"תרנה","bp":"גלינא","dt":"תשכה","dp":"ניו יורק","b":"אחיו של מרדכי בן יחזקאל הלפרין בעל \"ספר המעשיות\". עלה לארץ-תרסו, חזר לגליציה. והיגר לארה\"ב-תרסט. חיבר \"חורבן גליניאני\" ניו יורק תשו. ?? לא באוצר ??"},{"i":15685,"n":"הלפרין, חנינא יוסף מברזאן","f":"אברהם זרח אריה יהודה","bt":"תקכ","dt":"תקף","dp":"לברטוב","b":"רבה של ברזאן על מקום אביו. חתן ר יחזקאל טרכטנברג מברודי."},{"i":15686,"n":"הלפרין, חנינא יוסף מפמורן","f":"טוביה יחיאל מיכל","bt":"תסב","dt":"תקכד","b":"אב\"ד פמורן-תפד, אב\"ד ברזאן על מקום אביו. חתן ר נתן נטע אב\"ד אלעסק."},{"i":15687,"n":"הלפרין, חנניה יוסף מברזן","b":"רב בברעזאן-ת\"ע"},{"i":15688,"n":"הלפרין, חנניה יוסף מירושלים","f":"צבי הירש","bt":"תרסב","bp":"ירושלים","dt":"תשמח","dp":"ירושלים","b":"חתן ר מנחם מנדל שטרנברג, ובזיוו\"ש חתן ר שמואל אלעזר ווארטמן. רב בירושלים."},{"i":15689,"n":"הלפרין, חנניה יוסף מירושלים","f":"יחיאל מיכל מהליטש","b":"חתן ר יהודה ליב אורנשטין מפאלטישן וירושלים. עלה לירושלים-תרלד עם חותנו."},{"i":15690,"n":"הלפרין, חנניה מסטוקלישוק","f":"ישעיהו זליג מסטוקליש","b":"רב בסטוקלישוק על מקום אביו."},{"i":15691,"n":"הלפרין, טוביה יחיאל מיכל","f":"ליבש הלפרן"},{"i":15692,"n":"הלפרין, טוביה יחיאל מיכל מססוב","f":"אברהם זרח אריה יהודה","bt":"תרל","dt":"תרף - ג תשרי","dp":"למברג","b":"חתן ר שלמה מייער מסאסוב, ועבר לשם והתפרנס ממסחר."},{"i":15693,"n":"הלפרין, טוביה יחיאל מסווירז","f":"אברהם זרח אריה יהודה","bt":"תקטו","dt":"תקעט","b":"חתן ר שלמה יצחק הלפרין מטרנופול וחתן ר אברהם אבלי. רבה של סווירז, רב בברזאן על מקום אביו. בנו - ר משה אלחנן."},{"i":15694,"n":"הלפרין, יהודה ליבוש מברזן","f":"משלם שרגא פיבוש","b":"אדמו\"ר בברעזאן-תר\"מ"},{"i":15695,"n":"הלפרין, יהודה ליביש מסוקוליבקה","f":"אברהם שבח","k":"בעל קול יהודה","bt":"תקעד","bp":"ברודי","dt":"תרכא","dp":"חורוסטקוב","b":"חתן ר יהושע השל אפרתי מחוליוב. רב בסוקוליבקה-תרל והקים שם ישיבה, פמורן, חורוסטקוב-תריד. חיבר שות \"קול יהודה\" למברג תרנה."},{"i":15696,"n":"הלפרין, יואל - בעל שם מזמושץ","f":"אורי","k":"בעל שם מזמושץ","b":"מכונה \"יואל בעל שם השני\". חתן ר שמשון הכהן. מקובל בזאמושט-תק. חיבר \"נפלאות אלוקים\" זולקוא תקי. נזכר אצל ר זלמן מימון. הסכים על \"תולדות אדם\" - (והיו שטענו שהוא המחבר \"תולדות אדם\")."},{"i":15697,"n":"הלפרין, יואל הגדול מאוסטרהא","f":"יצחק איזיק מטיקטין","k":"בעל מפעלות אלקים?","dt":"תעד -ד תשרי","dp":"אוסטרהא","b":"מראשי ועד ארבע ארצות. רב בברודי, לוצק(=לויצקי)-תמט ובנו ר מרדכי על מקומו אחריו, פינסק-תנא, אוסטרהא-תנג על מקום ה\"סמיכת חכמים\", ירוסלב-תנא, לבוב-תעג. הסכים על \"כבוד חכמים\", \"קרנים\". חתן ר יהושע חזקיה פרנקל תאומים מפרמישלא ובזיוו\"ש חתן ר יעקב יוסף מניקלשבורג. בנו: ר מרדכי מאוסטרהא, חתניו: ר בצלאל הכהן מאוסטרהא בן מוהר\"נ כץ - על מקומו אחריו באוסטרהא, ר נתן מפולנאה, מנחם מנדל מרגליות מקרוטשין. (ראה גם יואל בעל שם הראשון)"},{"i":15698,"n":"הלפרין, יואל מזילין וברעזן","f":"אברהם זרח אריה יהודה","k":"אדמור מברעזן-נ\"י,אדמור מברעזן","bt":"תרמז","bp":"ברזאן","dt":"תשד - כא תשרי","b":"חתן ר אליהו הורביץ מזילין (בנו של הצדיק הפלאי). התישב ברישא, היגר לארה\"ב-תרץ. אדמור מזילין בניו יורק-תרץ. (אולי נספה בשואה)."},{"i":15699,"n":"הלפרין, יואל מיאסלו","f":"מתתיהו חיים","k":"בעל תקנות עגונות","bt":"תרסד","bp":"קראקא","b":"נסמך מאת ר שמואל אנגל מרדומישל. חתן ר אלימלך רובין מיאסלו. רב ביאסלו לצד חותנו. ניצל מהשואה בה איבד את משפחתו והגיע לבוכרה. רב מחנה ברגן בלזן-תשה ופעל רבות להתרת עגונות ונישואין. היגר לארה\"ב-תשח, רב בברונזוויל."},{"i":15700,"n":"הלפרין, יואל מלעשנוב","f":"ישראל מזסלב ואוסטרהא","b":"רב בלעשנוב-תקכ. חתנו - ר פנחס הורביץ בעל ההפלאה."},{"i":15701,"n":"הלפרין, יום טוב ליפמן הכהן מיר","f":"יהודה זאב","k":"בעל מלבושי יום טוב","dt":"תרנג - ז טבת","b":"נכד ר יו\"ט ליפמן בעל \"קדושת יו\"ט\". רב בשומיאץ, חסלביץ על מקום ר משה נחמיה כהנוב שעלה לירושלים, מיר. פרסם מאמרים ב\"מכילתא דרבנן\" - אודסה תרמו."},{"i":15702,"n":"הלפרין, יום טוב ליפמן מקאפוליא","f":"אברהם אשר מאליק","k":"בעל קדושת יום טוב","r":"אב\"ד קאפוליא","bt":"תקטז","dt":"תקנה","b":"חתן ר בצלאל דרשן. ממקורבי הגר\"א, חברו של ר חיים מוולוזין. רב בקאפוליא(=קופל)-תקמה, סולי. הערותיו לתלמוד נדפסו בש\"ס וילנא בשם \"מלאכת יו\"ט\". בנו - ר אברהם, ונכדו - ר חיים שיינזון מהורדנא.","bk":[["קדושת יום טוב – זבחים מנחות ושו\"ת",""]]},{"i":15703,"n":"הלפרין, יונה מזולקוא","f":"משה","b":"מחכמי זולקוא, חתם-שפו על תקנ"},{"i":15704,"n":"הלפרין, יוסף","f":"אלחנן","k":"בעל אם הילד","b":"מדקדק-שנות ה-ש'. חיבר גם \"קול הקורא\" קצור מפרק שירה - קראקא שס."},{"i":15705,"n":"הלפרין, יוסף יהושע מסוינגורדקה","f":"יחיאל מיכל","bt":"תרכט","b":"חתן ר שלמה קרלינר מטולצין. רב בסווניגורודקה(=זוועניגראדקא)-תרנב. נסמך מאת: ר משה נחום ירושלמסקי, ור דוד שור מטולנא."},{"i":15706,"n":"הלפרין, יוסף יואל מסטעפין","f":"יעקב אהרן מסטעפין","dt":"תקל - י אד\"ב","dp":"סטעפני","b":"תלמיד הבעשט - שבקרו בביתו. רב בלויצק(=לויצקא), אב\"ד סטעפין, וחתנו ר אהרן שמואל הכהן בעל \"וציוה הכהן\" על מקומו אחריו והביא ממנו בספרו. חתניו גם ר דוד המגיד מסטעפין, ור צבי הירש אשכנזי מאוסטרהא וברדיטשוב. חתנו ר אהרן שמואל סיפר בשמו שפעם היה הבעשט אצלו בסטעפאן ואח\"כ חזר חותנו עם הבעשט בעגלה וביער שמעו צפצוף צפורים - הבעשט אמר שאומרים לו ששכחו דבר נחוץ בעיר וחותנו הקפיד שהדבר היה רחוק בעיניו שיודע שפת העופות - אך כשחזרו התברר שאכן כך היה הדבר). בילדותו נתפס בעלילה ע\"י הדוכס מסטעפאן בטענה שהיה מעורב בגניבת תכשיטים ונגזר דינו למיתה אם לא ימיר דתו - ובאותו הלילה נתפסו הגנבים ושוחרר - וכל זה נכתב במגילת קלף בידי ר יעקב אהרן אביו שציוה על צאצאיו לנהוג תענית ביום כב אב. ."},{"i":15707,"n":"הלפרין, יוסף ישראל מאודסה","f":"יעקב ליבש","bt":"תר","bp":"ברדיטשוב","b":"רב באודסה-תרלז על מקום זקנו ר יחיאל מיכל. חתן ר אברהם דב קדינובסקי מסמילא. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":15708,"n":"הלפרין, יוסף מאודסה","bt":"תקצג","dt":"תרפח - יט שבט","b":"רב באודיסה"},{"i":15709,"n":"הלפרין, יוסף מאיר ממונקטש","f":"ישראל יעקב ממונקטש","dt":"תשד","b":"תלמיד ר חיים אלעזר ממונקטש. רב במונקטש על מקום אביו. נספה בשואה."},{"i":15710,"n":"הלפרין, יוסף מזשאבנה","dt":"תשג","b":"רב בזשאבנע"},{"i":15711,"n":"הלפרין, יוסף מטיסמניץ","f":"שמואל","bt":"תריב","bp":"בורשטשוב","dt":"תרנד","b":"חתן ר יואל דינין. תלמיד חכם שהתפרנס באמצעות קרובו הברון הירש. ברח מרוסיה לצורטקוב. רב באחוזת דודתו ליד פריס, חזר לגליציה. ארונו הובא לקבורה בארץ-תשח."},{"i":15712,"n":"הלפרין, יוסף ממנצסטר","f":"שמואל מאמשטרדם","bt":"תרסה","dt":"תשנט","b":"חסיד צורטקוב. סוחר בספרים עתיקים. חתן ר אליעזר אדלר מגייסהד, עבר למנצסטר-תרצד. שו\"ב קהילת מחז\"ה. ההדיר ספרים ופעיל בעניני ציבור."},{"i":15713,"n":"הלפרין, יוסף מפדובה","dt":"שפב - ה ניסן","dp":"פדובה","b":"רב בפדובה."},{"i":15714,"n":"הלפרין, יוסף משה ממזריטש","f":"אליעזר","b":"תלמיד הבעשט. מגיד מישרים במזריטש. מחותן עם ר אריה יהודה ליב מוואלטשיסק. עלה לארץ-תקנה."},{"i":15715,"n":"הלפרין, יחזקאל מסיגט","f":"ליביש","k":"אדמור מדעש בסיגט","dt":"תשד","b":"נכד ר יוסף ליב כהנא מסיגט-חתן ר יחזקאל פנט מקרלסבורג. תלמיד ר יחזקאל מדעש. אדמור מדעש בסיגט. נספה בשואה."},{"i":15716,"n":"הלפרין, יחיאל","f":"איסר הלפרן","b":"רב בקאזלוניצא. בנו ר גדליה הלפרין."},{"i":15717,"n":"הלפרין, יחיאל מיכל מבורשטטוב","f":"שמואל אריה","bt":"תריז","bp":"פולין","dt":"תרסט","dp":"טבריה","b":"עלה לטבריה בשנת תרם והיה מחכמי טבריה, בשנת תרנו אב\"ד טבריה, היה רב הקהלה האשכנזית בטבריה."},{"i":15718,"n":"הלפרין, יחיאל מיכל מבורשטשוב","f":"משה הלפרן","b":"רב בבורשטשוב-שנת תר\"נ. חתן המלבי\"ם"},{"i":15719,"n":"הלפרין, יחיאל מיכל מברעזן","f":"אברהם זרחיה אריה ליב","dt":"תקעט - כ שבט","b":"רב בברעזאן"},{"i":15720,"n":"הלפרין, יחיאל מיכל מברעזן","f":"חנניה יוסף הלפרן","dt":"תקטז","b":"רב בברעזאן-סקאליט. בניו ר יעקב, ור מרדכי, וחתנו ר אריה ליב בהנובר."},{"i":15721,"n":"הלפרין, יחיאל מיכל מברעזן","f":"ישראל","bt":"תל","dt":"תק - כא אדר","dp":"ברזאן","b":"אב\"ד בסווירז על מקום אביו. רב בבלז, ואחר כך ברזאן. חתן ר אברהם אבלי מבלז."},{"i":15722,"n":"הלפרין, יחיאל מיכל מברעזן","f":"נפתלי הירץ מברזן","b":"חתן הגביר ר צבי ר ישעיה'ס-חתן ר יצחק מראדויל (שושלת זלוטשוב). בנו ר חנניה יוסף-חתן ר יהודה ליב אורנשטין מפאלטישן."},{"i":15723,"n":"הלפרין, יחיאל מיכל מטבריה","f":"שלמה יצחק הלפרן","b":"רב במראחיווי"},{"i":15724,"n":"הלפרין, יחיאל מיכל צבי הירש","f":"חנניה יוסף","k":"הו\"ל ראשון לציון","bt":"תקן","dt":"תרל","b":"חתן ר ראובן הרטנשטין. אב\"ד אודסה. הוציא לאור \"ראשון לציון\" אודסה תרכז."},{"i":15725,"n":"הלפרין, יעקב","f":"ליפמן הלפרן","dt":"שצו"},{"i":15726,"n":"הלפרין, יעקב","dt":"תה - יח אלול"},{"i":15727,"n":"הלפרין, יעקב אהרן מלויצק וסטפנ","f":"מרדכי","b":"רב בסטפאן, לויצק."},{"i":15728,"n":"הלפרין, יעקב חיים מירוסלב","f":"אברהם ר חיימש","bt":"תקסד","b":"חתן ר אברהם יצחק חזק פורטיז דוקטור (העדיפה על בת ר יונתן איבשיץ), בזיוו\"ש חתן גיסו ר יעקב יצחק הוכגלרנטר מזמושץ. תלמיד ר יונתן איבשיץ. רב בירוסלב-תץ, לובלין-תצז. עמד יחד עם אביו לימינו של ר יונתן במחלוקת ר יעקב עמדן - ואף הטילו חרם על תומכי היעבץ - היעבץ יצא כנגדם."},{"i":15729,"n":"הלפרין, יעקב ישראל","b":"רב במלניק-תר\"נ"},{"i":15730,"n":"הלפרין, יעקב מאפטא","k":"בעל קיצור אברבנל","b":"רב באפטא-שס\"ז."},{"i":15731,"n":"הלפרין, יעקב מזורווני","b":"רב בזורווני-ת\"ק"},{"i":15732,"n":"הלפרין, יעקב מטיקטין","b":"רב בטיקטין"},{"i":15733,"n":"הלפרין, יעקב מטרמבובלה","f":"מרדכי או ישכר דב ברי","bt":"תע-פ","dt":"תקלה-ן","dp":"למברג","b":"לדעת בובר אביו - ר מרדכי מסווירז בנו של ר יחיאל מיכל הלפרין מברעזן. נכד ר משה פנחס חריף. חתן ר שמעון מיזלוביץ. רבה של טרמבובלה-תקכז, רב בלבוב-תקמא. חברו של ה\"פרי מגדים\" שהביא ממנו בספרו \"פורת יוסף\" לבעל פמ\"ג. הסכים על \"מחנה ארון\", \"פרי מגדים\", \"הדרת אליהו\", ועוד. בנו ר שאול חריף אב\"ד זורובנא ואלסק."},{"i":15734,"n":"הלפרין, יעקב מלבוב","f":"אליקום","dt":"תא-ה - יח אלול","dp":"לבוב","b":"מרביץ תורה בלבוב. נזכר בשו\"ת מהר\"ם מלובלין בענין גט שסידר בעל הסמ\"ע - חתם עם ר שמשון בוכנר ור אבא הלוי ור צבי בן נתן ז\"ק."},{"i":15735,"n":"הלפרין, יעקב מלודמיר","f":"ישראל חריף מזסלב","b":"רב בלאדמיר-תקכ, סוקהאל."},{"i":15736,"n":"הלפרין, יעקב מסוקוליבקה","f":"יהודה ליב- קול יהודה","k":"בעל יעקב לחק","bt":"תר","dt":"תרעה","b":"נכד ר יהושע אפרתי בעל \"נחלת יהושע\". רבה של סוקוליבקה(=סאקאליוקע)-תרכג על מקום אביו במשך יובל שנים. חתן ר משולם פיבוש הלפרין מברזאן בעל \"שפת אמת\". חיבר \"יעקב לחק\" למברג תרסג, \"ברכת יעקב\".","bk":[["יעקב לחק",""]]},{"i":15737,"n":"הלפרין, יעקב מסקוליע","f":"מרדכי","bt":"תרך","dt":"תקץ","b":"רבה של סקוליע (ולא סקאלא) על מקום אביו, ברדיטשוב-תקעג. חתן הנגיד ר איציק שהיה חתנו של ר נתן נטע מאלעסק."},{"i":15738,"n":"הלפרין, יעקב מפדובה","f":"מרדכי מפולין או אלחנ","k":"בעל נחלת יעקב","b":"ממשפחה ממגורשי פולין שהגיעו לאיטליה. תלמיד מהר\"ם פאדובה, ר אביגדור ציוידאל מונציה. ישב אצל הגביר ר נחמיה לוצטו בונציה - ושלו הקדיש את ספרו \"נחלת יעקב\". רב בפדובה בזמן בעל \"ערוגת הבושם\" ור שמחה לוצטו. חיבר \"שושנת יעקב\" ונדפס עם \"ארחות חיים\" לר אליעזר הגדול בונציה. חיבר \"נחלת יעקב\" פדובה שפג."},{"i":15739,"n":"הלפרין, יעקב מפמורן","f":"טוביה יחיאל מיכל","k":"בעל בית יעקב","bt":"תנח","dt":"תצח","b":"מצאצאי מהרש\"ל והלבוש. רבה של פמורן (פייארין), רב בזוואניץ - פודוליה. וחכם הספרדים? מחאטין עד בנדר. קיבל הצעות רבנות מברלין וקושטא אך נפטר. חתן ר זאב וולף הכהן מלומזא. חיבר \"בית יעקב\" סטרי תר.","bk":[["בית יעקב - שו\"ת",""]]},{"i":15740,"n":"הלפרין, יעקב משה מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":15741,"n":"הלפרין, יעקב קופל מבריסק","f":"יהושע השל","dt":"תריז - ט אייר","dp":"בריסק","b":"גביר בפולין וליטא, עבר מביאליסטוק לבריסק."},{"i":15742,"n":"הלפרין, יעקב שמריל מוילנא","f":"יצחק מטראק וועוויע","bp":"וילנא","dt":"תרלד - כא תשרי","b":"גיסו של אד\"ם הכהן מוילנא. גביר מחכמי קיוב. ב\"הצפירה\" - תרמט פורסם כי תרם סכום גדול לקהלות וילנא, קיוב וירושלים ביום מלאת 50 שנה ליום חתונתו."},{"i":15743,"n":"הלפרין, יצחק איזיק","b":"רב-שנת ת\"כ"},{"i":15744,"n":"הלפרין, יצחק איזיק","f":"דוד מאוסטרהא","b":"בנו של ר דוד - רבה של אוסטרהא ותלמיד הבעשט. נזכר ב\"שבחי הבעש\"ט\"."},{"i":15745,"n":"הלפרין, יצחק איזיק מאוסטרהא","b":"רב באוסטרהא-תנ\"ג"},{"i":15746,"n":"הלפרין, יצחק איזיק מאוסטרהא","f":"מרדכי","dt":"תקכו - ז כסלו","dp":"אוסטרהא","b":"נכד ר יואל הלפרין רב הגליל. פרנס באוסטרהא, וחתם בפנקס הח\"קבנו ר זכריה וולף."},{"i":15747,"n":"הלפרין, יצחק איזיק מטיקטין","f":"אליעזר ליפמן מטיקטין","b":"רב בטיקטין על מקום אביו. חתן ר יעקב שור מבריסק בעל \"בית יעקב\", ובזיוו\"ש חתן ר מרדכי סגל מלמברג בן הט\"ז. הסכים על סידור \"שערי שמים\"-תלג. אביו של ר יואל מאוסטרהא."},{"i":15748,"n":"הלפרין, יצחק איזיק מסקאהל","f":"ישראל חריף מזסלב","b":"רבה של סקול-תקך, ואח\"כ טרטקוב-תקמו. רבו של רצ\"ה מזידיטשוב."},{"i":15749,"n":"הלפרין, יצחק אליהו מזלוזיץ","f":"יהושע מצורטקוב","b":"רבה של זלוזיץ, זבורוב-לפני תקפח."},{"i":15750,"n":"הלפרין, יצחק אריה ליבוש מלידז","f":"אלחנן","bt":"תשה","b":"חסיד צאנז. התיישב בפתח תקוה-תשלא ושימש כרב קהילת צאנז. חתן ר שמואל אלכסנדר אונסדורפר."},{"i":15751,"n":"הלפרין, יצחק מקוזלוב","b":"רבה של קוזלוב-תרטז. בנו של מוהר\"י או מוהר\"ם."},{"i":15752,"n":"הלפרין, יקותיאל יהודה מאראד","f":"ראה: הלפרין-הלפרט"},{"i":15753,"n":"הלפרין, ישכר בריש","f":"דוד מאוסטרהא","b":"בנו של ר דוד - רבה של אוסטרהא ותלמיד הבעשט. חתן ר יחיאל מהורדנא או קאוולע. צוואתו נדפסה עם צוואת אביו בשם \"דרכי ציון\"."},{"i":15754,"n":"הלפרין, ישכר דב בריש מבייטש","f":"חיים יונה מרישא","k":"אדמור מבייטש","bt":"תרמט","bp":"רישא","dt":"תשכט - ה סיון","dp":"ארה\"ב","b":"תלמיד ר נתן לוין מריישא ונסמך ממנו ומאת: ר מאיר אריק, ר דוד הורביץ מסטניסלב. רב באלפין-תרעה. חתן ר אהרן הורביץ האדמור מבייטש-תרעז חתן ה\"דברי חיים\". רב ואדמור בבייטש-תרעז על מקום חותנו. ניצל מהשואה - לאחר שאיבד את אשתו וארבע ילדים, ואחריה היה רב ברומא ועבר לארה\"ב-תשז שם שימש רב בניו יורק. הוציא לאור \"נחלת ראובן\" לזקנו ר נחום מרישא - תרפד. בזיוו\"ש חתן ר טוביה יחיאל הלפרין מסאסוב (משושלת ברזאן). חיבר \"אהל יששכר\". ההדיר \"משנה למלך\" לגיסו ר אלעזר מרישא (ליזנסק)."},{"i":15755,"n":"הלפרין, ישעיה מויטקוב","f":"יחיאל בעל סדר הדורות","dt":"תפד","b":"אב\"ד ויטיקוב, ברודי או ברודשין. חתן ר ישראל הלפרין מסווירז. בנו ר משה אב\"ד ברדיטשוב וידידו של הבעשט, בנו ר שאול וואהל ע\"ש זקנו השר."},{"i":15756,"n":"הלפרין, ישעיה מזברז","f":"אליעזר ליפמן מזולקיב","dt":"תקנח","dp":"ברודי","b":"רב בזברז על מקום אביו."},{"i":15757,"n":"הלפרין, ישעיהו זליג מסטוקלישוק","k":"בעל מוסדי ישעיהו","b":"רב בסטוקלישוק-ליטא, ובנו ר חנניה על מקומו אחריו."},{"i":15758,"n":"הלפרין, ישראל","f":"אברהם הלפרן","b":"רב-שנת ת\"פ"},{"i":15759,"n":"הלפרין, ישראל","f":"דוד מאוסטרהא","dt":"תקל - כה אלול","dp":"זסלב","b":"בנו של ר דוד-רבה של אוסטרהא ותלמיד הבעשט."},{"i":15760,"n":"הלפרין, ישראל איסר מפינסק","f":"משה מבריסק","b":"נכד המהרש\"א. רב בבריסק ומינסק. בנו ר נפתלי הרץ אב\"ד נוברדוק."},{"i":15761,"n":"הלפרין, ישראל אריה ליב מלבוב","f":"ברוך פרנקל","k":"אדמור מסקוליבקה לבוב","bp":"סוקוליבקה","dt":"תשכב - ט אייר","b":"אימץ את שם אמו - הלפרין. אדמור מסקוליבקה בלמברג, רב ואדמור בניו יורק-תרצא. חתן ר ליבוש שטיקלר מקוליקוב."},{"i":15762,"n":"הלפרין, ישראל אריה מפרמישלן","f":"צבי אריה מפרמישלאן","k":"אדמור מפרמישלן","b":"אדמו\"ר בפרעמישלן-תר\"נ"},{"i":15763,"n":"הלפרין, ישראל דוד ממאליאט","dt":"תרמג","b":"מצאצאי בעל \"סדר הדורות\". דרשן מפורסם ורב במאליאט-ליטא, ובנו ר משה על מקומו אחריו."},{"i":15764,"n":"הלפרין, ישראל חריף מזסלב ואוסט","f":"אליעזר ליפמן מטרניגר","dt":"תצא - כט טבת","dp":"זסלב או אוסטרהא","b":"אירס את בת הש\"ך ונפטרה לפני החתונה-תעא. חתן ר יצחק באב\"ד מברודי. רב בזסלב, ואוסטרהא על מקום ר אברהם כהנא מזסלב. וחזר לזסלב. בניו: ר ליפמן ממזבוז, ר דוד מזסלב ואוסטרהא, ר זלמן מזלסלב, ר אברהם מרדכי מזסלב. חתנו - ר דוד בן פתחיה בן דוד לידא. (מסופר עליו כי נפגע ממלשין וקיללו ואותו היום טבע המלשין בנהר ההארין)."},{"i":15765,"n":"הלפרין, ישראל יעקב ממונקטש","f":"ליביש","k":"אדמור מדעש במונקטש","dt":"תרצז","b":"נכד ר יוסף ליב כהנא מסיגט-חתן ר יחזקאל פנט מקרלסבורג. תלמיד חבר לר יחזקאל מדעש."},{"i":15766,"n":"הלפרין, ישראל מברוד","f":"יוסף","dt":"תקנד","b":"רב בברודי."},{"i":15767,"n":"הלפרין, ישראל מזסלב","f":"אברהם מרדכי מזולקווא","b":"רב קהלת חייטים בזסלב. חתנו - הגביר ר מרדכי קלמן היילפירסאהן(=הלפרין) מזסלב."},{"i":15768,"n":"הלפרין, ישראל ממינסק","f":"חיים","dt":"תקצו - ח תשרי","dp":"מינסק","b":"נכד ר מרדכי מסווירז. תלמיד ר יום טוב ליפמן מקאפולי בעל \"קדושת יו\"ט\". רב באלקוניק, רוזינאי, מינסק-תקצג על מקום ר שמואל סגל. בניו - ר רפאל יום טוב מביאליסטוק, ר משה צבי ממינסק, שמואל הלפרין מאלשאן."},{"i":15769,"n":"הלפרין, ישראל מסקאהל","f":"יצחק איזיק","b":"רב בסקול-תקמו על מקום אביו."},{"i":15770,"n":"הלפרין, ישראל מקרוטושין","f":"אליעזר ליפמן מטיקטין","k":"מהר\"י חרנ\"ש","b":"רב בקרוטושין-תי. חתן ה\"מגלה עמוקות\". אחיו: ר יצחק מטיקטין, ר משה יהודה זאלקי מפוזנא."},{"i":15771,"n":"הלפרין, ישראל מראקוב","dt":"תשג","b":"רב בראקוב"},{"i":15772,"n":"הלפרין, ישראל מרישא","f":"אברהם מקאוולי","b":"חתן ר יעקב אליהו. רב ברישא, רבה של סוירז ורבה של מדינת רייסן יחד עם הט\"ז. חותנו של ר יעקב אליהו חברו של הט\"ז."},{"i":15773,"n":"הלפרין, ישראל שמואל דוד נחום","f":"אלחנן מלונדון","b":"למד בישיבת טשבין. חתן רצ\"ה מייזלש מוויצען. רב בלונדון."},{"i":15774,"n":"הלפרין, כתריאל","f":"אברהם לוריא","b":"רב-שנת ת\"ר"},{"i":15775,"n":"הלפרין, ליפמן","f":"אברהם הלפרן","b":"רב-שנת ת\"מ"},{"i":15776,"n":"הלפרין, ליפמן ממזבוז","f":"ישראל מזסלב ואוסטרהא","b":"גביר תלמיד חכם במזבוז."},{"i":15777,"n":"הלפרין, מאיר","k":"בעל הגדול ממינסק","b":"חתן ר בצלאל ורהפטיג מסעלץ. ממקורבי הגדול ממינסק וחיבר \"הגדול ממינסק\". חיבר קונקורדנציה לתלמוד - סדר זרעים מועד - בכת\"י. חתנו - ר מיכל יצחק מירושלים."},{"i":15778,"n":"הלפרין, מאיר מחעלם ולובלין","f":"בנימין וולף פרנס","dt":"תפג - ה חשון","dp":"לובלין","b":"נינו של המהר\"ם מלובלין. רב בחלם-תסט, אפטא-תעג, לובלין-תפא על מקום ר שמחה רפפורט. הסכים על \"זרע בירך\", \"דרש משה\" לר משה דרשן מקראקא, \"ברית שלום\"-תעג, ועוד. בניו: ר משה, ר ישכר בר מלומבלא, ר עוזר מבומברג."},{"i":15779,"n":"הלפרין, מאיר מטרנגרד","f":"משה יוסף","b":"חכם ומקובל בעיר טארנגראד, הדפיס בפיורדא את ספרו של ר נסים שלמה אלגזי \"זהב שיבה\"."},{"i":15780,"n":"הלפרין, מאיר מלובלין","f":"דוד","b":"סו\"ד בלובלין,מג\"מ ומו\"צ במאהליב-תק\"א-תקכ\"ב"},{"i":15781,"n":"הלפרין, מאיר שלמה מפיעטרקוב","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":15782,"n":"הלפרין, מיכל צבי מאודסה","b":"חתן ר ראובן הרטנשטין מזיטומיר. רב באודסה על מקום חותנו."},{"i":15783,"n":"הלפרין, מנחם מוניש מברוד","f":"מרדכי","k":"בעל מנחם משיב נפש","bt":"תר","bp":"ברודי","dt":"תרע","b":"חתן ר אברהם מאיר מסקאלי. שו\"ב בסקאלי וברודי. חיבר \"מנחם משיב נפש\" למברג תרס."},{"i":15784,"n":"הלפרין, מנחם מנדל","b":"חתן ר דוד הלפרין בן ר ישראל חריף - רבה של אוסטרהא ותלמיד הבעשט. זקנו של האדמור ר מנחם מנדל מקוצק."},{"i":15785,"n":"הלפרין, מנחם מנדל מדוקלא","f":"חנניה יוסף","k":"אדמור מדוקלא","bt":"תרכו-ל","dt":"תשג","b":"רב בברזאן עם ר יחיאל מיכל לייטר מדוניוב. ועבר להיות אדמור בדוקלא.עבר ליאסלו-תרץ, בז'ז'ין. נספה בשואה (ולפי אלפסי אבדו עקבותיו במלחמ\"ה ה-I)."},{"i":15786,"n":"הלפרין, מנחם מנדל מירושלים","b":"חתם-תרעג על קבלה עבור ישיבת תורת חיים בירושלים."},{"i":15787,"n":"הלפרין, מנחם מנכין","f":"שלום","k":"בעל כבוד חכמים","bt":"תרד","bp":"גרודנה","dt":"תרפד - ו ניסן","dp":"ירושלים","b":"מקובל מחכמי ליטא, עלה לירושלים בתרסא. מראשי \"שער השמים\". חיבר \"כבוד חכמים\" ובו הגן על ספר חמדת ימים מפני מתנגדיו, חיבר עוד פירוש \"מבוא שערים\" ירושלים תרעד, ועוד."},{"i":15788,"n":"הלפרין, מרדכי מאוסטרהא","f":"יואל הגדול מאוסטרהא","dt":"תקטז - כג כסלו","b":"גיסו של ר בצלאל הכהן מאוסטרהא. רב בלויצק על מקום אביו שעבר לאוסטרהא ובנו ר יוסף יואל על מקומו אחריו, עבר לאוסטרהא בעקבות אביו ופרש מהרבנות בגלל שהיה עשיר גדול, פרנס ומו\"צ באוסטרהא. עוד מבניו: ר יצחק איזיק פרנס באוסטרהא, ר נחמן פרנס באוסטרהא, ואולי גם ר אליעזר ליפמן שחתם \"מרדכי באב\"ד היילפרין\"."},{"i":15789,"n":"הלפרין, מרדכי מברוד","f":"אברהם שבח מזורובנא","bt":"תקע","dt":"תרטו","b":"חתן ר שמואל מדרוהוביטש."},{"i":15790,"n":"הלפרין, מרדכי מגלינא","f":"יחזקאל הלוי","k":"בעל ספר המעשיות","bt":"תרמג","bp":"גלינא","dt":"תשלא","b":"היה חוקר חסידות ופרסם בשם מרדכי בן יחזקאל. חיבר \"ספר המעשיות\" ברלין תרפו. אחיו - ר חנוך הניך קנלר - לקח את שם אמו."},{"i":15791,"n":"הלפרין, מרדכי מזורובנא","f":"יעקב","bt":"תקם","dt":"תר","b":"רבה של זורובנא. חתן רא\"ל ברודא מקריווטש."},{"i":15792,"n":"הלפרין, מרדכי מזסלב","f":"ישראל מזסלב ואוסטרהא","dp":"ארץ ישראל","b":"רב בזסלב, קרמניץ, חתן ר יעקב מברוד וגיסו של ר יחזקאל לנדא בעל נודע ביהודה. הסכים על \"שפת אמת\", עלה לארץ ישראל. בנו - ר ישראל - רב דחייטים בזסלב."},{"i":15793,"n":"הלפרין, מרדכי מזסלב","k":"החזן מזסלב","b":"תלמיד הבעשט, ונאמר כי הבעשט קשרו לעולם הניגון. ר אלימלך מליזנסק פחד לשמוע את תפלתו שמא יגוע מרוב מתיקות."},{"i":15794,"n":"הלפרין, מרדכי מירוסלב","f":"יצחק איזיק מטיקטין","dt":"תע","b":"חתן ר ליב ריבידיטשר מפרמישלא. בנו ר אליעזר ליזר חריף."},{"i":15795,"n":"הלפרין, מרדכי מנ\"י","b":"פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":15796,"n":"הלפרין, מרדכי מסווריז","f":"טוביה יחיאל מיכל","bt":"תסד","dt":"תקך או תקלה","b":"רבה של סווירז על מקום אביו. חתן ר ישכר בריש סגל מטשכנובצי."},{"i":15797,"n":"הלפרין, מרדכי מסקאהל","f":"יעקב הלפרן","dt":"תקנד - כו אדר","b":"רב בסקאהל"},{"i":15798,"n":"הלפרין, מרדכי מסקאלא","f":"חנינא יוסף מברזאן","bt":"תק","dt":"תקע","b":"רבה של סקאלא, בנו ר יעקב על מקומו אחריו."},{"i":15799,"n":"הלפרין, מרדכי סגל מבורשטין","b":"אב\"ד בורשטין-תרמג."},{"i":15800,"n":"הלפרין, מרדכי קלמן מזסלב","k":"היילפירסאן","b":"גביר מחכמי זסלב. בנו - ר דב בער."},{"i":15801,"n":"הלפרין, מרדכי ר ליבושס מזולק","f":"ישראל איסר מפינסק","k":"מרדכי רבי ליבוש'ס","dt":"תסח - ב טבת","dp":"זולקוא","b":"נכד ר איסרל בעל \"מהדורא בתרא\"-חתן המהרש\"א. פרנס בזולקוא. חתן ר אריה ליב הכהן וע\"ש נקרא ליבושס. חתם-תמח עם ר הלל בעל \"בית הלל\". בניו - ר משה מנדל מדרוהוביטש ובלז, ר אברהם אבלי מזולקווא, חתניו - ר אלכסנד סנדר שור בעל \"תבואות שור\", ר יצחק רפפורט מאוסטרהא. (אצל בובר-זולקוא מופיע נוסח מצבת בתו וויטל אשת ר אלכסנדר שור ושם מופיע שמו - משה מרדכי). אחיו - ר אברהם אבלי מלובלין-פרנס ועד ארבע ארצות."},{"i":15802,"n":"הלפרין, משה","b":"רב-שנת ש\"מ"},{"i":15803,"n":"הלפרין, משה אלחנן מזלוטשוב","f":"טוביה יחיאל מיכל מבר","b":"אביו היה אב\"ד בערזאן. חתן ר נתן מפולנא בן שמואל ממזריטש, בזיוו\"ש חתן ר נתן הפרנס מזולקוא. אב\"ד זלוטשוב, חתם-תצא בפנקס קהלת לבוב, הסכים על \"אהל משה\" על התורה. בנו - ר נפתלי הרץ - חתן הפני יהושע? (התאריכים לא מסתדרים)."},{"i":15804,"n":"הלפרין, משה אלחנן מטרניגרד","k":"חתן הפני יהושע","b":"רב בטרניגרד-תק\"מ"},{"i":15805,"n":"הלפרין, משה אליהו מלודז","bt":"תרלב","dt":"תרפא - יז ניסן","b":"רב פעלים,ראב\"ד בלודז,נבחר לסיים הפולני-תרע\"ט"},{"i":15806,"n":"הלפרין, משה זאב מזלוטיפול","k":"בעל זכרון משה","b":"נכדו של מרדכי החזן מזסלב-תלמיד הבעשט. תלמיד ר לוי יצחק מברדיטשוב. רב בזלטיפולי, ובנו ר חיים על מקומו אחריו. ?? לא באוצר ??"},{"i":15807,"n":"הלפרין, משה יהודה זלקי","f":"אליעזר ליפמן הלפרן","b":"דרשן בפוזנא-תמ\"ט"},{"i":15808,"n":"הלפרין, משה ישעיה אלחנן"},{"i":15809,"n":"הלפרין, משה מדובנא","f":"אליעזר ליפמן הלפרן","b":"דומ\"צ בדובנא-תקנ\"ח"},{"i":15810,"n":"הלפרין, משה מדולהינוב ומינסק","f":"יחיאל","b":"חתן ר אריה ליב שפירא בעל \"מעונות אריות\". רב בדאלהינוב(=דולהינוב)-פלך וילנא, מינסק-תקד על מקום אביו ור יוסף רפפורט על מקומו אחריו, והיה מחלוקת עם בעל שאגת אריה שאביו ר אשר היה רב גליל מינסק."},{"i":15811,"n":"הלפרין, משה ממאליאט","f":"ישראל דוד ממאליאט","b":"רב במאליאט על מקום אביו."},{"i":15812,"n":"הלפרין, משה מצורטקוב","f":"שלמה דב בעריש","bt":"תק","dt":"תקסט - ד תמוז","b":"רב בצורטקוב(=טשארטקוב). חתן ר איציקל מאה\"ו."},{"i":15813,"n":"הלפרין, משה צבי ממינסק","f":"ישראל ממינסק","b":"לפי מרקוביץ היה בנו של ר רפאל יו\"ט ליפמן בעל \"עונג יו\"ט\", ונכדו של ר ישראל ממינסק. מו\"ץ במינסק-תרכ."},{"i":15814,"n":"הלפרין, משלם יעקב מבורשטשוב","f":"אברהם מרדכי","bt":"תקן","dt":"תריב","b":"במקור ממשפחת מרגליות ושינה שמו להלפרין. רבה של בורשטשוב, ברדיטשוב. חתן ר גרשון מנדל כץ."},{"i":15815,"n":"הלפרין, משלם פייביש מירושלים","f":"יצחק","dp":"ארץ ישראל","b":"מחכמי ירולשים מחבורת ר יהודה החסיד, בשנת תעג היה באלטונא, בשנת תעה הדפיס באמשטרדם את ספר הזהר. בשנת תפו הדפיס בקושטא את הספר \"נגיד ומצוה\" לר יעקב צמח. יתכן שהוא שליח ירושלים שהדפיס באמשטרדם בתעט את סדר הלימוד בלילה שלפני המילה שמקורו בארץ ישראל."},{"i":15816,"n":"הלפרין, משלם שרגא פיבוש מברזן","f":"נפתלי הירץ מברזן","k":"בעל שפת אמת","bt":"תקע","dt":"תרלד - יט אלול","b":"חתן ר שמחה (או בנו חיים) מבוברקא. ובזיוו\"ש חתן ר אשר ישעיה מרופשיץ. רב בברעזאן-תרי. חיבר \"שפת אמת\" למברג תרלט. ?? לא באוצר ??"},{"i":15817,"n":"הלפרין, מתתיהו חיים מדובשיץ","f":"אברהם זרח אריה מברעז","bt":"תרלט","dt":"תרצג - כא אייר","b":"רבה של דובשיץ כ-30 שנה. חתן ר שמעון אלטר פרנקל תאומים מפודגורזע."},{"i":15818,"n":"הלפרין, נחום ראובן מרישא","f":"חיים יונה מרישא","b":"חתן הגביר ר זאב שטוק מסקאלא."},{"i":15819,"n":"הלפרין, נחמן מאוסטרהא","f":"מרדכי","b":"פרנס באוסטרהא-תק."},{"i":15820,"n":"הלפרין, נחמן מבריסק","b":"רב בבריסק-תקך בזמן רבנות ר אברהם קצנלנבוגן. הסכים על \"תפארת ישראל\"-תקלד. חתנו - ר זאב וולף הלברשטט מדובנא."},{"i":15821,"n":"הלפרין, נחמן צבי מבויאן","b":"פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא תרע."},{"i":15822,"n":"הלפרין, נפתלי הרץ מאיר","k":"בעל שדה נפתלי","bt":"תרלה","dt":"תשב","b":"רב בפפד\"מ,עלה לירושלים-תרצ\"ה. מכתביו ב\"תל תלפיות\" - ירושלים תשא.","bk":[["דורשי רשומות, דורשי חמורות - הפטרות",""],["לב אבות – אבות",""],["שדה נפתלי - בהלכה, כרם נפתלי - באגדה",""],["תל תלפיות – הדרנים על הש\"ס",""]]},{"i":15823,"n":"הלפרין, נפתלי הרץ מברזאן","f":"טוביה יחיאל מיכל","bt":"תקלה","dt":"תרה - א טבת","b":"תלמיד החוזה מלובלין והיה מהשותפים במאמצי החוזה לקרב את הגאולה. אב\"ד ברזאן על מקום אביו."},{"i":15824,"n":"הלפרין, נפתלי מברזן","b":"נכד אדמורי ברזן. מזכיר המזרחי בגליציה. עלה לארץ-תרצו. חזר לפולין, ניצל מהשואה והיגר לארה\"ב. רב בניו יורק."},{"i":15825,"n":"הלפרין, נתן מאלטונא","b":"דיין באלטונה-תק. נזכר אצל היעב\"ץ."},{"i":15826,"n":"הלפרין, פנחס מלובלין","f":"בנימין וולף מלובלין","b":"גבאי בלובלין-תעד. בנו - ר שאול מזולקוא."},{"i":15827,"n":"הלפרין, צבי הירש מבוצאץ","b":"רב בבוצאץ-תקפח"},{"i":15828,"n":"הלפרין, צבי הירש מברזאן","dt":"תקפח","b":"אב\"ד ברזאן. מתלמידי החוזה מלובלין."},{"i":15829,"n":"הלפרין, צבי הירש מזמושץ","f":"ישעיהו","b":"חתן ר רלכסנדר סנדר גינצבורג אשכנזי שנהרג עקד\"ה ביום ו סיון תקב."},{"i":15830,"n":"הלפרין, צבי הירש מסאסוב","f":"טוביה יחיאל מיכל","k":"אדמור מברזאן בסאסוב","bt":"תרן","bp":"סאסוב","dt":"תשלא - כד ניסן","b":"תלמיד זקנו האדמור ר שלמה מסוסוב. אדמור מברזאן בסאסוב, למברג וניו יורק."},{"i":15831,"n":"הלפרין, צבי הירש מפודהייץ","f":"חנניה יוסף","bt":"תרלב","bp":"פודהייץ","dt":"תרעז","dp":"ירושלים","b":"נכד ר יהודה ליב אורנשטין מיסד וראב\"ד החסידים. עלה לירושלים בילדותו. חתן ר זאב דב סלונים מחברון. עסק בצרכי ציבור."},{"i":15832,"n":"הלפרין, צבי הירש מפמורן","b":"רבה של פמורן-תרטו."},{"i":15833,"n":"הלפרין, קהת מירוסלב","f":"נפתלי הירץ מברזן","k":"אדמור מירוסלב","bt":"תקף","dt":"תרס-ז","b":"חתן ר שמעון מרילס מירוסלב. רב בירוסלב לצד חותנו ורשם את תורתו, אדמור בירוסלב על מקום חותנו. נפטר ללא ילדים. חיבר \"תורת שמעון\"."},{"i":15834,"n":"הלפרין, שאול מזולקוא","f":"פנחס מלובלין","b":"רב בזולקוא, חתם-תקיא על החרם לטובת ר יונתן איבשיץ (בלוחות העדות)."},{"i":15835,"n":"הלפרין, שבח מזורוולר","f":"אלחנן הלפרן","dt":"תרכט - יב טבת","b":"רב בזורוולר"},{"i":15836,"n":"הלפרין, שלום יוסף מוואסלי","f":"דוד מברדיטשוב","k":"אדמור מבוהוש-וואסלוי","bt":"תרטז","dt":"תש - כד אב","b":"נכד(-אבי אמו) ר ישראל מרוזין. חתן ר יצחק מבוהוש. . אדמור ברעדנקן-תרנו, וואסלוי-רומניה-תרע. בקי במדעים ובעל זכרון."},{"i":15837,"n":"הלפרין, שלמה יצחק מטרנופול","f":"יעקב","k":"בעל יריעות שלמה","bt":"תפט","dt":"תקנב - ד חשון","b":"גדל אצל זקנו ר טוביה יחיאל מיכל אב\"ד ברזאן. אב\"ד ברודשין. נמנה בין הרבנים שהשתתפו בויכוח עם הפרנקיסטים. רב בטרנופול, רבה של באר-תקלח וחורוסטקוב. חתן ר יעקב סגל לנדא מטרנופול, ובזיוו\"ש חתן ר יצחק הורודנקר. חיבר \"יריעות שלמה\" ו\"מרכבת המשנה\" - בכתב יד."},{"i":15838,"n":"הלפרין, שלמה מביאליסטוק","f":"חיים נפתלי הרץ הלפרן","bt":"תרמב","dt":"תשג","b":"חבר ועד הרבנים בביאליסטוק"},{"i":15839,"n":"הלפרין, שלמה מלבוב","f":"וולף מסוכטשוב","b":"מראשי קהלת לבוב, חתם-תקי על שטר מתנה בפנקס הקהל."},{"i":15840,"n":"הלפרין, שלמה מלברטוב","f":"כתריאל הלפרן","dt":"תע","b":"רב בלברטוב, סוקולוב. בנו - ר יחיאל."},{"i":15841,"n":"הלפרין, שמואל","f":"ישראל ממינסק","b":"רב-שנת תר\"ך. חתנו - ר בנימין מייזל מפאנימאן."},{"i":15842,"n":"הלפרין, שמואל מאוסטרהא","f":"אליהו","dt":"תפה - ז טבת","dp":"אוסטרהא","b":"מראשי הח\"ק באוסטרהא בזמן ר מרדכי הלפרין. חתם כמה פעמים בפנקס הח\"ק. כונה במצבתו \"צנצנת המן\" - בשם זה השתמשו לגדולי משפחת הלפרין."},{"i":15843,"n":"הלפרין, שמואל מזלישטשיק","b":"רב בבזלישטשיק."},{"i":15844,"n":"הלפרין, שמואל מסמילוביץ","dt":"תרלה - יח אדר","b":"רב בסמילוביטש"},{"i":15845,"n":"הלפרין, שמואל פסח מזלוזיץ","f":"יוסף או שמשון","k":"בעל שם משמואל","bt":"תרלו","bp":"זלוזיץ-ליד ברודי","dt":"תשיט","b":"נסמך מאת: מהרש\"ם מברעזן, ר פנחס בורשטין מסערט, ר יוסף וייס מטשרנוביץ. רבה של גייטסהד-אנגליה. אחר כך בלייפציג, ברלין ואמשטרדם-תרפה, עלה לארץ-תרפה. ההדיר \"חסדי השם\" לר יוסף יעבץ מספרד - ירושלים תרצד, ועוד. חתן ר משה מרגליות ממיוליטשין (באהלי שם - חתן ר משה וינטר מרוסקוב). כיהן כרבה הראשן של זכרון מאיר. ?? לא באוצר ??"},{"i":15846,"n":"הלפרין, שמעון מוילנא","f":"יעקב ישראל הלפרן","k":"בעל מטה שמעון","bt":"תרלט","dt":"תשטז - כז אדר","b":"מו\"צ בוילנא-תרעד, עלה לירושלים-תרפה. עורך פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו. עורך \"תל תלפיות\" - ירושלים תשא. חיבר גם \"מאורה של תורה\", ועוד."},{"i":15847,"n":"הלפרין, שמעון מפדובה","b":"רב בפדובה, ראש חברת \"לומדי תורה\" ולצדו ר משלם אלפרון, ר בנימין ן דנא, ר דוד גאנסי. חתנו - ר אברהם קאטלנו בעל \"עולם הפוך\" והזכירו בספרו. ר\"מ בישיבת הגמרא מיסודו של ר יהודה כץ מהחזנים."},{"i":15848,"n":"הלפרין, שרגא פיבוש משלם מברזן","f":"אברהם זרח אריה מברעז","k":"אדמור מברזאן","bt":"תרלה","bp":"ברזאן","dt":"תשג","b":"חתן ר פנחס חודרוב מזביא-חתנו של ר ברוך מגורליץ, ובזיוו\"ש חתן ר מנחם מנדל מזידיטשוב. רב בזביא-תרס על מקום חותנו. רב ואדמור בברזן-תרעא על מקום אביו."},{"i":15849,"n":"הלפרין-באבד, יהושע השל מחעלם","f":"מאיר מלובלין ואפטא","b":"פרנס קהילת חלם וועד ארבע ארצות."},{"i":15850,"n":"הלפרין-באבד, ישכר בער מלובמלא","f":"מאיר מלובלין ואפטא","b":"רב בלובמלא-תצ."},{"i":15851,"n":"הלפרין-באבד, משה מלובלין","f":"מאיר מלובלין ואפטא","dt":"תקב - אחרי","dp":"לובלין","b":"מחכמי לובלין. אחיהם של ר יהושע השל פרנס חעלמא, ר ישכר בר מלובמלא, ר עוזר מבומברג. חתם על קול קורא מאחינו יושבי טשליץ-תקב לעזרת יושבי ארה\"ק."},{"i":15852,"n":"הלפרין-באבד, עוזר מבומברג","f":"מאיר מלובלין ואפטא","b":"אב\"ד בומברג. נזכר ב\"חק יעקב\"."},{"i":15853,"n":"הלפרין-גולד, יעקב שלמה מדוניוב","f":"דב בריש","k":"בעל יפה ענף","bt":"תקפז","dt":"תרנה","b":"רבה של דוניוב-תריד, פרימישלן-תריז על מקום ר אפרים פישל. חיבר \"יפה ענף\" (שושלת היוחסין של המשפחה) ירושלים תשיט."},{"i":15854,"n":"הלפרין-היילברון, יעקב מאדא","f":"יצחק מזענטא","k":"בעל לשון צדק","r":"אב\"ד דק\"ק אדא","bt":"תקע","dt":"תרט - י שבט","dp":"זענטא","b":"תלמיד החת\"ס. רב בזענטא לצד אביו, רב באדא-תרא. נהרג עק\"ה (ע\"י הצבא הסרבי), ולזכרו נקבע יום תענית לבני הח\"ק בזענטא. ספריו נדפסו החל משנת תשלג.","bk":[["כוכב מיעקב (נדפס בסו\"ס שו\"ת אור פני יהושע) - הל' פסח",""],["לשון צדק - דרשות",""],["מגילת סדרים - על התורה ושו\"ת ודרשות ויו\"ד הלכות טריפות",""]]},{"i":15855,"n":"הלפרין-היילברון, משה","f":"אהרן שלמה","bp":"היילפרין-היילברון","b":"מראשוני משפחת הלפרין, חתם שמו-שלד."},{"i":15856,"n":"הלפרין-הילמן, שמואל ממנהיים","f":"ישראל מקרוטושין","bt":"תל - בערך","dt":"תקכו","dp":"מיץ","b":"תלמיד ר אברהם ברוידא. מקובל, ממנהיגי ועד ארבע ארצות בירוסלב-תנג?, רב בקרמזיאר, מנהיים-תפח-צח, מיץ-תקך על מקום ר יונתן איבשיץ, ור אריה ליב בעל שאגת אריה על מקומו אחריו. הסכים על \"כרם שלמה\" לר שלמה גייגר. היה ממתנגדי ר יונתן איבשיץ וחשד בו בשבתאות והוא שפתח קמיעות חשודות של ר יונתן (ולדברי ר יונתן הקמיעות אינם ממנו), ושכנע יחד עם ר יעקב עמדין רבנים לצאת כנגד ר יונתן ובהם ר יעקב יהושע בעל \"פני יהושע\". בניו: ר משה מגלינא (חותנו של ר מיכל הלוי מאייזנשטט), ר אורי פיביש מליסא (מחותן עם הנודע ביהודה)."},{"i":15857,"n":"הלפרין-הלפרט, בן ציון מנאנאש","f":"יוסף","k":"בעל בן ציון","bt":"תרכב","dp":"תרעט - יב תמוז","b":"חתן ר ישראל אפרים סופר מנאנאש בעל \"אפסי ארץ\", רב בנאנאש-תרנח על מקום חותנו וראש ישיבה שם, ובנו ר שלמה על מקומו אחריו, בנו גם - ר יוסף צבי בעל שלשה ספרים נפתחים, אחד מהשלשה הוא שו\"ת \"בן ציון\" ממנו."},{"i":15858,"n":"הלפרין-הלפרט, יוסף צבי משמקוט","f":"בן ציון הלפרט מנאנאש","k":"בעל צרי לנפש יפה","r":"אב\"ד נאנאש","bt":"תרמה","bp":"נאנאש","dt":"תשד","b":"נכד ר ישראל אפרים פישל סופר בעל \"אפסי ארץ\" וגדל אצלו. תלמיד ר יהודה גרינפלד בסעמיהאי, ור מרדכי ליב וינקלר במאד. חתן ר אהרן צבי קלר משמקוט ועבר לשם וכיהן כר\"מ בישיבת חותנו. רב ודיין בשאמקוט(=נאדי-שאמקוט)-תרסו, רבה האחרון של שאמקוט-תרפח על מקום חותנו. נספה בשואה. חסיד אדמורי סיגט ה\"קדושת יו\"ט\" ובעל \"עצי חיים\". בנו ר ישראל אפרים הלפרט מציריך הו\"ל את ספריו בשם \"שלשה ספרים נפתחים\"- ירושלים תשלט. פרסם מאמרים ב\"דגל התורה\" - אויבר-וישובה תרפח.","bk":[["צרי לנפש יפה",""]]},{"i":15859,"n":"הלפרין-הלפרט, יקותיאל יהודה","f":"בן ציון מנאנש -שלמה?","bt":"תרמד","dt":"תשלא - טו אב","dp":"ארה\"ב - ירושלים","b":"תלמיד ר משה גרינוולד בחוסט. חתן הגביר ר אליעזר הירש מארדד(=ערדאד). רב בארדד-תרסה, נאנאש-תרעט על מקום אביו. בזיוו\"ש חתן ר מנחם שטרן מפילדש. ניצל מהשואה וחזר לנאנאש. היגר לארה\"ב. (במורשת רבני הונגריה - אביו - ר שלמה מנאנאש-בנו של ר בן ציון מנאנאש)."},{"i":15860,"n":"הלפרין-הלפרט, שלמה מנאנאש","f":"בן ציון מנאנאש","b":"רב בסטמר ארדוש, רב וראש ישיבה בנאנאש על מקום אביו-תרעח."},{"i":15861,"n":"הלפרין-ראך, אברהם ר חיימש","f":"חיים","k":"אברהם רבי חיימש","bt":"תנ","dt":"תקכג - טו חשון","b":"גדל אצל אביו חורגו ר אברהם איסרלש פרנס ועד ארבע ארצות. השם הלפרין הוא שם אמו. חתן ר יוסף מאופוטשני. רב בלובלין בנו - ר משה פנחס מזולקוא."},{"i":15862,"n":"הלר ברנט, דב מבודפשט","b":"פרופ' למקרא בביהמ\"ד לרבנים בבודפשט. חוקר האגדה והפולקלור, ועוד. בקי בספרות המזרחית והאירופית."},{"i":15863,"n":"הלר יהושע בן אהרן","f":"אהרן מוילנא","k":"בעל חוסן יהושע","bt":"תקעד","dt":"תרמ - כב-ג סיון","dp":"טלז","b":"תלמיד ר דוד טבלי ממינסק. חתן ר אליעזר מהורדנא. מגיד מישרים בהורדנא, רב בפולנגן, טלז-תרלו על מקום ר יוסף רוזין, נתקבל כמגיד בוילנא-תרלט אך נפטר בטרם הגיע. בזמן שכיהן בפולנגן דאג לשיפור מצבם של הפועלים ובהשתדלותו עבדו בערב שבת חצי יום וקבלו שכר של יום וכן קבלו זמן לתפילת מנחה. חיבר גם \"דברי יהושע\", ועוד. אחיו: ר יחיאל ור מאיר. נפטר ללא ילדים.","bk":[["אהל יהושע",""],["דברי יהושע",""],["חוסן יהושע",""],["מעוז הדת",""],["מעיני יהושע",""],["פרקי אבות עם פירוש תולדות יהושע",""],["דברי יהושע - בית תפילה",""],["דברי יהושע - שלשה מאמרים",""]],"e":"תקע\"ד-תר\"מ"},{"i":15864,"n":"הלר שמואל בן ישראל","bt":"1803","dt":"ה'תרמד 1884","bk":[["דברי אברהם",""],["דברי משפט",""],["דרך נשר",""],["כבוד מלכים",""],["רפואות וסגולות",""],["שם משמואל",""]]},{"i":15865,"n":"הלר, אברהם זאב הלוי","k":"בעל שיחות של סבא","bt":"תרמו","bp":"הלוסק","dt":"תשא","b":"תלמיד הסבא מסלובודקה, וכולל קובנא. רב בז'ידיק על מקום ר חיים נתנזון, מאריאמפול-תרפח על מקום הרב פופל. פעיל במועצת הרבנים בליטא. נספה בשואה עם בני עדתו. פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב, \"דברי תבונה\" - קובנה תרף, פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"תבונה\" - קובנא תרפא, \"תבונה\" - ירושלים תשא."},{"i":15866,"n":"הלר, אברהם יחיאל הלר מזלישטשיק","b":"רב בזלישטשיק."},{"i":15867,"n":"הלר, אברהם יצחק מצפת","f":"שמואל","bt":"תריא","bp":"צפת","dt":"תרסט","dp":"צפת","b":"מחכמי צפת בנו של רב העיר."},{"i":15868,"n":"הלר, אברהם מאיר מקוידנוב","f":"ישראל-נחלה לישראל","bt":"תקצא","dt":"תרנד - יז תמוז","b":"תלמיד ר ישראל סלנטר. רב בקוידנוב-תרכד על מקום אביו, ובנו ר יחיאל על מקומו אחריו. חתנו - ר יצחק יונה קפלן מהאראדוק."},{"i":15869,"n":"הלר, אברהם מדולינא","f":"משה הלוי","b":"רב בדולינא"},{"i":15870,"n":"הלר, אברהם מיאנישוק","f":"יחיאל","k":"בעל יפה נוף","bt":"תרב","bp":"סובאלק","dt":"תרפפב - כז תמוז","dp":"יאנישוק","b":"רב ביאנישוק-תרך, האזנפוט-תרלז על מקום ר יצחק זאב אהרונוביץ, ליבאוי(=ליבאו)-תרמב."},{"i":15871,"n":"הלר, אברהם מסקאהל","f":"יום טוב - תוי\"ט","b":"חתן ר יחיאל לוריא בן ר שלמה הרופא מלובלין. רב בלובלין, מנהל ישיבה בסקאלא(=סקול)-פלך לובלין-תנ. הגיה \"מעדני מלך\", \"מעדני יו\"ט\". חיבר פירוש לירושלמי. נזכר בספר אביו. בנו ר שמשון."},{"i":15872,"n":"הלר, אברהם מצפת","f":"פרץ מלובלין","b":"תלמיד החוזה מלובלין ובעל תוקע בבית מדרשו. עלה לארץ. בניו: ר שמואל מצפת ור משה ליב מצפת."},{"i":15873,"n":"הלר, אברהם נח מדולינא","f":"אהרן משה מסניאטין","k":"בעל זריזותא דאברהם","bt":"תץ","dt":"תקמו - יח אלול","dp":"ברודשין","b":"נכד התוי\"ט, אחיו של ר משולם פיבוש מזבאריז. מחכמי הקלויז בברודי. חתן הנגיד ר נחמן ליסוויטשער. רב בבוליחוב, דולינא, ברודשין. חיבר \"זריזותא דאברהם\" למברג תרס. בניו ר מאיר - מגיד בברודי, ר אהרן יהודה אב\"ד טויסט, ר שלמה צבי מברוד."},{"i":15874,"n":"הלר, אברהם שמואל מבודזנוב","f":"משלם פיבש מברודשין","bt":"תקעח","dt":"תרל","b":"חתן ר פנחס בן יהודה מאיר שפירא משפיטובקה. אב\"ד בודזאנוב. בנו ר יעקב שמשון על כסאו אחריו."},{"i":15875,"n":"הלר, אהרן אריה מלשקוביץ","f":"יוסף יוסקי מלשקוביץ","dt":"תרנה - בערך","b":"רב באלשקוביץ(=לשקוביץ) על מקום אביו, ובנו ר יוסף יוסקי על מקומו אחריו-תרנה. חתנו - ר אהרן משה רפפורט דרשן מקלוש. תשובה אליו - \"אהל - הואיל משה\"."},{"i":15876,"n":"הלר, אהרן יהודה מטויסט","f":"אברהם נח","bt":"תקיב","dt":"תקמז","dp":"צפת","b":"רבה של טויסט, עלה לצפת."},{"i":15877,"n":"הלר, אהרן ליב משאוולי","f":"יחיאל","b":"רב \"מטעם\" בשאוולי. סייע לר יצחק מאיר יודלביץ להקים ישיבה בשאוולי-תרעג."},{"i":15878,"n":"הלר, אהרן מוילנא","b":"רב בוילנא. בניו: ר יחיאל בעל \"עמודי אור\", ר ישראל חריף בעל \"נחלת ישראל\", ר יהושע בעל \"דברי יהושע\". חתנו - ר שרגא עזריה זוסיא סטאליאר (ספיר) ונכדו ר איזיק ליב ספיר מראצקי."},{"i":15879,"n":"הלר, אהרן מסטרי","bp":"סטרי","dt":"תשג","b":"מצאצאי התוי\"ט. תלמיד מהר\"ם שפירא ובהשפעתו נתמנה לדיין בסטרי. נספה בשואה."},{"i":15880,"n":"הלר, אהרן משאוולי","dt":"1944","dp":"דכאו","b":"רב מטעם בשאוולי עד מלחה\"ע ה-I, עזב את הרבנות וניהל את בנק הסוחרים, פעיל בתנועה הציונית. בימי השואה חבר במועצה היהודית בגיטו, והצטיין במסירותו לעניני צבור. נספה בשואה."},{"i":15881,"n":"הלר, אהרן משה מסניאטין","f":"מאיר","bt":"תע","dt":"תקל","b":"חתן ר ישראל משה מטיסמניץ (הנקרא \"הירושלמי\" על כי בא מהספרדים שבירושלים נכד ר יהודה החסיד). אב\"ד בסניאטין."},{"i":15882,"n":"הלר, אהרן נתן מפרמפול","f":"שמואל זנויל","bt":"תקעז או תקפ","dt":"תרטו - כז אדר","b":"חתן ר ישעיה שיף מזמושץ. רבה של פראמפול, רב על מקום אביו בקרעשוב. מאמר ממנו ב\"העץ\" - לובלין תרצג."},{"i":15883,"n":"הלר, אליעזר מטבריה","f":"גודל","bt":"תרכה","bp":"קולומיאה","dt":"תשיג","b":"עלה לטבריה בילדותו. חזר לקולומיאה ולמד שם, חזר לטבריה ונתמנה רבה של הקהלה החסידית. בשליחות לגליציה מספר פעמים."},{"i":15884,"n":"הלר, אריה יהודה מקולומיאה","f":"יום טוב ליפמן","bt":"תרע","bp":"קולומיאה","dt":"תשג","b":"חתן ר שבתי הכהן רפפורט מפינטשוב ובזיוו\"ש חתן הרבי קוטן מקולומיאה. התיישב למברג והיה רב ועסקן ציבורי. נספה בשואה. פרסם בכתבי עת שונים."},{"i":15885,"n":"הלר, אריה ליבש הכהן מסטרי","bt":"תקעז","dt":"תרלט","b":"רבה של סטרי על מקום אביו."},{"i":15886,"n":"הלר, אריה ליבש מזמושט","dt":"כה כסלו","b":"רב בזאמוטש-תק\"ל"},{"i":15887,"n":"הלר, אריה מבוסק","f":"פנחס משה","k":"בעל שקלי גולה","bt":"תרך","bp":"ציעשינוב","dt":"תש","b":"רב בבוסק. חיבר \"שקלי גולה\" למברג תרנח, ועוד. ?? לא באוצר ??"},{"i":15888,"n":"הלר, ברוך יצחק מזוואניץ","f":"משלם פיבש מזבאריז","bt":"תקם","dt":"תקץ","b":"אב\"ד זוואניץ."},{"i":15889,"n":"הלר, דב צבי מסלובודקה","dt":"תשד - כב תמוז","b":"משפיע רוחני בישיבת סלובודקה"},{"i":15890,"n":"הלר, דוד זאב מפמורן","b":"רב בפמורן-תרב ובסקול."},{"i":15891,"n":"הלר, זאב דב מפרמישלא","f":"שמואל זנויל מפרמישלא","k":"הו\"ל מנחם ציון","b":"רב בפרמישלא-תרמה. הביא לדפוס \"מנחם ציון\" פרמישלא תרמה."},{"i":15892,"n":"הלר, זאב וולף ממריאמפול","dt":"תשג","b":"רב במריאמפול-תרפט. נספה בשואה."},{"i":15893,"n":"הלר, זאב וולף מצפת","f":"שמואל מצפת","b":"מנהל ביה\"ח \"משכיל אל דל\" בצפת-תרנו."},{"i":15894,"n":"הלר, זאב סגל מקראקא","b":"רב בקרקא-ת\"ל"},{"i":15895,"n":"הלר, זנוויל מפרמישלא","f":"אריה ליבש הלר","b":"רב בפרעמיסלא-תק\"פ"},{"i":15896,"n":"הלר, חיים מוארשא","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":15897,"n":"הלר, חיים מלומזה וארה\"ב","f":"ישראל פינסקר","k":"בעל לחקרי הלכות","bt":"תרלט-ם","bp":"ביאליסטוק","dt":"תשכ - יג ניסן","b":"ר\"ח הלר הו\"ל ספרים שונים, בחלקם הביא נוסחאות שונות, ומהם: הנוסח השומרוני של התורה; לחקרי הלכות [חו\"מ]; מסורת התנ\"ך; נוסחאות התרגומים לתורה; על התרגום הירושלמי לתורה; פשיטא [התרגום הסורי]; על תרגום השבעים; פרי חיים [נדפס בסוף זרע חיים]; קונטרס בדין מוכר גוף החפץ של משכונו ביד אחר; קונטרס בירורים.","bk":[["תוצאות חיים [על סהמ\"צ]",""],["לחקרי הלכות",""],["על דבר מסורת השס בירושלמי",""],["על התרגום הירושלמי",""],["על תרגום השבעים",""],["פשיטא",""],["קונטרס",""],["שני קונטרסים",""],["המעלות לשלמה - ירושלמי תרומות",""],["לחקרי הלכות - חו\"מ",""],["נוסחאות התרגומים לתורה - וראיות נוספות המוכיחות כי נוסח השומרונים לתורה אינו אלא עיבוד של הנוסח של המסורה",""],["על דבר מסורת הש\"ס לירושלמי",""],["על התרגום הירושלמי לתורה",""],["פרי חיים - רמב\"ם",""],["פשיטא - התרגום הסורי לתורה",""]]},{"i":15898,"n":"הלר, יהודה מאוסציא","b":"רב באוסציא."},{"i":15899,"n":"הלר, יהושע מבלשביץ","b":"נכד ר בנימין וולף מסטניסלב ושל רד\"ב הלפרין מסטניסלב. רבה של בריש, בלשביץ, סטרי-תרמא."},{"i":15900,"n":"הלר, יום טוב ליפמן מזברז","dt":"תרע - יא אדר","b":"רב בזבאריז"},{"i":15901,"n":"הלר, יום טוב ליפמן מקולומיאה","f":"שמשון","bt":"תרם","bp":"קולומיאה","dt":"תשב","b":"חסיד בויאן. מחכמי קולומיאה ומפרנסיה."},{"i":15902,"n":"הלר, יוסף הלוי מלמברג","f":"נתן הלר","dt":"תיט - כב טבת","dp":"לבוב","b":"מרביץ תורה, ראב\"ד בלבוב. אחיו של בעל התוספות יום טוב."},{"i":15903,"n":"הלר, יוסף יוסקה מלשקוביץ - הזק","f":"שמשון מאזיראן","dt":"יח כסלו","b":"רב בלאשקוביץ-תרך ובנו ר אהרן אריה על מקומו אחריו."},{"i":15904,"n":"הלר, יוסף יוסקה מלשקוביץ - הנכ","f":"אהרן ליב מלשקוביץ","dt":"תרצג - ז סיון","b":"אדמו\"ר בלשקביץ(=אלשקוביץ)-גליציה-תרנה על מקום אביו, זלישטשיק."},{"i":15905,"n":"הלר, יוסף יוסקי הלוי מלשקוביץ","f":"משלם פיבש מזבריז","b":"רב בלשקוביץ."},{"i":15906,"n":"הלר, יוסף מקאליש","f":"יחיאל","dt":"תקלא - כג כסלו","b":"רב בקאליש. אביו של בעל הקצות."},{"i":15907,"n":"הלר, יחיאל הלוי","f":"שלמה דב מסיגט"},{"i":15908,"n":"הלר, יחיאל מהאלוסק","f":"אהרן מוילנא","k":"בעל עמודי אור","r":"ראב\"ד ור\"מ דק\"ק סוואלק","bt":"תקעד","bp":"קידאן","dt":"תרכב - יא כסלו","dp":"פלונגיאן","b":"רב בהלוסק-תקצז, וילקוביסק-תרג, סובאלק - ועמד בראש קיבוץ של לומדי תורה חשובים ובהם ר יוסף זכריה שטרן, פלונגיאן. חיבר \"שני פרקים\" אודות חובות היהודים למדינה ברוסית וגרמנית. פרסם מאמרים בכתב העת \"תבונה\" - ממל-קניגסברג תרכא - של ר ישראל סלנטר.","bk":[["עמודי אור",""],["עמודי אור (שו\"ת)",""],["עוטה אור",""]],"e":"תקע\"ד-תרכ\"ב"},{"i":15909,"n":"הלר, יחיאל מקוידנוב","f":"אברהם מאיר בן ישראל","bt":"תרכז","b":"תלמיד ישיבת וולוזין. חתן ר צבי הירש למפרט בעל \"פסקי הגר\"א\" על השו\"ע. רב בקוידנב(=קאיידנאוו)-פלך מינסק-תרנד על מקום אביו, עלה לפתח תקוה-תר\"פ. נסמך מאת: ר יצחק אלחנן מקובנא, ר משה דונישבסקי, ר אליהו דוד רבינוביץ-האדר\"ת, ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\"."},{"i":15910,"n":"הלר, יעקב יהודה ליב מצ'כנוביץ","b":"אב\"ד צ'כנוביץ. הסכים על \"יסוד ושורש העבודה\" - תקמב."},{"i":15911,"n":"הלר, יעקב שמשון מבוזנוב","f":"אברהם שמואל","bt":"תר","dt":"תרסט","b":"רב בבוזנוב-תרל על מקום אביו. יד פרטים רבים אודות משפחתו עד התוספות יום טוב רמח\"א בלוך הדפיס על פיהם \"אבני חיים\" שנספח לספרו \"אוצר חיים\" - אבד בשואה."},{"i":15912,"n":"הלר, יצחק איזיק הלוי מתל אביב","k":"בעל בנין הריא\"ל","b":"חיבר ספר על מידות בית המקדש - תל אביב תרצח."},{"i":15913,"n":"הלר, יצחק ממיכלפולי וקריליביץ","f":"נחמן","k":"בעל ויעתר יצחק","bt":"תרכד","b":"מצאצאי ר בן ציון קמינקר-תלמיד הבעש\"ט. רב במעכלפאלי-פודוליה-תרמז, קריליוויץ-פודוליה, קרמניץ-ווהלין. חיבר גם \"מכתם לדוד\", \"מנחת יעקב\", \"מנחת יצחק\". נסמך מאת: ר יצחק אהרן איטינגא מלבוב. בנו - ר נחמן בעל \"עטרת יצחק\"."},{"i":15914,"n":"הלר, ישכר בריש מדוברומיל","dp":"צפת","b":"רב בדוברומיל וסנוק."},{"i":15915,"n":"הלר, ישעיה צבי מפרמפול","f":"אהרן נתן","bt":"תר","dt":"תרסה","b":"רבה של גוריי - פולין, פרמפול על מקום אביו."},{"i":15916,"n":"הלר, ישראל חריף ממינסק","f":"אהרן מוילנא","k":"בעל נחלת ישראל","dp":"קוידנוב","b":"ר\"מ במינסק, קוידנוב-תקץ, ובנו ר אברהם מאיר על מקומו אחריו. אחיהם של ר יחיאל בעל \"עמודי אור\", ר יהושע מטלז, ר מאיר מקושטוקוביץ."},{"i":15917,"n":"הלר, ישראל מקאבאשן","b":"רב בקאבאשאן-בסרביה. חתנו - ר יחזקאל גרבטה בן ר ישראל חיים מקולטשין."},{"i":15918,"n":"הלר, מאיר הלוי משטרוויץ","dt":"תריד","b":"רבה של שטרוויץ, בויאן."},{"i":15919,"n":"הלר, מאיר מברוד","f":"אברהם נח","bt":"תקי","dt":"תקס","b":"רב בברודי."},{"i":15920,"n":"הלר, מאיר מברודשין","f":"שמשון","bt":"תנ","dt":"תקה","b":"חתן ר יעקב משה תלמיד הרבי ר השל. רב בברודשין על מקום אביו. הבעשט נסע אליו לקיים מצות שימוש חכמים."},{"i":15921,"n":"הלר, מאיר מוילנא","f":"אהרן","bt":"תקסד","dt":"תרלז - ה אייר","dp":"קסטיוקוביטש-פלך מאהליב","b":"דומ\"צ בוילנא-תקץ, רב בטראקי,קסטקוביץ-פלך מאהליב-תרז"},{"i":15922,"n":"הלר, מאיר מירושלים","b":"מקנאי ירושלים וממתנגדי הרב קוק. שלח מכתבים על כך לליטא, נזכר במכתב ר דוד אידל חיים בנגיס מליבוי."},{"i":15923,"n":"הלר, מאיר מרדשין","f":"שמשון הלוי","dt":"תקעה - כט שבט","b":"רב בראדשין או ראדשיץ-תקי."},{"i":15924,"n":"הלר, מנחם מנדל דב מאלמשאד","f":"צבי הירש","bt":"תקס","dt":"תריח","b":"רב באלמשאד-הונגריה, רב בבלז-תקצט."},{"i":15925,"n":"הלר, מרדכי מלמברג","f":"משלם פיביש","b":"חתן ר שמעון מירוסלב. רב בלמברג. בנו ר יוסף יצחק."},{"i":15926,"n":"הלר, משה אברהם זידא מצפת","f":"זאב","k":"בעל דברי אברהם","bt":"תרנד","bp":"צפת","b":"תלמיד הרידב\"ז ולמד בישיבת הרב אלבז. עבר לבלז ולמד אצל האדמור. חזר לצפת-תרעד. חתן ר חיים ברזל. רב בצפת. חיבר \"דברי אברהם\" - בתוך \"שם משמואל\" לזקנו, ירושלים תשלט, \"הקרב על צפת\" צפת תשלג."},{"i":15927,"n":"הלר, משה אהרן","f":"משלם פיבוש הלר"},{"i":15928,"n":"הלר, משה אהרן הלוי מסניאטין","f":"מאיר הלוי הלר","b":"רב בסניאטין-תק\"מ"},{"i":15929,"n":"הלר, משה הלוי","b":"מגדולי חכמי דורו,רב ראשי לכל מדינות אשכנז-ש\"מ"},{"i":15930,"n":"הלר, משה הלוי","f":"יום טוב - תוי\"ט","b":"מגדולי חכמי דורו-ת\"כ"},{"i":15931,"n":"הלר, משה הלוי","f":"זאב הלר","b":"מגדולי דורו"},{"i":15932,"n":"הלר, משה מרימנוב","b":"רב ברימנוב, סדיגורא, פודילאי."},{"i":15933,"n":"הלר, משה צבי הירש מבקשביץ","f":"יוסף","k":"בעל גאון צבי","bt":"תץ","dt":"תקכז או תקל","b":"רב בבקשביץ. הניח כתבים רבים ומהם הדפיס נכדו - ר צבי יוסף מבאשטין - \"גאון צבי\" למברג תר."},{"i":15934,"n":"הלר, משלם פיבוש הלוי מזבאריז","f":"אהרן משה מסניאטין","k":"בעל יושר דברי אמת","bt":"תק","dt":"תקנה - כ כסלו","b":"מצאצאי התוי\"ט. תלמיד המגיד ממזריטש, והמגיד מזלוטשוב, ור מנחם מנדל מפרמישלן. מחכמי זברז-רוסיה (לא זברז הסמוכה לטרנופול). חתן ר מרדכי הלפרין מברזאן ובזיוו\"ש חתן נכדת (או בת) בעל \"צאן קדשים\" - אשתו נחשבה לצדקת שגדולי ישראל באו להתברך אצלה. חיבר \"דרך אמת\" למברג תקץ, \"יושר דברי אמת\" מונקטש תרסה, ועוד. בנו - ר יוסף.","bk":[["יושר דברי אמת","חסידות"],["דרך אמת (זבוריז)",""],["יושר דברי אמת - מוסר",""]]},{"i":15935,"n":"הלר, משלם פיביש מאוסציא","f":"ש'","b":"רב באוסציא-זילוני. נכד רמ\"פ מזבריז והשר שלום מבלז. מתורותו - \"ועד חכמים\"-תרנח."},{"i":15936,"n":"הלר, משלם פיביש מברודשין","f":"ברוך יצחק מזוואניץ","k":"בעל שפת אמת","bt":"תקס","dt":"תקצט - יח חשון","b":"תלמיד ר חיים מטשרנוביץ. חתן ר משה מנדל בן בנימין זאב מזבארז (זלוטשוב). רב בברודשין. חיבר \"שפת אמת\" קולומיאה תרמא. בניו ר אברהם שמואל מבודזנוב, ר שלמה."},{"i":15937,"n":"הלר, משלם פיביש מברודשין","f":"שמעון מנחם מנדל","dt":"תרן","b":"חתן רי\"מ היבנר."},{"i":15938,"n":"הלר, משלם פיביש מרוהטין","b":"רב ברוהטין-תרנה."},{"i":15939,"n":"הלר, נחום מאיר מקולומיאה","f":"עזריאל","k":"הו\"ל זריזותא דאברהם","bp":"קולומיאה","dt":"תרצח","b":"חסיד בויאן. נשיא יח\"ל. חתן ר יצחק לנגסם מלינסק. רב בקראקא. העתיק מכתב יד את \"זריזותא דאברהם\" ח\"ב והביאו לדפוס. ?? לא באוצר ??"},{"i":15940,"n":"הלר, נחמן","f":"יצחק מקרמניץ","k":"בעל עטרת יצחק","b":"רב-שנת תר\"ס. חיבר גם \"לשכת מוריה\". מתורתו בספרי אביו - \"מכתם לדוד\", \"מנחת יצחק\"."},{"i":15941,"n":"הלר, נתן הלוי","f":"משה וולרשטיין","dt":"שלט","b":"אבי התוספות יום טוב,שנולד לאחר פטירתו"},{"i":15942,"n":"הלר, נתן זאב","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":15943,"n":"הלר, עזריאל מקולומיאה","f":"נחום מאיר","bt":"תר","dt":"תרסז","b":"חתן ר יום טוב ליפמן הלר מסטניסלב. חסיד בויאן ומחכמי קולומיאה."},{"i":15944,"n":"הלר, צבי אלימלך","f":"שמואל זנויל מפשמישל","k":"הו\"ל תפוחי זהב","b":"הוציא לאור \"תפוחי זהב\" לדודו - תרלד, \"זכרון שמואל\" לאביו - תרמב. ?? לא באוצר ??"},{"i":15945,"n":"הלר, צבי הירש חריף מבריגל","f":"אריה ליבוש","k":"בעל טיב גיטין","bt":"תקלו","bp":"זמושץ-מורביה","dt":"תקצה - כה תשרי","b":"חתן הגביר ר חיים ויינרב מראווא. למד עם ה\"ישועות יעקב\", ועם ר שלמה קלוגר מברודי. רב בבריגל, ראש הישיבה בברודי-תקעז - בגלל מחלוקת עם ראשי הקהל והלשנה עליו נאלץ לברוח להונגריה והיה לרבה של אונגוואר על פי המלצת החתם סופר. רב וראש הישיבה בבוניהאד(=בניהאד)-תקעח. על מקום ר בנימין זאב בוסקוביץ, בודפשט על מקום ר משה מינץ-תקצד - בהמלצת החת\"ס. בכל מקום שישב בו העמיד ישיבה ולימד תלמידים רבים. החתם סופר נשא את אלמנתו אחריו. בנו ר מנחם הו\"ל את ספרו \"חדוש טיב גיטין\". חיבר גם \"תפוחי זהב\". מתלמידיו: ר משה טויבש מיאסי, ר צבי ליסקה בעל \"אך פרי תבואה\", ר שלמה גנצפריד בעל \"קיצור שו\"ע\". חתנו ר יצחק וינברג מקלינורדין בעל \"פני יצחק\". חיבר גם \"תפוח זהב\", ועוד. תחתיו כיהנו בבוניהאד ר יעקב צבי מאיר פרידלנד משוראני, ור משה בן ירמיהו מלייפניק.","bk":[["טיב גיטין",""],["קונטרס הגאון ר' צבי חריף, ש\"ס",""],["שו\"ת ר' צבי הלר",""],["שו\"ת ר' צבי הלר , קונטרס הגאון ר' צבי חריף, ש\"ס, טיב גיטין",""]]},{"i":15946,"n":"הלר, צבי הירש כהנא","f":"משה","k":"בעל זכרון יהודה","b":"סופר,מגדולי חכמי סיגעט-תר\"נ"},{"i":15947,"n":"הלר, צבי הירש מבאריש","b":"אב\"ד באריש-תרנו."},{"i":15948,"n":"הלר, צבי הירש מפמורן","b":"רבה של פמורן-תרעב."},{"i":15949,"n":"הלר, קלמן משאץ","b":"רב בשאץ, רומעניע. פרסם מאמרים ב\"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב."},{"i":15950,"n":"הלר, שלמה","f":"משלם פיבש מברודשין","b":"חתן ר צבי וולף מקולומיא."},{"i":15951,"n":"הלר, שלמה דב הלוי מסיגט","dt":"תשד - כד סיון","b":"חתן ר שלמה ליב טאבאק מסיגט בעל \"ערך ש\"י\". דיין בסיגט-תרס, רב על מקום חותנו-תרסח כ-40 שנה. נספה בשואה. תשובה ממנו לחתנו - ר עמרם רוזנברג אב\"ד ראצפרט נדפסה בספר \"חמדת שאול\" למחותנו."},{"i":15952,"n":"הלר, שלמה מסקרן","b":"חתן ר פנחס ברטשין מסקרן. דומ\"צ בסקרן-בסרביה-תר\"ע."},{"i":15953,"n":"הלר, שמואל הלוי מקראקא","f":"יום טוב - תוי\"ט","k":"בעל מגילת איבה","b":"חתן ר אברהם קצנלנבוגן. רב בקראקא-תלט, בריסק."},{"i":15954,"n":"הלר, שמואל זנוויל מפשמישל","f":"אריה ליב","k":"בעל זכרון שמואל","bt":"תקן","dt":"תריט - יח אדר","b":"רב בברודי, רב בקרעשוב-פולין-תקצב, פשמישל-תרב. לימד את ה\"דברי חיים\" בצעירותו. חיבר \"זכרון שמואל\" פרמישלא תרמב."},{"i":15955,"n":"הלר, שמואל מצפת","f":"ישראל הלוי","k":"בעל טהרת הקדש","r":"ראב\"ד צפת","bt":"תקמו או תקס","bp":"וארשא","dt":"תרמד - כב טבת","dp":"צפת","b":"עלה לצפת-תקעז עם אביו, תלמיד ר אברהם מאבריטש, עמד בראש קהילת החסידים כארבעים שנה החל משנת תרא. בדרכם נשבו על ידי שודדי ים יוונים אמו ואחיותיו (הגדולה נפדתה ברודוס והקטנה שוחררה לאחר שבפקודת הקיסר נשלחו מאזמיר אוניות מלחמה לשחררה. לאחר הרעש ממנו ניצל נשא בזיוו\"ש את בתו של ר אשר זליג ברבש שהיה עשיר גדול, ומאז הקים ספריה גדולה ובין ספריו היו כתבי יד מהאר\"י שמהם שלח למחותניו האדמורים. חיבר \"טהרת הקדש\" צפת תרכד, ועוד. נספד מאת ר אברהם משה רעלימאן ב\"שם משמואל\" - בתוך \"אבל משה\" - ירושלים תרמד. בנו - זאב וולף - מנהל ביה\"ח \"משכיל אל דל\" בצפת. חתנו - ר יצחק לוברבוים.","bk":[["דרך נשר – על העופות החדשים",""],["כבוד מלכים – שריפת בגדים חדשים במדורת ל\"ג בעומר",""]]},{"i":15956,"n":"הלר, שמשון הלוי מראדשין","f":"אברהם הלר","b":"רב בראדשין-ת\"פ"},{"i":15957,"n":"הלר, שמשון מאוזיראן","f":"משלם פיבש מזבאריז","k":"אדמור מאוזריאן","r":"בן המהרש\"ם ואב\"ד חאצמער","bt":"תקמב","dt":"תר-כח - יט חשון","dp":"לשקוביץ","b":"חתן ר יוסף יוסקא מוולוטשיסק, וחתן ר יוסף הלוי הורביץ מיאסי. אדמור באוזריאן ובנו ר בנימין זאב גוטסמן על מקומו אחריו. בנו ר יוסף גוטסמן אדמור על מקומו בלשקוביץ. חיבר \"נזירת שמשון\" בתוך ספר אביו \"יושר דברי אמת\". נסע לר ישראל מרוזין שהחשיבו מאוד. אצל אלפסי תאריך פטירתו תרכח."},{"i":15958,"n":"הלר, שמשון מקולומיאה","f":"שלמה","k":"הו\"ל יושר דברי אמת","bt":"תר","dt":"תרע","b":"מחכמי קולומיאה שעסק במסחר. הוציא לאור \"יושר דברי אמת\" לזקנו מונקטש תרסה עם הוספה משלו."},{"i":15959,"n":"הלר-כהנא, חיים יוסף דב","f":"יחיאל","dt":"תרנא","b":"נכד בעל \"קונטרס הספיקות\" מסיגט. מחכמי קראסנא וסירב לרבנות. מתורתו ב\"מקור דמעה\". חתניו ר עמרם בלום בעל \"בית שערים\" ור משה נתן יונגריז בעל \"תורת משה נתן\"."},{"i":15960,"n":"הלר-כהנא, יוסף מרדכי מסיגט","f":"יהודה-קונטרס הספיקות","dt":"תקצד - ב אדר","dp":"קוסוב","b":"חסיד האדמור ר מנחם מנדל מקוסוב בעל \"אהבת שלום\". בנו של בעל \"קונטרס הספיקות\". חתן הגביר ר בנימין אביש בלוך מנדבורנה. סירב לרבנות סיגט, אך התרצה לכהן כדיין. מקורב לאדמורי קוסוב ר מנחם מנדל בעל \"אהבת שלום\" וחברו של בנו בעל \"תורת חיים\". וביקש להיקבר ליד רבו בקוסוב."},{"i":15961,"n":"הלר-כהנא, כתריאל","f":"יחיאל כהנא","dt":"תרלט - ג תשרי","b":"רב בסאלקא-תר\"ו"},{"i":15962,"n":"הלר-כהנא, צבי הירש מסיגט","f":"משה","k":"בעל בית הלל","dt":"תרנה","b":"נכד בעל \"קונטרס הספיקות\". מחכמי גרוסורדין-תרלד, תלמיד ר שלמה זלמן אולמן בעל \"יריעות שלמה\" במאקאווא, ור הלל ליכטנשטין. עבר לסיגט-תרנג וערך עתון \"סיגעטער צייטונג\" ובו לחם נגד עתוני המשכיל ר הירש לייב גוטליב."},{"i":15963,"n":"הלר-מירלש, אברהם ישראל הלוי","k":"בעל הגהות לילקוט שמע","b":"חיבר הגהות לילקוט שמעוני - פפד\"א תסט."},{"i":15964,"n":"הלר-מירלש, אהרן מולרשטין","b":"רב בולרשטין-ש'. בנו ר יעקב קאפל, נכדו ר נפתלי צבי מפולדא, אביו של ר יעקב דוד ניימארך מירלס מוינה אבי משפחת מירל'ס מאשכנז."},{"i":15965,"n":"הלר-מירלש, אהרן מולרשטין","b":"ראש משפחת הלר-מירלש-ניימרק. רב בולרשטין-ש'. בנו ר יעקב קאפל, נכדו ר נפתלי צבי מפולדא, אביו של ר יעקב דוד ניימארך מירלס מוינה אבי משפחת מירל'ס מאשכנז."},{"i":15966,"n":"הלר-שטין, מנחם נחום מבריסק","k":"מנחם נחום טראספולר","dt":"תקצא","dp":"בריסק","b":"רב בבריסק. אחיו - ר אליהו יוסף מטראספול."},{"i":15967,"n":"הלרינג, אליעזר דב מירושלים","b":"גבאי חברת תפארת בחורים (בזמן שכיהן שם ר יוסף שלום אלישיב), חתם-תשכו על שטר חוב של ר יוסף שלום אלישיב."},{"i":15968,"n":"הלרמן, יצחק משה מדרוהוביטש","bt":"תרנה","dt":"תשב","b":"למד בביהמ\"ד בברלין-תרעד. מורה בלייפציג-תרף, מנהל בית היתומים בפירט. נספה בשואה."},{"i":15969,"n":"הלרמן, שמריהו מגריווא","f":"אליעזר","b":"מראשי קהלת גריווא, יסד ביכנ\"ס בגריווא-תקצא, עם ר יעקב יעקובזון, ובימ\"ד-תרח עם ר יהושע שלוכטמן."},{"i":15970,"n":"הלשטוק, אברהם יצחק הלוי","f":"יחזקאל","bt":"תרמז","bp":"סקרנביץ","dt":"תשג","b":"רב במונדזשייא, אוסטרובצה. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":15971,"n":"הלשטוק, אלימלך","f":"יחזקאל","dt":"תשג","b":"רב בנאשעלסק"},{"i":15972,"n":"הלשטוק, חיים הלוי","f":"יחזקאל מאוסטרובצא","b":"חתן האדמו\"ר מאלכסנדר. פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר, \"נהור שרגא\" - אלכסנדר תרצט."},{"i":15973,"n":"הלשטוק, יחזקאל הלוי מאוסטרובצא","f":"מאיר יחיאל מאוסטרובצ","k":"אדמור מאוסטרובצא","bt":"תרמז","bp":"סקרנביץ","dt":"תשג - י טבת","dp":"צויזמיר","b":"חתן ר נפתלי ממעליץ (שושלת רופשיץ). למד עם תלמידי אביו שנשלחו אליו - ר עמנואל מבנדין, ור יהודה מאיר מקראקא - על מנת להכשירו לרבנות. רב באינוולודז-ליד טומשוב-תרעא, נאשלסק-תרפא, רב ואדמו\"ר באוסטרובצה-תרפח על מקום אביו. הקים רשת ישיבות \"בית מאיר\" ועמד בראשן. נספה בשואה. חיבר \"קדשי יחזקאל\". הסכים על קובץ תלמידיו \"בית מאיר\" - אוסטרובצא - פיעטרקוב - תרצא. נספה בשואה עם משפחתו ובהם בנו - ר יעקב."},{"i":15974,"n":"הלשטוק, יעקב הלוי מאוסטרובצא","f":"יחזקאל מאוסטרובצא","dt":"תשג","b":"ראב\"ד באוסטרובצא אצל אביו - האדמור. נספה בשואה עם אביו ומשפחתם."},{"i":15975,"n":"המאירי, מנחם","k":"בעל בית הבחירה","bt":"ט'","dt":"עה","b":"מגדולי הראשונים מפרשי התלמוד,מרביץ תורה בפירפיניאן"},{"i":15976,"n":"המבורג, אברהם בנימין מפיורדא","k":"בעל שער הזקנים","bt":"1770","dt":"תרי - ב סיון","b":"תלמיד ר משלם זלמן מפיורדא. רב בפיורדא. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז. חיבר גם \"שמלת בנימין\", \"אלון בכות\" - הספד על ר אברהם נפתלי שייער בעל \"מספד המשנה\", \"קול בוכים\" ובו הספד על רבו - ר משלם זלמן מפיורדא, ועוד.","bk":[["מספד",""],["מספד המשנה",""],["שער הזקנים",""]]},{"i":15977,"n":"המבורג, אברהם בר מקרוז","b":"דיין בקרוז'-תרן, אצל ר זאב וולף טורבוביץ."},{"i":15978,"n":"המבורג, אברהם מלונדון","f":"שלמה","k":"בעל עלי תרופה","b":"מחכמי לונדון. חיבר \"עלי תרופה\" על תרופה לאבעבועות, \"מרכבת המשנה\" על מסכת ברכות, ועוד."},{"i":15979,"n":"המבורג, אפרים מגרוניגן","b":"רב בגרוינינגן-הולנד-תרעד."},{"i":15980,"n":"המבורג, בנימין וולף מפיורדא","b":"תלמיד בעל בגדי כהונה. רב בפיורדא-תקפ וראש ישיבה שם, מתלמידיו רבים מגדולי אשכנז. היה במחלוקת עם הריפורמים שפעלו כנגדו ונגד ישיבתו. חברו - החת\"ס."},{"i":15981,"n":"המבורג, בר מפפד\"מ","b":"מחכמי פפד\"מ-תפ בערך."},{"i":15982,"n":"המבורג, זכריה מנדל","b":"נכד ר רפאל הכהן מהמבורג. בנו - ר אברהם בהרב ממינסק."},{"i":15983,"n":"המבורג, יוחנן מפפד\"מ","b":"מחכמי פפד\"מ-תפ בערך."},{"i":15984,"n":"המבורג, יעקב","b":"מגדולי חכמי המבורג-תק\"י"},{"i":15985,"n":"המבורג, מאיר מהעלישוי","dt":"תקכ - כד תשרי","b":"רב בהעלישוי"},{"i":15986,"n":"המבורג, רפאל","f":"אברהם בהרב ממינסק","k":"הו\"ל מר שמואל","dt":"תרמז - ו טבת","dp":"מינסק","b":"נכד ר שמואל הכהן מאמדור. הו\"ל ספר שו\"ת זקנו בשם \"מר שמואל\"."},{"i":15987,"n":"המבורגר, אברהם אריה מירושלים","f":"משה מעיר חדש","dt":"תרעח - כג תשרי","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":15988,"n":"המבורגר, אהרן ליב מצעהלים","f":"יהושע המבורגר מפרג","dt":"תקמה - ט תמוז","dp":"צעהלים","b":"דומ\"צ בפרג, רב בצלם(=צעהלים)-תקיא על מקום ר דוד קויפמן ור יואב על מקומו אחריו."},{"i":15989,"n":"המבורגר, אהרן מירושלים","f":"משה מעיר חדש","dt":"תרעב - תמוז","dp":"ירושלים","b":"מחכמי ירושלים, חתן ר דוד שפר מפורינקירכן וירושלים."},{"i":15990,"n":"המבורגר, אורי פיבוש","f":"הירץ מברסלוי","b":"רב בלונדון-תס. חיבר \"אורים ותומים\" בענין מחלוקת על גט."},{"i":15991,"n":"המבורגר, אליעזר ממפדמ","b":"מחכמי פפדמ-תרסג. חתן ר בנימין שלמה זלמן הלוי שפיצר מוינה."},{"i":15992,"n":"המבורגר, בנימין שלמה זל' מפריז","f":"אליעזר מפפדמ","dt":"תשב","b":"תלמיד הדעת סופר. רב במונטרה (שוייץ), דיין בפריז-תרצד. נספה בשואה."},{"i":15993,"n":"המבורגר, חיים","k":"בעל שלשה עולמות","b":"נכד ר משה נאועמעסטא, וחיבר ספר לתולדות משפחתו."},{"i":15994,"n":"המבורגר, יהודה ליב מצעלם","b":"רב בצלם-תק\"מ"},{"i":15995,"n":"המבורגר, יהושע מפרג","b":"מגדולי חכמי פרג-ת\"פ"},{"i":15996,"n":"המבורגר, יוסף ליב מירושלים","b":"מחכמי ירושלים, יסד גמ\"ח ספרים, שכנראה עברו אחר כך לישיבת עץ חיים."},{"i":15997,"n":"המבורגר, יעקב אריה מזבורוב","b":"אב\"ד זבורוב, פשוורסק, יאס, רובנה, ורב בברודי."},{"i":15998,"n":"המבורגר, יעקב מעקלנברוג","r":"ראש ב\"ד בפראג","bt":"תקפז","bp":"לאסלוי (שלזיה)","dt":"תרעב - א חשון","dp":"אלט שטרליץ","b":"תלמיד הכת\"ס, וישיבות הוצנפלוץ וניקלשבורג. רב בניישטט-תריב ומתרטו גם רב האיזור. רב המדינה מקלנבורג-שטרליץ וישב באלט-שטרעליץ, רב בניי-שטרליץ.","bk":[["קול קול יעקב - ש\"ס שו\"ע ועה\"ת",""]]},{"i":15999,"n":"המבורגר, יצחק מאמשטרדם","b":"דיין בביה\"ד האשכנזי באמשטרדם-תקע."},{"i":16000,"n":"המבורגר, יצחק מקראקא","f":"אפרים פישל","k":"בעל שיח יצחק","bt":"תקץ","bp":"קראקא","dt":"תרס","b":"מחכמי קראקא, למברג וברודי - שם נתפס להשכלה אך חזר בתשובה וקיבל לתרגם ספרי מוסר לאידיש. רב בפודגורזע. תרגם ספר \"חיי אדם\" לאידיש, למברג תרכז, \"שיח יצחק\" למברג תרלג, ועוד."},{"i":16001,"n":"המבורגר, מאיר הלוי מפרשבורג","f":"משה נאוואמסטא-שלזינג","bt":"תקצז","bp":"פרשבורג","dt":"תרפא - יז אב","dp":"ירושלים","b":"תלמיד הכת\"ס, ור יואל אונגר מפאקש. חתן ר קופל בלטנר מיפו-תריז. עלה לארץ עם אביו-תריז והתישב ביפו וכיהן כשו\"ב, ירושלים."},{"i":16002,"n":"המבורגר, מאיר מברלין","b":"מראשי הקהילה בברלין. חתם על הסכם ויתור מס הקהילה ממשה מנדלסון-תקכג."},{"i":16003,"n":"המבורגר, מרדכי מלונדון","f":"משה הכהן מאלטונא","b":"חתן גליקל האמיל בעלת \"זכרונות גליקל\". היגר מאשכנז ללונדון, עסק במסחר בהודו והתעשר, חזר ללונדון ויסד קהלה חדשה וביכנ\"ס. נזכר ב\"מגילת ספר\", \"זכרונות גליקל\"."},{"i":16004,"n":"המבורגר, משה מבנדין","f":"אהרן רוקח מלמברג","b":"גיסו של ר אלימלך מליזנסק. רב בבנדין כ-30 שנה."},{"i":16005,"n":"המבורגר, משה מנאוואמעסטא","f":"יוסף ישראל ארוויץ","bt":"תקסא","bp":"עיר חדש = נאוואמסטא","dt":"תרמח - ג כסלו","dp":"ירושלים","b":"תלמיד החת\"ס. חתן ר אברהם אריה קונשטאט מפרשבורג ועבר לשם. עלה לירושלים-תריז והיה ממיסדי כולל אונגרן. חתניו - ר שאול יעקב סלומון מירושלים, ור יצחק בעער מירושלים. נתבקש ע\"י מהר\"ם שיק מחוסט לשלוח אליו מירושלים את כל הדברים שראה וידע מהחת\"ס."},{"i":16006,"n":"המבורגר, משה מעיר חדש בוסקוביץ","b":"אב\"ד עיר חדש(=נאוי-מעסטא), בוסקוביץ-תקכו. ישב בבוררות ביערגן-תקכא כדיין מכריע יחד עם ר יוסף יעקב סטופאווא מסעניץ - בסכסוך שבין קהלות פרשבורג שטמפן וסערדהאלי - יחד עם נציגי הקהלות ר שמעון דוד מסערדהאלי, ר יצחק איזיק קאליש, ר יצחק לנדא כנציג פרשבורג. חתניו: - ר זליג בן מרדכי סגל מעיר חדש, ר שמואל פישהוף. (היה רב נוסף באותו השם - יש בלבול באוצר הרבנים)."},{"i":16007,"n":"המבורגר, נתן צבי נטע הרש","f":"משה מעיר חדש","dt":"תרעב - יב שבט","dp":"ירושלים","b":"חתן ר ראובן בן ירוחם הכהן מירושלים. מחכמי ירושלים."},{"i":16008,"n":"המבורגר, פנחס מירושלים","f":"משה מעיר חדש","dt":"תרסח - ה אדר","dp":"ירושלים","b":"מחכמי ירושלים. מחותן עם ר אפרים בנימין מקאמין."},{"i":16009,"n":"המבורגר-שפיץ, י' ליב","b":"דיין באמסטרדם-תש\"ט"},{"i":16010,"n":"המוגרבי, חיים","b":"מגדולי המקובלים בדרעא(מרוקו)"},{"i":16011,"n":"המון, אברהם מפורטוגל","b":"מחכמי פורטוגל. בנו ר חיים מהושקא שעלה לארץ וחכמי הושקא כתבו לו אגרת מליצה לעזור לו לאחר שנשדד והתרושש - בין החותמים ר מיכאל הכהן מקנדיא."},{"i":16012,"n":"המון, אברהם מצפת","f":"יוסף","b":"מחכמי צפת, חתם-תקכד על כתב שליחות ר מרדכי בונאן."},{"i":16013,"n":"המון, אברהם מקושטא - א","f":"יוסף","b":"קושטא-שמח. חתנו - ר מרדכי מטוילי."},{"i":16014,"n":"המון, אברהם משלוניקי","dt":"תקל - ח סיון","dp":"שלוניקי","b":"גביר מראשי קהלת שלוניקי, נפטר במגיפה-תקל."},{"i":16015,"n":"המון, אהרן מקושטא","f":"יהודה","b":"גביר, בלשן ומשורר מחכמי קושטא, עבר לאדרינופול וחזר לקושטא-תפ בערך. חיבר הקדמה ל\"מעין גנים\", \"שמאל ישראל\". קרובו או אחיו של ר יהודה המון."},{"i":16016,"n":"המון, חיים יעקב מקושטא","b":"מחכמי קושטא, דיין-תקז, אב\"ד."},{"i":16017,"n":"המון, יהודה מאדרינופול","dt":"תלח - כה אייר","dp":"אדרינופול","b":"רופא באדרינפול."},{"i":16018,"n":"המון, יהודה מקושטא","dt":"תח","dp":"קושטא","b":"גביר וחכם שלם בקושטא."},{"i":16019,"n":"המון, יום טוב מקושטא","f":"אהרן","bt":"תרלג","bp":"קושטא","b":"משפטן ופעיל צבור בקושטא, שופט בירושלים-בזמן התורכים."},{"i":16020,"n":"המון, יוסף מספרד וקושטא","f":"משה","b":"ממגורשי ספרד-רנב, רופא השולטן סלים בקושטא. משורר ועמד בקשרים עם ר גדליה ן יחיא משלוניקי. בנו - הרופא ר יצחק."},{"i":16021,"n":"המון, יוסף משלוניקי","dt":"רצא - ז טבת","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":16022,"n":"המון, יצחק","b":"תלמיד ר חיים מנחם פראנג'י-תרכה."},{"i":16023,"n":"המון, יצחק הרופא מקושטא","f":"יוסף הרופא מקושטא","b":"רופא בקושטא, ומקורב למלכות כאביו לפניו."},{"i":16024,"n":"המון, יצחק מקושטא","b":"דיין בקושטא אצל ר אליהו פאלומבו."},{"i":16025,"n":"המון, משה מירושלים","b":"מחכמי ירושלים, בשנת שמז חתם על תקנת המס."},{"i":16026,"n":"המון, משה מספרד וקושטא","f":"יוסף","bt":"רנא","bp":"ספרד","dt":"שכה","b":"מגדולי חכמי ספרד,בגירוש עבר לקושטא-רנב. רב ורופא חצר הסולטן בקושטא על מקום אביו ור יהודה די שיגורה על מקומו אחריו (כאשר בנו - ר יוסף המון - רופא גם הוא בחצר). עזר רבות ליהודים בזכות השפעתו בחצר הסולטן, סייע בידי קהילת שלוניקי לאכוף את תקנותיה. הודח מכהונתו-רפ בגלל עלילה ולאחר זמן חזר לתפקידו, השתתף במסע המלחמה של הסולטן בפרס-רצד, והביא מבגדד את ר יעקב בן יוסף טאווס שהדפיס תורה עם תרגום לפרסית ולערבית. הקים ישיבה בקושטא והעמיד בראשה חכם משלוניקי. מתשובותיו בספרי חכמי דורו."},{"i":16027,"n":"המון, עובדיה מצפת","b":"רב בצפת. נזכר ב\"משפט שמואל\" לר שמואל קלעי."},{"i":16028,"n":"המילבורג, אורי פיבש מאמשטרדם","f":"יוזביל","b":"מחכמי אמשטרדם, הו\"ל משניות עם פירושים ובהם \"לחם משנה\" והוא קיצור תוי\"ט, ולקוטים מ\"קול הרמז\" - אמשטרדם תפו."},{"i":16029,"n":"המכירי, נתן","f":"רבינו מכיר","k":"בעל פירוש לתפלה","b":"מגדולי הפוסקים הראשונים בחכמי אשכנז וצרפת-ד'תת\"מ"},{"i":16030,"n":"המלן, משה","b":"רב בפייערסדורף-ת\"פ,בן האשה הנודעת מרת גליקל המלן,בעלת ספר הזכרונות בשבעה חלקים"},{"i":16031,"n":"המעילי מאיר מנרבונה; בלוי משה יהודה","bt":"1912","dt":"ה'תשסג 2003","bk":[["ספר המאורות",""]]},{"i":16032,"n":"המעילי, מאיר מספרד","k":"בעל שיטות על הש\"ס","b":"מגדולי חכמי ספרד-שנת ס'. חיבר שיטות על השס"},{"i":16033,"n":"המר, זאב וולף מבלשביץ","k":"בעל דרישת הזאב","bt":"תקף","dt":"תרנג - טו תמוז","b":"רבה של בלשביץ-תרלו, סטרי-תרכה. חיבר \"דרישת הזאב\" אך נשרף באמצע ההדפסה. ?? לא באוצר ??"},{"i":16034,"n":"המר, יעקב יוסף מסניאטין","f":"שמואל","bt":"תריז","dt":"תרעז","b":"חתן ר דוד מאיר באב\"ד מפוביזנא. רב בפרובזינא לצד חותנו. סניאטין לצד חותנו וראב\"ד על מקומו כשעלה לארץ. בזיוו\"ש חתן ר משה וייס מדיאר-לאפוש."},{"i":16035,"n":"המר, ישעיה ממישלניץ","f":"שאול","k":"בעל ענף אבות","bt":"תקף","dt":"תרס","b":"רב במישלניץ ובקראקא. חיבר \"ענף אבות\" קראקא תרמט."},{"i":16036,"n":"המר, צבי הכהן מסטרליסק","b":"תשובה אליו - \"שושנים לדוד\"."},{"i":16037,"n":"המר, רפאל מקומפלונג","b":"מחכמי פמורן, עבר לזלוטשוב, רב בקומפלונג."},{"i":16038,"n":"המראני, אלעזר","b":"רב בטהראן"},{"i":16039,"n":"המרלינג, אורי מיברוב","dt":"תרלב - אחרי","b":"רב ביברוב, אב\"ד בקשביץ."},{"i":16040,"n":"המרלינג, חיים יהודה ליבוש","f":"יוסף משטערויץ","bt":"תרל","dt":"תשב","b":"חתן ר אשר זליג אפטוביצר מיזירנה. רב בלופאטין-תרנה של חסידי בלז והיה שם מחלוקת עם חסידי הוסיאטין. נספה בשואה (עדות אחת מוסרת כי משומד בן העיירה הכהו למוות)."},{"i":16041,"n":"המרלינג, יוסף משטרויץ","f":"עקיבא משטרויץ","bt":"תרו","dt":"תרעו","b":"רב בשטרוויץ(=שטערויץ)-תרכה כיובל שנים על מקום אביו. בנו - ר חיים ליב מלאפ."},{"i":16042,"n":"המרלינג, יצחק צבי הירש מירוסלב","f":"אורי","bt":"תרי","dt":"תרפה","b":"למד בפשמישל אצל ר\"י שמלקיס וערך את המפתחות לספרו ח\"א. רבה של בשקביץ-תרמב. ראב\"ד ירוסלב-תרמט. קיבל היתר מאה רבנים ובזיוו\"ש חתן ר אליעזר צבי ספרין. רב ברוזניאטוב(=רעזניא). בנו ר פנחס על מקומו בירוסלב."},{"i":16043,"n":"המרלינג, עקיבא מקראס","dt":"תש..","b":"חתן ר\"ש פירר. נספה בשואה."},{"i":16044,"n":"המרלינג, עקיבא משטרוויץ","f":"[משה מרדכי]","dt":"תרכה או תרכח","b":"נכד הג\"ר מרדכי מרדוש ויינרב. רבה של שטרוויץ. בנו ר יוסף על מקומו אחריו-תרכה."},{"i":16045,"n":"המרלינג, פנחס מירוסלב","f":"יצחק צבי הירש מירוסל","bt":"תרל","dt":"תש","b":"ראב\"ד ירוסלב-תרע על מקום אביו. נספה בשואה."},{"i":16046,"n":"הנדין, יהושע ממינסק","f":"משה יהושע הנדין","bt":"תרטז","dt":"תרעט - כב חשון","b":"מו\"צ במינסק"},{"i":16047,"n":"הנדין, יעקב יצחק","dt":"תשג","b":"רב בפינסק"},{"i":16048,"n":"הנדין, משה יהודה ליב ממינסק","b":"מו\"צ במינסק-תר\"כ"},{"i":16049,"n":"הנדל מוינה","b":"רב בווינה-ש\"ע"},{"i":16050,"n":"הנדל, אברהם אהרן","b":"חתם-תרפה בוארשא עם ראשי ישיבת 'מתיבתא' בוארשא. אב\"ד דוואלנסקי והגליל."},{"i":16051,"n":"הנדל, יצחק","b":"תלמיד ישיבת אוטואצק. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":16052,"n":"הנדל, מאיר מראדום","b":"תלמיד ישיבת אוטואצק. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":16053,"n":"הנדלב, יעקב אהרן מבאחמאטש","f":"שניאור זלמן","k":"בעל נעם מגדים","bt":"תריז","b":"חתן ר משה חאייטין מבארזנא. רב בבחמאטש-תרנח. חיבר נעם מגדים על הפמ\"ג."},{"i":16054,"n":"הנדלס, מאיר מלאסק","b":"חתן ר איצק גאלדעס(=יצחק גולדעס) מלוסק. גביר מחכמי לוסק. מבניו: ר שמואל מקמפנא, מחתניו: ר משה וישעגראדער מלוסק, נכדו ר איצק לסקר מלובראניץ."},{"i":16055,"n":"הנדלס, מנחם מנדל מאשוואר","f":"יעקב","b":"מחבורת חסידי קאליב באשוואר."},{"i":16056,"n":"הנדלס, פיבל מלודז","b":"מרביץ תורה בישיבת תורת חסד בלודז-תר\"ס"},{"i":16057,"n":"הנדלס, שמואל מקמפנא","f":"מאיר מלוסק","b":"דיין ומו\"ץ בקמפנא."},{"i":16058,"n":"הנדלסמן, אברהם צבי","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":16059,"n":"הנדלסמן, יעקב מראדום","b":"גביר בראדום, חתניו - ר יואב וינגרטן בעל חלקת יואב, ר משה נתן כהנא-שפירא בעל 'שמן למאור'."},{"i":16060,"n":"הנדלסמן, יעקב נתן נטע","k":"בעל נתיבות אור","b":"רב בקלצק-תרמ. אולי הוא ר יעקב מראדום - חותנו של ר יואב יהושע וינגרטן בעל \"חלקת יואב\"."},{"i":16061,"n":"הנדלר, יעקב מדוקלא","b":"מחכמי דוקלא-תרפט. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":16062,"n":"הנדלר, יעקב משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":16063,"n":"הנדלר, מרק מהאוואש","b":"רב הקהלה הניאולוגית בהאוואש, הקהילה הניאולוגית בטאטא. פרסם מאמרים ב\"בן חנניה\". פרסם מאמרים ב\"בן חנניה\". בנו שמעון האוואשי כיהן כרב הניאולוגי הראשי בבודפשט."},{"i":16064,"n":"הנדלר, שלום ממישלניץ","f":"משה","bt":"תרעה","bp":"מישלניץ","dt":"תשג","b":"תלמיד בישיבת בובוב. נספה בשואה."},{"i":16065,"n":"הנדלר, שמואל בן ציון","k":"בעל אמונת ישראל","bp":"שטמפן","dt":"תקפד - י טבת","dp":"שטמפן","b":"חיבר \"אמונת ישראל\" - פרג תקפג."},{"i":16066,"n":"הנדלר, שמריה הכהן מקולבסוב","dt":"תשב","dp":"ניו יורק"},{"i":16067,"n":"הנדלר, שמשון מלאפוש","b":"רב ניאולוגי בלאפוש על מקום ד\"ר לאיוש ונציאנר, רב בביהכ\"נ הגדול בבודפשט."},{"i":16068,"n":"הנובר נתן נטע בן משה","f":"משה מאוסטרהא","k":"בעל שערי ציון","bt":"1620","dt":"תמג - כ תמוז","b":"עק\"ה,מקובל,סופר,דרשן,רשם מאורעות ימיו,רב בזסלב,נמלט לאשכנז-בגזירת ת\"ח,הולנד איטליה,רב בליוורנו,רומניה,יאס,פוקשני,אונגריש-ברוד","bk":[["יון מצולה - היסטוריה",""],["טעמי סוכה",""],["יון מצולה",""],["שערי ציון",""],["שפה ברורה",""]]},{"i":16069,"n":"הנובר, יוסף מהמבורג","f":"שמואל זנויל מהמבורג","dt":"תרה","dp":"אה\"ו","b":"סגי נהור, מחכמי הקלויז בהמבורג-תקפא."},{"i":16070,"n":"הנובר, שמואל זנויל מהמבורג","f":"יוסף","k":"בעל רפואת הנפש","dt":"תקפו - כז טבת","dp":"אלטונא","b":"חתן ר מרדכי יפה משוערין. מחכמי ביהמ\"ד הישן בהמבורג, בקי בדקדוק, מגיה המחזור שנדפס בדפוס ר שמואל באנן ונזכר בהקדמה למחזור אלטונא-תקסד. היה מחלוקת כנגדו מצד המדקדק ר איזיק ברלין. בניו - ר יוסף, ר איזיק."},{"i":16071,"n":"הנוסע האלמוני - ירושלים","b":"כמה רבנים אלמונים שהיה בירושלים."},{"i":16072,"n":"הניג, אליהו מירושלים","b":"סופר חברת עזרת נדחים ומושב זקנים בירושלים-תרמה."},{"i":16073,"n":"הניג, אלעזר מגרוסורדין","f":"יעקב בן מרדכי ממונקט","k":"בעל זכרון יעקב-תשא","b":"חתן ר אפרים פישל אפשטין, וגיסו של ר אהרן אפשטין מפרג. מחכמי גרוסורדין. נספה בשואה."},{"i":16074,"n":"הניג, יוסף","dt":"תרמח - יב תמוז","b":"ראב\"ד במיאווא,רב בנייטרא"},{"i":16075,"n":"הניג, נפתלי הרץ משארמאש ונ\"י","f":"שמחה יוסף מסיגט","k":"בעל תפארת נפתלי-תשמא","bt":"תרנח","dt":"תשמה - יד ניסן","b":"נכד ר יעקב פרץ זילברמן בן ר נפתלי האדמור מרצפרט. תלמיד בעל \"עצי חיים\", ר יהודה גרינוולד, ור ישעיה זילברשטין. חתן ר שלמה יהודה בראך מלכנזיץ. רב בשארמאש-ליד טודרה-תרפד וראש ישיבה שם. ניצל מהשואה ואחריה רב מחנה פוקינד וואלדשטדט בגרמניה וראש ישיבה שם בחסות האדמור מצאנז. היגר לארה\"ב וכיהן כרב בניו יורק, וכיהן בהוראה בלשכת ההוראה של התאחדות הרבנים בארה\"ב."},{"i":16076,"n":"הניך","dt":"תרה - ז שבט","b":"דיין ביאס"},{"i":16077,"n":"הניך מסטוצין","b":"ר\"מ בבישיבת \"ענף כנסת ישראל\" בסטוצין אצל ר ליב חסמן-תרעב. (לא ידוע שם משפחתו)."},{"i":16078,"n":"הניך, שמואל משאוולאן","b":"רב בשאוולאן-תרפא."},{"i":16079,"n":"הנלדר, יצחק הכהן מבאיאר-וואגאש","b":"בנו ר אברהם מתל אביב, וחתנו ר צבי קינסטליכר מסעבען-תרנו."},{"i":16080,"n":"הנלין, ישראל יחיאל אלתר מפאלאצ","f":"אהרן מהורודוק","bt":"תרכב","b":"תלמיד דודו ר אליהו חאנעלעש בעל \"יד אליהו\". חתן ר שניאור זלמן שניאורסון הדמור מקפוסט בעל \"מגן אבות\". רב בפלאצק-תרנז. נסמך מאת אחי חותנו - ר שמריהו נח מבוברויסק."},{"i":16081,"n":"הנקין, אליעזר מקלימוביץ","f":"אברהם","b":"ראש ישיבה בקלימוביץ. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה. בנו - ר יוסף אליהו."},{"i":16082,"n":"הנקין, יהושע אליעזר","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":16083,"n":"הנקין, מרדכי דוד (דב) מליטא","bt":"תרמב","dt":"תשג","b":"רב בפאנעמון, רבה האחרון של שאדובה. נספה בשואה. פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":16084,"n":"הנקלש, ליב","b":"מגדולי חכמי פרג-ת\"ק"},{"i":16085,"n":"הנרי, ה' מארה\"ב","k":"בעל אמרי שפר","b":"מחכמי ניו יורק. חיבר \"אמרי שפר\" נ\"י תקצח."},{"i":16086,"n":"הנריקוס, חיים יאשיהו הכהן","dt":"תריט","b":"רב בקורסאו."},{"i":16087,"n":"הנריקס מיראנדה, אברהם משלוניקי","dt":"תקך","dp":"שלוניקי","b":"גביר בשלוניקי. סייע - יחד עם אחיו יוסף בהדפסת \"מאיר לארץ\" לר מאיר ביקיאם ואירחוהו בביתם, סייעו בהדפסת \"בתי כהונה\"-תקד, \"צרור הכסף\"-תקטז. ר אברהם סייע גם בהדפסת \"פרי האדמה\"-תקיב-תקטו."},{"i":16088,"n":"הנריקס מיראנדה, יוסף","dt":"תקטז - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי. סייע יחד עם אחיו אברהם בהדפסת כמה ספרים (ראה אצל אחיו)."},{"i":16089,"n":"הס, משה","k":"בעל רומי וירושלים","bt":"תקעב","dt":"תרלד"},{"i":16090,"n":"הסבא משפאלי","dt":"ו תשרי תקע\"ב"},{"i":16091,"n":"הסטן, משה מניזנוב","f":"יוסף מחודרוב","bt":"תקץ","dt":"תרלה","b":"מחכמי ניזנוב.ידידו האב\"ד רי\"מ היבנר השיב לו בספריו \"משכנות הרועים\" ועוד."},{"i":16092,"n":"הסינג, ישראל מגרוסורדין","b":"פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":16093,"n":"הספל, משה מגבוזדזיץ","dt":"תש..","b":"רב בגבוזדזיץ.בנו שלמה עלה לארץ - בעל פרדס בנתניה (תרעה-תשמב)."},{"i":16094,"n":"העלוויא לוגאר סאנטא, יצחק מירו","b":"שמש הכותל המערבי בירושלים-תרמב."},{"i":16095,"n":"העליס, אלתר חיים מזוואניץ","f":"יחיאל","bt":"תרטו","b":"רב בזוואנץ-פודוליה-תרם. בנו - ר שניאור זוסיא מקאליס."},{"i":16096,"n":"העליס, שניאור זוסיא מקאליס","f":"אלתר חיים מזווניץ","bt":"תרלג","b":"רב בקוליס(=קאליס)פודוליה-תרסב."},{"i":16097,"n":"העליץ, שמואל חיים מקושטא","b":"מגיה בדפוס ר יצחק אלחכים בקושטא-שי."},{"i":16098,"n":"העליר שמואל בן ישראל","bt":"1803","dt":"ה'תרמד 1884","bk":[["קונטרס כבוד מלכים",""]]},{"i":16099,"n":"העלמן הלוי","f":"משה סגל","b":"רב בשיינלינג"},{"i":16100,"n":"העלפגט, אפרים מנחם","bt":"תרנח","b":"מרביץ תורה בישיבת טלז"},{"i":16101,"n":"העלפט, משה מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":16102,"n":"הענא, חנוך הניך","f":"צבי הירש הענא"},{"i":16103,"n":"הענא, יצחק איזיק","f":"חנוך הניך הענא","b":"רב בפרדאן"},{"i":16104,"n":"הענא, מאיר שמואל מרוהטין","f":"משלם זלמן הלוי","bt":"תרי","dt":"תרצג","b":"רב ברוהטין."},{"i":16105,"n":"הענא, מרדכי מהמבורג","f":"יוסף יוזפא מהענא","k":"בעל ברוך מרדכי","r":"דיין דק\"ק המבורג","dt":"תקכז - יח אייר","dp":"אה\"ו","b":"מצאצאי בעל \"חות יאיר\", נכד ר יצחק ברילין ממנהיים. חתן ר שמשון חסיד. דרשן, דיין בהמבורג-תפד. מחותן עם ר יעקב עמדין ועמד לצדו של ר יונתן איבשיץ בזמן המחלוקת ועל כך היה מחלוקת גדולה בינו לבין מחותנו-היעב\"ץ. חיבר \"ברוך מרדכי\" ו\"שושנת המלך\" על הרמב\"ם, \"אגודת מרדכי\", ועוד.","bk":[["אגדת מרדכי - הגדה של פסח",""],["אורות מרדכי (כת\"י)",""],["גדולת מרדכי - חידושי שו\"ת וחידושי הלכות (כת\"י)",""],["דברי מרדכי - שו\"ת (כת\"י)",""],["דרישת מרדכי - אבות (כת\"י)",""],["השם מרדכי - חידושי ש\"ס כסדרן (כת\"י)",""],["ידיעת מרדכי (כת\"י)",""],["לבוש מלכות (כת\"י)",""],["מאמר מרדכי - מאמרי חז\"ל (כת\"י)",""],["מגדים חדשים (כת\"י)",""],["מגילת מרדכי - תרי\"ג מצוות (כת\"י)",""],["מעשה מרדכי - אגדות ירושלמי (כת\"י)",""],["פרשת מרדכי - מדרשים תמוהים (כת\"י)",""],["שושנת המלך וברוך מרדכי - רמב\"ם מדע אהבה זמנים (כת\"י)",""],["שירת מרדכי (כת\"י)",""],["תולדות הנשמה (כת\"י)",""]]},{"i":16106,"n":"הענא, נתן מפפד\"מ","dt":"שפא - כא אלול","b":"מרביץ תורה בפפד\"מ"},{"i":16107,"n":"הענא, צבי הירש","b":"רב באנסבך"},{"i":16108,"n":"הענא, שלמה זלמן הכהן","f":"יהודה ליב","k":"בעל צוהר התיבה","dt":"תקז - א תשרי","b":"מדקדק מחכמי אשכנז. חיבר \"צוהר התיבה\", \"בנין שלמה\" ועוד. היה מחלוקת נגדו מאת ר יעקב עמדן בספרו \"לוח ארש\", ואחרים - ור שלמה זלמן חיבר להגנתו \"צהר התיבה\" ו\"קורי עכביש\" כנגד \"עבותות אהבה\"."},{"i":16109,"n":"הענדילש, אברהם ישראל מקראקא","b":"מראשי קהלת קראקא. חתנו - ר יצחק איזיק מדוברובא או ואנגרוב (1945). חתן בתו - ר רפאל סופר לימא ישב אצלו בהיותו בקראקא."},{"i":16110,"n":"הענטשין, ישעיה דוב מקיעלץ","b":"רב בקיעלץ"},{"i":16111,"n":"הענין, שלמה זוסמן","f":"יהודה ליב","bt":"תרכד","b":"מו\"צ במינסק, רב בהאראדק-פלך מינסק-תרנה, אראן-פלך וילנא תרסג על מקום ר מתתיהו גדליה קבצניק."},{"i":16112,"n":"הענינגן, יצחק","b":"תלמידו בעל \"דבק טוב\" הזכיר חדושיו על רש\"י."},{"i":16113,"n":"העפער, מנדל מוארשא","b":"מראשי ה\"מתיבתא\" בוארשא. פרסם מאמרים ב\"הלפיד\" - וארשא תרצז."},{"i":16114,"n":"הערינג, יוסף מחעלם","b":"מרבני ישיבת חכמי לובלין"},{"i":16115,"n":"הערצקא, צבי מוינה","f":"משה מונא","bt":"תריג","bp":"פישטיאן","dt":"תרצד - יא אייר","b":"תלמיד הכת\"ס, והשב\"ס. חתן ר פנחס זוננשטין ממיאווע ועבר לשם-תרמג. מחכמי וינה."},{"i":16116,"n":"ה\"פ, רפאל ממנהיים","f":"זלמן","b":"דיין במנהיים, חתם-תקלד בהיינספורט עם ר צבי הירש נאמן קהלת היינספורט."},{"i":16117,"n":"הפולייש, אהרן","b":"מגדולי חכמי ספרד בזמן הגירוש,רב באדרונופולי-רנ\"ב"},{"i":16118,"n":"הפטמן, אליהו מבולחוב","f":"ישראל ליב","b":"רב בבולחוב-תרנט, כנראה היה בנו של ר ישראל ליב אב\"ד בולחוב וישב על מקומו."},{"i":16119,"n":"הפטמן, יוסף","f":"משה מתתיהו","bt":"1888","bp":"בריאנסק-פלך גרודנא","dt":"1955","dp":"תל אביב","b":"תלמיד ישיבות ליטא. עתונאי, פרסם מאמרים ב\"השלוח\" ועוד. הצטרף לתנועה הציונית ועבר בערי פולין במסע תעמולה ציוני. עלה לארץ, חזר לפולין והיה מפעילי המרכז הציוני בוארשא. חזר לארץ-1935 והיה עורך \"הבוקר\"."},{"i":16120,"n":"הפטמן, יצחק מסטרי","f":"אליהו נתן","b":"חסיד זידיטשוב. שו\"ב בסטרי על מקום אביו. מלחין ובעל תפלה."},{"i":16121,"n":"הפטמן, ישראל ליב מבולחוב","b":"מחכמי בולחוב-תרטו, נבחר לראש העיר. חתם מסטרי בשנת תר."},{"i":16122,"n":"הפטמן, משה מבולחוב","b":"רב בבולחוב-תרסד. חתן ר אליהו הורשובסקי אב\"ד דרוהוביטש. הספר \"אזור אליהו\" נדפס על פי תורות שרשם מחמיו."},{"i":16123,"n":"הפטר, דוד מטרנופול","f":"משה מעשיל","k":"בעל מאמר דוד","b":"מגדל גפנים ויצרן יין בהונגריה. חתן הגביר ר יצחק רייז מפרוביזנא ועבר לצורטקוב. עלה לארץ. חיבר \"מאמר דוד\" למברג תרן."},{"i":16124,"n":"הפטר, זאב וולף מלינסק","b":"מחכמי לינסק, תשובה אליו ב\"דובב מישרים\"-תרץ."},{"i":16125,"n":"הפטרמן, אברהם מארה\"ב","f":"אריה דב","k":"בעל היהדות לאור ההגד","bt":"תרנז","bp":"נמירוב-אוקראינה","b":"תלמיד ישיבת קישינוב אצל ר יהודה ליב צירלסון, ונסמך ממנו ומאת ר עוזר רובין מפרוסקורוב. רב בפלורשטי-בסרביה-תרפב, היגר לארה\"ב וכיהן כרב במנצסטר-ארה\"ב. חיבר \"רפי שוטה שנתשפה. פרסם מאמרים בעתוני התקופה. חבר אגודת הרבנים באמריקה, ותנועת המזרחי."},{"i":16126,"n":"הפרחי, אשתורי יצחק","f":"משה בן נתן","k":"בעל כפתור ופרח","bt":"ה'מ'-מג","bp":"פלורנציה - ספרד","dt":"קטו - לפני","b":"שם עירו פלורנצא(=פרח) ומכאן שמו. תלמיד הרשב\"א, הרא\"ש, ר נתן מטרונקטילה, ור אליעזר מקינון, וכן מזכיר את קרובו ר יעקב בן מכיר ן תיבון. הוגלה מצרפת בגירוש שנת ס\"ו, עבר לפרובנס ולמד אצל ר יעקב בן מכיר ממונפלייר. חיבר \"כפתור ופרח\" ועוד, עלה לארץ - סג או עב והתישב בירושלים ופגש את ר ברוך פנרוך-תלמיד הרא\"ש ואת ר מתתיה ולמד מהם והזכירם בספרו. חקר את מקום המקדש, וכן את גבולות הארץ, עזב את ירושלים בגלל מחלוקת (הקשורה לר שלמה הקטן והרמב\"ם), והתישב בבית שאן כדי לכתוב את ספרו, (הספר הגיע לספריית הנגידים במצרים והודפס בונציה שח), וכדי להראות שבית שאן בתוך גבולות הארץ, מגדולי חוקרי ארץ ישראל. חיבר גם ספרים ברפואה, ועוד.","bk":[["כפתור ופרח","הלכה ומנהג - ראשונים"],["כפתור ופרח – עניני ארץ ישראל",""]]},{"i":16127,"n":"הפרחי, יעקב","f":"יוסף","dt":"פב - ב תשרי","dp":"פלורנצה","b":"עק\"ה,מגדולי חכמי דורו"},{"i":16128,"n":"הפרחי, משה מפלורנצה-ספרד","f":"יוסף מקינון","k":"ר' משה הפרחי","dt":"פב - ב תשרי","b":"מחכמי פלורנצה-ספרד. נהרג עק\"ה-ה'פב. אביו של אשתורי הפרחי."},{"i":16129,"n":"הפרחי, נתנאל מאיטליה","f":"יוסף","k":"ר' נתנאל הפרחי","dt":"פב - ב תשרי","b":"עק\"ה,מגדולי חכמי איטליה,מרביץ תורה בפלורנץ"},{"i":16130,"n":"הפרין, אפרים זלמן","b":"נאמן האדמור ר ישראל מצורטקוב, קיבל מהאדמור מטבע לשמירה עם שמו עליו."},{"i":16131,"n":"הצמאן, חיים משלוניקי","f":"יצחק","bp":"מורביה","b":"רב בקהלת האשכנזים בשלוניקי-שכט על מקום ר יחיאל אשכנזי."},{"i":16132,"n":"הצפלד, משה ליב מהידנגספלד","b":"רב בהיידנגספלד"},{"i":16133,"n":"הקארו, דוד","f":"ראה קארו, דוד"},{"i":16134,"n":"הקשר, אלעזר מברוינשויג","f":"שמואל זנויל-דברי חדו"},{"i":16135,"n":"הקשר, מרדכי מהמבורג","f":"שמואל זנויל-דברי חדו","dt":"תקך - יח תשרי","dp":"אלטונא","b":"פרנס באה\"ו, היה מעורב במחלוקת ר יונתן איבשיץ ור יעקב עמדין והיה ממחנה היעב\"ץ,"},{"i":16136,"n":"הקשר, מרדכי מהמבורג","f":"אפרים","k":"בעל דרכים טובים","dt":"תקמז - ה ניסן","dp":"אלטונא","b":"מחכמי המבורג. חיבר פירוש למשלי, קהלת, שיר השירים, ועוד."},{"i":16137,"n":"הקשר, שמואל זנויל","f":"מאיר","k":"בעל דברי חידות","dt":"תעד - י אב","dp":"אלטונא","b":"מחכמי אלטונא. נזכר ב\"זכרונות גליקל\". בניו: ר אפרים בעל \"לוית חן\", ר מרדכי מהמבורג, ר אליעזר מברונשוייג."},{"i":16138,"n":"הר שושן, יצחק מפון","f":"יו\"ט ליפמן","k":"בעל אבל משה","b":"אב\"ד פון-פלך וילנא. חיבר \"אבל משה\" - הספד על מונטיפיורי - וארשא תרמו."},{"i":16139,"n":"הרב חיים נבון","r":"רב קהילת השמשוני במודיעין","bt":"תשלג בערך","bk":[["גשר בנות יעקב - מעמד האשה בהלכה",""],["הגדר הטובה - על משמעותה של ההלכה בחיינו",""],["חוה לא אכלה תפוח ועוד מאה טעויות נפוצות",""],["נאחז בסבך - מבוא להגותו של ר' יוסף סולובייצ'יק",""],["פרשות - אוסף של טורי פרשת שבוע",""],["תיקו - מאה ואחד מחלוקות יסוד",""]]},{"i":16140,"n":"הרב חכם רפאל אלשוילי זצ\"ל רבה הראשי של יהדות גרוזיה","k":"התשס\"ה","dt":"כג סיון"},{"i":16141,"n":"הרב מנחם מנדל ב\"ר אברהם קרוכמל","r":"מגדולי תלמידי הב\"ח ולמד שם יחד עם ה'טורי זהב', בעודו צעיר לימים נתמנה כאחד מדיני העיר בקראקא והב\"ח נתן לו רשות להנהיג ישיבה, בשנת שצ\"ו נתקבל לאב\"ד קרעמזיר, ואחר כך שמש ברבנות פרוסטיץ, ובשנת ת\"ח נתמנה לאב\"ד ניקלשבורג, בה כהן עד יום פטירתו. בשו\"ת 'עבודת הגרשני' כותב עליו: אשרי הדור אשר רבנו שורה בתוכו","bt":"1600","dt":"א חשון ה' תכא","bk":[["צמח צדק הראשון",""],["זמר נאה לכבוד התורה",""],["פי צדיק",""],["צמח צדק",""],["צמח צדק – שו\"ת",""]]},{"i":16142,"n":"הרב שלום ב\"ר עזרא שמאע שקאלו מחסידי ארם צובא","dt":"טו סיון"},{"i":16143,"n":"הרב שלמה גלמן -","dt":"כד תמוז"},{"i":16144,"n":"הרבי יהודה עייאש","bk":[["בית יהודה",""]]},{"i":16145,"n":"הרבסט, חיים הניך","b":"מהחותמי על הכתרת הדברי חיים-תקפח. בנו או אחיו - ר שלמה - יד ימינו של הדב\"ח."},{"i":16146,"n":"הרבסט, יצחק מקרעניץ","b":"מחכמי קרעניץ, תשובה אליו ב\"מנחת אברהם\"-תרצב."},{"i":16147,"n":"הרבסט, עוזיאל מצאנז","f":"שלמה","b":"מחסידי צאנז."},{"i":16148,"n":"הרבסט, פנחס אליהו מאיזביצא","b":"רב באיזביצא. הו\"ל \"אהל מועד\" - איזביצא - בילגוריי - תרפו, \"בית ועד לחכמים\" - סטמר תרפב."},{"i":16149,"n":"הרבסט, צבי מהוידונאנש","f":"חיים הניך","b":"חסיד הדברי חיים. עבר להונגריה בפקודת הדב\"ח - בגלל הצבא. גר בהוידונאנש ומראשי הקהל שם. חתן ר יעקב בוקסבוים. בנו ר יעקב עלה לרמלה-תשטז. לתולדות המשפחה \"שמע בני\" ירושלים תשמז."},{"i":16150,"n":"הרבסטמן, אליעזר מבריגל","b":"סופר בבריגל, מליץ. תשובה אליו \"אמרי יושר\" ו\"מחזה אברהם\"-תרעב."},{"i":16151,"n":"הרבסטמן-סתוי, יוסף","bt":"תרעג","bp":"גליציה","dt":"תשנד","dp":"ירושלים","b":"למד בישיבה בפפד\"מ, ובביהמ\"ד בברלין-תרצה. גורש לפולין וחזר לפולדא. היגר לאנגליה-תרצט. עלה לירושלים-תשז. שינה שמו ל-סתוי. ספרן הכנסת-תשיב."},{"i":16152,"n":"הרברג, שלמה יוסף","k":"בעל במעגל","bt":"1884","bp":"ניישטט-שאקי","dt":"1966","dp":"תל אביב","b":"תלמיד ישיבות סלובודקה, טלז, וולוזין. סופר ומחנך. עלה לארץ-1920 ועבד בהוראה. תרגם יצירות שונות לעברית."},{"i":16153,"n":"הרדאקר, משה מירושלים","f":"אהרן","dt":"תרטז - ב תשרי","dp":"ירושלים","b":"מחכמי ירושלים, האשכנזי הראשון שנקבר בבית הקברות של כולל הפרושים בירושלים."},{"i":16154,"n":"הרדאקר, צבי הירש","b":"רב בהרדק"},{"i":16155,"n":"הרה\"ק רבי דוד מקאצק","k":"זי\"ע","dt":"כב תמוז תרל\"ג"},{"i":16156,"n":"הרואה-שויער, ישראל","dt":"תרכא - כד אייר","b":"רב בבאנוביץ-סאבאטיטש"},{"i":16157,"n":"הרוש, אברהם מירושלים","b":"דיין בירושלים, שד\"ר למרוקו-תרכ\"ב"},{"i":16158,"n":"הרוש, אליהו","f":"אברהם","bp":"צפרו(מרוקו)","dt":"תרמג - ח סיון","dp":"צפרו","b":"מרביץ תורה, דרשן"},{"i":16159,"n":"הרוש, אליהו מצפרו-מרוקו","b":"מחכמי צפרו-מרוקו. חיבר פירוש לתורה, הגדה, ועל מאמרים בתלמוד - בכת\"י שהוחזק אצל נכדו ר שמעון חיים עובדיה."},{"i":16160,"n":"הרוש, דוד ממכנאס","dt":"תעה - אחרי","b":"מקובל מחכמי מכנאס-שנות ה-ת'. בנו - ר יוסף."},{"i":16161,"n":"הרוש, יהודה מצפרו-מרוקו","f":"נסים","b":"מחכמי צפרו-מרוקו, נגיד הקהלה-תע, נאסר-תפא ע\"י שר העיר ושוחרר."},{"i":16162,"n":"הרוש, יום טוב ממרוקו - ב","f":"מסעוד","b":"מחכמי מרוקו-שנות ה-ת' - תק'."},{"i":16163,"n":"הרוש, יום טוב מצפרו - א","b":"מחכמי צפרו-שנות ה-ת', הניח חדושים בכת\"י."},{"i":16164,"n":"הרוש, יוסף ממראקש","f":"יצחק","b":"מחכמי מראקש, חתם על פס\"ד-תקמז."},{"i":16165,"n":"הרוש, יוסף ממרוקו","f":"יצחק","b":"מחכמי מרוקו, חתם על פס\"ד-תפז עם ר יצחק חותא."},{"i":16166,"n":"הרוש, יחיא ממכנאס","f":"שלמה","b":"מחכמי מכנאס-שנות ה-ש'."},{"i":16167,"n":"הרוש, יעקב דידיע עדון ממכנאס","b":"מחכמי מכנאס-תקפו."},{"i":16168,"n":"הרוש, מכלוף ממרוקו","b":"מו\"ץ בכפר זא-מרוקו, שנות ה-תק'. נכדו - ר שלמה."},{"i":16169,"n":"הרוש, מכלוף מפאס","f":"מרדכי","b":"מחכמי פאס-שנות ה-ת'."},{"i":16170,"n":"הרוש, מסעוד ממכנאס","b":"מחכמי מכנאס, חתם-תפג על פס\"ד עם ר אברהם ן חסין."},{"i":16171,"n":"הרוש, מסעוד מצפרו-מרוקו","f":"יום טוב","b":"מחכמי צפרו-שנות ה-ת'."},{"i":16172,"n":"הרוש, נסים ממרוקו","f":"יוסף","b":"מחכמי צפרו, חתום על עדות עם ר שלמה אביטבול-תקלז."},{"i":16173,"n":"הרוש, ראובן ממכנאס","dt":"תרמו","dp":"טבריה","b":"מחכמי מכנאס. עלה לארץ והתישב בטבריה. נספד ע\"י ר משה ארזי הכהן בספר דרושים שלו בכת\"י."},{"i":16174,"n":"הרוש, רפאל ממרוקו","b":"רב בפאס-תרם."},{"i":16175,"n":"הרוש, שלום ממכנאס","b":"מחכמי מכנאס. חתם-תקנו עם חכמי מכנאס."},{"i":16176,"n":"הרוש, שלמה מדמנאת-מרוקו","f":"יעקב","b":"מחכמי דמנאת-שנות ה-ת' ונזכר אצל היעב\"ץ."},{"i":16177,"n":"הרוש, שלמה ממכנאס","b":"מחכמי מכנאס בזמן היעב\"ץ. בנו - ר יחיא."},{"i":16178,"n":"הרוש, שלמה ממרוקו","f":"מכלוף","b":"מו\"ץ בכפר ג'א-מרוקו, חתם-תקעט על פס\"ד. אולי הוא שהיה גם מו\"ץ בתאפילאלת."},{"i":16179,"n":"הרוש, שמואל ממרוקו","k":"בעל שם משמואל","dt":"תשסא","b":"מחכמי מרוקו, עלה לארץ וכיהן כרב בכפר שלם."},{"i":16180,"n":"הרט, ירוחם פישל ממוסט","f":"משה אהרן ממוסט","k":"בעל הארת ירוחם","bp":"מוסט","dt":"תשמו","b":"תלמיד רד\"ב וידנפלד מטשבין. ניצל מהשואה. חתן ר ברוך גולדשטין. עבר לארה\"ב. חיבר \"הארת ירוחם\" ניו יורק תשיג."},{"i":16181,"n":"הרטום, אליהו שמואל מאיטליה","b":"רב באיטליה, רב ראשי ראשון בלוב-תרף התפטר-תרפג, ומאז עד תרץ - לא היה רב ראשי בלוב."},{"i":16182,"n":"הרטמן, בנימין דב מבאלא-קאטשארד","b":"פרסם מאמרים ב\"מגד ירחים\" - סיגט תרנח."},{"i":16183,"n":"הרטמן, בנימין הכהן משאמלוי","dt":"תרך - בערך","dp":"שאמלוי","b":"רבה הראשון של שאמלוי(=שימלאו)-תרי. נזכר ב\"בית הלל\" לר הלל ליכטנשטין שנזף בתלמיד אחד שחלק על ר בנימין."},{"i":16184,"n":"הרטמן, בנימין זאב הכהן","f":"אהרן יהודה משאמלוי","k":"בעל ילקוט בנימין","bt":"תרך","dt":"תרפח","b":"נכד ר יצחק שמחה ברגר מלאפוש וצפת. תלמיד בעל \"ייטב לב\" ובעל \"קדושת יום טוב\" בסיגט. חתן אחיו ר יחיאל משה מבעניעד. שו\"ב ורב בכפר נאג' שאיו-ליד ביסטריץ. חסיד אדמורי דעש ר מנחם פאנט וממשיכיו. רבים מכתביו אבדו בשואה. ?? לא באוצר ??"},{"i":16185,"n":"הרטמן, בנימין כץ","b":"רב בשאמלוי-תר\"י"},{"i":16186,"n":"הרטמן, חיים מאיר זאב משאמלוי","f":"בנימין הכהן משאמלוי","bt":"תקצו","dt":"תרכז - יג אלול","b":"רב בשאמלוי-תרך על מקום אביו ובנו ר אברהם מרדכי על מקומו אחריו. נספד ב\"דרך יבחר\"."},{"i":16187,"n":"הרטמן, יואל","f":"ישראל איסר","b":"מצאצאי הב\"ח. בנו ר מנחם מנדל מסלטוינה מביא מחדושיו בספרו \"סמוכים לעולם\"."},{"i":16188,"n":"הרטמן, יחיאל משה הכהן","f":"אהרן יהודה משאמלוי","dt":"י שבט","b":"נכד ר בנימין - הרב הראשון בשאמלוי. חסיד דעש. תלמיד ר מנחם מנדל פאנט. דיין בעניעד-תרעד. נזכר בספר אחיו \"ילקוט בנימין\""},{"i":16189,"n":"הרטמן, ישראל מטימישואר","f":"משה","bt":"תקעג","bp":"מישקולץ","dt":"תרמו - י תשרי","dp":"טימישואר","b":"רב ודיין בטימישואר-תרד - כ-40 שנה. ממיסדי \"משכיל אל דל\"."},{"i":16190,"n":"הרטמן, מנחם מנדל מסלטוינה","f":"יואל","k":"בעל דרך חקיך","bt":"תקפה","dt":"תרסה","b":"תלמיד ר שלמה ליב וינשלבוים. רבה של סלטוינה, בוריסלוב-תרמו. חתן נכדת ר ישעיה הלר מפרמפול. חיבר \"דרך חקיך\" דראהביטש תרמז, \"יונה תמה\" דראהביטש תרמח."},{"i":16191,"n":"הרטמן, שלמה מאיר מביקוביקץ","b":"גביר מחכמי ביקוביקץ."},{"i":16192,"n":"הרטמן, שמואל אלימלך מארה\"ב","f":"יעקב מסטמר","k":"בעל משרת שמואל","bp":"סטמר","b":"היגר מסטמר בתחילת המאה ה-20. רב בארה\"ב. חיבר \"משרת שמואל\" - נ\"י תרסג - לבאר ר\"ת של מחברים ופוסקים. נזכר אצל דיינארד הלועז לו ולחיבורו."},{"i":16193,"n":"הרטנשטין, יוסף מקונסטנטין","f":"משה חריף","b":"מצאצאי התוי\"ט. רב בקונסטנטין ישן. בנו - ר ראובן מקונסטנטין וזיטומיר."},{"i":16194,"n":"הרטנשטין, ראובן מזיטומיר","f":"יוסף מקונסטנטין ישן","dt":"תקצה - כו ניסן","b":"תלמיד ר אברהם יהושע השל מאפטא, ר משה צבי מסאווראן, ור ישראל מרוזין. רב בזיטומיר, אודסה, קונסטנטין ישן על מקום אביו. מתולדותיו ב\"תפארת ישראל\" - רוזין - גליון יג. חתנו ר מיכל צבי הלפרין על מקומו באודסה."},{"i":16195,"n":"הרטשטיין, שמואל מקאשוי","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":16196,"n":"הרידב\"ז מצפת","dt":"ב תשרי"},{"i":16197,"n":"הרינזון, שלום דב מקלוצק","f":"שמעון","k":"בעל היכלי שן","b":"רב בקלעצק(-קלוצק)."},{"i":16198,"n":"הריס, מרדכי מירושלים","dt":"תשכט - יב סיון","b":"מיקירי ירושלים"},{"i":16199,"n":"הריש, דוד מאייזגרוב","f":"יצחק","bt":"תקפא","bp":"אייזגרוב","dt":"תרנה - ט אב","dp":"אייזגרוב","b":"תלמיד ישיבות ניקלשבורג ופרשבורג. חתן ר ישראל איסר פרוסטיץ מפרשבורג. מחכמי שטאמנסדורף, רב באייזגרוב-תרכג."},{"i":16200,"n":"הרכבי צבי","bt":"1908","dt":"ה'תשלט 1979","bk":[["לחקר משפחות",""]]},{"i":16201,"n":"הרכבי, אברהם אליהו מפטרבורג","f":"יעקב","k":"בעל היהודים ושפת הסל","bt":"1835","bp":"נובהרדוק","dt":"1919","b":"אביו היה ר\"מ בישיבת עץ חיים בירושלים, ואבי זקנו היה מתלמידי הגר\"א ומהעולים הראשונים בעליית תלמידי הגר\"א, לאחר שנתייתם בגיל 16 עלה אביו לארץ והוא נשלח לישיבת וולוזין, למד בביהמ\"ד לרבנים בוילנא, בפטרבורג, השתלם בברלין ופאריס ועמד לכהן כפרופסור בפטרבורג אך המינוי בוטל בגלל יהדותו. מנהל המחלה המזרחית בספריה בפטרבורג. היה הראשון שפרסם את ספרות הגאונים באורח שיטתי, חוקר תולדות הקראים והתריע על זיופי פירקוביץ. מגדולי חכמי ישראל בדורו. פרסם מאמרים ב\"ירושלים\" - ירושלים תרמב-תרעט, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב, \"הפסגה\" - וילנא-וארשא-פיעטרקוב תרנה."},{"i":16202,"n":"הרכבי, אליהו (אלחנן) מנוברדוק","f":"גרשון מאיויא וירושלי","dt":"תר","dp":"ירושלים","b":"רב בנוברדוק, עלה לירושלים."},{"i":16203,"n":"הרכבי, אליעזר","bt":"תרלג","dt":"תרצד - כה אלול","b":"דרשן,רב בפורוזוב"},{"i":16204,"n":"הרכבי, אלכסנדר זיסקינד מנוברדו","f":"גרשון מאיויא וירושלי","b":"רב בנוברדוק על מקום ר דוד בעל \"גליא מסכת\" ור יצחק אלחנן ספקטור על מקומו אחריו. נזכר בשו\"ת קהלת יעקב\" וילנא תרז. הסכים על \"גבורות ארי\", עמק הלכה\" וילנא תרו, ועוד. אחיו - ר אלחנן מנוברדוק וירושלים. מתלמידיו ר גרשון חן טוב מביאליסטוק בעל \"מנחה חדשה\"."},{"i":16205,"n":"הרכבי, אלכסנדר מארה\"ב","k":"בעל דור ישרים","b":"רב בארה\"ב. חיבר \"דור ישרים\" לתולדות משפחת הרכבי - נ\"י תרסג."},{"i":16206,"n":"הרכבי, גרשון זלמן","f":"יעקב הרכבי","dt":"תרסג","b":"ר\"מ עץ חיים בירושלים"},{"i":16207,"n":"הרכבי, גרשון מאיוויא וירושלים","f":"יוסף","bt":"תקטו","bp":"נווהרדוק","dt":"תקפז","dp":"ירושלים","b":"שהה שנה תמימה במחיצת הגר\"א, היה עשיר מופלג ועלה לצפת בשנת תקעט ותמך בבית מדרש ללומדי תורה ע\"ש הגר\"א שם התרכזו הפרושים. אבי כל משפחת הרכבי בארץ ישראל. בניו - ר אלכסנדר זיסקינד מנוברדוק, ר אלחנן מנוברדוק."},{"i":16208,"n":"הרכבי, יעקב מירושלים","f":"אלחנן","bt":"תקסא","dt":"תרנד - יא אלול","dp":"ירושלים","b":"מחכמי ירושלים, נכדו של ר גרשון הרכבי מתלמידי הגר\"א שעלו לצפת, עלה מנוברדוק, כיהן כראש \"עץ חיים\", אשתו חנה היתה שליחה (יחידה בתפקיד זה) מטעם ישיבת \"עץ חיים\". בנו - החכם ד\"ר הרכבי מפטרבורג."},{"i":16209,"n":"הרכבי, צבי מירושלים","b":"פרסם מאמרים ב\"מוריה\" - ירושלים תשג."},{"i":16210,"n":"הרכבי, שלמה מגרודנא","bt":"תרנ","dt":"תשג","b":"חתן ר חיים בער גרינגרוס מקרמנצוג. מנהל רוחני ומוסרי בישיבת \"שער התורה\" בגרודנא-תרפב. פרסם מאמרים ב\"חידושי תורה\" - לודז תרצו."},{"i":16211,"n":"הרליג, מרדכי מצורטקוב","f":"שלום","bt":"תרסו","bp":"צורטקוב","dt":"תשמח","b":"חתן ר מרדכי הלפרין. גדל בסנוק אצל דודו המהר\"ם מלובלין. משמש האדמור מצורטקוב-תרפט. ניצל מהשואה והגיע לארה\"ב-תש וכיהן כרב בניו יורק. פרסם מאמרים ב\"אור המאיר\" - נ\"י תשח."},{"i":16212,"n":"הרלינג ישראל אליהו בן משה דוד","bt":"1909","dt":"ה'תשיט 1959","bk":[["דפי תלמוד",""]]},{"i":16213,"n":"הרמלין, ברוך דוד מלמברג","f":"יוסף דב","k":"בעל אפוד בד","bt":"תרך","dt":"תרץ","b":"חתן ר יהושע מינץ, ובזיוו\"ש חתן ר מרדכי זאב מצאצאי המהרל. חיבר \"אפוד בד\" מונקטש תרעב."},{"i":16214,"n":"הרמלין, לוי יצחק מאלסק","f":"יהושע השל","k":"בעל אלון בכות","bt":"תרנה","bp":"ברודי","dt":"תשג","b":"חתן ר דוד קליינהנדלר מזבורוב. רב בברודי, ראב\"ד אלסק, רבה של פודקמין-תרפז. חיבר \"אלון בכות\" בילגוריא תרצט. כנראה נספה בשואה."},{"i":16215,"n":"הרמלין, משה אריה ליב מברוד","f":"מאיר","bt":"תקפו","bp":"ברודי","dt":"תרנג","b":"מחכמי ברודי, פרסם ספר \"החולץ\" למברג תריב כנגד יהושע השל שור."},{"i":16216,"n":"הרמלע, בנימין ממעליץ","b":"חסיד בלז. גביר במעליץ, פרסם ב\"אהל מועד\"-תרנח."},{"i":16217,"n":"הרמן, אברהם יהודה","f":"פנחס","bt":"תריח","b":"נכד ר אברהם יהודה ממאזיר ונאראווליא, ונכד ר צבי מנארינסק. רב בברדינקא-תרמה. נסמך מאת: ר מרדכי דב מהורנסטייפל. חתנו ר שמואל דב בן מרדכי מיעלסק."},{"i":16218,"n":"הרמן, אברהם מארה\"ב","f":"אליהו","bp":"קרמנצוג","b":"עסקן צבור בניו יורק, נשיא ביהכ\"נ \"האיאס\"."},{"i":16219,"n":"הרמן, יעקב יוסף מנ\"י וירושלים","bt":"תרם","bp":"סלוצק","dt":"תשכז - יז תמוז","dp":"ירושלים","b":"הגיע בילדותו עם משפחתו לניו יורק. איש חסד בניו יורק ואירח בביתו את גדולי הדור שבאו לאמריקה, עלה לירושלים. מלמד תורה ועוסק בפעילות צדקה וחסד. חתן ר שמואל יצחק אנדרמן-ראש ישיבת יעקב יוסף בניו יורק. ממנהלי ישיבת \"היכל התורה\" בירושלים-תשכה. היה מכונה החפץ חיים של אמריקה. לתולדותיו בספר בתו - רוחמה שיין - \"הכל לאדון הכל\"."},{"i":16220,"n":"הרמן, נחום דוד מארה\"ב","f":"יעקב יוסף","bt":"תרסה","bp":"ניו יורק","b":"תלמיד ישיבות סלובודקה בחברון, מיר. נסמך מאת: רא\"י הכהן קוק, ר משה מרדכי אפשטין, ר אליהו קלצקין מלובלין, ר ברוך בר ליבוביץ, ר שמעון שקופ, ר הניך אייגעש"},{"i":16221,"n":"הרמן, נפתלי מהיבניב","b":"רב בהיבניב בזמן האב\"ד רא\"ל הורושובסקי, ור מייטשע הרמן."},{"i":16222,"n":"הרמן, עזריאל מסווירז וניו יורק","f":"יוסף אליעזר","k":"בעל עת קץ","bt":"תרך","bp":"סווירז","b":"למד בחברותא עם המהרי\"ד, ונסמך מהמהר\"י. היגר לארה\"ב, רב בברונזוויל, ניו יורק-תרעח."},{"i":16223,"n":"הרמן, צבי מניזנוב","b":"מחכמי ניזנוב-תרכב."},{"i":16224,"n":"הרמן, שמואל מסניאטין","f":"יואל","bt":"תרסח","bp":"סניאטין","dt":"תשלג","b":"ברח מהשואה והגיע לסיביר. אחרי השואה חזר לפולין ולימד שם לימודי קודש . עלה לארץ תשך והיה חוקר במפעל הביבליוגרפיה."},{"i":16225,"n":"הרמן, שמואל צבי מניו יורק","k":"בעל ארץ ישראל ובעיות","b":"תלמיד הדעת סופר. רב בניו יורק, תל אביב. חתן ר שלמה פישהוף מסעליש - ניו יורק."},{"i":16226,"n":"הרניק, אפרים פישל מזלישטשיק","b":"נכד ר חיים הכהן מלבוב. בנו - ר ישראל בעל \"פאר ישראל\"."},{"i":16227,"n":"הרניק, ישראל מזלישטשיק","f":"אפרים פישל","k":"בעל פאר ישראל","bt":"תרלט","bp":"זלישטשיק","b":"תלמיד ר אריה ליב ברנפלד מזלישטשיק. חתן ר אהרן טיילער, רב באובר-וויקוב-בוקובינה-תרסג, רדוביץ. ניצל מהשואה וכיהן בב\"ד התרת עגונות עם ר\"ב הגר מסרעט ור\"ד שניבלג. חיבר \"פאר ישראל\" טשרנוביץ תרצה, \"דמעות ישראל\", \"זכרון אריה\" - הספד על רבו ר אריה ליב הורביץ מסטניסלב. נסמך מאת: ר יצחק שמלקס מלבוב, ר אריה ליב הורביץ מסטניסטלב, ר בנימין אריה וייס מטשרנוביץ."},{"i":16228,"n":"הרניק, צבי הירש מפשמישל","b":"תשובה אליו בשו\"מ."},{"i":16229,"n":"הרניק, שלמה מטלוסט","f":"דוד","dt":"תרמב - בערך","dp":"ירושלים","b":"מחכמי טלוסט, עלה לארץ. הביא לדפוס מכת\"י \"תורת נתן\" לר נתן שפירא בעל \"מצות שמורים\" למברג תרמה (דוגמא בלבד)."},{"i":16230,"n":"הרנסון, חיים שמעון","b":"רב בקלצק"},{"i":16231,"n":"הרסון, חיים צבי","k":"בעל דרך אמונה"},{"i":16232,"n":"הרץ מאידליץ","b":"רב באידליץ-תק\"נ"},{"i":16233,"n":"הרץ מבריסק","b":"רב בבריסק דליטא"},{"i":16234,"n":"הרץ מדובנא","b":"רב בדובנא רבתי"},{"i":16235,"n":"הרץ מה-יפית, שמחה","dt":"תשג","b":"רב ברוונא"},{"i":16236,"n":"הרץ מוילנא","f":"שלמה זלמן","b":"מחכמי ווילנה"},{"i":16237,"n":"הרץ מיכאל","k":"מפפד\"מ","b":"מראשי קהילת פפד\"מ, ומבין 12 מחברי תקנות הקהילה-תקיג."},{"i":16238,"n":"הרץ מנווהרדוק","f":"אשר","b":"רב בנוברדוק"},{"i":16239,"n":"הרץ מפרנקוניה","b":"מחכמי אשכנז. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":16240,"n":"הרץ מפרשבורג","b":"רב בפרשבורג-רס ונזכר בשו\"ת הרמ\"א, כנראה הרב האחרון לפני גירוש-רמו."},{"i":16241,"n":"הרץ מרישא","b":"רב ברישא"},{"i":16242,"n":"הרץ פילא מברלין","b":"דיין בברלין-תקד אצל ר דוד פרנקל."},{"i":16243,"n":"הרץ, אברהם מגורליץ","f":"אלעזר","bt":"תרך","dt":"תרף"},{"i":16244,"n":"הרץ, יהודה ליב הלוי מדוברזינק","f":"יוסף","k":"בעל מנחת יהודה","dt":"תרצג - כג אלול","b":"רב בדברזינסקי(=דוברזינעק). פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":16245,"n":"הרץ, יהושע מדנבורנה","b":"מחכמי נדבורנא. אביו של בנימין יצחק שהוציא לאור את התלמוד בתרגום גרמני בברלין."},{"i":16246,"n":"הרץ, יוסף","dt":"תשד","b":"רב בפאריס"},{"i":16247,"n":"הרץ, יוסף צבי מיוהניסבורג","k":"בעל פירוש לתנ\"ך","bt":"תרלב","dt":"תשו - יב שבט","b":"תלמיד ביהמ\"ד לרבנים בניו יורק, בעל תואר ד\"ר. רב בקהלת \"עדת ישורון\" בניו יורק, סירקוסה-ארה\"ב-תרנד, יוהניסבורג-תרנח והיה גם פרופ' באוניב' טראנסוול, ניו יורק-תרעב, רב ראשי לבריטניה-תרעג. פרסם מאמרים וערכים באנציקלופדיה היהודית של איזידור זינגר. לכבודו נדפסה חוברת יהונסבורג תרנח - באנגלית."},{"i":16248,"n":"הרץ, יצחק מגלוגוב","b":"רב בגלוגוב, טרנוב. תשובה אליו בשות חיים של שלום."},{"i":16249,"n":"הרץ, יצחק צבי מצפת","f":"אברהם אלימלך מרישא","bt":"תרכב","bp":"צפת","dt":"תשכב","b":"חסיד צאנז. נכד הנועם אלימלך. שמש כולל גליציה ונקרא ר הרשל שמש. נפטר בגיל 100. חתנו - ר אברהם שפר ב\"ר חיים מטבריה."},{"i":16250,"n":"הרץ, ירחמיאל יצחק מלודז","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":16251,"n":"הרץ, מאיר מדזיקוב","b":"רב בדזיקוב."},{"i":16252,"n":"הרץ, מנחם מנדל מקשביץ","b":"אב\"ד קשביץ. חסיד זידיטשוב"},{"i":16253,"n":"הרץ, קלמן מרישא","f":"שמעון","bt":"תרמט","bp":"רישא","dt":"תשב","b":"חתן ר משה ליכט מרישא. רב ברישא. נספה בשואה."},{"i":16254,"n":"הרץ, שלום משנדישוב","f":"שמעון","bt":"תרם","dt":"תשב","b":"רב בדזיקוב-תרפט על מקום אביו שעלה לארץ. רב בשנדישוב. נספה בשואה."},{"i":16255,"n":"הרץ, שלמה (דוד) מבורשטשוב","f":"שרגא פיבל","bt":"תרנב","dt":"תשב","b":"חתן ר אליעזר מישל. רב בטומשוב, גלאגוב-תרף, רבה של בורשצ'וב-תרפד. נספה בשואה. פרסם מאמרים ב\"הבאר\" - זאמושץ-וארשא(=בורשטטוב) - תרפד, \"יבנה\" - לבוב תרפט, \"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב, \"הנצח\" - לבוב תרפז, \"קובץ דרושים\" - פיעטרקוב תרפג, \"אסיפת חכמים\" - מלניץ תרפח, \"הנצח\" - לבוב תרפז, \"רבותינו שבגולה\" - פרשבורג תרעה."},{"i":16256,"n":"הרץ, שמעון מדזיקוב","f":"אלעזר","bt":"תרי","bp":"גלוגוב","dt":"תרצה","dp":"ירושלים","b":"חתן ר דב בריש בריל ובזיוו\"ש חתן ר חיים ברייט מדוקלא. רב ברישא. דזיקוב-תרן. עלה לירושלים-תרפט ומונה לרב על ידי הרב קוק שאמר בהספדו עליו שהיה אחד מגדולי הדור."},{"i":16257,"n":"הרץ, שרגא פיבל מגלוגוב","f":"אלעזר","k":"בעל שות על השוע","bt":"תריח","bp":"גלוגוב","dt":"תרפב - ו סיון","b":"רב בסטבניץ. גלוגוב, סטרי-תרסד. חיבר שו\"ת על שו\"ע - לא נדפס. אחיו של ר יצחק חנוך הירש אב\"ד טאלדיעש."},{"i":16258,"n":"הרצברג, אברהם מאיר","b":"פרסם מאמרים ב\"יבנה\" - פאביאניץ תרפד."},{"i":16259,"n":"הרצברג, אברהם מליביטשוב","f":"ירחמיאל","k":"הו\"ל שפת אמת","dt":"תרעה","dp":"ליביטשוב","b":"חתן נכדת ה\"בני ישכר\". הביא לדפוס \"שפת אמת\" לרמ\"ע מפאנו בלובטשוב תרנט."},{"i":16260,"n":"הרצברג, אליהו מניו יורק","f":"יוסף מדלבוי","bt":"תריז","b":"תלמיד ישיבות זאגר, וולוזין. ר\"מ בביהמ\"ד לרבנים בברלין. היגר לארה\"ב וכיהן כרב קהילת יוצאי קורלנד בניו יורק. פרסם מאמרים תורניים ב\"המאסף\", קובץ \"עץ חיים\", \"שדה חמד\", ועוד. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":16261,"n":"הרצברג, יוסף ממוהליב","k":"בעל מועדי שחר","bp":"מוהליב","dt":"תרל - כח אב","dp":"מאהליב(=מוהליב)","b":"בקי בשפות, ותרגם ספרים לעברית, ובהם מספרי מנדלסון, עמנואל קנט, גרץ, ועוד."},{"i":16262,"n":"הרצברג, יוסף שאול מליביטשוב","f":"אברהם מליביטשוב","b":"חסיד בלוזוב. בעל יערות בליביטשוב, שותפו של רמ\"מ יולס מרישא ב\"ר שמחה נתן. אביו של בעל \"עליתי מספציה\"."},{"i":16263,"n":"הרצברג, ירחמיאל מליביטשוב","f":"שמעון","b":"הביא לדפוס חידושי מהר\"פ לר פסח גוטליב מנמירוב - למברג תרמט. בנו ר אברהם."},{"i":16264,"n":"הרצברג, מאיר דוד","f":"יוסף","k":"בעל אור החמה","b":"מחסידי בלז בפשמישל. חיבר \"אור החמה\" פרמישלא תרפד."},{"i":16265,"n":"הרצברג, מרדכי חיים מפיסטין","f":"אברהם מליביטשוב","k":"בעל תמכין דאוריתא","bt":"תרי","bp":"ווהלין","dt":"תרצו","b":"דרשן ורב בחרסון וקריוורוג. חתן לבית שניאורסון. הגיע לסטניסלב-תרסו. רבה של פיסטין, ראש ישיבה בירוסלב-תרפג. יסד ישיבה בקלויז היבניב. מנהל ישיבה בלובלין-תרפד. חיבר \"תמכין דאורייתא\" וויזניטץ תרעב, \"כללים שבברכות\" וויזניטץ תרעג. מכתב כנגדו בעזבו את ישיבת סטניסלב לטובת ברזן - מחז\"ה-תרסז. פרסם מאמרים ב\"אוצר החיים\" - זאמושט תרצז."},{"i":16266,"n":"הרצברג, משה","b":"פרסם מאמרים ב\"יבנה\" - פאביאניץ תרפד."},{"i":16267,"n":"הרצברג, צבי אלימלך מלובטשוב","f":"אברהם מליביטשוב","k":"בעל צדיק באמונתו","bt":"תרנד","bp":"דינוב","dt":"תשלא","b":"מהיושבים בבלז עם ארבעת אחיו, ספרן האדמור מהרי\"ד ומלמד לבנו ר ארהלה. חתן ר משה אלטשטט. היגר לארה\"ב ועבר ליונגסטון-אוהיו, היגר לארה\"ב-תרפג והתישב בבולטימור בה גרו אחיו ודודיו וכיהן שם כרב וכן סייע בהקמת ישיבת \"נר ישראל\". חיבר \"צדיק באמונתו\" ירושלים תשמז. הניח כתבים רבים בכל מקצועות התורה - בכתב יד."},{"i":16268,"n":"הרצברג, שרגא פיביש מסוקולוב","b":"שו\"ב בסוקולוב (ליד סטרי). תשובה אליו \"אוצר חיים\"-תרצו."},{"i":16269,"n":"הרצוג, אריה ליבוש מבובוב","f":"נפתלי מנחם מוילקוטש","bt":"תרכה","dt":"תרפה","b":"רב בבובוב ור\"מ בישיבה שם. חסיד שינאווא. הציל מטביעה בנהר ביאלא את ר בן ציון מבובוב וחתנו ר חיים יעקב."},{"i":16270,"n":"הרצוג, דוד מניזנקוביץ","f":"יעקב שלום","bt":"תרן","dt":"תשג","b":"רב בניזנקוביץ על מקום אביו. נספה בשואה."},{"i":16271,"n":"הרצוג, זאב וולף מאולינוב","b":"רב באולינוב."},{"i":16272,"n":"הרצוג, חיים מליביטשוב","b":"רב בליביטשוב-תרנח, ממשתתפי \"אהל מועד\"."},{"i":16273,"n":"הרצוג, יואל אריה ליב מפאריס","f":"נפתלי הרץ","k":"בעל אמרי יואל","bt":"תרכה","bp":"לומזה","dt":"תרצד - כה תשרי","dp":"פאריס","b":"תלמיד ישיבת סלובודקא, קובנא, ר הלל דוד טריווש מוילקי. נסמך מאת: ר אליקים שפירא מהורדנא, ר מלכיאל טננבוים מלומזה, ר יצחק מאיר מסלובודקא, ר יעקב יוסף מניו יורק, ר נח יצחק דיסקין, ר אברהם שמואל דיסקין מולקוביסק. רב ומגיד בלומזה, לידס-אנגליה-תרנט, פאריס-תרעא על מקום ר יהודה ליב לובצקי. בנו - ר יצחק איזיק הרב הראשי."},{"i":16274,"n":"הרצוג, יוסף מסנוק","f":"יעקב אליהו","b":"אב\"ד קרייז סאנוק. בנו ר מרדכי אב\"ד וילקוטש."},{"i":16275,"n":"הרצוג, יוסף מסנוק","f":"צבי הירש מסלטוינה"},{"i":16276,"n":"הרצוג, יעקב מיאלע ואבאני","f":"ר\"מ","k":"בעל פרי יעקב","dt":"תריז-ח - א תשרי","b":"תלמיד מהר\"ם מינץ מאויבן. רב ביאלע(=יאלי)-תקפב, אבאני(=אבאניא)-מחוז פעשט, ור יצחק קונשטט על מקומו אחריו, אסאד(=אסויד)-תקצג."},{"i":16277,"n":"הרצוג, יעקב שלום מנינקוביץ","f":"זאב וולף","bt":"תרך","dt":"תרצה","b":"חסיד בלז. חתן ר דוד גלר מניזנקוביץ. רב בניזנקוביץ על מקום חותנו (והיה שם מחלוקת עם חסידי צורטקוב שהיו רוב העיר). תלמידו ר כגליה פלדר."},{"i":16278,"n":"הרצוג, יצחק מדוברומיל","f":"צבי הירש","bt":"תקכ","dt":"תקף","b":"רבה של דוברומיל-תקעה."},{"i":16279,"n":"הרצוג, מרדכי מוילקוטש","f":"יוסף","b":"חתן ר משה אלבוים מליזנסק. רבה של וילקוטש, בנו ר נפתלי מנחם על מקומו אחריו."},{"i":16280,"n":"הרצוג, משה דוד מדוקלא","b":"רב בדוקלא."},{"i":16281,"n":"הרצוג, משה מטשיטש","f":"נפתלי מנחם הרציק","bt":"תרכו","dt":"תרצא","b":"תלמיד ר נתן גולדברג מלימנוב. חתן ר אריה מאיר לנדא מטשיטש. רב בטשיטש-תרמט על מקום חותנו שעלה לארץ. בנו: ר נפתלי צבי הרציק-הרצוג, חתנו - ר מרדכי הורביץ בן ר יעקב ממיעליץ."},{"i":16282,"n":"הרצוג, משה שמואל מסקאהל","f":"שבתי מסקול","bt":"תרלח","dt":"תשב","b":"רב בבלז-תרנט ולמד כל יום עם השר שלום, דיין בקרלסבד. השתתף ב\"אהל מועד\". נספה בשואה."},{"i":16283,"n":"הרצוג, משה שמואל משטמפן","f":"חיים מטירנא","k":"בעל קורות בתינו","bt":"תרלא","dt":"תשב-כ - כג סיון","dp":"שטאמפן","b":"תלמיד השב\"ס. בזיוו\"ש חתן ר אליקים מראנדעג. רב בדיווא, שטאמפי(=שטמפען)-תרנח. חיבר \"קורות בתינו\" לתולדות קהילת שטאמפן. נכדו ר חיים פרידלנדר - ר\"מ בישיבת פוניבז בבני ברק."},{"i":16284,"n":"הרצוג, נפתלי מנחם מוילקוטש","f":"מרדכי","bt":"תר","dt":"תרס","b":"גר בסנוק וכיהן כרב בוילקוטש על מקום אביו. חתן רצ\"ה הכהן גלנץ משיניבה. נסמך מאת: ר שמואל אנגל מרדומישל."},{"i":16285,"n":"הרצוג, נפתלי צבי מטשיטש","f":"משה מטשיטש","bt":"תרן","dt":"תשב","b":"רבה של טשיטש על מקום אביו. חתן ר אריה ליבוש רוקח מבוקובסק ממשפחת אדמורי בלז. נספה בשואה."},{"i":16286,"n":"הרצוג, עזריאל צבי מקראקא","bt":"תקצג","dt":"תרעג","b":"רב בקראקא - התפרנס כמוכר ספרים."},{"i":16287,"n":"הרצוג, שבתי יצחק מגדוב","f":"נפתלי צבי","bt":"תרסט","dt":"תשב","b":"חתן ר יצחקל רובין מצפת. רב בגדוב-תרצו. נספה בשואה."},{"i":16288,"n":"הרצוג, שבתי מסקאהל","f":"זאב וולף מאולינוב","b":"חתן ר נח שטרלברג מבלז. רב בסקול-תרפא. בנו ר משה שמואל מקרלסבד."},{"i":16289,"n":"הרצל, אברהם אבא מפרשבורג","f":"יהושע מפאקש","k":"בעל שפתי חכמים","bt":"תרי-יז","dt":"תרפח - י ניסן","dp":"פרשבורג","b":"תלמיד הכת\"ס, ור משה פולק מבאניהאד. חתן ר יחיאל שלזינגר מפרשבורג, ובזיוו\"ש חתן ר שמשון זינגר. גיסו של ר הלל מקאלאמיי, ושל ר עקיבא יוסף שלזינגר בעל \"לב העברי\". רב בפאקש-תרמב, רב ודרשן בפרשבורג, רב בחברת ש\"ס-תרנא על מקום חותנו כ-40 שנה, ורב בית הסהר ובצבא. חיבר \"נחלת אברהם\", \"ויגד אברהם\". . בשליחות עצמו באמריקה-תרן, ובדרכו חזרה נגנב כל כספו.","bk":[["שפתי חכמים",""]]},{"i":16290,"n":"הרצל, יהודה מדונא-פאלדוואר","f":"נפתלי צבי הרצל נ\"ש","b":"חתנו - ר אשר אנשיל אדלר מדונא-פאלדוואר-תרמב."},{"i":16291,"n":"הרצל, יחיאל הלל מסאבארטן","f":"אברהם אבא מפרשבורג","dt":"תשכה","dp":"ירושלים","b":"תלמיד הדעת סופר. רב בסאברטען-תרפז. עלה לירושלים."},{"i":16292,"n":"הרצל, מרדכי יהודה מפאקש","f":"יהושע מפאקש","dt":"תרצט","dp":"ירושלים","b":"נכד ר מנחם מנדל בנט מפאקש. תלמיד הכת\"ס. חתן ר יחיאל רובינשטין מקאדלבורג. מחכמי פאקש. עלה לארץ-תרסט והתישב במושב שפיה, ירושלים."},{"i":16293,"n":"הרצל, משה יצחק מדונא-פאלדוואר","f":"נפתלי צבי הרצל נ\"ש","bt":"תרד","dt":"תרעה - כב חשון","dp":"פאקש","b":"תלמיד הכת\"ס, ור יואל אונגר מפאקש, ור אברהם צבי אבלס משארבאגארד. חתן נכדת ר משה חיים הכט מסילאש-באלהאש. רב בדונא-פאלדוואר ויסד שם את קהילת החרדים."},{"i":16294,"n":"הרצמן, אלחנן יוסף מניו יורק","k":"בעל בית נאמן"},{"i":16295,"n":"הרצמן, חיים הלוי מראסיין","f":"שלום מראסיין","k":"בעל דברי הפורים","bp":"ראסיין","b":"מחכמי ראסיין. חיבר גם \"המבאר\" על אגדות הש\"ס. פרסם מאמרים ב\"שמעתתי דרבנן\" - אודסה תרמז, \"תורה מציון\" - ירושלים תרנה-תרסה, \"יגדיל תורה\", ועוד."},{"i":16296,"n":"הרצמן, חיים מאויבן","b":"רב באויבן-שכ\"ט"},{"i":16297,"n":"הרצמן, שלום הלוי מראסיין","dt":"תרסט","b":"מחכמי ראסיין. בנו - ר חיים בעל \"דברי הפורים\"."},{"i":16298,"n":"הרצנברג, יוסף מליבאוי","f":"אליהו מפילטען","bp":"פילטען","dt":"תרמב - כב תשרי","b":"מו\"ץ בפילטען-תרט על מקום ר בר דיאמנט, רב בליבאוי-תרטז על מקום ר מנחם מנדל איזראלזון (ור מנדל איזראזון על מקומו בפילטען)."},{"i":16299,"n":"הרצפלד, אהרן יהושע אליהו אשר","f":"שלמה דובריש אשכנזי","dt":"תרלו","b":"שם אביו אולי ר יצחק הלוי. ראב\"ד בקניגסברג-תקס, רוויטש(=ראויטש)-תקצ. בנו - ר נפתלי צבי מהולנד."},{"i":16300,"n":"הרצפלד, אליקום מגולדינגן","bp":"גריווא","b":"מ\"מ בגולדינגן."},{"i":16301,"n":"הרצפלד, יום טוב ליפמן מחוסט","bp":"פרשבורג","b":"תלמיד הכת\"ס. רב בחוסט. עלה לירושלים-תרסז."},{"i":16302,"n":"הרצפלד, יעקב אליהו משימלויא","f":"יצחק איציק מפרשבורג","bp":"פרשבורג","dt":"תרסב - בערך","b":"תלמיד הכת\"ס, ור יהודה אסאד, והשבט סופר. רב בשימלויא-תרכו."},{"i":16303,"n":"הרצפלד, יעקב שלום משטמפן","b":"מחכמי שטמפן, חתם-תקעו על כתב רבנות ר מרדכי בנט."},{"i":16304,"n":"הרצפלד, ישראל מבלאשוי","b":"רב בבלאשוי-תק\"ל"},{"i":16305,"n":"הרצפלד, משה מסילאש","f":"ליב","bt":"תקעו","bp":"מילכדורף","dt":"תרלב - כ אד\"ב","dp":"סילאש-באלהאש","b":"תלמיד החת\"ס, הכת\"ס, ור ישכר דב דייטש ממילכדורף. חתן ר דניאל פרוסטיץ מפרשבורג ועבר לשם. רב במילכדורף-תרט, סילאש-באלהאש-תרטז, חתנו ר אברהם צבי קליין על מקומו אחריו."},{"i":16306,"n":"הרצפלד, משה מסערדאוהל","f":"אליעזר","k":"בעל דברי משה","bt":"תקפג - בערך","bp":"פרשבורג","dt":"תרמג - יח אד\"ב","b":"תלמיד החת\"ס, והכת\"ס. חתן ר מאיר בלוי מסערדאוהל. מחכמי פרשבורג-תרח, רב בסערדאוהל. בניו ר מיכאל צבי מירושלים, ר יצחק מסערדאוהל - נספה בשואה, ר שלמה מוויצען."},{"i":16307,"n":"הרצפלד, משה משטמפן","b":"פרנס ממנהיגי קהלת שטאמפי-תקו."},{"i":16308,"n":"הרצפלד, נפתלי צבי הרש","f":"אהרן יהושע אליה אשר","k":"בעל אמרי שפר","bt":"תקמב","dt":"תרלו","b":"נכד (אבי אמו) ר שלמה מחעלמא בעל \"מרכבת המשנה\", ונכד (מצד אביו) הפני יהושע. חתן ר יעקב משה לוונשטם מקליווא, ועבר אל חותנו שעבר להולנד. רב בבניאקרכן, שוואל-הולנד וכל מדינת גלדרלנד ודרנטה. חיבר שיר לכבוד חנוכת ביה\"כ באאטמארשען-הולנד-תרד."},{"i":16309,"n":"הרצפלד, שאול מטומשוב","f":"יהושע אליהו אשר","dt":"תקצז - ג טבת","b":"רב בטאמשוב"},{"i":16310,"n":"הררי ג'יבלי, צדוק מתימן","b":"מחכמי תימן, עלה לירושלים והיה ממקובלי \"רחובות הנהר\"."},{"i":16311,"n":"הררי רפול, אברהם מחלב וירושלים","f":"עזרא","r":"זקן רבני ארם צובא","bt":"תרנה","bp":"ירושלים","dt":"תשנב - כה כסלו","b":"זקן רבני ארם צובא. ר\"מ בישיבת \"פורת יוסף\"","bk":[["אמרי אברהם – עה\"ת",""]]},{"i":16312,"n":"הררי רפול, נסים מחלב","k":"בעל עלי נהר","dt":"תרל - טו שבט","b":"רב ומקובל בחלב, תשובות ממנו ב\"ויוסף אברהם לר אברהם דיין, ו\"פה אליהו\" לר אליהו חמווי. תלמידו ר חיים שאול דוויך מזכירו בספרו \"בניהו בן יהוידע\"."},{"i":16313,"n":"הררי רפול, עזרא מחלב","f":"יוסף","k":"בעל הכין עזרא","bt":"תרטז-יז","bp":"חלב","dt":"תרצז - י סיון","dp":"ירושלים","b":"תלמיד ר יעקב שאול דוויך הכהן. עלה לירושלים-תרן, ולמד אצל ר חיים שאול דוויך בישיבת המקובלים \"רחובות הנהר\". ממיסדי ישיבת \"אהל מועד\"-תרסד. מראשי העדה החלבית בירושלים."},{"i":16314,"n":"הררי, חייא","f":"יצחק","dt":"תרסד - י אייר","dp":"מצרים","b":"מחכמי חלב,ביקש לעלות לא\"י,אך לא הסתייע הדבר,ונפטר במצרים"},{"i":16315,"n":"הררי, יצחק מאר\"ץ","k":"בעל זכור ליצחק","dt":"תקע","dp":"צפת","b":"נכד ר משה הררי - חברו של ר יהודה רוזניס. מחכמי אר\"ץ, עלה לארץ והתישב בצפת. בניו - ר משה, ר מיכאל, ור חייא סייעו בהדפסת ספרו \"זכור ליצחק\" וכתבו לו הקדמה."},{"i":16316,"n":"הררי, ישעיה רפאל","b":"מגדולי רבני ארם צובה-תרל\"ד"},{"i":16317,"n":"הררי, מיכאל מחלב","b":"מחכמי אר\"ץ-תקו. חתם על פסק איסור אכילת עלי גפנים. חתנו - ר אברהם לאניאדו (נפטר בחייו - תקו)."},{"i":16318,"n":"הררי, משה מחלב","f":"אברהם","b":"מחכמי חלב. אביו של ר יצחק, וחתנו של ר משה. נזכר ב\"קרבן אשה\" לר אליהו שאמע."},{"i":16319,"n":"הררי, משה מחלב","f":"רפאל","dt":"תפט","dp":"חלב","b":"זקנו של ר יצחק הררי המזכירו בספרו \"זכור ליצחק\". רב בשלוניקי, אדרינופול, עלה לחברון, חלב-תן. חתם עם ר ר שמואל פינטו, ר שמואל דווייק הכהן ור שמואל לאניאדו ור יוסף נאוי."},{"i":16320,"n":"הררי, משה מחלב - א","b":"מקובל,רב בארם צובה-תנ\"א"},{"i":16321,"n":"הררי, משה מחלב - א","f":"יצחק","dt":"תקעז - ו אלול","b":"מחכמי חלב. כתב הקדמה לספר אביו \"זכור ליצחק\". נזכר אצל ר דוד לניאדו ב\"לקדושים אשר בארץ\"."},{"i":16322,"n":"הררי, משה מחלב - ב","f":"יצחק","dt":"תרעח - יא אלול","dp":"ירושלים","b":"דיין בחלב-תרנה, עלה לירושלים. שאלה ממנו ב\"ישא איש\" לר יעקב שאול אלישר."},{"i":16323,"n":"הררי, שלמה מדמשק","dt":"תרב - יב אדר","dp":"דמשק","b":"רב בדמשק. בניו ר יעקב ור יצחק מחכמי דמשק."},{"i":16324,"n":"הררי-גורניאסקי, שמשון","bp":"תרעח","dp":"תשנט","b":"תלמיד ר אבא גרוסברד בישיבת לומזה-פתח תקוה, עבר עם רבו לישיבת פוניבז בבני ברק, וכיהן שם כר\"מ. הו\"ל \"בעקבות בית אבא\" ובו מתורתו ומתורת רבו."},{"i":16325,"n":"הררי-רפול","k":"משפחה","b":"משפחה רבנים מארם צובא."},{"i":16326,"n":"הרריס, מ. מניו יורק","bt":"1859","bp":"לונדון","b":"רב ריפורמי בקהילת \"היכל ישראל\" בניו יורק. חיבר ספר באנגלית - \"אנשי הספר\"."},{"i":16327,"n":"הרש, בן ציון מדרום אפריקה","bt":"1885","bp":"יאנישוק","dt":"1935","dp":"יוהנסבורג-דרו\"א","b":"היגר לדרום אפריקה והיה ממיסדי הפדרציה הציונית וועד שליחי הקהילות בדרום אפריקה. עסקן ציבור ופעל בעניני הגירה. פרסם מאמרים בעתונים שונים. שופט שלום ביונהסבורג."},{"i":16328,"n":"הרש, פסח ליבמן","f":"מאיר דוד","k":"בעל די יודישע עמיגרא","bt":"1882","bp":"פאמושה-ליד שאוולי","dt":"1955","b":"למד מתמטיקה וכלכלה בג'בה-שוייץ ונשאר שם כפרופסור לסטטיסטיקה. חיבר מאמר ביקורת כנגד המבקר אליעזר אטלס, הצטרף לבונד. פרסם ב\"צוקונפט\" בעניני הגירה יהודית ועל בעית היהודים בפולין. בזמן השואה עסק בפעולות הצלה. חיבר \"די יודישע עמיגראציע\" - 1914, ועוד. ?? לא באוצר ??"},{"i":16329,"n":"הרשברג, אברהם מרדכי משיקגו","f":"אברהם מרדכי","k":"בעל מחשבת הקדש","bt":"תרעו","bp":"קאדניע-פלך ביאלא","b":"תלמיד ישיבות בריסק, חכמי לובלין-אצל רבו המובהק ר מאיר שפירא. נסמך מאת: הרב במטרספוליע, ר אברהם שורצברג, הרב מיכלזון מפלונסק, בעל \"משמרת שלום\". ראש ישיבת חכמי לובלין בראכוב, ניצל מהשואה והגיע לוילנא-תשא, קובה-יפן, רב בקהלת \"צעירי דת ודעת\" במונטריאול-קנדה, שיקגו בקהלת \"שערי תפלה בני ראובן\", ראש ישיבת חכמי לובלין בדטרויט ונשיא הסתדרות ישיבת חכמי לובלין באמריקה. חיבר \"מחשבת הקדש\" לובלין תרצז. סקירה על ספרו ב\"תלפיות\" - טרנוב תרצח."},{"i":16330,"n":"הרשברג, יוסף מארה\"ב","b":"רב באולבנני-ארה\"ב. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח."},{"i":16331,"n":"הרשהורן, יהושע הלוי ממונטריאול","k":"בעל ממעיני ישועה","b":"רב במונטריאול."},{"i":16332,"n":"הרשטין-רפפורט, מאיר אליעזר","k":"בעל שלשלת זהב","b":"מצאצאי ר נפתלי בעל \"סמיכת חכמים\". רב באוהל. חתנו - ר גבריאל גשטטנר משטינמאנגר. חיבר \"שלשלת הזהב\" לתולדות זקנו - \"הסמיכת חכמים\"."},{"i":16333,"n":"הרשיינסקי, בריש","b":"רב בלובטוב-תר\"כ"},{"i":16334,"n":"הרשלר, אברהם צבי מפילדלפיה","f":"אבא","k":"בעל מחקרי נעלה","b":"מצאצאי הגר\"א. תלמיד ר חיים ליב טיקטינסקי ממיר, ובישיבת וולוזין. רב בפילדלפיה."},{"i":16335,"n":"הרשלר, אריה ליב דיין","f":"אלימלך דב","k":"ר לייב מיילך'ס","bp":"פינסק","dt":"תרעז","dp":"ירושלים","b":"עלה בגיל שנה לירושלים, למד אצל ר שלמה זלמן בהרן, הוסמך על ידי ר יהושע ליב דיסקין ור שמואל סלנט, בשנת תרנב נתמנה לדיין. יסד עם ר זלמן בהרן ור יוסף חיים זוננפלד את שכונת \"בית ישראל \", \"שערי פינה\" \"נחלת צבי\" ו\"גבעת שאול\". היה חבר בית המשפט הממלכתי יחד עם פחה, פטריארך וקאדי, ובמסגרת תפקידו עזר רבות לקהלה היהודית."},{"i":16336,"n":"הרשלר, אשר אנשיל מנאמעסוויט","f":"צבי משוראן","dt":"תרלו - בערך","b":"תלמיד החת\"ס. רב בנאמעסוויט(=נעמעש-וויטא, נאוועמסטע)."},{"i":16337,"n":"הרשלר, יוסף שמואל מסאבאדי","dt":"תרנד - ז כסלו","dp":"ירושלים","b":"חתן ר פנחס יהודה פייפר מקאוועגרעש. רב בסאבאדי, עלה לירושלים - אבי משפחת הרשלר בירושלים."},{"i":16338,"n":"הרשלר, מאיר צבי מחברון","k":"אדמור מלנצהוט","b":"מראשי הועד הכללי בחברון-תרמט."},{"i":16339,"n":"הרשלר, מאיר צבי מחברון","b":"מראשי חסידי חב\"ד בחברון, חתם-תרן עם ר מנשה שמעון חייקין ור בנימין ריבלין."},{"i":16340,"n":"הרשלר, משה מירושלים","b":"פרסם מאמרים ב\"תורה אור\" - ירושלים תשה."},{"i":16341,"n":"הרשלר, שלמה","b":"פרסם מאמרים ב\"שמוש חכמים\" - בני ברק תשז."},{"i":16342,"n":"הרשמן, אברהם מארה\"ב","bt":"1880","bp":"ניישטט-שאקי","dt":"1959","b":"תלמיד ישיבות ליטא. היגר לארה\"ב ולמד בסמינר שכטר בנ\"י. רב (רפורמי?) בדטרויט-1908, מיש. יו\"ר המגבית לא\"י. נציג יהודי דטרויט בקונגרס היהודי האמריקאי."},{"i":16343,"n":"הרשמן, זאב נחום מוארשא","k":"אדמור מרדושיץ","b":"רב בוארשא (טרגובעק)-תרצה."},{"i":16344,"n":"הרשקוביץ, דוד אליהו מבודפשט","f":"יחיאל מיכל מהאלאש","bt":"תרן","bp":"האלאש","dt":"תשמד - ה אד\"א","dp":"ירושלים","b":"תלמיד הדעת סופר. רב במישקולץ, עיר חדש, בודפשט-תרפח על מקום אביו. ניצל מהשואה ועלה לירושלים-תשה, וכיהן כרב בגבעת שאול."},{"i":16345,"n":"הרשקוביץ, יהודה מבודפשט","f":"פיבל","bt":"תרלב","dt":"תשד - יא ניסן","dp":"בודפשט","b":"נתייתם בילדותו וגדל אצל חורגו ר יוסף שטרויס ממאקווא. תלמיד הכת\"ס, ור יוסף שטרויס ממאקווא. רב בקהילת \"לינת הצדק\" בבודפשט. חתנו ר גבריאל שלזינגר מרמת גן (בנו של ר ישראל דוד רב \"לינת הצדק\" בבודפשט)."},{"i":16346,"n":"הרשקוביץ, יהודה ממעליץ","f":"שלום","b":"רב במעליץ, היגר לארה\"ב-תרעג, והיה שם רב. דברי תורה ממנו ב\"פרח לבנון\"."},{"i":16347,"n":"הרשקוביץ, יחיאל מיכל מבודפשט","f":"יהודה","bt":"תרכה","dt":"תרפח - ח טבת","dp":"בודפשט","b":"תלמיד השב\"ס. חתן ר משה דייטש משאלגא-טאריאן. רב בהאלאש-תרן, מישקולץ-תרנח, בודפשט-תרסא (חברת ש\"ס) ובנו ר דוד אליהו על מקומו אחריו."},{"i":16348,"n":"הרשקוביץ, מאיר מבודפשט","b":"רב בבודפשט. פרסם מאמרים ב\"אהל שם\" - רומניה תשב - תשה."},{"i":16349,"n":"הרשקוביץ, מרדכי חיים מטורנא","b":"מתורתו - \"כבוד התורה\"-תרצא."},{"i":16350,"n":"הרשקוביץ, משה משומוג'-סיל","dt":"תשד","b":"רב הקהילה הניאולוגית בשומוג'-סיל-מחוז שומוג'י. חיבר ספר על פרשנות התנ\"ך של הרד\"ק. נספה בשואה."},{"i":16351,"n":"הרשקס, אברהם","b":"רב בלבוב"},{"i":16352,"n":"השירוני, אליעזר מקושטא","bp":"שירון","b":"רב בקושטא בזמן הרא\"ם."},{"i":16353,"n":"השירוני, שלמה מקושטא","bp":"שירון(=סיריס)","b":"מחכמי עדת הרומנים בקושטא, נזכר בתשובות הרא\"ם."},{"i":16354,"n":"השכל, אריה ליב הכהן ממינסק","f":"משה","dt":"תרמז - יא טבת","dp":"מינסק","b":"ראב\"ד במינסק-תר בערך."},{"i":16355,"n":"השכל, מיכאל","bt":"1880","bp":"וילנא","dt":"1942","dp":"יוהנסבורג-דרו\"א","b":"היגר לדרום אפריקה והתעשר. יו\"ר התנועה הרביזיוניסטית בדרום אפריקה ופעיל ציבור. נהרג בתאונת דרכים."},{"i":16356,"n":"השל (מעשיל) מווישקעס","k":"העילוי מסוואלק","b":"רב בווישקעס. חתנו - ר צבי הירש ימיני מוילאן."},{"i":16357,"n":"השל מאטוסאוו ומינסק","b":"ר\"מ בביהמ\"ד במינסק. נשלח ע\"י קהלת מינסק לפרוזין לבדוק את מועמדות ר ירחם יהודה פרלמן - הגדול ממינסק, וע\"פ המלצתו הנלהבת נתקבל לרבנות מינסק."},{"i":16358,"n":"השל מגרובין","b":"רב בגרובין-קורלנד-תקעט."},{"i":16359,"n":"השל מלובלין","f":"בהגאון אב\"ד קראקא","b":"מחכמי לובלין. נזכר בפנקס קובץ פסקים אודות דין ודברים שהיו לו עם ר אריה ליב בן אב\"ד שברשין אודות שכירת חנות אצל ר שאול מרגליות-תקמג."},{"i":16360,"n":"השל ממינסק","k":"ראה: יהושע השל ממינ","b":"מחכמי ווילנה-תק\"נ"},{"i":16361,"n":"השל משימבורג","f":"מרדכי רבינר?","dt":"תרסה - כד אדר","dp":"ריגא","b":"חתן (כנראה בן ולא חתן) ר מרדכי רבינר מבויסק בעל \"גדולת מרדכי\". שו\"ב בשימבורג-תר והיה מו\"צ עם חברו ר יעקב באופן זמני לאחר עזיבת ר מרדכי בן יקותיאל הלוי שעבר ליאקובשטט, עבר לריגא וניהל את עסקי חתנו - ר יוסף פאס. נכדו - ר השל קרצמר מבירז. חיבר ספרים בעברית ללימוד חשבון."},{"i":16362,"n":"השל, אברהם יהושע השל מוינה","f":"יצחק מאיר מקופיטשניץ","k":"אדמור מקופיטשניץ","bt":"תרמח","bp":"הוסיאטין","dt":"תשכט - טז תמוז","dp":"טבריה","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן דודו ר משה מרדכי השל (פרלוב) מנובומינסק. אדמור מקופיטשיניץ בוינה על מקום אביו. הגיע לארה\"ב-תרצט לפני השואה והיה רב ואדמור בניו יורק. הקים רשת מוסדות \"בית אברהם\" בארץ ישראל, ופעל למען ה\"חינוך העצמאי\" של אגו\"י."},{"i":16363,"n":"השל, אברהם יהושע השל ממזבוב","f":"ישראל שלום יוסף","k":"אדמור ממזבוז","bt":"תרנב","dt":"תשג - ד-כה ניסן","dp":"פיעטרקוב","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן דודו ר יצחק מאיר מקופיטשיניץ. אדמור ממזבוז-תרעא על מקום אביו.ברח-תרפה מהבולשביקים לגליציה, וקבע את חצרו בטרנופול. נספה בשואה."},{"i":16364,"n":"השל, אברהם יהושע השל ממזבוז","f":"משלם זוסיא מזינקוב","k":"בעל אור יהושע","bt":"תקצב","dt":"תרמא - יט תשרי","dp":"קמינקא","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן ר שלום יוסף האדמור מסדיגורא. וישב אצל האדמור מרוזין. אדמור ממזבוז-תרכד. בתקופתו נפתחו קלויזים לחסידי מזבוז ברחבי בסרביה. חיבר \"אור יהושע\" ירושלים תשמב."},{"i":16365,"n":"השל, אברהם יהושע מאפטא","f":"שמואל מזמיגרד","k":"אדמור מאפטא-אוהב ישר","r":"האוהב ישראל מאפטא","bt":"תקח","bp":"זמיגורד","dt":"תקפה - ה ניסן","b":"חתן ר יעקב מטיטשין. התקרב לחסידות והיה מתלמידי הנועם אלימלך. רב ואדמור בקולבסוב-תקמה, אפטא-תקס, יאסי-תקסח, מזיבוז. חיבר \"אוהב ישראל\" זיטומיר תרכג. בגלל הנהגות שנויות במחלוקת רצה בעל \"קצות החושן\" להחרימו. (נאלץ לעזוב את יאסי לאחר שאמר בתפלה כהן גדול ביו\"כ \"וכך הייתי אומר\"). תולדותיו ב\"הרב מאפטא\". חתנו ר ישראל מליטשניץ (ברדיטשוב).","bk":[["תורת אמת – עה\"ת , אוהב ישראל – עה\"ת , שמירות וסגולות נפלאות",""],["אוהב ישראל – עה\"ת",""],["שמירות וסגולות נפלאות",""],["תורת אמת – עה\"ת",""],["אוהב ישראל (הרב מאפטא) [עה\"ת]",""],["אוהב ישראל",""]],"e":"תק\"ח-תקפ\"ה"},{"i":16366,"n":"השל, אברהם יהושע מקפושטניץ","f":"יצחק מאיר מקאפושטניץ","bt":"תרמט","dt":"תשכז - טז תמוז","b":"אדמו\"ר בקאפושטניץ,רב בווינה-תרצ\"ו"},{"i":16367,"n":"השל, חיים מנחם מזינקוב","f":"משלם זוסיא מזינקוב","k":"אדמור מזינקוב","bt":"תקצז","bp":"זינקוב","dt":"תרנב-ג -כד ניסן","b":"רב בזינקוב-תרכד על מקום אביו. מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן ר דוד מטולנא (טשרנוביל), ובזיוו\"ש חתן ר יחיאל מיכל מקאשיבקא. הניח כת\"י רבים."},{"i":16368,"n":"השל, חיים מנחם מזינקוב","f":"משה מזינקוב","k":"אדמור מזינקוב","bt":"תרנח","bp":"זינקוב","dt":"תשן - יג חשון","dp":"בני ברק","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן ר יעקב ישראל שפירא מלובני. רב ואדמור בזינוקב על מקום אביו. ניצל מהשואה ועבר לקיוב ולמוסקבה והמשיך לכהן כאדמור גם תחת השלטון הקומוניסטי. עלה לארץ-תשכז והתישב בבני ברק."},{"i":16369,"n":"השל, יוסף משה ממזבוז","f":"אברהם יהושע מאפטא","bt":"תקם","dt":"תריב - טו חשון","b":"רב במזבוז ולא נהג אדמורות. חתן ר יהודה נכד ר משה מפשוורסק. (אצל וונדר תאריך הפטירה - תרטו)"},{"i":16370,"n":"השל, יחיאל מקריליביץ","f":"משלם זוסיא מזינקוב","k":"אדמור מורבה-קרילוביץ","bt":"תרג-ז","dt":"תרעו - ט תמוז","dp":"קישינוב","b":"מצאצאי האדמור ר אברהם יהושע השל \"האוהב ישראל\" מאפטא. חתן ר יהושע רוקח האדמור מבלז, ובזיוו\"ש חתן ר דוד מסטעפין. אדמור במורבה-קרילוביץ(=מאראוונע-קריליוויץ)-פודוליה-תרלה על מקום אחיו ר שמואל. ביקר הרבה אצל חסידיו בעיירות פודוליה ובסרביה. בנו ר משולם זוסיא-חתן ר אליהו מזידיטשוב נפטר בחיי אביו, מחותניו גם: ר מרדכי טברסקי האדמור מרחמיסטריבקה, והרמ\"מ ממאקרוב."},{"i":16371,"n":"השל, יעקב מלונדון","f":"משה מרדכי","bt":"תרסג","dt":"תשלג","b":"חתן ר נחום מרדכי פרידמן מצ'ורטקוב. רב בלונדון."},{"i":16372,"n":"השל, יצחק מאיר מזינקוב","f":"אוהב ישראל מאפטא","k":"אדמור מזינקוב-אפטא","bt":"תקלו","dt":"תרטו - א אדר","b":"חתן ר חיים יעקב שטרום מדוקלא. רבה של קולבסוב על מקום אביו. רב בזמיגרוד. רב במזבוז על מקום אביו. עבר לזינקוב-ליד מזבוז והיה אדמור שם. בנו - ר זושא מזינקוב."},{"i":16373,"n":"השל, יצחק מאיר ממזבוז חיפה","f":"ישראל שלום יוסף","k":"אדמור ממזבוז באודסה","bt":"תרנח-סא","bp":"מזבוז","dt":"תשמו - יט אב","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן ר מנחם נחום רבינוביץ מקנטיקוזובה. רב במזבוז על מקום אביו. עבר לאודסה-תרצא וכיהן כאדמור במחתרת מפחד הבולשביקים. עלה לארץ-תרצו-ח וכיהן כרב בחיפה. רב בניו יורק-תשא, ושוב בחיפה-תשכח."},{"i":16374,"n":"השל, יצחק מאיר מקופיטשיניץ","f":"אברהם יהושע השל ממזב","k":"אדמור מקופיטשניץ","bt":"תרכב","bp":"זינקוב","dt":"תרצו - א תשרי","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן ר מרדכי שרגא מהוסיאטין. רב ואדמור קופיטשיניץ על פי הוראת דודו האדמור מצורטקוב. עבר לוינה אחר מלחמת העולם הראשונה."},{"i":16375,"n":"השל, יצחק מאיר מקרילוביץ","f":"שמואל מקרילוביץ","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן דודו ר אפרים זלמן ממאציוב. נתייתם בילדותו וגדל אצל זקנו ר אברהם טברסקי מטריסק."},{"i":16376,"n":"השל, ישראל שלום יוסף ממזבוז","f":"אברהם יהושע השל ממזב","bt":"תריג","bp":"זינקוב","dt":"תרעא - כט אב","dp":"ויזניץ","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. רב ואדמור במזבוז על מקום אביו. חתן דודו ר אברהם יעקב מסדיגורא, ובזיוו\"ש חתן ר יעקב שמשון חודרוב מאהופולי. ההספד עליו בספר \"שרש ישי\"."},{"i":16377,"n":"השל, מנחם נחום מלויצק","f":"יצחק מאיר מקרילוביץ","k":"אדמור מלוצק","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן ר חיים לארבער."},{"i":16378,"n":"השל, משה מזינקוב","f":"חיים מנחם מזינקוב","k":"אדמור מזינקוב","bt":"תרלט","dt":"תרפג-ט -יג טבת","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן ר מרדכי מקוריסטשוב (טשרנוביל). אדמור בזינקוב. בנו - אברהם יהושע-חתנו של ר ישראל לברטובסקי."},{"i":16379,"n":"השל, משה מרדכי ממזבוז וארשא","f":"אברהם יהושע השל","k":"אדמור ממזבוז בוארשא","bt":"תרלג","dt":"תרעז - כז חשון","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. לאחר פטירת אביו נשאה אמו לר דוד משה מצורטקוב שגדלו. חתן ר יעקב פרלוב מנובומינסק. אדמור בפעלצאוויזנע-תרס, ואחר כך אדמור ממזבוז בוארשא-תרס."},{"i":16380,"n":"השל, משה מרדכי מקופיטשניץ -א","f":"אברהם יהושע מקופיטשנ","k":"אדמור מקופיטשניץ","bt":"תרפט","dt":"תשלז - יז ניסן","dp":"טבריה","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן ר צבי ברנדלר."},{"i":16381,"n":"השל, משה מרדכי מקופיטשניץ -ב","f":"אברהם יהושע השל","k":"אדמור מקופטשיניץ נ\"י","bt":"תרפז","bp":"וינה","dt":"תשלה - יז ניסן","b":"אדמור מקופטשיניץ בניו יורק-תשכז על מקום אביו."},{"i":16382,"n":"השל, משלם זוסיא","f":"יחיאל מקרילוביץ","dt":"תרעו - לפני","b":"חתן ר אליהו מזידיטשוב. נפטר בחיי אביו."},{"i":16383,"n":"השל, משלם זוסיא מזינקוב","f":"יצחק מאיר מזינקוב","k":"אדמור מזינקוב","bt":"תקעג-ד","dt":"תרכד - ג אלול","b":"נכד האדמור ר אברהם יהושע השל מאפטא. חתן ר ישראל חתן ר משה צבי מסאווראן ועבר אל חותנו זקנו האדמור מסאווראן. רב ואדמור בזינקוב על מקום אביו. מדברי תורתו בתוך ספר \"שמועות טובות\" וארשא תרנו. חיבר אקדמות לראש השנה ועוד. הו\"ל ספר זקנו \"אוהב ישראל\" עם הקדמה ממנו. הניח כת\"י וציוה שלא להדפיסם. (באוצר הרבנים תאריך פטירתו - ב אלול תרכו)."},{"i":16384,"n":"השל, משלם זוסיא ממזבוז","f":"אברהם יהושע השל ממזב","k":"אדמור ממזבוז","bt":"תרלא","dt":"תרף - י אדר","dp":"מזבוז","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן ר צבי נכד ר דוד לייקיס. אדמור במזבורז. נהרג עק\"ה בפרעות ברוסיה."},{"i":16385,"n":"השל, פנחס מזינקוב","f":"חיים מנחם מזינקוב","k":"אדמור מזינקוב","bt":"תרלב","dt":"תרעו-ץ ז שבט","dp":"אודסה","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן ר יצחק מבוהוש (רוזין). רב ואדמור בזינקוב על מקום אביו."},{"i":16386,"n":"השל, שמואל מזמיגרוד","f":"אריה ליב","dt":"תקסג","b":"חתן ר משה הלפרין דוברושיש מחעלמא. רב בזמיגרוד, ראב\"ד בעיר חדש."},{"i":16387,"n":"השל, שמואל מקריליביץ","f":"משלם זוסיא מזינקוב","k":"אדמור מקריליביץ","bt":"תר","dt":"תרכב - יב ניסן","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. חתן ר אברהם מטריסק (טשרנוביל). אדמור במורבה-קריליביץ בחיי אביו האדמור מזינקוב. נפטר צעיר ואחיו ר יחיאל על מקומו אחריו."},{"i":16388,"n":"השל-טברסקי, דוד מרדכי מטריסק","f":"יצחק מאיר מקרילוביץ","k":"אדמור משטפנשט","bt":"תרם","dt":"תשכד - כב טבת","dp":"אירופה - בני ברק","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. שם משפחתו טברסקי - הוא מצד זקנו חורגו-ר אברהם טברסקי מטריסק. חתן ר מרדכי זוסיא מהוצאלעס-יאס (טשרנוביל), ובזיוו\"ש חתן ר פנחס מבוארשא (קוסוב). אדמור בשטעפינטשט, עבר לארה\"ב."},{"i":16389,"n":"השלס, דב בר מלמברג","f":"דוד","b":"תשובה אליו - \"נדרי זריזין\"."},{"i":16390,"n":"השמעוני, אליעזר משלוניקי","f":"שמעון-ילקוט שמעוני?","dt":"רץ - ה אד\"ב","dp":"שלוניקי","b":"מחכמי אשכנז והתישב בשלוניקי (כך לדברי רוזניס - ואילו לדברי דוד פיפאנו היה מספרד). רב הקהילה האשכנזית בשלוניקי-רס, ואח\"כ רב קהילת קטלוניה ור חיים בן יעקב עובדיה בישאל על מקומו אחריו. בזמן ר יעקב ן חביב בעל \"עין יעקב\". היה מחלוקת כנגדו מהרב הראשי - ר משה קפסלי שאסר עליו לדון לבד בעניני גיטין, אולם חכמי שלוניקי לא קיימו את ההוראה והמשיך לדון בגיטין אולם צרפו לו את ר יהודה בנבנישתי. יזם את הדפסת מחזור קאטאלאן-רפו. היה אחד מ-3 הרבנים שהנהיגו את העיר - חבריו: ר אליעזר השמעוני, ור יעקב ן חביב בעל \"עין יעקב\". בניו: ר חנניה שעסק גם בהדפסת ספרים, ור אסטרוק."},{"i":16391,"n":"השמעוני, אשטרוק משלוניקי","f":"אליעזר משלוניקי","b":"סייע בהדפסת \"שארית יוסף\" - שלוניקי רפא."},{"i":16392,"n":"השמעוני, חנניה משלוניקי","f":"אליעזר משלוניקי","b":"גביר מחכמי קושטא. תמך בכספו בהדפסת ספרים ועוד."},{"i":16393,"n":"השמעוני, מסעוד","dt":"תרפג","b":"מחכמי קזבלנקה. מתורתו ב\"דשנת בשמן\"."},{"i":16394,"n":"השערה: מר חפץ אלוף","bk":[["ספר והזהיר",""]]},{"i":16395,"n":"השערה: ר\"י [ר' יוסף ב\"ר יצחק] מאורלינש","dt":"ד'תתקנג","b":"ספר העיטור, נקרא בכתבי ראשונים רבים בשם: \"עיטור סופרים\" [וכן הוא נקרא בעמ' הראשון של מהדו' תיקון סופרים ומקרא סופרים לררי\"א גירון]. דרושה הבחנה, שלא להחליפו בספר \"תיקון סופרים\" [נוסחי שטרות] למהר\"ש יפה בעל \"יפה תואר\", המכונה בספר כנסת הגדולה בשם: \"עיטור סופרים\". בעל העיטור חיבר גם: הגהות מאה שערים."},{"i":16396,"n":"התנא יונתן בן עוזיאל","dt":"כו סיון"},{"i":16397,"n":"התנא רבי עקיבא בן יוסף","dt":"י תשרי"},{"i":16398,"n":"התשואל, יוסף","b":"מגדולי רבני מערב אפריקה-תרט\"ז"},{"i":16399,"n":"התשואל, מסעוד מחיפה","f":"יוסף","bt":"תרב","bp":"טיטואן","dt":"תרסט - יג אדר","dp":"חיפה","b":"עלה מטיטואן לארץ והתישב בחיפה, טבריה, תלמיד רח\"ש הכהן קנורטי בטבריה. רב בחיפה-תרמו. חיבר שו\"ת בכת\"י. מתשובותיו ב\"ישא איש\" לר יעקב שאול אלישר."}];
